const _englishTextOriginals = new WeakMap();
const _englishAttrOriginals = new WeakMap();
let _englishUiObserver = null;
function translateExtendedLiteral(value){
    if(!value)return '';
    if(EN_UI_LITERALS[value])return EN_UI_LITERALS[value];
    const rules=[
        [/^已有\s*(\d+)\s*个自动化任务正在运行$/, '$1 automations running'],
        [/^已启用\s*(\d+)\s*个自动化任务$/, '$1 automations enabled'],
        [/^最近\s*(\d+)\s*条记录中，今天\s*(\d+)\s*条\s*·\s*(\d+)\s*项等待确认\s*·\s*(\d+)\s*项异常$/, '$2 today among $1 recent records · $3 pending approvals · $4 issues'],
        [/^今天生成\s*(\d+)\s*份报告\s*·\s*(\d+)\s*项等待确认\s*·\s*(\d+)\s*项异常$/, '$1 reports today · $2 pending approvals · $3 issues'],
        [/^(\d+)\s*个会话$/, '$1 conversations'],
        [/^(\d+)\s*个$/, '$1 items'],
        [/^(\d+)\s*个任务\s*·\s*(\d+)\s*份资料$/, '$1 tasks · $2 resources'],
        [/^(\d+)\s*条\s*·\s*(.+)$/, '$1 messages · $2'],
        [/^当前结果\s*(\d+)$/, '$1 results'],
        [/^已选择\s*(\d+)$/, '$1 selected'],
        [/^已归档\s*(\d+)$/, '$1 archived'],
        [/^占用\s*(.+)$/, 'Storage: $1'],
        [/^创建于\s*(.+)$/, 'Created $1'],
        [/^完成，收录\s*(\d+)\s*条$/, 'Completed · $1 items'],
        [/^完成，(\d+)\/(\d+)\s*个网站发生变化$/, 'Completed · $1 of $2 websites changed'],
        [/^每隔\s*(\d+)\s*小时$/, 'Every $1 hours'],
        [/^每天\s*(\d{1,2}:\d{2})$/, 'Daily at $1']
    ];
    for(const [pattern,replacement] of rules)if(pattern.test(value))return value.replace(pattern,replacement);
    return '';
}
function translateUnmarkedUi(root=document.body){
    if(!root)return;
    const translateText=node=>{if(node.parentElement?.closest('[data-i18n],[data-i18n-html],#messages,#session-list,[contenteditable="true"],textarea,script,style'))return;const raw=node.nodeValue||'',trim=raw.trim(),translated=translateExtendedLiteral(trim);if(!trim||!translated)return;if(!_englishTextOriginals.has(node))_englishTextOriginals.set(node,raw);node.nodeValue=raw.replace(trim,translated);};
    const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);while(walker.nextNode())translateText(walker.currentNode);
    const list=root.querySelectorAll?root.querySelectorAll('[placeholder],[title],[data-tooltip]'):[];
    list.forEach(el=>{if(el.closest('#messages,#session-list'))return;let saved=_englishAttrOriginals.get(el);if(!saved){saved={};_englishAttrOriginals.set(el,saved);}['placeholder','title','data-tooltip'].forEach(attr=>{const value=el.getAttribute(attr),translated=translateExtendedLiteral(value);if(value&&translated){if(!(attr in saved))saved[attr]=value;el.setAttribute(attr,translated);}});});
}
function restoreChineseUi(){
    document.querySelectorAll('body *').forEach(el=>{[...el.childNodes].filter(n=>n.nodeType===Node.TEXT_NODE).forEach(node=>{const original=_englishTextOriginals.get(node);if(original!==undefined)node.nodeValue=original;});const saved=_englishAttrOriginals.get(el);if(saved)Object.entries(saved).forEach(([key,value])=>el.setAttribute(key,value));});
}
function syncExtendedLanguage(){
    if(currentLang==='en'){
        translateUnmarkedUi();
        if(!_englishUiObserver){let queued=false;_englishUiObserver=new MutationObserver(()=>{if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;translateUnmarkedUi();});});_englishUiObserver.observe(document.body,{childList:true,subtree:true,characterData:true});}
        document.documentElement.classList.add('lang-en');
    }else{
        _englishUiObserver?.disconnect();_englishUiObserver=null;restoreChineseUi();document.documentElement.classList.remove('lang-en');
    }
}

// Resolve language by priority: user choice (localStorage) -> backend-detected
// (cow_lang) -> browser language -> 'zh'. Shares __cowResolveLang__ defined in
// chat.html; falls back to a local resolver if loaded standalone.
let currentLang = (typeof window.__cowResolveLang__ === 'function')
    ? window.__cowResolveLang__()
    : (function () {
        const norm = (raw) => {
            if (!raw) return '';
            const v = String(raw).trim().toLowerCase();
            if (v === 'auto') return '';
            if (v === 'zh-hant' || v.startsWith('zh-hant-') || v === 'zh-tw' || v === 'zh-hk') return 'zh';
            if (v.indexOf('zh') === 0) return 'zh';
            if (v.indexOf('en') === 0) return 'en';
            return '';
        };
        return norm(localStorage.getItem('cow_lang'))
            || norm(window.__COW_DEFAULT_LANG__)
            || norm(navigator.language)
            || 'zh';
    })();

function t(key) {
    return (I18N[currentLang] && I18N[currentLang][key]) || (I18N.en[key]) || key;
}

// Resolve a localized label that may be either a plain string or
// a {zh, en} object returned by the backend.
function localizedLabel(label) {
    if (label && typeof label === 'object') {
        return label[currentLang] || label.en || label.zh || '';
    }
    return label || '';
}

function applyI18n() {
    document.querySelectorAll('[data-i18n]').forEach(el => {
        el.textContent = t(el.dataset.i18n);
    });
    document.querySelectorAll('[data-i18n-html]').forEach(el => {
        el.innerHTML = t(el.dataset.i18nHtml);
    });
    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
        el.placeholder = t(el.dataset['i18nPlaceholder']);
    });
    document.querySelectorAll('[data-i18n-title]').forEach(el => {
        el.title = t(el.dataset['i18nTitle']);
    });
    document.querySelectorAll('[data-i18n-aria-label]').forEach(el => {
        el.setAttribute('aria-label', t(el.dataset['i18nAriaLabel']));
    });
    document.querySelectorAll('[data-tip-key]').forEach(el => {
        el.setAttribute('data-tooltip', t(el.dataset.tipKey));
    });
    installCfgTipPortal();
    
    // Clear any status messages when language changes
    document.querySelectorAll('[id$="-status"]').forEach(el => {
        el.classList.add('opacity-0');
    });
    
    const langLabel = document.getElementById('lang-label');
    if (langLabel) {
        if (currentLang === 'zh') langLabel.textContent = '简体';
        else langLabel.textContent = 'EN';
    }
    // Highlight the active option in the header language dropdown menu.
    document.querySelectorAll('#lang-menu .lang-menu-item').forEach(item => {
        const active = item.dataset.lang === currentLang;
        item.classList.toggle('text-blue-600', active);
        item.classList.toggle('dark:text-blue-400', active);
        item.classList.toggle('font-medium', active);
    });
    // Point the docs link to the locale-specific documentation site.
    // Workspace panel content is rendered by JS, not data-i18n attributes.
    if (typeof relocalizeWorkspacePanel === 'function') relocalizeWorkspacePanel();
    localizeRetentionControls();
    syncExtendedLanguage();
}

function localizeRetentionControls(){
    ['conversations','logs','uploads','artifacts'].forEach(key=>{const select=document.getElementById(`retention-${key}`);if(!select)return;[...select.options].forEach(option=>{const value=Number(option.value);if(!value)option.textContent=currentLang==='en'?'Keep forever':'永久保留';else if(value===365)option.textContent=currentLang==='en'?'1 year':'1 年';else option.textContent=currentLang==='en'?`${value} days`:`${value} 天`;});});
    const language=document.querySelector('#settings-system select[onchange*="setLanguage"]');if(language)language.value=currentLang;
}

// Single entry point for switching language. Updates the in-memory language,
// persists the user choice locally, re-renders the UI, and binds the choice to
// the backend `cow_lang` config so logs / agent replies / CLI follow suit.
function setLanguage(lang) {
    const next = (lang === 'en' || lang === 'zh') ? lang : 'zh';
    if (next === currentLang) {
        // Still persist + sync in case storage/backend drifted from the UI.
        syncLanguageToBackend(next);
        return;
    }
    currentLang = next;
    localStorage.setItem('cow_lang', currentLang);
    applyI18n();
    renderQuickSettingsShortcuts();
    renderQuickSettingsEditor();
    _applyInputTooltips();
    // Session-panel labels (default space, today/yesterday, pinned group) are
    // produced via t() at render time, so repaint the list to pick up the new
    // language instead of leaving stale text like "默认空间" under English.
    if (sessionPanelOpen && _sessionItems.length) _renderSessionList();
    // Keep the language switch button and config selector visually in sync.
    try { updateLangControls(); } catch (e) {}
    
    // Sync language choice to backend first, then trigger dynamic views reload
    // to avoid race conditions on API endpoints.
    syncLanguageToBackend(currentLang, () => {
        try { rerenderDynamicViews(); } catch (e) {}
    });
}

// Persist the language to the backend `cow_lang` config (best-effort; the UI
// has already switched locally, so a network failure is non-blocking).
function syncLanguageToBackend(lang, callback) {
    try {
        fetch('/config', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ updates: { cow_lang: lang } })
        })
        .then(() => { if (callback) callback(); })
        .catch(() => { if (callback) callback(); });
    } catch (e) {
        if (callback) callback();
    }
}

// Reflect the current language on both the top-right toggle and the config
// selector (if present), so the two entry points stay synchronized.
function updateLangControls() {
    const langLabel = document.getElementById('lang-label');
    if (langLabel) {
        if (currentLang === 'zh') langLabel.textContent = '简体';
        else langLabel.textContent = 'EN';
    }
    // Highlight the active option in the header language dropdown menu.
    document.querySelectorAll('#lang-menu .lang-menu-item').forEach(item => {
        const active = item.dataset.lang === currentLang;
        item.classList.toggle('text-blue-600', active);
        item.classList.toggle('dark:text-blue-400', active);
        item.classList.toggle('font-medium', active);
    });
    // The config language picker is the custom .cfg-dropdown component. Only
    // sync it once it has been initialized (i.e. the config panel was opened).
    const sel = document.getElementById('cfg-lang-select');
    if (sel && sel._ddValue !== undefined && sel._ddValue !== currentLang) {
        sel._ddValue = currentLang;
        const textEl = sel.querySelector('.cfg-dropdown-text');
        if (textEl) {
            if (currentLang === 'zh') textEl.textContent = '简体中文';
            else textEl.textContent = 'English';
        }
        sel.querySelectorAll('.cfg-dropdown-item').forEach(i => {
            i.classList.toggle('active', i.dataset.value === currentLang);
        });
    }
}

// Toggle the header language dropdown menu open/closed.
function toggleLangMenu(event) {
    if (event) event.stopPropagation();
    const menu = document.getElementById('lang-menu');
    if (menu) menu.classList.toggle('hidden');
}

// Pick a language from the dropdown, then close the menu.
function selectLanguage(lang) {
    const menu = document.getElementById('lang-menu');
    if (menu) menu.classList.add('hidden');
    setLanguage(lang);
}
window.toggleLangMenu = toggleLangMenu;
window.selectLanguage = selectLanguage;

const QUICK_SETTINGS_STORAGE_KEY = 'cow_quick_settings_items_v1';
const QUICK_SETTINGS_ITEMS = [
    {key:'system', zh:'通用', en:'General', icon:'fa-gear', section:'system'},
    {key:'user-profile', zh:'个人主页', en:'Profile', icon:'fa-user-pen', section:'user-profile'},
    {key:'quick-tags', zh:'快捷标签', en:'Quick tags', icon:'fa-keyboard', section:'quick-tags'},
    {key:'config', zh:'智能体与模型', en:'Agent & models', icon:'fa-user-gear', view:'config'},
    {key:'memory', zh:'记忆', en:'Memory', icon:'fa-brain', view:'memory'},
    {key:'memory-wiki', zh:'Memory Wiki', en:'Memory Wiki', icon:'fa-book-atlas', view:'memory-wiki'},
    {key:'channels', zh:'通道与连接', en:'Channels & connections', icon:'fa-link', view:'channels'},
    {key:'tasks', zh:'定时任务', en:'Scheduled tasks', icon:'fa-clock', view:'tasks'},
    {key:'remote-bridge', zh:'远程 Bridge', en:'Remote Bridge', icon:'fa-tower-cell', view:'remote-bridge'},
    {key:'knowledge', zh:'数据管理', en:'Data management', icon:'fa-database', view:'knowledge'},
    {key:'api', zh:'API 管理', en:'API management', icon:'fa-code', view:'api'},
    {key:'logs', zh:'系统日志', en:'System logs', icon:'fa-terminal', view:'logs'},
    {key:'maintenance', zh:'维护看板', en:'Maintenance dashboard', icon:'fa-heart-pulse', view:'maintenance'},
    {key:'about', zh:'关于我们', en:'About', icon:'fa-circle-info', section:'about'},
];
function getQuickSettingsSelection(){
    try {
        const stored=JSON.parse(localStorage.getItem(QUICK_SETTINGS_STORAGE_KEY)||'[]');
        return Array.isArray(stored)?stored.filter(key=>QUICK_SETTINGS_ITEMS.some(item=>item.key===key)):[];
    } catch { return []; }
}
function setQuickSettingsShortcut(key,enabled){
    const selected=new Set(getQuickSettingsSelection());
    if(enabled)selected.add(key);else selected.delete(key);
    localStorage.setItem(QUICK_SETTINGS_STORAGE_KEY,JSON.stringify(QUICK_SETTINGS_ITEMS.filter(item=>selected.has(item.key)).map(item=>item.key)));
    renderQuickSettingsShortcuts();
}
function openQuickSettingsShortcut(key){
    const item=QUICK_SETTINGS_ITEMS.find(candidate=>candidate.key===key);
    if(!item)return;
    openSettingsCenter();
    if(item.section)selectSettingsSection(item.section);
    else showSettingsView(item.view,currentLang==='en'?item.en:item.zh);
    closeOwnerMenu();
}
function renderQuickSettingsShortcuts(){
    const host=document.getElementById('owner-menu-custom');
    if(!host)return;
    host.replaceChildren();
    const selected=new Set(getQuickSettingsSelection());
    QUICK_SETTINGS_ITEMS.filter(item=>selected.has(item.key)).forEach(item=>{
        const button=document.createElement('button');
        button.type='button';button.className='owner-menu-row';
        const left=document.createElement('span');
        const icon=document.createElement('i');icon.className=`fas ${item.icon} text-slate-400`;
        left.append(icon,document.createTextNode(currentLang==='en'?item.en:item.zh));
        const arrow=document.createElement('i');arrow.className='fas fa-chevron-right text-[10px] opacity-50';
        button.append(left,arrow);
        button.onclick=()=>openQuickSettingsShortcut(item.key);
        host.appendChild(button);
    });
}
function renderQuickSettingsEditor(){
    const host=document.getElementById('settings-shortcut-list');
    if(!host)return;
    host.replaceChildren();
    const selected=new Set(getQuickSettingsSelection());
    QUICK_SETTINGS_ITEMS.forEach(item=>{
        const label=document.createElement('label');label.className='settings-shortcut-option';
        const input=document.createElement('input');input.type='checkbox';input.checked=selected.has(item.key);
        input.setAttribute('aria-label',`${currentLang==='en'?'Add to quick settings':'添加到快捷设置'}：${currentLang==='en'?item.en:item.zh}`);
        input.onchange=()=>setQuickSettingsShortcut(item.key,input.checked);
        const icon=document.createElement('i');icon.className=`fas ${item.icon}`;
        const name=document.createElement('span');name.textContent=currentLang==='en'?item.en:item.zh;
        label.append(input,icon,name);host.appendChild(label);
    });
}

function toggleOwnerMenu(event) {
    if (event) event.stopPropagation();
    const menu = document.getElementById('owner-menu');
    const toggle = document.getElementById('owner-menu-toggle');
    if (!menu) return;
    const willOpen = menu.classList.contains('hidden');
    if (willOpen) renderQuickSettingsShortcuts();
    menu.classList.toggle('hidden', !willOpen);
    toggle?.classList.toggle('is-open', willOpen);
}

function closeOwnerMenu() {
    document.getElementById('owner-menu')?.classList.add('hidden');
    document.getElementById('owner-menu-toggle')?.classList.remove('is-open');
}

window.toggleOwnerMenu = toggleOwnerMenu;
window.closeOwnerMenu = closeOwnerMenu;

document.addEventListener('click', (e) => {
    const ownerArea = document.getElementById('sidebar-owner-area');
    if (ownerArea && !ownerArea.contains(e.target)) closeOwnerMenu();
});

// Close the language menu when clicking outside of it.
document.addEventListener('click', (e) => {
    const selector = document.getElementById('lang-selector');
    const menu = document.getElementById('lang-menu');
    if (menu && !menu.classList.contains('hidden') && selector && !selector.contains(e.target)) {
        menu.classList.add('hidden');
    }
});

// Refresh JS-rendered views after a language switch. Each branch uses the
// lightweight in-memory re-render path (no extra network round-trips).
function rerenderDynamicViews() {
    if (currentView === 'config' && _configModelsLoaded && typeof renderModelsView === 'function'
            && modelsState && (modelsState.providers || modelsState.capabilities)) {
        renderModelsView();
    }
    // Reload task list after language switch
    if (currentView === 'tasks') {
        tasksLoaded = false;
        loadTasksView();
    }
    // Reload skills and tools after language switch
    if (currentView === 'skills') {
        toolsLoaded = false;
        loadSkillsView();
    }
    // Reload channels after language switch
    if (currentView === 'channels') {
        loadChannelsView();
    }
    // Reload config after language switch
    if (currentView === 'config') {
        loadConfigView();
    }
    const embeddedId=settingsMountedView?.node?.id||'';
    if(embeddedId==='view-config')loadConfigView();
    else if(embeddedId==='view-tasks'){tasksLoaded=false;loadTasksView();}
    else if(embeddedId==='view-skills'){toolsLoaded=false;loadSkillsView();}
    else if(embeddedId==='view-channels')loadChannelsView();
}

// Floating tooltip portal for [data-tip-key] elements. Tooltip nodes are
// appended to <body> so they aren't clipped by overflow:hidden ancestors
// (e.g. the config panel's scroll container).
let _cfgTipPortalEl = null;
let _cfgTipPortalInstalled = false;
function installCfgTipPortal() {
    if (_cfgTipPortalInstalled) return;
    _cfgTipPortalInstalled = true;

    const showTip = (target) => {
        const text = target.getAttribute('data-tooltip');
        if (!text) return;
        if (!_cfgTipPortalEl) {
            _cfgTipPortalEl = document.createElement('div');
            _cfgTipPortalEl.className = 'cfg-tip-floating';
            document.body.appendChild(_cfgTipPortalEl);
        }
        _cfgTipPortalEl.textContent = text;
        const rect = target.getBoundingClientRect();
        // Render once to measure, then position relative to the target.
        _cfgTipPortalEl.style.left = '0px';
        _cfgTipPortalEl.style.top = '0px';
        _cfgTipPortalEl.classList.add('show');
        const tipRect = _cfgTipPortalEl.getBoundingClientRect();
        let left = rect.left + rect.width / 2 - tipRect.width / 2;
        // Clamp horizontally to the viewport with an 8px gutter.
        left = Math.max(8, Math.min(left, window.innerWidth - tipRect.width - 8));
        // Default above the target; place below when data-tooltip-pos="bottom".
        const below = target.getAttribute('data-tooltip-pos') === 'bottom';
        const top = below ? rect.bottom + 6 : rect.top - tipRect.height - 6;
        _cfgTipPortalEl.style.left = left + 'px';
        _cfgTipPortalEl.style.top = top + 'px';
    };
    const hideTip = () => {
        if (_cfgTipPortalEl) _cfgTipPortalEl.classList.remove('show');
    };

    // Matches config keys and any element opting into the floating tooltip via
    // [data-tip-float] (used for dynamic tooltips like the workspace selector,
    // whose data-tooltip is set at runtime rather than from a translation key).
    const _tipSel = '[data-tip-key],[data-tip-float]';
    document.addEventListener('mouseover', (e) => {
        const target = e.target.closest(_tipSel);
        if (target) showTip(target);
    });
    document.addEventListener('mouseout', (e) => {
        const target = e.target.closest(_tipSel);
        if (target) hideTip();
    });
    // Hide on scroll/resize so the tooltip doesn't drift away from its anchor.
    window.addEventListener('scroll', hideTip, true);
    window.addEventListener('resize', hideTip);
}

// =====================================================================
// Theme
// =====================================================================
let currentTheme = localStorage.getItem('cow_theme') || 'dark';

function applyTheme() {
    const root = document.documentElement;
    if (currentTheme === 'dark') {
        root.classList.add('dark');
        root.style.colorScheme = 'dark';
        document.getElementById('theme-icon').className = 'fas fa-sun';
        document.getElementById('hljs-light').disabled = true;
        document.getElementById('hljs-dark').disabled = false;
    } else {
        root.classList.remove('dark');
        root.style.colorScheme = 'light';
        document.getElementById('theme-icon').className = 'fas fa-moon';
        document.getElementById('hljs-light').disabled = false;
        document.getElementById('hljs-dark').disabled = true;
    }
    document.body?.setAttribute('data-theme', currentTheme);
    let themeColor = document.querySelector('meta[name="theme-color"]');
    if (!themeColor) {
        themeColor = document.createElement('meta');
        themeColor.name = 'theme-color';
        document.head.appendChild(themeColor);
    }
    themeColor.content = currentTheme === 'dark' ? '#090909' : '#ffffff';
}

function toggleTheme() {
    currentTheme = currentTheme === 'dark' ? 'light' : 'dark';
    localStorage.setItem('cow_theme', currentTheme);
    applyTheme();
}

// =====================================================================
// Task completion notification (client-side preference)
// =====================================================================
const TASK_NOTIFY_KEY = 'cow_task_notify';
const TASK_NOTIFY_SOUND_KEY = 'cow_task_notify_sound';
let taskNotifyEnabled = localStorage.getItem(TASK_NOTIFY_KEY) !== '0';
let taskNotifySound = localStorage.getItem(TASK_NOTIFY_SOUND_KEY) !== '0';
let notifyAudioCtx = null;
let unreadCount = 0;
const baseDocTitle = document.title;

// Unlock audio on the first user gesture; browsers block autoplay otherwise.
document.addEventListener('pointerdown', function() {
    if (window.AudioContext) notifyAudioCtx = notifyAudioCtx || new AudioContext();
    if (notifyAudioCtx && notifyAudioCtx.state === 'suspended') {
        notifyAudioCtx.resume().catch(function() {});
    }
}, { once: true });

function playNotifyBeep() {
    if (!taskNotifySound) return;
    try {
        if (!notifyAudioCtx) {
            const Ctx = window.AudioContext || window.webkitAudioContext;
            if (!Ctx) return;
            notifyAudioCtx = new Ctx();
        }
        if (notifyAudioCtx.state === 'suspended') {
            notifyAudioCtx.resume().catch(function() {});
        }
        // Two short sine tones (A5 → D6); no audio asset needed.
        const t0 = notifyAudioCtx.currentTime;
        [880, 1174.66].forEach(function(freq, i) {
            const at = t0 + i * 0.09;
            const osc = notifyAudioCtx.createOscillator();
            const gain = notifyAudioCtx.createGain();
            osc.type = 'sine';
            osc.frequency.value = freq;
            gain.gain.setValueAtTime(0.001, at);
            gain.gain.exponentialRampToValueAtTime(0.12, at + 0.01);
            gain.gain.exponentialRampToValueAtTime(0.001, at + 0.09);
            osc.connect(gain).connect(notifyAudioCtx.destination);
            osc.start(at);
            osc.stop(at + 0.1);
        });
    } catch (_) {
        // Autoplay still blocked or AudioContext unavailable; stay silent.
    }
}

function firstLineSnippet(text) {
    return (text || '').split('\n')[0].trim().slice(0, 80);
}

function sessionTitleOf(sid) {
    const el = document.querySelector(`.session-item[data-session-id="${sid}"] .session-title`);
    return el ? el.textContent.trim() : '';
}

function popNotification(title, body, sid) {
    if (typeof Notification === 'undefined' || Notification.permission !== 'granted') return;
    try {
        const n = new Notification(title, { body: body || title });
        n.onclick = function() {
            window.focus();
            if (sid && sid !== sessionId) switchSession(sid);
            n.close();
        };
    } catch (_) {
        // Notification API unavailable; beep + title badge still applied.
    }
}

let backgroundChatNoticeState = '';
function ensureBackgroundChatNotice() {
    let el = document.getElementById('background-chat-notice');
    if (el) return el;
    el = document.createElement('button');
    el.id = 'background-chat-notice';
    el.type = 'button';
    el.style.cssText = 'display:none;position:fixed;right:24px;bottom:24px;z-index:120;max-width:360px;padding:12px 16px;border-radius:14px;background:#111827;color:#fff;box-shadow:0 16px 40px rgba(15,23,42,.28);text-align:left;align-items:center;gap:10px;';
    el.onclick = function() {
        const sid = el.dataset.sessionId;
        navigateTo('chat');
        if (sid && sid !== sessionId) switchSession(sid);
        hideBackgroundChatNotice();
    };
    document.body.appendChild(el);
    return el;
}

function showBackgroundChatNotice(state, text, sid) {
    if (currentView === 'chat') return;
    const el = ensureBackgroundChatNotice();
    backgroundChatNoticeState = state;
    el.dataset.sessionId = sid || sessionId;
    el.style.display = 'flex';
    const icon = state === 'running' ? 'fa-spinner fa-spin' : state === 'error' ? 'fa-circle-exclamation' : 'fa-circle-check';
    const title = state === 'running' ? 'Agent 正在后台处理' : state === 'error' ? 'Agent 处理失败' : 'Agent 已完成回复';
    el.innerHTML = `<i class="fas ${icon}" style="color:${state==='error'?'#f87171':state==='done'?'#34d399':'#60a5fa'}"></i><span style="min-width:0"><b style="display:block;font-size:13px">${title}</b><span style="display:block;margin-top:2px;font-size:11px;color:#cbd5e1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${escapeHtml(firstLineSnippet(text)||'点击返回会话查看')}</span></span>`;
}

function hideBackgroundChatNotice() {
    const el = document.getElementById('background-chat-notice');
    if (el) el.style.display = 'none';
    backgroundChatNoticeState = '';
}

function showTaskNotification(title, body, sid) {
    if (!taskNotifyEnabled) return;
    if (currentView !== 'chat') showBackgroundChatNotice('done', body, sid);
    // Only notify when the window is not focused. If the user is actively
    // watching the tab, the reply is already on screen — a notification/beep
    // would just be noise (especially for short tasks).
    if (document.hasFocus()) return;
    playNotifyBeep();
    if (document.hidden) {
        unreadCount += 1;
        document.title = `(${unreadCount}) ${baseDocTitle}`;
    }
    if (typeof Notification === 'undefined') return;
    // First time we actually need to notify (window is in the background):
    // request permission now, then show this notification once granted. This
    // is more contextual than prompting on page load.
    if (Notification.permission === 'default') {
        Notification.requestPermission()
            .then(function(perm) {
                if (perm === 'granted') popNotification(title, body, sid);
                else refreshNotifyBlockedHint();
            })
            .catch(function() {});
        return;
    }
    if (Notification.permission === 'denied') {
        // Can't notify; surface the hint in settings so the user knows why.
        refreshNotifyBlockedHint();
        return;
    }
    popNotification(title, body, sid);
}

function notifyTaskFinished(sid, kind, text) {
    const label = t(kind === 'error' ? 'notify_task_error' : 'notify_task_done');
    const snippet = firstLineSnippet(text);
    if (currentView !== 'chat') showBackgroundChatNotice(kind === 'error' ? 'error' : 'done', snippet || label, sid);
    showTaskNotification(sessionTitleOf(sid) || label, snippet ? `${label}: ${snippet}` : label, sid);
}

document.addEventListener('visibilitychange', function() {
    if (!document.hidden) {
        unreadCount = 0;
        document.title = baseDocTitle;
    }
});

// Request OS notification permission when notifications are enabled and the
// browser hasn't decided yet. Safe to call repeatedly.
function ensureNotifyPermission() {
    if (taskNotifyEnabled
        && typeof Notification !== 'undefined'
        && Notification.permission === 'default') {
        Notification.requestPermission().catch(function() {});
    }
}

// Show the "blocked by browser" hint only when notifications are enabled but
// the browser permission is denied (nothing the app can do about it in code).
function refreshNotifyBlockedHint() {
    const el = document.getElementById('cfg-task-notify-blocked');
    if (!el) return;
    const blocked = taskNotifyEnabled
        && typeof Notification !== 'undefined'
        && Notification.permission === 'denied';
    el.classList.toggle('hidden', !blocked);
}

function initTaskNotifyToggles() {
    const notifyEl = document.getElementById('cfg-task-notify');
    if (notifyEl) {
        notifyEl.checked = taskNotifyEnabled;
        notifyEl.addEventListener('change', function() {
            taskNotifyEnabled = notifyEl.checked;
            localStorage.setItem(TASK_NOTIFY_KEY, taskNotifyEnabled ? '1' : '0');
            ensureNotifyPermission();
            refreshNotifyBlockedHint();
        });
    }
    const soundEl = document.getElementById('cfg-task-notify-sound');
    if (soundEl) {
        soundEl.checked = taskNotifySound;
        soundEl.addEventListener('change', function() {
            taskNotifySound = soundEl.checked;
            localStorage.setItem(TASK_NOTIFY_SOUND_KEY, taskNotifySound ? '1' : '0');
        });
    }
    refreshNotifyBlockedHint();
}

document.addEventListener('DOMContentLoaded', initTaskNotifyToggles);

// =====================================================================
// Sidebar & Navigation
// =====================================================================
const VIEW_META = {
    'mission-control': { group: 'menu_mission_control', page: '仪表盘' },
    chat:     { group: 'nav_chat',    page: 'menu_chat' },
    config:   { group: 'nav_manage',  page: 'menu_config' },
    skills:   { group: 'nav_manage',  page: 'menu_skills' },
    'common-functions': { group: 'nav_manage', page: 'menu_common_functions' },
    'memory-wiki': { group: 'nav_manage', page: 'menu_memory_wiki' },
    'agent-roster': { group: 'nav_manage', page: 'menu_agent_roster' },
    'remote-bridge': { group: 'nav_manage', page: 'menu_remote_bridge' },
    maintenance: { group: 'sidebar_system_management', page: 'menu_maintenance_dashboard' },
    projects: { group: 'nav_manage',  page: 'page_projects' },
    artifacts:{ group: 'nav_manage',  page: 'page_artifacts' },
    'weixin-assistant': { group: 'sidebar_daily_collaboration', page: 'page_weixin_assistant' },
    memory:   { group: 'nav_manage',  page: 'menu_memory' },
    knowledge:{ group: 'nav_manage',  page: 'menu_knowledge' },
    channels: { group: 'nav_manage',  page: 'menu_channels' },
    tasks:    { group: 'nav_manage',  page: 'menu_tasks' },
    intelligence: { group: 'nav_manage', page: 'page_automation' },
    api:      { group: 'nav_manage',  page: 'page_api' },
    logs:     { group: 'nav_monitor', page: 'menu_logs' },
};

let currentView = 'mission-control';

function navigateTo(viewId) {
    if (!VIEW_META[viewId]) return;
    document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
    const target = document.getElementById('view-' + viewId);
    if (target) target.classList.add('active');
    document.querySelectorAll('.sidebar-item').forEach(item => {
        item.classList.toggle('active', item.dataset.view === viewId);
    });
    const meta = VIEW_META[viewId];
    document.getElementById('breadcrumb-group').textContent = t(meta.group);
    document.getElementById('breadcrumb-group').dataset.i18n = meta.group;
    document.getElementById('breadcrumb-page').textContent = t(meta.page);
    document.getElementById('breadcrumb-page').dataset.i18n = meta.page;
    currentView = viewId;
    const chatOnly=viewId==='chat';
    if (chatOnly) updateChatSessionHeader();
    document.getElementById('session-toggle-btn')?.classList.toggle('hidden', !chatOnly);
    const chatActions = document.getElementById('chat-header-actions');
    if (chatActions) chatActions.style.display = chatOnly ? 'flex' : 'none';
    if (!chatOnly) closeChatToolPanel();
    if(!chatOnly)closeSessionPanel();
    positionCapabilityTabs(viewId === 'skills');
    if (viewId === 'projects') renderProjects();
    if (viewId === 'artifacts') loadArtifacts();
    if (viewId === 'mission-control') loadMissionControl(true);
    if (viewId === 'maintenance') loadMaintenanceDashboard(true);
    if (viewId === 'common-functions') showCommonFunctionsHome();
    if (viewId === 'memory-wiki') loadMemoryWiki();
    if (viewId === 'agent-roster') loadAgentRoster();
    if (viewId === 'remote-bridge') loadRemoteBridge();
    if (viewId === 'weixin-assistant') loadWeixinAssistantConversations();
    
    // Clear status messages when navigating away
    document.querySelectorAll('[id$="-status"]').forEach(el => {
        el.classList.add('opacity-0');
    });
    
    if (window.innerWidth < 1024) closeSidebar();
}

function toggleSidebar() {
    const sidebar = document.getElementById('sidebar');
    const overlay = document.getElementById('sidebar-overlay');
    const isOpen = !sidebar.classList.contains('-translate-x-full');
    if (isOpen) {
        closeSidebar();
    } else {
        sidebar.classList.remove('-translate-x-full');
        overlay.classList.remove('hidden');
    }
}

function closeSidebar() {
    document.getElementById('sidebar').classList.add('-translate-x-full');
    document.getElementById('sidebar-overlay').classList.add('hidden');
}

let memoryWikiSections = [];
let memoryWikiFactStore = { stats: { total: 0, by_type: {} }, items: [] };
let memoryWikiSelectedFacts = new Set();
let memoryWikiFactStatusFilter = 'all';
let currentMemoryWikiSection = 'tree';
let memoryWikiDirty = false;
let memoryWikiMode = 'edit';

function setMemoryWikiStatus(text, type = 'muted') {
    const el = document.getElementById('memory-wiki-status');
    if (!el) return;
    const color = type === 'success' ? 'text-emerald-600' : type === 'error' ? 'text-red-500' : type === 'warning' ? 'text-amber-600' : 'text-slate-400';
    el.className = `text-xs min-h-5 ${color}`;
    el.textContent = text || '';
}

async function loadMemoryWiki(force = false) {
    if (memoryWikiSections.length && !force) {
        renderMemoryWikiSections();
        renderMemoryWikiCurrent();
        return;
    }
    setMemoryWikiStatus('正在读取 Memory Wiki…');
    try {
        const response = await fetch('/api/memory-wiki');
        const data = await response.json();
        if (data.status !== 'success') throw new Error(data.message || '读取失败');
        memoryWikiSections = data.sections || [];
        memoryWikiFactStore = data.fact_store || { stats: { total: 0, by_type: {} }, items: [] };
        document.getElementById('memory-wiki-path').textContent = data.path || '';
        if (!memoryWikiSections.find(x => x.id === currentMemoryWikiSection)) {
            currentMemoryWikiSection = memoryWikiSections[0]?.id || 'profile';
        }
        memoryWikiDirty = false;
        renderMemoryWikiSections();
        renderMemoryWikiFactStore();
        renderMemoryWikiCurrent();
        setMemoryWikiStatus(`已读取 ${memoryWikiSections.length} 个 Wiki 页面`, 'success');
    } catch (error) {
        setMemoryWikiStatus(`读取失败：${error.message}`, 'error');
    }
}

function renderMemoryWikiSections() {
    const host = document.getElementById('memory-wiki-sections');
    if (!host) return;
    const query = (document.getElementById('memory-wiki-search')?.value || '').trim().toLowerCase();
    const items = memoryWikiSections.filter(item => {
        if (!query) return true;
        const text = [item.title, item.source, item.content, item.effective_summary].join(' ').toLowerCase();
        return text.includes(query);
    });
    host.innerHTML = items.map(item => {
        const active = item.id === currentMemoryWikiSection;
        const badge = item.edited ? '<span class="ml-auto text-[10px] px-2 py-0.5 rounded-full bg-blue-50 dark:bg-blue-500/10 text-blue-600">已编辑</span>' : '<span class="ml-auto text-[10px] px-2 py-0.5 rounded-full bg-slate-100 dark:bg-white/10 text-slate-400">系统生成</span>';
        return `<button onclick="switchMemoryWikiSection('${item.id}')" class="w-full flex items-center gap-3 rounded-xl px-3 py-3 text-left transition ${active ? 'bg-purple-600 text-white shadow-sm' : 'hover:bg-slate-50 dark:hover:bg-white/5 text-slate-600 dark:text-slate-300'}"><i class="fas ${escapeHtml(item.icon || 'fa-file-lines')} w-5 text-center ${active ? 'text-white' : 'text-purple-400'}"></i><span class="font-medium text-sm">${escapeHtml(item.title)}</span>${active ? '' : badge}</button>`;
    }).join('') || '<div class="p-4 text-sm text-slate-400">没有找到匹配的 Wiki 页面</div>';
    renderMemoryWikiFactStore();
}

function memoryFactTypeLabel(type) {
    return {
        learning_takeaway: '学习结论',
        learning_point: '学习要点',
        reuse_pattern: '复用方法',
        preference: '用户偏好',
        output_preference: '输出偏好',
        source_preference: '来源偏好',
        notification_preference: '通知偏好',
        approval_preference: '审批偏好',
        failure_lesson: '失败经验',
        success_path: '成功路径',
        knowledge: '知识'
    }[type] || type || '事实';
}

function memoryFactStatusOf(item = {}) {
    return String(item.status || 'active');
}

function memoryFactStatusMatch(item = {}) {
    const status = memoryFactStatusOf(item);
    if (memoryWikiFactStatusFilter === 'pending') return status === 'pending';
    if (memoryWikiFactStatusFilter === 'active') return status === 'active';
    if (memoryWikiFactStatusFilter === 'disabled') return status === 'disabled';
    return status !== 'deleted';
}

function memoryFactSearchMatch(item = {}) {
    const query = (document.getElementById('memory-wiki-search')?.value || '').trim().toLowerCase();
    if (!query) return true;
    return [item.title, item.content, item.fact_type, item.source, (item.tags || []).join(' ')].join(' ').toLowerCase().includes(query);
}

function filteredMemoryFacts() {
    return (memoryWikiFactStore?.items || []).filter(item => memoryFactStatusMatch(item) && memoryFactSearchMatch(item));
}

function setMemoryFactStatusFilter(filter = 'all') {
    memoryWikiFactStatusFilter = ['all', 'pending', 'active', 'disabled'].includes(filter) ? filter : 'all';
    memoryWikiSelectedFacts.clear();
    renderMemoryWikiFactStore();
}

function renderMemoryWikiFactStore() {
    const host = document.getElementById('memory-wiki-fact-store');
    if (!host) return;
    const stats = memoryWikiFactStore?.stats || {};
    const filteredItems = filteredMemoryFacts();
    const items = filteredItems.slice(0, 6);
    const visibleIds = items.map(item => String(item.id || '')).filter(Boolean);
    memoryWikiSelectedFacts = new Set([...memoryWikiSelectedFacts].filter(id => (memoryWikiFactStore?.items || []).some(item => item.id === id)));
    const selectedCount = memoryWikiSelectedFacts.size;
    const allVisibleSelected = visibleIds.length > 0 && visibleIds.every(id => memoryWikiSelectedFacts.has(id));
    const byType = stats.by_type || {};
    const typeBadges = Object.entries(byType).slice(0, 4).map(([key, count]) => `<span class="px-2 py-0.5 rounded-full bg-white/70 dark:bg-white/10">${escapeHtml(memoryFactTypeLabel(key))} ${Number(count || 0)}</span>`).join('');
    const filterButtons = [
        ['all', '全部', Number(stats.total || 0) + Number(stats.pending || 0) + Number(stats.disabled || 0)],
        ['pending', '待确认', Number(stats.pending || 0)],
        ['active', '已生效', Number(stats.total || 0)],
        ['disabled', '已禁用', Number(stats.disabled || 0)]
    ].map(([key, label, count]) => {
        const active = memoryWikiFactStatusFilter === key;
        return `<button onclick="setMemoryFactStatusFilter('${key}')" class="px-2 py-1 rounded-lg ${active ? 'bg-purple-600 text-white' : 'bg-white/80 dark:bg-white/10 text-purple-600'}">${label} ${count}</button>`;
    }).join('');
    host.innerHTML = `<div class="rounded-2xl border border-purple-100 dark:border-purple-500/20 bg-purple-50/60 dark:bg-purple-500/10 p-3">
        <div class="flex items-center justify-between gap-2">
            <div>
                <div class="text-xs font-semibold text-purple-700 dark:text-purple-200"><i class="fas fa-database mr-1"></i>本地事实库</div>
                <div class="mt-1 text-[11px] text-purple-500 dark:text-purple-300">可生效 ${Number(stats.total || 0)} 条 · 待确认 ${Number(stats.pending || 0)} 条 · 已禁用 ${Number(stats.disabled || 0)} 条</div>
            </div>
            <button onclick="refreshMemoryFactStore()" class="w-8 h-8 rounded-lg bg-white/80 dark:bg-white/10 text-purple-600" title="刷新事实库"><i class="fas fa-rotate text-xs"></i></button>
        </div>
        <div class="flex flex-wrap gap-1 mt-2 text-[10px] text-purple-600 dark:text-purple-200">${typeBadges || '<span class="text-purple-400">等待快速学习或任务经验沉淀</span>'}</div>
        <div class="mt-3 flex flex-wrap gap-1 text-[10px]">${filterButtons}</div>
        <div class="mt-3 flex flex-wrap items-center gap-2 text-[10px]">
            <button onclick="toggleMemoryFactSelectVisible(${allVisibleSelected ? 'false' : 'true'})" class="px-2 py-1 rounded-lg bg-white/80 dark:bg-white/10 text-purple-600">${allVisibleSelected ? '取消全选' : '选择可见项'}</button>
            <span class="text-purple-500">已选 ${selectedCount} 条</span>
            <button onclick="bulkUpdateMemoryFacts('approve')" class="px-2 py-1 rounded-lg bg-emerald-50 text-emerald-600 dark:bg-emerald-500/10 ${selectedCount ? '' : 'opacity-40 pointer-events-none'}"><i class="fas fa-circle-check mr-1"></i>批量确认</button>
            <button onclick="bulkUpdateMemoryFacts('disable')" class="px-2 py-1 rounded-lg bg-amber-50 text-amber-600 dark:bg-amber-500/10 ${selectedCount ? '' : 'opacity-40 pointer-events-none'}"><i class="fas fa-ban mr-1"></i>批量禁用</button>
            <button onclick="bulkUpdateMemoryFacts('delete')" class="px-2 py-1 rounded-lg bg-red-50 text-red-500 dark:bg-red-500/10 ${selectedCount ? '' : 'opacity-40 pointer-events-none'}"><i class="fas fa-trash-can mr-1"></i>批量删除</button>
        </div>
        <div class="mt-3 space-y-2">${items.map(item => {
            const disabled = item.status === 'disabled';
            const pending = item.status === 'pending';
            const checked = memoryWikiSelectedFacts.has(String(item.id || ''));
            const statusText = pending ? ' · 待确认' : (disabled ? ' · 已禁用' : '');
            return `<div class="w-full rounded-xl ${disabled ? 'bg-slate-100/80 dark:bg-white/5 opacity-75' : pending ? 'bg-amber-50/80 dark:bg-amber-500/10' : 'bg-white/80 dark:bg-white/5'} p-2">
            <div class="flex items-start gap-2">
                <input type="checkbox" ${checked ? 'checked' : ''} onclick="toggleMemoryFactSelection(event,'${encodeURIComponent(item.id || '')}')" class="mt-1 rounded border-slate-300 text-purple-600">
                <button onclick="openMemoryFactDetail('${encodeURIComponent(item.id || '')}')" class="min-w-0 flex-1 text-left">
                <div class="flex items-center justify-between gap-2">
                    <span class="text-[11px] font-medium ${disabled ? 'text-slate-400' : pending ? 'text-amber-600' : 'text-purple-600'}">${escapeHtml(memoryFactTypeLabel(item.fact_type))}${statusText}</span>
                    <span class="text-[10px] text-slate-400">${escapeHtml(String(item.updated_at || '').replace('T', ' ').slice(0, 10))}</span>
                </div>
                <p class="mt-1 text-xs text-slate-600 dark:text-slate-300 line-clamp-2">${escapeHtml(item.content || '')}</p>
                </button>
            </div>
            <div class="mt-2 flex flex-wrap items-center gap-1 text-[10px]">
                ${pending ? `<button onclick="updateMemoryFactStatus(event,'${encodeURIComponent(item.id || '')}','approve')" class="px-2 py-1 rounded-lg bg-emerald-50 text-emerald-600 dark:bg-emerald-500/10"><i class="fas fa-circle-check mr-1"></i>确认生效</button>` : disabled ? `<button onclick="updateMemoryFactStatus(event,'${encodeURIComponent(item.id || '')}','enable')" class="px-2 py-1 rounded-lg bg-emerald-50 text-emerald-600 dark:bg-emerald-500/10"><i class="fas fa-rotate-left mr-1"></i>恢复</button>` : `<button onclick="updateMemoryFactStatus(event,'${encodeURIComponent(item.id || '')}','disable')" class="px-2 py-1 rounded-lg bg-amber-50 text-amber-600 dark:bg-amber-500/10"><i class="fas fa-ban mr-1"></i>禁用</button>`}
                <button onclick="updateMemoryFactStatus(event,'${encodeURIComponent(item.id || '')}','delete')" class="px-2 py-1 rounded-lg bg-red-50 text-red-500 dark:bg-red-500/10"><i class="fas fa-trash-can mr-1"></i>删除</button>
                <span class="ml-auto text-slate-400">${escapeHtml(item.source || '本地')}</span>
            </div>
        </div>`;
        }).join('') || '<div class="rounded-xl bg-white/60 dark:bg-white/5 p-3 text-xs text-slate-400">暂无匹配事实。使用快速学习、自动化或微信任务后会逐步沉淀。</div>'}</div>
    </div>`;
}

function toggleMemoryFactSelection(event, factIdEncoded) {
    event?.stopPropagation?.();
    const factId = decodeURIComponent(factIdEncoded || '');
    if (!factId) return;
    if (memoryWikiSelectedFacts.has(factId)) memoryWikiSelectedFacts.delete(factId);
    else memoryWikiSelectedFacts.add(factId);
    renderMemoryWikiFactStore();
}

function toggleMemoryFactSelectVisible(select = true) {
    const visible = filteredMemoryFacts().slice(0, 6);
    visible.forEach(item => {
        const id = String(item.id || '');
        if (!id) return;
        if (select) memoryWikiSelectedFacts.add(id);
        else memoryWikiSelectedFacts.delete(id);
    });
    renderMemoryWikiFactStore();
}

async function bulkUpdateMemoryFacts(action) {
    const ids = [...memoryWikiSelectedFacts].filter(Boolean);
    if (!ids.length) return setMemoryWikiStatus('请先选择要处理的事实', 'warning');
    if (action === 'delete' && !confirm(`确定删除选中的 ${ids.length} 条事实吗？删除后不会再参与记忆和路由。`)) return;
    const label = action === 'approve' ? '确认生效' : action === 'disable' ? '禁用' : '删除';
    setMemoryWikiStatus(`正在批量${label} ${ids.length} 条事实…`);
    try {
        const response = await fetch('/api/fact-store', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ action: `bulk_${action}`, ids })
        });
        const data = await response.json();
        if (data.status !== 'success') throw new Error(data.message || '批量操作失败');
        memoryWikiSelectedFacts.clear();
        await refreshMemoryFactStore();
        await loadMemoryWiki(true);
        const errors = Array.isArray(data.errors) ? data.errors.length : 0;
        setMemoryWikiStatus(`已批量${label} ${ids.length - errors} 条${errors ? `，${errors} 条失败` : ''}`, errors ? 'warning' : 'success');
    } catch (error) {
        setMemoryWikiStatus(`批量操作失败：${error.message}`, 'error');
    }
}

async function refreshMemoryFactStore() {
    try {
        const response = await fetch('/api/fact-store?limit=30&include_disabled=1');
        const data = await response.json();
        if (data.status !== 'success') throw new Error(data.message || '读取失败');
        memoryWikiFactStore = { stats: data.stats || {}, items: data.items || [] };
        renderMemoryWikiFactStore();
        setMemoryWikiStatus('事实库已刷新', 'success');
    } catch (error) {
        setMemoryWikiStatus(`事实库刷新失败：${error.message}`, 'error');
    }
}

function insertFactIntoMemoryWiki(factIdEncoded) {
    const factId = decodeURIComponent(factIdEncoded || '');
    const fact = (memoryWikiFactStore?.items || []).find(item => item.id === factId);
    const editor = document.getElementById('memory-wiki-editor');
    if (!fact || !editor) return;
    const line = `\n- ${memoryFactTypeLabel(fact.fact_type)}：${fact.content}${fact.source_url ? ` [来源](${fact.source_url})` : ''}\n`;
    editor.value = `${editor.value || ''}${line}`;
    markMemoryWikiDirty();
    toggleMemoryWikiMode('edit', true);
    closeMemoryFactDetail();
    setMemoryWikiStatus('已把事实插入当前 Wiki 编辑框，确认后点击保存', 'warning');
}

function memoryFactStatusLabel(status = '') {
    return { pending: '待确认', active: '已生效', disabled: '已禁用', deleted: '已删除' }[status] || '已生效';
}

function memoryFactStatusClass(status = '') {
    return status === 'pending'
        ? 'bg-amber-50 text-amber-600 dark:bg-amber-500/10'
        : status === 'disabled'
            ? 'bg-slate-100 text-slate-500 dark:bg-white/10'
            : status === 'deleted'
                ? 'bg-red-50 text-red-500 dark:bg-red-500/10'
                : 'bg-emerald-50 text-emerald-600 dark:bg-emerald-500/10';
}

function memoryFactConfidenceText(value) {
    const n = Number(value);
    if (!Number.isFinite(n)) return '未标注';
    return `${Math.round(Math.max(0, Math.min(1, n)) * 100)}%`;
}

function closeMemoryFactDetail() {
    document.getElementById('memory-fact-detail-modal')?.remove();
}

async function openMemoryFactDetail(factIdEncoded) {
    const factId = decodeURIComponent(factIdEncoded || '');
    if (!factId) return;
    document.getElementById('memory-fact-detail-modal')?.remove();
    const modal = document.createElement('div');
    modal.id = 'memory-fact-detail-modal';
    modal.className = 'fixed inset-0 z-[240] bg-black/50 p-4 flex items-center justify-center';
    modal.onclick = event => { if (event.target === modal) closeMemoryFactDetail(); };
    modal.innerHTML = `<div class="w-full max-w-3xl max-h-[90vh] overflow-y-auto rounded-2xl bg-white dark:bg-[#181818] shadow-2xl">
        <div class="sticky top-0 z-10 bg-white dark:bg-[#181818] border-b border-slate-200 dark:border-white/10 p-5 flex items-center justify-between">
            <div>
                <h2 class="font-bold text-slate-800 dark:text-slate-100"><i class="fas fa-book-atlas mr-2 text-purple-500"></i>记忆详情</h2>
                <p class="text-xs text-slate-400 mt-1">查看来源、标签、置信度和历史事件，再决定是否确认生效。</p>
            </div>
            <button onclick="closeMemoryFactDetail()" class="w-9 h-9 rounded-lg hover:bg-slate-100 dark:hover:bg-white/10"><i class="fas fa-times"></i></button>
        </div>
        <div id="memory-fact-detail-body" class="p-5">
            <div class="py-12 text-center text-slate-400"><i class="fas fa-spinner fa-spin mr-2"></i>正在读取记忆详情…</div>
        </div>
    </div>`;
    document.body.appendChild(modal);
    try {
        const response = await fetch(`/api/fact-store?id=${encodeURIComponent(factId)}`, { cache: 'no-store' });
        const data = await response.json();
        if (data.status !== 'success') throw new Error(data.message || '读取失败');
        renderMemoryFactDetail(data.item || {}, data.events || [], data.source_trace || {});
    } catch (error) {
        const body = document.getElementById('memory-fact-detail-body');
        if (body) body.innerHTML = `<div class="rounded-xl bg-red-50 dark:bg-red-500/10 p-4 text-red-600">记忆详情读取失败：${escapeHtml(error.message)}</div>`;
    }
}

function memoryFactSourceIcon(kind = '') {
    return {
        url: 'fa-arrow-up-right-from-square',
        artifact: 'fa-box-archive',
        automation_run: 'fa-route',
        automation_task: 'fa-wand-magic-sparkles',
        weixin_session: 'fa-comments',
        chat_session: 'fa-message',
        common_function: 'fa-grid-2',
        agent2: 'fa-brain',
        view: 'fa-location-arrow',
    }[kind] || 'fa-link';
}

function renderMemoryFactSourceTrace(trace = {}) {
    const actions = Array.isArray(trace.actions) ? trace.actions : [];
    const actionHtml = actions.length ? actions.map(action => {
        const encoded = encodeURIComponent(JSON.stringify(action));
        return `<button onclick="openMemoryFactSource('${encoded}')" class="px-3 py-2 rounded-xl border border-blue-100 dark:border-blue-500/20 bg-blue-50/70 dark:bg-blue-500/10 text-blue-600 text-xs"><i class="fas ${memoryFactSourceIcon(action.kind)} mr-1"></i>${escapeHtml(action.label || '打开来源')}</button>`;
    }).join('') : '<span class="text-xs text-slate-400">暂无可直接跳转的来源入口。</span>';
    return `<section class="rounded-2xl border border-blue-100 dark:border-blue-500/20 bg-blue-50/50 dark:bg-blue-500/10 p-4">
        <div class="flex items-start justify-between gap-3">
            <div>
                <h4 class="font-semibold text-sm text-blue-700 dark:text-blue-300"><i class="fas fa-location-dot mr-2"></i>记忆来源追踪</h4>
                <p class="mt-1 text-xs text-slate-500">${escapeHtml(trace.summary || trace.source || '本地学习来源')}</p>
            </div>
            ${trace.source_url ? `<a href="${escapeHtml(trace.source_url)}" target="_blank" rel="noopener" class="text-xs text-primary-500 hover:underline shrink-0">原文链接</a>` : ''}
        </div>
        <div class="mt-3 flex flex-wrap gap-2">${actionHtml}</div>
    </section>`;
}

function openMemoryFactSource(actionEncoded) {
    let action = {};
    try { action = JSON.parse(decodeURIComponent(actionEncoded || '')); } catch (_) { action = {}; }
    const kind = action.kind || '';
    closeMemoryFactDetail();
    if (kind === 'url' && action.url) {
        window.open(action.url, '_blank', 'noopener');
        return;
    }
    if (kind === 'artifact' && action.artifact_id) {
        navigateTo('artifacts');
        setTimeout(() => openArtifactDetail?.(action.artifact_id), 120);
        return;
    }
    if (kind === 'automation_run' && action.run_id) {
        navigateTo('intelligence');
        setTimeout(async () => { switchAutomationTab?.('runs'); await loadAutomationRuns?.(); showAutomationRun?.(action.run_id); }, 120);
        return;
    }
    if (kind === 'automation_task') {
        navigateTo('intelligence');
        setTimeout(() => { switchAutomationTab?.('tasks'); loadAutomationTasks?.(); }, 100);
        _wsToast?.('已打开自动化任务列表，可按任务名称或 ID 搜索来源任务');
        return;
    }
    if (kind === 'weixin_session' && action.session_id) {
        navigateTo('weixin-assistant');
        setTimeout(async () => {
            if (action.channel && typeof setWeixinAssistantTab === 'function') setWeixinAssistantTab(action.channel);
            await loadWeixinAssistantConversations?.();
            openWeixinAssistantConversation?.(encodeURIComponent(action.session_id), null, action.channel || 'weixin');
        }, 120);
        return;
    }
    if (kind === 'chat_session') {
        navigateTo('chat');
        _wsToast?.('已回到对话页；该记忆来自历史会话，详情见记忆元数据里的 session_id');
        return;
    }
    if (kind === 'common_function' && action.function_id) {
        navigateTo('common-functions');
        setTimeout(() => openCommonFunction?.(action.function_id), 100);
        return;
    }
    if (kind === 'agent2') {
        navigateTo('intelligence');
        setTimeout(() => { switchAutomationTab?.('agent2'); loadAgent2Dashboard?.(); }, 100);
        return;
    }
    if (kind === 'view' && action.view) {
        navigateTo(action.view);
        return;
    }
    _wsToast?.('暂时无法打开该来源，已保留来源信息供核对');
}

function renderMemoryFactDetail(fact = {}, events = [], sourceTrace = {}) {
    const body = document.getElementById('memory-fact-detail-body');
    if (!body) return;
    const status = memoryFactStatusOf(fact);
    const tags = Array.isArray(fact.tags) ? fact.tags : [];
    const metadata = fact.metadata && typeof fact.metadata === 'object' ? fact.metadata : {};
    const metadataHtml = Object.keys(metadata).length
        ? `<pre class="mt-2 max-h-40 overflow-auto rounded-xl bg-slate-50 dark:bg-white/5 p-3 text-[11px] text-slate-500 whitespace-pre-wrap">${escapeHtml(JSON.stringify(metadata, null, 2))}</pre>`
        : '<p class="mt-2 text-xs text-slate-400">暂无附加元数据。</p>';
    const sourceUrl = fact.source_url ? `<a href="${escapeHtml(fact.source_url)}" target="_blank" rel="noopener" class="text-primary-500 hover:underline break-all">${escapeHtml(fact.source_url)}</a>` : '<span class="text-slate-400">无来源链接</span>';
    body.innerHTML = `<div class="space-y-4">
        ${renderMemoryFactSourceTrace(sourceTrace)}
        <section class="rounded-2xl border border-slate-200 dark:border-white/10 p-4">
            <div class="flex flex-wrap items-start justify-between gap-3">
                <div class="min-w-0">
                    <div class="flex flex-wrap items-center gap-2">
                        <span class="px-2 py-1 rounded-full text-[11px] ${memoryFactStatusClass(status)}">${memoryFactStatusLabel(status)}</span>
                        <span class="px-2 py-1 rounded-full bg-purple-50 text-purple-600 dark:bg-purple-500/10 text-[11px]">${escapeHtml(memoryFactTypeLabel(fact.fact_type))}</span>
                        <span class="px-2 py-1 rounded-full bg-blue-50 text-blue-600 dark:bg-blue-500/10 text-[11px]">置信度 ${memoryFactConfidenceText(fact.confidence)}</span>
                        <span class="px-2 py-1 rounded-full bg-slate-100 text-slate-500 dark:bg-white/10 text-[11px]">出现 ${Number(fact.seen_count || 1)} 次</span>
                    </div>
                    <h3 class="mt-3 text-lg font-bold text-slate-800 dark:text-slate-100">${escapeHtml(fact.title || '未命名记忆')}</h3>
                </div>
                <span class="text-xs text-slate-400">${escapeHtml(String(fact.updated_at || '').replace('T', ' ').slice(0, 19))}</span>
            </div>
            <p class="mt-4 rounded-xl bg-slate-50 dark:bg-white/5 p-4 text-sm leading-7 text-slate-700 dark:text-slate-200 whitespace-pre-wrap">${escapeHtml(fact.content || '')}</p>
            <div class="mt-4 grid sm:grid-cols-2 gap-3 text-xs">
                <div class="rounded-xl bg-slate-50 dark:bg-white/5 p-3"><b class="block text-slate-500 mb-1">来源</b>${escapeHtml(fact.source || '本地学习')}</div>
                <div class="rounded-xl bg-slate-50 dark:bg-white/5 p-3"><b class="block text-slate-500 mb-1">范围</b>${escapeHtml(fact.scope || 'private')}</div>
                <div class="sm:col-span-2 rounded-xl bg-slate-50 dark:bg-white/5 p-3"><b class="block text-slate-500 mb-1">来源链接</b>${sourceUrl}</div>
            </div>
            <div class="mt-4">
                <b class="text-xs text-slate-500">标签</b>
                <div class="mt-2 flex flex-wrap gap-1">${tags.length ? tags.map(tag => `<span class="px-2 py-1 rounded-full bg-purple-50 text-purple-600 dark:bg-purple-500/10 text-[11px]">${escapeHtml(tag)}</span>`).join('') : '<span class="text-xs text-slate-400">暂无标签</span>'}</div>
            </div>
        </section>
        <section class="rounded-2xl border border-slate-200 dark:border-white/10 p-4">
            <h4 class="font-semibold text-sm">附加信息</h4>
            ${metadataHtml}
        </section>
        <section class="rounded-2xl border border-slate-200 dark:border-white/10 p-4">
            <h4 class="font-semibold text-sm">历史事件</h4>
            <div class="mt-3 space-y-2">${events.length ? events.map(event => `<div class="rounded-xl bg-slate-50 dark:bg-white/5 p-3 text-xs">
                <div class="flex justify-between gap-3"><b>${escapeHtml(event.action || 'event')}</b><span class="text-slate-400">${escapeHtml(String(event.created_at || '').replace('T', ' ').slice(0, 19))}</span></div>
                <p class="mt-1 text-slate-500">${escapeHtml(event.summary || '')}</p>
            </div>`).join('') : '<div class="text-xs text-slate-400">暂无历史事件。</div>'}</div>
        </section>
        <footer class="sticky bottom-0 -mx-5 -mb-5 bg-white/95 dark:bg-[#181818]/95 border-t border-slate-200 dark:border-white/10 p-4 flex flex-wrap items-center justify-between gap-3">
            <button onclick="insertFactIntoMemoryWiki('${encodeURIComponent(fact.id || '')}')" class="px-3 py-2 rounded-xl border border-purple-200 dark:border-purple-500/20 text-purple-600 text-sm"><i class="fas fa-plus mr-1"></i>插入当前 Wiki</button>
            <div class="flex flex-wrap gap-2">
                ${status === 'pending' ? `<button onclick="updateMemoryFactStatus(event,'${encodeURIComponent(fact.id || '')}','approve');closeMemoryFactDetail()" class="px-4 py-2 rounded-xl bg-emerald-600 text-white text-sm"><i class="fas fa-circle-check mr-1"></i>确认生效</button>` : ''}
                ${status === 'disabled' ? `<button onclick="updateMemoryFactStatus(event,'${encodeURIComponent(fact.id || '')}','enable');closeMemoryFactDetail()" class="px-4 py-2 rounded-xl bg-emerald-600 text-white text-sm"><i class="fas fa-rotate-left mr-1"></i>恢复</button>` : ''}
                ${status === 'active' ? `<button onclick="updateMemoryFactStatus(event,'${encodeURIComponent(fact.id || '')}','disable');closeMemoryFactDetail()" class="px-4 py-2 rounded-xl bg-amber-500 text-white text-sm"><i class="fas fa-ban mr-1"></i>禁用</button>` : ''}
                <button onclick="updateMemoryFactStatus(event,'${encodeURIComponent(fact.id || '')}','delete');closeMemoryFactDetail()" class="px-4 py-2 rounded-xl bg-red-500 text-white text-sm"><i class="fas fa-trash-can mr-1"></i>删除</button>
            </div>
        </footer>
    </div>`;
}

function renderMemoryWikiCurrent() {
    const item = memoryWikiSections.find(x => x.id === currentMemoryWikiSection) || memoryWikiSections[0];
    if (!item) return;
    const title = document.getElementById('memory-wiki-current-title');
    const meta = document.getElementById('memory-wiki-current-meta');
    const effective = document.getElementById('memory-wiki-effective');
    const editor = document.getElementById('memory-wiki-editor');
    const preview = document.getElementById('memory-wiki-preview');
    if (title) title.textContent = item.title;
    if (meta) meta.textContent = `${item.edited ? '已人工编辑' : '系统生成'} · 来源：${item.source || '系统'}${item.updated_at ? ` · 更新：${String(item.updated_at).replace('T', ' ').slice(0, 19)}` : ''}`;
    if (effective) effective.innerHTML = `<i class="fas fa-circle-check mr-1"></i>${escapeHtml(item.effective_summary || '当前页面已纳入 Memory Wiki。')}`;
    if (editor) editor.value = item.content || '';
    if (preview) {
        preview.innerHTML = renderMarkdown(item.content || '');
        applyHighlighting(preview);
    }
    renderMemoryWikiHistory(item);
    toggleMemoryWikiMode(memoryWikiMode, true);
    memoryWikiDirty = false;
}

function renderMemoryWikiHistory(item) {
    const host = document.getElementById('memory-wiki-history');
    if (!host) return;
    const history = item?.history || [];
    if (!history.length) {
        host.innerHTML = '<div class="rounded-xl border border-dashed border-slate-200 dark:border-white/10 p-4 text-sm text-slate-400">暂无历史版本。保存或重新生成后会自动留下版本记录。</div>';
        return;
    }
    host.innerHTML = history.slice(0, 8).map(rev => `<div class="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-slate-100 dark:border-white/5 p-3">
        <div class="min-w-0">
            <div class="text-xs text-slate-400">${escapeHtml(rev.source || '历史版本')} · ${escapeHtml(String(rev.created_at || '').replace('T', ' ').slice(0, 19))}</div>
            <p class="mt-1 text-sm text-slate-600 dark:text-slate-300 truncate">${escapeHtml(rev.summary || '无摘要')}</p>
        </div>
        <button onclick="restoreMemoryWikiRevision('${escapeHtml(item.id)}','${escapeHtml(rev.id || '')}')" class="px-3 py-1.5 rounded-lg border border-purple-200 dark:border-purple-500/20 text-xs text-purple-600">恢复到编辑框</button>
    </div>`).join('');
}

function restoreMemoryWikiRevision(sectionId, revisionId) {
    const item = memoryWikiSections.find(x => x.id === sectionId);
    const rev = (item?.history || []).find(x => x.id === revisionId);
    const editor = document.getElementById('memory-wiki-editor');
    if (!item || !rev || !editor) return setMemoryWikiStatus('没有找到该历史版本', 'warning');
    if (memoryWikiDirty && !confirm('当前编辑内容尚未保存，确定用历史版本覆盖编辑框吗？')) return;
    editor.value = rev.content || '';
    item.content = editor.value;
    memoryWikiDirty = true;
    toggleMemoryWikiMode('edit', true);
    setMemoryWikiStatus('历史版本已恢复到编辑框，请确认后点击保存', 'warning');
}

function switchMemoryWikiSection(sectionId) {
    if (memoryWikiDirty && !confirm('当前页面尚未保存，确定切换吗？')) return;
    currentMemoryWikiSection = sectionId;
    renderMemoryWikiSections();
    renderMemoryWikiCurrent();
}

function markMemoryWikiDirty() {
    memoryWikiDirty = true;
    const item = memoryWikiSections.find(x => x.id === currentMemoryWikiSection);
    if (item) item.content = document.getElementById('memory-wiki-editor')?.value || '';
    setMemoryWikiStatus('有未保存修改', 'warning');
}

function toggleMemoryWikiMode(mode, silent = false) {
    memoryWikiMode = mode || 'edit';
    const editor = document.getElementById('memory-wiki-editor');
    const preview = document.getElementById('memory-wiki-preview');
    const editTab = document.getElementById('memory-wiki-edit-tab');
    const previewTab = document.getElementById('memory-wiki-preview-tab');
    if (preview && editor && memoryWikiMode === 'preview') {
        const content = editor.value || '';
        preview.innerHTML = renderMarkdown(content);
        applyHighlighting(preview);
    }
    editor?.classList.toggle('hidden', memoryWikiMode !== 'edit');
    preview?.classList.toggle('hidden', memoryWikiMode !== 'preview');
    editTab?.classList.toggle('bg-purple-600', memoryWikiMode === 'edit');
    editTab?.classList.toggle('text-white', memoryWikiMode === 'edit');
    previewTab?.classList.toggle('bg-purple-600', memoryWikiMode === 'preview');
    previewTab?.classList.toggle('text-white', memoryWikiMode === 'preview');
    if (!silent && memoryWikiMode === 'preview') setMemoryWikiStatus('已切换到预览模式');
}

async function saveMemoryWikiSection() {
    const editor = document.getElementById('memory-wiki-editor');
    const item = memoryWikiSections.find(x => x.id === currentMemoryWikiSection);
    if (!editor || !item) return;
    setMemoryWikiStatus('正在保存…');
    try {
        const response = await fetch('/api/memory-wiki', {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ section_id: item.id, content: editor.value })
        });
        const data = await response.json();
        if (data.status !== 'success') throw new Error(data.message || '保存失败');
        memoryWikiSections = data.sections || [];
        memoryWikiFactStore = data.fact_store || memoryWikiFactStore;
        memoryWikiDirty = false;
        renderMemoryWikiSections();
        renderMemoryWikiCurrent();
        setMemoryWikiStatus('保存成功', 'success');
    } catch (error) {
        setMemoryWikiStatus(`保存失败：${error.message}`, 'error');
    }
}

async function regenerateMemoryWikiSection() {
    const item = memoryWikiSections.find(x => x.id === currentMemoryWikiSection);
    if (!item) return;
    if (!confirm(`确定重新生成「${item.title}」吗？当前 Wiki 编辑内容会恢复为系统汇总。`)) return;
    setMemoryWikiStatus('正在重新生成…');
    try {
        const response = await fetch('/api/memory-wiki', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ action: 'regenerate', section_id: item.id })
        });
        const data = await response.json();
        if (data.status !== 'success') throw new Error(data.message || '重新生成失败');
        memoryWikiSections = data.sections || [];
        memoryWikiFactStore = data.fact_store || memoryWikiFactStore;
        memoryWikiDirty = false;
        renderMemoryWikiSections();
        renderMemoryWikiCurrent();
        setMemoryWikiStatus('已从系统数据重新生成', 'success');
    } catch (error) {
        setMemoryWikiStatus(`重新生成失败：${error.message}`, 'error');
    }
}

let agentRosterItems = [];
let agentRosterStatusFilter = 'all';
let agentRosterCategoryFilter = 'all';

function agentRosterTone(color) {
    const tones = {
        blue: ['bg-blue-50 dark:bg-blue-500/10', 'text-blue-600'],
        cyan: ['bg-cyan-50 dark:bg-cyan-500/10', 'text-cyan-600'],
        teal: ['bg-teal-50 dark:bg-teal-500/10', 'text-teal-600'],
        sky: ['bg-sky-50 dark:bg-sky-500/10', 'text-sky-600'],
        amber: ['bg-amber-50 dark:bg-amber-500/10', 'text-amber-600'],
        orange: ['bg-orange-50 dark:bg-orange-500/10', 'text-orange-600'],
        indigo: ['bg-indigo-50 dark:bg-indigo-500/10', 'text-indigo-600'],
        fuchsia: ['bg-fuchsia-50 dark:bg-fuchsia-500/10', 'text-fuchsia-600'],
        emerald: ['bg-emerald-50 dark:bg-emerald-500/10', 'text-emerald-600'],
        violet: ['bg-violet-50 dark:bg-violet-500/10', 'text-violet-600'],
        slate: ['bg-slate-100 dark:bg-white/10', 'text-slate-600 dark:text-slate-300'],
    };
    return tones[color] || tones.slate;
}

function agentRosterHealthTone(status) {
    const tones = {
        ready: 'bg-emerald-50 dark:bg-emerald-500/10 text-emerald-600',
        attention: 'bg-amber-50 dark:bg-amber-500/10 text-amber-600',
        missing_config: 'bg-red-50 dark:bg-red-500/10 text-red-600',
        disabled: 'bg-slate-100 dark:bg-white/10 text-slate-400',
    };
    return tones[status] || tones.attention;
}

function setAgentRosterStatus(text, type = 'muted') {
    const el = document.getElementById('agent-roster-status');
    if (!el) return;
    const color = type === 'success' ? 'text-emerald-600' : type === 'error' ? 'text-red-500' : type === 'warning' ? 'text-amber-600' : 'text-slate-400';
    el.className = `text-xs min-h-5 ${color}`;
    el.textContent = text || '';
}

async function loadAgentRoster(force = false) {
    if (agentRosterItems.length && !force) {
        renderAgentRoster();
        return;
    }
    setAgentRosterStatus('正在读取 Agent 名册…');
    try {
        const response = await fetch('/api/agent-roster');
        const data = await response.json();
        if (data.status !== 'success') throw new Error(data.message || '读取失败');
        agentRosterItems = data.agents || [];
        renderAgentRoster();
        const summary = data.health_summary || {};
        setAgentRosterStatus(`已读取 ${agentRosterItems.length} 个 Agent · 可用 ${summary.ready || 0} · 需关注 ${(summary.attention || 0) + (summary.missing_config || 0)}`, 'success');
    } catch (error) {
        setAgentRosterStatus(`读取失败：${error.message}`, 'error');
    }
}

function renderAgentRosterSummary(items = agentRosterItems) {
    const host = document.getElementById('agent-roster-summary');
    if (!host) return;
    const enabled = items.filter(x => x.status === 'enabled').length;
    const disabled = items.length - enabled;
    const ready = items.filter(x => (x.health || {}).status === 'ready').length;
    const attention = items.filter(x => ['attention', 'missing_config'].includes((x.health || {}).status)).length;
    const cards = [
        ['全部 Agent', items.length, `${enabled} 个已启用，${disabled} 个已停用`, 'fa-robot', 'sky'],
        ['当前可用', ready, '配置和权限基本满足，可参与路由', 'fa-circle-check', 'emerald'],
        ['需要关注', attention, '存在缺配置、缺权限或近期失败', 'fa-triangle-exclamation', 'amber'],
        ['已停用', disabled, '不会被主动推荐或自动路由', 'fa-circle-pause', 'slate'],
    ];
    host.innerHTML = cards.map(([title, value, desc, icon, color]) => {
        const tone = agentRosterTone(color);
        return `<div class="rounded-2xl border border-slate-200 dark:border-white/10 bg-white dark:bg-[#1A1A1A] p-4"><div class="flex items-center gap-3"><div class="w-10 h-10 rounded-xl ${tone[0]} ${tone[1]} flex items-center justify-center"><i class="fas ${icon}"></i></div><div><div class="text-2xl font-bold">${value}</div><p class="text-xs text-slate-400">${escapeHtml(title)}</p></div></div><p class="text-xs text-slate-500 mt-3">${escapeHtml(desc)}</p></div>`;
    }).join('');
}

function renderAgentRosterCategories(items = agentRosterItems) {
    const host = document.getElementById('agent-roster-category-filter');
    if (!host) return;
    const counts = {};
    items.forEach(x => counts[x.category || '未分类'] = (counts[x.category || '未分类'] || 0) + 1);
    const categories = [['all', `全部 ${items.length}`], ...Object.entries(counts).map(([name, count]) => [name, `${name} ${count}`])];
    host.innerHTML = categories.map(([key, label]) => `<button onclick="setAgentRosterCategoryFilter('${encodeURIComponent(key)}')" class="agent-roster-category-tab px-3 py-1.5 rounded-full text-xs ${agentRosterCategoryFilter === key ? 'bg-sky-600 text-white' : 'bg-slate-100 dark:bg-white/5 text-slate-500'}">${escapeHtml(label)}</button>`).join('');
}

function renderAgentRoster() {
    renderAgentRosterSummary();
    renderAgentRosterCategories();
    document.querySelectorAll('.agent-roster-status-tab').forEach(btn => {
        const active = btn.dataset.agentStatus === agentRosterStatusFilter;
        btn.classList.toggle('bg-white', active);
        btn.classList.toggle('dark:bg-[#292929]', active);
        btn.classList.toggle('shadow-sm', active);
        btn.classList.toggle('text-slate-500', !active);
    });
    const query = (document.getElementById('agent-roster-search')?.value || '').trim().toLowerCase();
    const filtered = agentRosterItems.filter(item => {
        const healthStatus = (item.health || {}).status || (item.status === 'enabled' ? 'ready' : 'disabled');
        const statusOk = agentRosterStatusFilter === 'all' || healthStatus === agentRosterStatusFilter || (agentRosterStatusFilter === 'enabled' && item.status === 'enabled');
        const categoryOk = agentRosterCategoryFilter === 'all' || (item.category || '未分类') === agentRosterCategoryFilter;
        const health = item.health || {};
        const haystack = [item.name, item.category, item.description, item.entry, health.label, health.summary, ...(item.scenarios || []), ...(item.permissions || []), ...(item.outputs || []), ...((health.issues || []).map(x => x.text || ''))].join(' ').toLowerCase();
        return statusOk && categoryOk && (!query || haystack.includes(query));
    });
    const host = document.getElementById('agent-roster-list');
    if (!host) return;
    host.innerHTML = filtered.length ? filtered.map(renderAgentRosterCard).join('') : '<div class="lg:col-span-3 rounded-2xl border border-dashed border-slate-200 dark:border-white/10 py-16 text-center text-slate-400">没有找到匹配的 Agent</div>';
}

function renderAgentRosterCard(item) {
    const tone = agentRosterTone(item.color);
    const enabled = item.status === 'enabled';
    const health = item.health || {};
    const stats = health.stats || {};
    const healthStatus = health.status || (enabled ? 'ready' : 'disabled');
    const successRate = stats.success_rate === null || stats.success_rate === undefined ? '暂无样本' : `${Math.round(Number(stats.success_rate || 0) * 100)}%`;
    const chip = text => `<span class="px-2 py-1 rounded-full bg-slate-100 dark:bg-white/5 text-[11px] text-slate-500">${escapeHtml(text)}</span>`;
    const issueHtml = (health.issues || []).slice(0, 2).map(issue => `<li class="${issue.level === 'error' ? 'text-red-500' : 'text-amber-600'}">${escapeHtml(issue.text || '')}</li>`).join('');
    const actionHtml = (health.actions || []).slice(0, 2).map(action => `<li>${escapeHtml(action)}</li>`).join('');
    return `<article class="rounded-2xl border border-slate-200 dark:border-white/10 bg-white dark:bg-[#1A1A1A] p-5 flex flex-col gap-4">
        <div class="flex items-start justify-between gap-3"><div class="flex items-start gap-3 min-w-0"><div class="w-11 h-11 rounded-xl ${tone[0]} ${tone[1]} flex items-center justify-center shrink-0"><i class="fas ${escapeHtml(item.icon || 'fa-robot')}"></i></div><div class="min-w-0"><h3 class="font-bold truncate">${escapeHtml(item.name)}</h3><p class="text-xs text-slate-400 mt-1">${escapeHtml(item.category || '未分类')} · ${item.builtin ? '内置' : '自定义'}</p></div></div><span class="px-2 py-1 rounded-full text-[10px] ${enabled ? 'bg-emerald-50 dark:bg-emerald-500/10 text-emerald-600' : 'bg-slate-100 dark:bg-white/10 text-slate-400'}">${enabled ? '已启用' : '已停用'}</span></div>
        <div class="rounded-xl border border-slate-100 dark:border-white/5 bg-slate-50/70 dark:bg-white/[0.03] p-3">
            <div class="flex flex-wrap items-center justify-between gap-2"><span class="px-2.5 py-1 rounded-full text-[11px] ${agentRosterHealthTone(healthStatus)}">${escapeHtml(health.label || '待检查')}</span><span class="text-[11px] text-slate-400">成功率：${escapeHtml(successRate)}${stats.total ? ` · ${stats.total} 次样本` : ''}</span></div>
            <p class="mt-2 text-xs leading-5 text-slate-500">${escapeHtml(health.summary || '暂无健康状态。')}</p>
            ${stats.last_error ? `<p class="mt-1 text-[11px] text-red-500">最近失败：${escapeHtml(stats.last_error)}</p>` : ''}
        </div>
        <p class="text-sm leading-6 text-slate-600 dark:text-slate-300 line-clamp-3">${escapeHtml(item.description || '暂无描述')}</p>
        <div><p class="text-xs font-semibold text-slate-400 mb-2">使用场景</p><div class="flex flex-wrap gap-1.5">${(item.scenarios || []).slice(0, 4).map(chip).join('') || chip('待补充')}</div></div>
        <div class="grid sm:grid-cols-2 gap-3 text-xs"><div><p class="font-semibold text-slate-400 mb-1">权限</p><p class="text-slate-500 leading-5">${escapeHtml((item.permissions || []).join('、') || '未设置')}</p></div><div><p class="font-semibold text-slate-400 mb-1">输出</p><p class="text-slate-500 leading-5">${escapeHtml((item.outputs || []).join('、') || '未设置')}</p></div></div>
        ${issueHtml || actionHtml ? `<div class="grid sm:grid-cols-2 gap-3 text-xs rounded-xl bg-slate-50 dark:bg-white/[0.03] p-3">${issueHtml ? `<div><p class="font-semibold text-slate-400 mb-1">问题</p><ul class="space-y-1">${issueHtml}</ul></div>` : ''}${actionHtml ? `<div><p class="font-semibold text-slate-400 mb-1">建议动作</p><ul class="space-y-1 text-slate-500">${actionHtml}</ul></div>` : ''}</div>` : ''}
        <div class="mt-auto flex flex-wrap items-center justify-between gap-2 pt-2 border-t border-slate-100 dark:border-white/5"><button onclick="openAgentRosterEntry('${encodeURIComponent(item.entry || '')}')" class="px-3 py-1.5 rounded-lg ${tone[0]} ${tone[1]} text-xs"><i class="fas fa-arrow-up-right-from-square mr-1"></i>打开</button><div class="flex gap-1.5"><button onclick="toggleAgentRoster('${escapeHtml(item.id)}',${!enabled})" class="px-3 py-1.5 rounded-lg border text-xs">${enabled ? '停用' : '启用'}</button><button onclick="openAgentRosterEditor('${escapeHtml(item.id)}')" class="px-3 py-1.5 rounded-lg border text-xs text-blue-600">编辑</button><button onclick="deleteAgentRoster('${escapeHtml(item.id)}')" class="px-3 py-1.5 rounded-lg text-xs text-red-500">删除</button></div></div>
    </article>`;
}

function setAgentRosterStatusFilter(status) {
    agentRosterStatusFilter = status || 'all';
    renderAgentRoster();
}

function setAgentRosterCategoryFilter(encoded) {
    agentRosterCategoryFilter = decodeURIComponent(encoded || 'all');
    renderAgentRoster();
}

function openAgentRosterEntry(encodedEntry) {
    const entry = decodeURIComponent(encodedEntry || '');
    if (!entry) return setAgentRosterStatus('该 Agent 暂未配置入口', 'warning');
    if (entry.startsWith('common-function:')) {
        navigateTo('common-functions');
        setTimeout(() => openCommonFunction(entry.split(':')[1]), 80);
        return;
    }
    if (entry.startsWith('common-preset:')) {
        navigateTo('common-functions');
        setTimeout(() => openCommonTrackingPreset(entry.split(':')[1]), 80);
        return;
    }
    if (entry === 'settings:channels') {
        openSettingsCenter?.();
        setTimeout(() => showSettingsView?.('channels', '通道与连接'), 80);
        return;
    }
    navigateTo(entry);
}

function openAgentRosterEditor(id = '') {
    const item = agentRosterItems.find(x => x.id === id) || {};
    document.getElementById('agent-roster-edit-id').value = item.id || '';
    document.getElementById('agent-roster-edit-name').value = item.name || '';
    document.getElementById('agent-roster-edit-category').value = item.category || '';
    document.getElementById('agent-roster-edit-icon').value = item.icon || 'fa-robot';
    document.getElementById('agent-roster-edit-entry').value = item.entry || '';
    document.getElementById('agent-roster-edit-description').value = item.description || '';
    document.getElementById('agent-roster-edit-scenarios').value = (item.scenarios || []).join('\n');
    document.getElementById('agent-roster-edit-permissions').value = (item.permissions || []).join('\n');
    document.getElementById('agent-roster-edit-outputs').value = (item.outputs || []).join('\n');
    document.getElementById('agent-roster-editor-title').textContent = item.id ? '编辑 Agent' : '新增 Agent';
    document.getElementById('agent-roster-editor-status').textContent = '';
    const modal = document.getElementById('agent-roster-editor-modal');
    modal.classList.remove('hidden');
    modal.classList.add('flex');
}

function closeAgentRosterEditor() {
    const modal = document.getElementById('agent-roster-editor-modal');
    modal?.classList.add('hidden');
    modal?.classList.remove('flex');
}

function agentRosterEditorPayload() {
    const lines = id => (document.getElementById(id)?.value || '').split(/\n|,|，/).map(x => x.trim()).filter(Boolean);
    const id = document.getElementById('agent-roster-edit-id')?.value || '';
    const existing = agentRosterItems.find(x => x.id === id) || {};
    return {
        id,
        name: document.getElementById('agent-roster-edit-name')?.value || '',
        category: document.getElementById('agent-roster-edit-category')?.value || '',
        icon: document.getElementById('agent-roster-edit-icon')?.value || 'fa-robot',
        entry: document.getElementById('agent-roster-edit-entry')?.value || '',
        description: document.getElementById('agent-roster-edit-description')?.value || '',
        scenarios: lines('agent-roster-edit-scenarios'),
        permissions: lines('agent-roster-edit-permissions'),
        outputs: lines('agent-roster-edit-outputs'),
        status: existing.status || 'enabled',
    };
}

async function saveAgentRosterEditor() {
    const status = document.getElementById('agent-roster-editor-status');
    const agent = agentRosterEditorPayload();
    if (!agent.name.trim()) {
        if (status) status.textContent = '请填写 Agent 名称';
        return;
    }
    if (status) status.textContent = '正在保存…';
    try {
        const response = await fetch('/api/agent-roster', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ action: 'save', agent }) });
        const data = await response.json();
        if (data.status !== 'success') throw new Error(data.message || '保存失败');
        agentRosterItems = data.agents || [];
        closeAgentRosterEditor();
        renderAgentRoster();
        setAgentRosterStatus('保存成功', 'success');
    } catch (error) {
        if (status) status.textContent = `保存失败：${error.message}`;
    }
}

async function toggleAgentRoster(id, enabled) {
    try {
        const response = await fetch('/api/agent-roster', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ action: 'toggle', id, enabled }) });
        const data = await response.json();
        if (data.status !== 'success') throw new Error(data.message || '操作失败');
        agentRosterItems = data.agents || [];
        renderAgentRoster();
        setAgentRosterStatus(enabled ? '已启用 Agent' : '已停用 Agent', 'success');
    } catch (error) {
        setAgentRosterStatus(`操作失败：${error.message}`, 'error');
    }
}

async function deleteAgentRoster(id) {
    if (!confirm('确定从名册中删除这个 Agent 吗？不会删除底层功能，可通过恢复默认找回内置 Agent。')) return;
    try {
        const response = await fetch('/api/agent-roster', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ action: 'delete', id }) });
        const data = await response.json();
        if (data.status !== 'success') throw new Error(data.message || '删除失败');
        agentRosterItems = data.agents || [];
        renderAgentRoster();
        setAgentRosterStatus('已从名册删除', 'success');
    } catch (error) {
        setAgentRosterStatus(`删除失败：${error.message}`, 'error');
    }
}

async function restoreDefaultAgentRoster() {
    if (!confirm('确定恢复默认 Agent 名册吗？当前自定义 Agent 会被重置。')) return;
    try {
        const response = await fetch('/api/agent-roster', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ action: 'restore_defaults' }) });
        const data = await response.json();
        if (data.status !== 'success') throw new Error(data.message || '恢复失败');
        agentRosterItems = data.agents || [];
        agentRosterStatusFilter = 'all';
        agentRosterCategoryFilter = 'all';
        renderAgentRoster();
        setAgentRosterStatus('已恢复默认名册', 'success');
    } catch (error) {
        setAgentRosterStatus(`恢复失败：${error.message}`, 'error');
    }
}

let remoteBridgeState = null;
let remoteBridgeSimulator = (() => {
    try { return JSON.parse(localStorage.getItem('cow_remote_bridge_simulator') || '{}') || {}; } catch (_) { return {}; }
})();

function setRemoteBridgeStatus(text, type = 'muted') {
    const el = document.getElementById('remote-bridge-status');
    if (!el) return;
    const color = type === 'success' ? 'text-emerald-600' : type === 'error' ? 'text-red-500' : type === 'warning' ? 'text-amber-600' : 'text-slate-400';
    el.className = `text-xs min-h-5 ${color}`;
    el.textContent = text || '';
}

async function remoteBridgeApi(payload = null) {
    const options = payload ? { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) } : {};
    const response = await fetch('/api/remote-bridge', options);
    const data = await response.json();
    if (data.status !== 'success') throw new Error(data.message || '请求失败');
    return data;
}

async function loadRemoteBridge(force = false) {
    if (remoteBridgeState && !force) {
        renderRemoteBridge();
        return;
    }
    setRemoteBridgeStatus('正在读取 Bridge 状态…');
    try {
        remoteBridgeState = await remoteBridgeApi();
        renderRemoteBridge();
        setRemoteBridgeStatus('Bridge 状态已更新', 'success');
    } catch (error) {
        setRemoteBridgeStatus(`读取失败：${error.message}`, 'error');
    }
}

function renderRemoteBridge() {
    const data = remoteBridgeState || {};
    const settings = data.settings || {};
    const set = (id, value, prop = 'value') => { const el = document.getElementById(id); if (el) el[prop] = value; };
    set('remote-bridge-device-name', data.device_name || '');
    set('remote-bridge-cloud-url', data.cloud_url || '');
    set('remote-bridge-enabled', !!data.enabled, 'checked');
    set('remote-bridge-allow-lan', !!data.allow_lan, 'checked');
    set('remote-bridge-require-approval', settings.require_approval !== false, 'checked');
    set('remote-bridge-allow-read', settings.allow_read !== false, 'checked');
    set('remote-bridge-allow-write', !!settings.allow_write, 'checked');
    set('remote-bridge-allow-execute', !!settings.allow_execute, 'checked');
    set('remote-bridge-ttl', settings.max_command_ttl_minutes || 30);
    renderRemoteBridgeSummary(data);
    renderRemoteBridgeHealth(data.health || {});
    renderRemoteBridgePairing(data.pairing || {});
    renderRemoteBridgeDevices(data.paired_devices || []);
    renderRemoteBridgeCapabilities(data.capabilities || []);
    renderRemoteBridgeQueue(data.command_queue || []);
    renderRemoteBridgeAudit(data.audit || []);
    renderRemoteBridgeSimulator();
}

function remoteBridgeTone(level) {
    if (level === 'success') return 'bg-emerald-50 dark:bg-emerald-500/10 text-emerald-600 border-emerald-100 dark:border-emerald-500/20';
    if (level === 'error') return 'bg-red-50 dark:bg-red-500/10 text-red-600 border-red-100 dark:border-red-500/20';
    return 'bg-amber-50 dark:bg-amber-500/10 text-amber-600 border-amber-100 dark:border-amber-500/20';
}

function renderRemoteBridgeSummary(data) {
    const host = document.getElementById('remote-bridge-summary');
    if (!host) return;
    const pairing = data.pairing || {};
    const items = [
        ['Bridge 状态', data.enabled ? '已启用' : '未启用', data.enabled ? '等待后续云端接入' : '默认安全关闭', 'fa-power-off', data.enabled ? 'emerald' : 'slate'],
        ['本机 ID', data.device_id || '--', data.device_name || '本机', 'fa-computer', 'sky'],
        ['配对状态', pairing.active ? '配对码有效' : '未配对', pairing.expires_at ? `到期 ${String(pairing.expires_at).replace('T', ' ').slice(0, 19)}` : '需要手动生成', 'fa-qrcode', pairing.active ? 'emerald' : 'amber'],
        ['待处理指令', (data.command_queue || []).length, '远程指令先进入队列', 'fa-list-check', 'violet'],
    ];
    host.innerHTML = items.map(([title, value, desc, icon, color]) => {
        const tone = agentRosterTone(color);
        return `<div class="rounded-2xl border border-slate-200 dark:border-white/10 bg-white dark:bg-[#1A1A1A] p-4"><div class="flex items-center gap-3"><div class="w-10 h-10 rounded-xl ${tone[0]} ${tone[1]} flex items-center justify-center"><i class="fas ${icon}"></i></div><div class="min-w-0"><div class="text-lg font-bold truncate">${escapeHtml(String(value))}</div><p class="text-xs text-slate-400">${escapeHtml(title)}</p></div></div><p class="text-xs text-slate-500 mt-3">${escapeHtml(desc)}</p></div>`;
    }).join('');
}

function renderRemoteBridgeHealth(health) {
    const host = document.getElementById('remote-bridge-health');
    if (!host) return;
    const checks = health.checks || [];
    const counts = health.counts || {};
    const protocol = health.protocol || {};
    const badgeClass = remoteBridgeTone(health.overall === 'success' ? 'success' : health.overall === 'error' ? 'error' : 'warning');
    host.innerHTML = `<section class="rounded-2xl border border-slate-200 dark:border-white/10 bg-white dark:bg-[#1A1A1A] p-5">
        <div class="flex flex-wrap items-start justify-between gap-3">
            <div><h3 class="font-bold"><i class="fas fa-stethoscope text-emerald-500 mr-2"></i>Bridge 健康检测</h3><p class="text-xs text-slate-400 mt-1">检查启用状态、设备、权限、队列、失败和回传链路。</p></div>
            <span class="px-3 py-1 rounded-full border text-xs ${badgeClass}">${escapeHtml(health.label || '待检查')}</span>
        </div>
        <div class="grid md:grid-cols-2 gap-3 mt-4">
            ${checks.length ? checks.map(item => `<div class="rounded-xl border p-3 ${remoteBridgeTone(item.level)}"><b class="text-sm">${escapeHtml(item.title || '')}</b><p class="mt-1 text-xs leading-5 opacity-90">${escapeHtml(item.summary || '')}</p>${item.action ? `<p class="mt-1 text-[11px] opacity-80">建议：${escapeHtml(item.action)}</p>` : ''}</div>`).join('') : '<div class="text-sm text-slate-400">暂无健康检测结果。</div>'}
        </div>
        <details class="mt-4 rounded-xl border border-slate-100 dark:border-white/5 bg-slate-50/70 dark:bg-white/[0.03] p-3">
            <summary class="cursor-pointer text-sm font-semibold text-slate-600 dark:text-slate-300"><i class="fas fa-code-branch text-emerald-500 mr-2"></i>真实设备接入协议</summary>
            <div class="mt-3 grid gap-2 text-[11px] leading-5 text-slate-500">
                <div><b>接口：</b><code>${escapeHtml(protocol.endpoint || '/api/remote-bridge')}</code></div>
                <div><b>绑定：</b>${escapeHtml(protocol.pair || '')}</div>
                <div><b>心跳：</b>${escapeHtml(protocol.heartbeat || '')}</div>
                <div><b>提交指令：</b>${escapeHtml(protocol.command || '')}</div>
                <div><b>拉取结果：</b>${escapeHtml(protocol.fetch_results || '')}</div>
                <div><b>结果确认：</b>${escapeHtml(protocol.delivery_ack || '')}</div>
                <p class="text-amber-600">设备 token 只在绑定成功时返回一次，系统只保存指纹；后续云端网关或手机端需要妥善保存 token。</p>
            </div>
        </details>
    </section>
    <aside class="rounded-2xl border border-slate-200 dark:border-white/10 bg-white dark:bg-[#1A1A1A] p-5">
        <h3 class="font-bold"><i class="fas fa-paper-plane text-sky-500 mr-2"></i>结果回传</h3>
        <p class="text-sm leading-6 text-slate-600 dark:text-slate-300 mt-3">${escapeHtml(health.result_return || '远程任务完成后默认发送到 Web 消息提醒。')}</p>
        <div class="grid grid-cols-2 gap-2 mt-4 text-xs">
            <div class="rounded-xl bg-slate-50 dark:bg-white/5 p-3"><b>${counts.pending || 0}</b><p class="text-slate-400 mt-1">待审批</p></div>
            <div class="rounded-xl bg-slate-50 dark:bg-white/5 p-3"><b>${counts.running || 0}</b><p class="text-slate-400 mt-1">执行中</p></div>
            <div class="rounded-xl bg-slate-50 dark:bg-white/5 p-3"><b>${counts.failed || 0}</b><p class="text-slate-400 mt-1">失败</p></div>
            <div class="rounded-xl bg-slate-50 dark:bg-white/5 p-3"><b>${counts.blocked || 0}</b><p class="text-slate-400 mt-1">被拦截</p></div>
        </div>
    </aside>`;
}

function renderRemoteBridgePairing(pairing) {
    const host = document.getElementById('remote-bridge-pairing');
    if (!host) return;
    if (pairing.active && pairing.code) {
        host.innerHTML = `<div class="flex flex-wrap items-center gap-4"><div class="px-5 py-4 rounded-2xl bg-white dark:bg-[#1A1A1A] border border-emerald-200 dark:border-emerald-500/20"><div class="text-xs text-slate-400 mb-1">配对码</div><div class="text-3xl font-black tracking-[0.3em] text-emerald-600">${escapeHtml(pairing.code)}</div></div><div class="text-sm text-slate-500 leading-7">有效期至：${escapeHtml(String(pairing.expires_at || '').replace('T', ' ').slice(0, 19))}<br>手机 App / 云端控制台使用该码调用 pair_device 绑定此电脑；绑定成功后用设备 token 上报心跳和提交指令。</div></div>`;
    } else {
        host.innerHTML = '<div class="rounded-xl border border-dashed border-emerald-200 dark:border-emerald-500/20 p-4 text-sm text-slate-500">暂无有效配对码。点击“生成配对码”后，手机/云端可在 10 分钟内完成绑定。</div>';
    }
}

function renderRemoteBridgeDevices(devices) {
    const host = document.getElementById('remote-bridge-devices');
    if (!host) return;
    host.innerHTML = devices.length ? devices.map(item => {
        const health = item.health || {};
        const tone = health.status === 'online' ? 'bg-emerald-50 text-emerald-600' : health.status === 'idle' ? 'bg-amber-50 text-amber-600' : 'bg-slate-100 text-slate-500';
        return `<div class="flex items-center justify-between gap-3 rounded-xl border border-slate-100 dark:border-white/5 p-3"><div><div class="flex items-center gap-2"><b class="text-sm">${escapeHtml(item.name || item.id || '远程设备')}</b><span class="px-2 py-0.5 rounded-full text-[10px] ${tone}">${escapeHtml(health.label || '未知')}</span></div><p class="text-xs text-slate-400 mt-1">${escapeHtml(item.platform || '未知平台')} · 最近：${escapeHtml(String(health.last_seen || item.created_at || '').replace('T', ' ').slice(0, 19) || '未上报')}</p></div><button onclick="removeRemoteBridgeDevice('${escapeHtml(item.id || '')}')" class="text-xs text-red-500">移除</button></div>`;
    }).join('') : '<div class="py-8 text-center text-sm text-slate-400">暂无已配对设备</div>';
}

function renderRemoteBridgeCapabilities(items) {
    const host = document.getElementById('remote-bridge-capabilities');
    if (!host) return;
    host.innerHTML = items.length ? items.map(item => `<span class="px-3 py-1.5 rounded-full bg-slate-100 dark:bg-white/5 text-xs text-slate-600 dark:text-slate-300"><i class="fas fa-robot mr-1.5 text-emerald-500"></i>${escapeHtml(item.name || item.id)}</span>`).join('') : '<span class="text-sm text-slate-400">暂无已启用 Agent，请先在 Agent 名册启用。</span>';
}

function renderRemoteBridgeQueue(items) {
    const host = document.getElementById('remote-bridge-queue');
    if (!host) return;
    const statusText = { pending_approval: '待审批', queued: '待执行', routed: '已路由', running: '执行中', done: '完成', failed: '失败', blocked: '已拦截', rejected: '已拒绝', expired: '已过期' };
    const statusTone = { pending_approval: 'bg-amber-50 dark:bg-amber-500/10 text-amber-600', queued: 'bg-blue-50 dark:bg-blue-500/10 text-blue-600', routed: 'bg-emerald-50 dark:bg-emerald-500/10 text-emerald-600', blocked: 'bg-red-50 dark:bg-red-500/10 text-red-600', rejected: 'bg-slate-100 dark:bg-white/5 text-slate-500', expired: 'bg-slate-100 dark:bg-white/5 text-slate-500', failed: 'bg-red-50 dark:bg-red-500/10 text-red-600' };
    host.innerHTML = items.length ? items.map(item => {
        const route = item.route_decision || {}, mission = item.mission_decision || {}, agents = (route.agent_candidates || []).slice(0, 2), tools = (route.tool_candidates || []).slice(0, 3), scopes = item.required_scopes || [];
        return `<div data-remote-command-id="${escapeHtml(item.id || '')}" class="rounded-xl border border-slate-100 dark:border-white/5 p-3">
            <div class="flex flex-wrap items-center justify-between gap-2">
                <b class="text-sm">${escapeHtml(item.command || '')}</b>
                <span class="px-2 py-1 rounded-full ${statusTone[item.status] || statusTone.queued} text-[10px]">${escapeHtml(statusText[item.status] || item.status || '待处理')}</span>
            </div>
            <p class="text-xs text-slate-400 mt-2">${escapeHtml(item.source || '远程')} · 创建 ${escapeHtml(String(item.created_at || '').replace('T', ' ').slice(0, 19))} · 过期 ${escapeHtml(String(item.expires_at || '').replace('T', ' ').slice(0, 19))}</p>
            <div class="mt-2 grid gap-1 text-[11px] text-slate-500">
                <div><b>路由：</b>${escapeHtml(route.intent || mission.intent || '待判断')} ${agents.length ? `· ${agents.map(escapeHtml).join(' / ')}` : ''}</div>
                <div><b>权限：</b>${scopes.length ? scopes.map(escapeHtml).join(' / ') : '读取'}</div>
                ${tools.length ? `<div><b>工具：</b>${tools.map(escapeHtml).join(' / ')}</div>` : ''}
                ${item.policy_block_reason ? `<div class="text-red-500"><b>拦截原因：</b>${escapeHtml(item.policy_block_reason)}</div>` : ''}
                ${item.result_summary ? `<div class="${item.status === 'failed' ? 'text-red-500' : 'text-emerald-600'}"><b>结果：</b>${escapeHtml(item.result_summary)}</div>` : ''}
                ${item.delivery ? `<div><b>回传：</b>${escapeHtml(item.delivery.label || '')} · ${escapeHtml(item.delivery.summary || '')}</div>` : ''}
                ${(item.delivery_confirmations || []).length ? `<div><b>确认：</b>${escapeHtml((item.delivery_confirmations[0] || {}).device_name || '远程设备')} 已确认收到</div>` : ''}
            </div>
            ${item.approval_id && item.status === 'pending_approval' ? `<div class="mt-3 flex justify-end"><button onclick="missionControlOpen('approvals')" class="px-3 py-1.5 rounded-lg bg-amber-600 text-white text-xs"><i class="fas fa-user-check mr-1"></i>去审批</button></div>` : ''}
            ${['failed','blocked','expired','rejected'].includes(item.status) ? `<div class="mt-3 flex justify-end"><button onclick="retryRemoteBridgeCommand('${escapeHtml(item.id || '')}')" class="px-3 py-1.5 rounded-lg bg-red-600 text-white text-xs"><i class="fas fa-rotate-right mr-1"></i>按当前配置重试</button></div>` : ''}
        </div>`;
    }).join('') : '<div class="py-8 text-center text-sm text-slate-400">暂无远程指令</div>';
}

function renderRemoteBridgeAudit(items) {
    const host = document.getElementById('remote-bridge-audit');
    if (!host) return;
    host.innerHTML = items.length ? items.slice(0, 20).map(item => `<div class="py-3 flex items-start justify-between gap-3"><div><b class="text-sm">${escapeHtml(item.message || item.action || '')}</b><p class="text-xs text-slate-400 mt-1">${escapeHtml(item.action || '')}</p></div><span class="text-xs text-slate-400 whitespace-nowrap">${escapeHtml(String(item.created_at || '').replace('T', ' ').slice(0, 19))}</span></div>`).join('') : '<div class="py-8 text-center text-sm text-slate-400">暂无审计记录</div>';
}

async function saveRemoteBridgeConfig() {
    const payload = {
        action: 'configure',
        device_name: document.getElementById('remote-bridge-device-name')?.value || '',
        cloud_url: document.getElementById('remote-bridge-cloud-url')?.value || '',
        enabled: !!document.getElementById('remote-bridge-enabled')?.checked,
        allow_lan: !!document.getElementById('remote-bridge-allow-lan')?.checked,
        require_approval: !!document.getElementById('remote-bridge-require-approval')?.checked,
        allow_read: !!document.getElementById('remote-bridge-allow-read')?.checked,
        allow_write: !!document.getElementById('remote-bridge-allow-write')?.checked,
        allow_execute: !!document.getElementById('remote-bridge-allow-execute')?.checked,
        max_command_ttl_minutes: Number(document.getElementById('remote-bridge-ttl')?.value || 30),
    };
    setRemoteBridgeStatus('正在保存 Bridge 配置…');
    try {
        remoteBridgeState = await remoteBridgeApi(payload);
        renderRemoteBridge();
        setRemoteBridgeStatus('保存成功', 'success');
    } catch (error) {
        setRemoteBridgeStatus(`保存失败：${error.message}`, 'error');
    }
}

async function createRemoteBridgePairCode() {
    setRemoteBridgeStatus('正在生成配对码…');
    try {
        remoteBridgeState = await remoteBridgeApi({ action: 'pair_code' });
        renderRemoteBridge();
        setRemoteBridgeStatus('配对码已生成，10 分钟内有效', 'success');
    } catch (error) {
        setRemoteBridgeStatus(`生成失败：${error.message}`, 'error');
    }
}

async function revokeRemoteBridgePairCode() {
    try {
        remoteBridgeState = await remoteBridgeApi({ action: 'revoke_pair_code' });
        renderRemoteBridge();
        setRemoteBridgeStatus('配对码已撤销', 'success');
    } catch (error) {
        setRemoteBridgeStatus(`撤销失败：${error.message}`, 'error');
    }
}

async function removeRemoteBridgeDevice(id) {
    if (!id || !confirm('确定移除这个远程设备吗？')) return;
    try {
        remoteBridgeState = await remoteBridgeApi({ action: 'remove_device', device_id: id });
        renderRemoteBridge();
        setRemoteBridgeStatus('设备已移除', 'success');
    } catch (error) {
        setRemoteBridgeStatus(`移除失败：${error.message}`, 'error');
    }
}

async function enqueueRemoteBridgeTestCommand() {
    const input = document.getElementById('remote-bridge-test-command');
    const command = (input?.value || '').trim();
    if (!command) return setRemoteBridgeStatus('请先输入模拟远程指令', 'warning');
    try {
        remoteBridgeState = await remoteBridgeApi({ action: 'enqueue_test_command', command });
        if (input) input.value = '';
        renderRemoteBridge();
        setRemoteBridgeStatus('已写入远程指令队列', 'success');
    } catch (error) {
        setRemoteBridgeStatus(`写入失败：${error.message}`, 'error');
    }
}

async function clearRemoteBridgeQueue() {
    if (!confirm('确定清空远程指令队列吗？')) return;
    try {
        remoteBridgeState = await remoteBridgeApi({ action: 'clear_queue' });
        renderRemoteBridge();
        setRemoteBridgeStatus('队列已清空', 'success');
    } catch (error) {
        setRemoteBridgeStatus(`清空失败：${error.message}`, 'error');
    }
}

function saveRemoteBridgeSimulatorState() {
    try { localStorage.setItem('cow_remote_bridge_simulator', JSON.stringify(remoteBridgeSimulator || {})); } catch (_) {}
}

function renderRemoteBridgeSimulator() {
    const status = document.getElementById('remote-bridge-sim-status');
    const results = document.getElementById('remote-bridge-sim-results');
    const name = document.getElementById('remote-bridge-sim-device-name');
    const platform = document.getElementById('remote-bridge-sim-platform');
    if (name && remoteBridgeSimulator.device_name) name.value = remoteBridgeSimulator.device_name;
    if (platform && remoteBridgeSimulator.platform) platform.value = remoteBridgeSimulator.platform;
    if (status) {
        if (remoteBridgeSimulator.device_token) {
            status.innerHTML = `<div class="flex items-center justify-between gap-2"><span class="text-emerald-600"><i class="fas fa-circle-check mr-1"></i>模拟设备已绑定</span><span class="text-slate-400">${escapeHtml(remoteBridgeSimulator.device_id || '')}</span></div><p class="mt-1 text-slate-400">可模拟手机端发送指令、拉取结果和确认回执。</p>`;
        } else {
            status.innerHTML = '<span class="text-amber-600"><i class="fas fa-circle-exclamation mr-1"></i>尚未绑定模拟设备</span><p class="mt-1 text-slate-400">请先启用 Bridge、生成配对码，再点击“模拟绑定”。</p>';
        }
    }
    if (results && !results.dataset.rendered) {
        results.innerHTML = '<div class="rounded-xl border border-dashed border-cyan-200 dark:border-cyan-500/20 p-4 text-sm text-slate-400">拉取结果后会显示在这里。</div>';
    }
}

async function remoteBridgeSimulatorPair() {
    const data = remoteBridgeState || {};
    if (!data.enabled) return setRemoteBridgeStatus('请先勾选“启用 Bridge”并保存配置，再模拟绑定。', 'warning');
    let pairing = data.pairing || {};
    try {
        if (!pairing.active || !pairing.code) {
            remoteBridgeState = await remoteBridgeApi({ action: 'pair_code' });
            pairing = remoteBridgeState.pairing || {};
        }
        if (!pairing.code) throw new Error('未生成有效配对码');
        const deviceName = document.getElementById('remote-bridge-sim-device-name')?.value || 'Web 模拟手机';
        const platform = document.getElementById('remote-bridge-sim-platform')?.value || 'web-simulator';
        const result = await remoteBridgeApi({ action: 'pair_device', code: pairing.code, device_name: deviceName, platform });
        remoteBridgeState = result;
        remoteBridgeSimulator = {
            device_token: result.device_token || '',
            device_id: (result.device || {}).id || '',
            device_name: deviceName,
            platform,
            paired_at: new Date().toISOString(),
        };
        saveRemoteBridgeSimulatorState();
        renderRemoteBridge();
        setRemoteBridgeStatus('模拟设备已绑定，可发送远程指令', 'success');
    } catch (error) {
        setRemoteBridgeStatus(`模拟绑定失败：${error.message}`, 'error');
    }
}

async function remoteBridgeSimulatorSendCommand() {
    const input = document.getElementById('remote-bridge-sim-command');
    const command = (input?.value || '').trim();
    if (!remoteBridgeSimulator.device_token) return setRemoteBridgeStatus('请先模拟绑定设备', 'warning');
    if (!command) return setRemoteBridgeStatus('请先输入要模拟发送的远程指令', 'warning');
    try {
        remoteBridgeState = await remoteBridgeApi({ action: 'enqueue_remote_command', device_token: remoteBridgeSimulator.device_token, command });
        if (input) input.value = '';
        renderRemoteBridge();
        setRemoteBridgeStatus('模拟设备指令已发送；如需审批，请到审批中心批准后再拉取结果', 'success');
    } catch (error) {
        setRemoteBridgeStatus(`模拟发送失败：${error.message}`, 'error');
    }
}

async function remoteBridgeSimulatorFetchResults() {
    if (!remoteBridgeSimulator.device_token) return setRemoteBridgeStatus('请先模拟绑定设备', 'warning');
    const host = document.getElementById('remote-bridge-sim-results');
    if (host) {
        host.dataset.rendered = '1';
        host.innerHTML = '<div class="rounded-xl border border-cyan-100 dark:border-cyan-500/20 p-4 text-sm text-cyan-600"><i class="fas fa-spinner fa-spin mr-2"></i>正在模拟设备拉取结果…</div>';
    }
    try {
        const data = await remoteBridgeApi({ action: 'fetch_results', device_token: remoteBridgeSimulator.device_token, limit: 20 });
        remoteBridgeState = await remoteBridgeApi();
        renderRemoteBridgeSimulatorResults(data.results || []);
        renderRemoteBridge();
        setRemoteBridgeStatus(`模拟设备已拉取 ${data.count || 0} 条结果`, 'success');
    } catch (error) {
        if (host) host.innerHTML = `<div class="rounded-xl border border-red-100 bg-red-50 dark:bg-red-500/10 p-4 text-sm text-red-600">拉取失败：${escapeHtml(error.message)}</div>`;
        setRemoteBridgeStatus(`拉取失败：${error.message}`, 'error');
    }
}

function renderRemoteBridgeSimulatorResults(items) {
    const host = document.getElementById('remote-bridge-sim-results');
    if (!host) return;
    host.dataset.rendered = '1';
    if (!items.length) {
        host.innerHTML = '<div class="rounded-xl border border-dashed border-cyan-200 dark:border-cyan-500/20 p-4 text-sm text-slate-400">当前模拟设备暂无可拉取结果。审批通过并执行完成后，再点击“拉取结果”。</div>';
        return;
    }
    host.innerHTML = items.map(item => `<div class="rounded-xl border border-cyan-100 dark:border-cyan-500/20 bg-white/90 dark:bg-white/5 p-4">
        <div class="flex flex-wrap items-center justify-between gap-2">
            <b class="text-sm">${escapeHtml(item.command || '远程指令')}</b>
            <span class="px-2 py-0.5 rounded-full text-[10px] ${item.status === 'done' ? 'bg-emerald-50 text-emerald-600' : item.status === 'failed' ? 'bg-red-50 text-red-600' : 'bg-amber-50 text-amber-600'}">${escapeHtml(item.status || '')}</span>
        </div>
        <p class="mt-2 text-xs text-slate-400">${escapeHtml(String(item.finished_at || item.created_at || '').replace('T',' ').slice(0,19))}</p>
        <pre class="mt-3 max-h-48 overflow-auto whitespace-pre-wrap rounded-lg bg-slate-50 dark:bg-black/20 p-3 text-xs leading-5 text-slate-600 dark:text-slate-300">${escapeHtml(item.result || item.summary || '暂无内容')}</pre>
        <div class="mt-3 flex justify-end"><button onclick="remoteBridgeSimulatorAck('${escapeHtml(item.command_id || '')}')" class="px-3 py-1.5 rounded-lg bg-cyan-600 text-white text-xs"><i class="fas fa-check mr-1"></i>确认收到</button></div>
    </div>`).join('');
}

async function remoteBridgeSimulatorAck(commandId) {
    if (!remoteBridgeSimulator.device_token || !commandId) return;
    try {
        remoteBridgeState = await remoteBridgeApi({ action: 'confirm_delivery', device_token: remoteBridgeSimulator.device_token, command_id: commandId, delivery_status: 'received', message: 'Web 模拟设备已确认收到结果' });
        renderRemoteBridge();
        await remoteBridgeSimulatorFetchResults();
        setRemoteBridgeStatus('模拟设备已确认收到结果', 'success');
    } catch (error) {
        setRemoteBridgeStatus(`确认失败：${error.message}`, 'error');
    }
}

function remoteBridgeSimulatorClear() {
    remoteBridgeSimulator = {};
    saveRemoteBridgeSimulatorState();
    const host = document.getElementById('remote-bridge-sim-results');
    if (host) {
        host.dataset.rendered = '';
        host.innerHTML = '<div class="rounded-xl border border-dashed border-cyan-200 dark:border-cyan-500/20 p-4 text-sm text-slate-400">拉取结果后会显示在这里。</div>';
    }
    renderRemoteBridgeSimulator();
    setRemoteBridgeStatus('已清除本机浏览器里的模拟设备 token', 'success');
}

async function retryRemoteBridgeCommand(id) {
    if (!id) return;
    setRemoteBridgeStatus('正在重新发起远程指令…');
    try {
        remoteBridgeState = await remoteBridgeApi({ action: 'retry_command', command_id: id });
        renderRemoteBridge();
        setRemoteBridgeStatus('已按当前配置重新发起；如需要审批，请到审批中心处理', 'success');
    } catch (error) {
        setRemoteBridgeStatus(`重试失败：${error.message}`, 'error');
    }
}

function toggleSidebarCompact(force){
    const sidebar=document.getElementById('sidebar');if(!sidebar)return;
    const compact=force===undefined?!sidebar.classList.contains('w-16'):!!force;
    sidebar.classList.toggle('w-60',!compact);sidebar.classList.toggle('w-16',compact);
    document.getElementById('sidebar-brand')?.classList.toggle('hidden',compact);
    sidebar.querySelectorAll('nav .menu-group > button').forEach(x=>x.classList.toggle('hidden',compact));
    sidebar.querySelectorAll('nav .sidebar-item span').forEach(x=>x.classList.toggle('hidden',compact));
    sidebar.querySelectorAll('nav .menu-group-items').forEach(x=>x.classList.toggle('pl-2',!compact));
    sidebar.querySelectorAll('nav .sidebar-item').forEach(x=>{x.classList.toggle('justify-center',compact);x.classList.toggle('px-3',!compact);x.title=compact?x.textContent.trim():'';});
    document.getElementById('sidebar-search-label')?.classList.toggle('hidden',compact);
    const icon=document.getElementById('sidebar-collapse-icon');icon?.classList.toggle('fa-angles-right',compact);icon?.classList.toggle('fa-table-columns',!compact);
    sidebar.style.width=compact?'4rem':`${getSavedSidebarWidth()}px`;
    localStorage.setItem('cow_sidebar_compact',compact?'1':'0');
}

const SIDEBAR_WIDTH_KEY='cow_sidebar_width';
function getSavedSidebarWidth(){const value=Number(localStorage.getItem(SIDEBAR_WIDTH_KEY)||240);return Math.max(220,Math.min(420,Number.isFinite(value)?value:240));}
function initializeSidebarResizer(){
    const sidebar=document.getElementById('sidebar'),handle=document.getElementById('sidebar-resizer');if(!sidebar||!handle)return;
    document.documentElement.style.setProperty('--cow-sidebar-width',`${getSavedSidebarWidth()}px`);
    if(!sidebar.classList.contains('w-16'))sidebar.style.width=`${getSavedSidebarWidth()}px`;
    let startX=0,startWidth=0;
    handle.addEventListener('pointerdown',event=>{
        if(window.innerWidth<1024||sidebar.classList.contains('w-16'))return;
        startX=event.clientX;startWidth=sidebar.getBoundingClientRect().width;document.body.classList.add('sidebar-resizing');handle.setPointerCapture?.(event.pointerId);event.preventDefault();
    });
    handle.addEventListener('pointermove',event=>{
        if(!document.body.classList.contains('sidebar-resizing'))return;
        const width=Math.max(220,Math.min(420,startWidth+event.clientX-startX));sidebar.style.width=`${width}px`;document.documentElement.style.setProperty('--cow-sidebar-width',`${width}px`);
    });
    const finish=()=>{if(!document.body.classList.contains('sidebar-resizing'))return;document.body.classList.remove('sidebar-resizing');const width=Math.round(sidebar.getBoundingClientRect().width);localStorage.setItem(SIDEBAR_WIDTH_KEY,String(width));};
    handle.addEventListener('pointerup',finish);handle.addEventListener('pointercancel',finish);
}

function positionCapabilityTabs(inHeader){const tabs=document.getElementById('capability-tabs'),header=document.getElementById('app-header'),breadcrumb=document.getElementById('app-breadcrumb');if(!tabs||!header)return;if(inHeader){header.insertBefore(tabs,header.querySelector('.flex-1'));tabs.classList.remove('hidden');breadcrumb?.classList.add('lg:hidden');breadcrumb?.classList.remove('lg:flex');}else{tabs.classList.add('hidden');breadcrumb?.classList.remove('lg:hidden');breadcrumb?.classList.add('lg:flex');}}

const GLOBAL_SEARCH_ITEMS=[['仪表盘','查看今日任务、微信状态、失败恢复和最新产物','mission-control','fa-sun'],['对话','开始新的 AI 对话','chat','fa-message'],['项目','管理目标、资料和团队协作','projects','fa-diagram-project'],['产物中心','查看报告、文档和任务成果','artifacts','fa-box-archive'],['常用功能','运行网络搜索 Agent 等高频能力','common-functions','fa-grid-2'],['Memory Wiki','编辑用户画像、偏好、长期记忆和失败经验','memory-wiki','fa-book-atlas'],['Agent 名册','管理网络搜索、邮件、文件、浏览器、财税和研究 Agent','agent-roster','fa-address-book'],['远程 Bridge','为云端控制台、手机和多设备远程控制做准备','remote-bridge','fa-tower-cell'],['网络搜索 Agent','搜索、阅读、过滤、去重并总结来源','common-function:network-search','fa-magnifying-glass-chart'],['个人研究 Agent','拆解复杂研究任务并生成决策报告','common-function:deep-research','fa-microscope'],['Agent-Reach 互联网能力','接入网页、RSS、GitHub、视频和社媒来源','common-function:agent-reach','fa-satellite'],['快速学习 Agent','提取公众号和网页正文，生成学习笔记','common-function:quick-learning','fa-book-open-reader'],['快速读书 Agent','输入书名或上传 PDF/TXT，生成读书笔记和知识库归档','common-function:fast-reading','fa-book-bookmark'],['音乐/视频来源助手','识别音乐视频来源、登记下载任务和格式处理','common-function:media-assistant','fa-photo-film'],['工具连接中心','管理 MCP 服务和本地 CLI 工具','common-function:tool-connector','fa-plug-circle-bolt'],['浏览器代办 Agent','打开网页、登录系统、填写表单和导出报表','common-function:browser-agent','fa-window-restore'],['本地文件/桌面自动化','查找读取整理本地文件并联动桌面软件','common-function:desktop-agent','fa-folder-tree'],['代码助手','阅读代码、拆解需求、修复错误并给出测试建议','common-function:code-agent','fa-code'],['网站更新监控','检测指定页面新增、删除或修改并通知','common-function:website-monitor','fa-satellite-dish'],['美元走势追踪','每日检索美元、汇率与美联储动态','common-preset:usd','fa-dollar-sign'],['财税政策追踪','跟踪财政税务新政及企业影响','common-preset:tax','fa-landmark'],['专家','选择专业角色处理任务','skills:experts','fa-user-tie'],['技能','安装和管理 Skill','skills:skills','fa-hammer'],['连接器','连接邮箱、Webhook 和外部系统','skills:connectors','fa-link'],['AI · 自动化','管理定时任务和运行结果','intelligence','fa-wand-magic-sparkles'],['通道','配置消息和邮箱通道','channels','fa-tower-broadcast'],['API 管理','创建和管理接口访问','api','fa-code'],['日志','查看系统运行日志','logs','fa-terminal']];
function openGlobalSearch(){const modal=document.getElementById('global-search-modal');modal.classList.remove('hidden');modal.classList.add('flex');const input=document.getElementById('global-search-input');input.value='';renderGlobalSearch('');setTimeout(()=>input.focus(),20);}
function closeGlobalSearch(){const modal=document.getElementById('global-search-modal');modal.classList.add('hidden');modal.classList.remove('flex');}
function renderGlobalSearch(query){const q=(query||'').trim().toLowerCase();const projectItems=readProjects().map(x=>[x.name,x.description||'项目',`project:${x.id}`,'fa-folder']);const expertItems=(typeof EXPERTS==='undefined'?[]:EXPERTS.map(x=>[x.name,x.desc,`expert:${x.name}`,x.icon]));const items=[...GLOBAL_SEARCH_ITEMS,...projectItems,...expertItems].filter(x=>!q||`${x[0]} ${x[1]}`.toLowerCase().includes(q)).slice(0,20);document.getElementById('global-search-results').innerHTML=items.length?items.map(x=>`<button onclick="activateGlobalSearch('${encodeURIComponent(x[2])}')" class="w-full flex items-center gap-3 p-3 rounded-xl text-left hover:bg-slate-100 dark:hover:bg-white/5"><div class="w-9 h-9 rounded-lg bg-slate-100 dark:bg-white/10 flex items-center justify-center"><i class="fas ${x[3]}"></i></div><div><div class="font-medium text-sm">${escapeHtml(x[0])}</div><p class="text-xs text-slate-400 mt-0.5 line-clamp-1">${escapeHtml(x[1])}</p></div></button>`).join(''):'<div class="py-12 text-center text-slate-400">没有找到相关功能</div>';}
function activateGlobalSearch(encoded){const target=decodeURIComponent(encoded);closeGlobalSearch();if(target.startsWith('expert:')){navigateTo('skills');switchCapabilityTab('experts');return;}if(target.startsWith('project:')){navigateTo('projects');return;}if(target.startsWith('skills:')){navigateTo('skills');switchCapabilityTab(target.split(':')[1]);return;}if(target.startsWith('common-function:')){navigateTo('common-functions');openCommonFunction(target.split(':')[1]);return;}if(target.startsWith('common-preset:')){navigateTo('common-functions');openCommonTrackingPreset(target.split(':')[1]);return;}if(target==='memory-wiki'){openSettingsCenter();setTimeout(()=>showSettingsView('memory-wiki','Memory Wiki'),60);return;}if(target==='api'||target==='logs'){openSettingsCenter();showSettingsView(target,target==='api'?'API 管理':'系统日志');return;}navigateTo(target);}

function missionToneClass(status){if(status==='success')return 'bg-emerald-50 text-emerald-600 dark:bg-emerald-500/10 dark:text-emerald-300';if(status==='error'||status==='failed')return 'bg-red-50 text-red-600 dark:bg-red-500/10 dark:text-red-300';if(status==='running')return 'bg-blue-50 text-blue-600 dark:bg-blue-500/10 dark:text-blue-300';if(status==='empty'||status==='warning')return 'bg-orange-50 text-orange-600 dark:bg-orange-500/10 dark:text-orange-300';return 'bg-slate-100 text-slate-500 dark:bg-white/5 dark:text-slate-300';}
function missionShortTime(value){const text=String(value||'');if(!text)return '暂无时间';return text.replace('T',' ').replace(/\.\d+.*$/,'').replace(/\+\d\d:\d\d$/,'').slice(0,19);}
function missionControlOpen(target,prefill=''){if(target==='new_task'){navigateTo('intelligence');setTimeout(()=>{openTaskCreator?.();if(prefill){const input=document.getElementById('natural-task-prompt');if(input){input.value=prefill;input.dispatchEvent(new Event('input',{bubbles:true}));parseNaturalTask?.();}}},80);return;}if(target==='artifacts'){navigateTo('artifacts');return;}if(target==='approvals'){navigateTo('intelligence');setTimeout(()=>{switchAutomationTab?.('approvals');loadAutomationApprovals?.();},100);return;}if(target==='remote-bridge'){openSettingsCenter?.();setTimeout(()=>showSettingsView?.('remote-bridge','远程 Bridge'),80);return;}if(target==='failed_runs'){navigateTo('intelligence');setTimeout(()=>{switchAutomationTab?.('runs');const status=document.getElementById('automation-run-status');if(status)status.value='failed';loadAutomationRuns?.();},100);return;}if(target==='runs'){navigateTo('intelligence');setTimeout(()=>{switchAutomationTab?.('runs');loadAutomationRuns?.();},100);return;}if(target==='inbox'){openNotificationCenter?.();return;}if(target==='maintenance'){openSettingsCenter?.();setTimeout(()=>showSettingsView?.('maintenance','维护看板'),80);return;}if(target==='channels'){openSettingsCenter?.();setTimeout(()=>showSettingsView?.('channels','通道与连接'),80);return;}if(target==='agent2'){navigateTo('intelligence');setTimeout(()=>{switchAutomationTab?.('agent2');loadAgent2Dashboard?.();},100);return;}if(target==='memory-wiki'){openSettingsCenter?.();setTimeout(()=>showSettingsView?.('memory-wiki','Memory Wiki'),80);return;}if(target==='agent-reach'){navigateTo('common-functions');setTimeout(()=>openCommonFunction?.('agent-reach'),80);return;}if(target==='network-search'){navigateTo('common-functions');setTimeout(()=>openCommonFunction?.('network-search'),80);return;}if(target==='intelligence'||target==='automation'){navigateTo('intelligence');return;}if(target==='common-functions'){navigateTo('common-functions');return;}navigateTo(target);}
function missionFillCommand(text){const input=document.getElementById('mission-command-input');if(input){input.value=text;input.focus();}}
function missionFillEncoded(encoded){missionFillCommand(decodeURIComponent(encoded||''));}
function missionCommandNotice(message,tone='blue'){const box=document.getElementById('mission-command-result');if(!box)return;const colors={blue:'text-blue-600 bg-blue-50 dark:bg-blue-500/10',green:'text-emerald-600 bg-emerald-50 dark:bg-emerald-500/10',red:'text-red-600 bg-red-50 dark:bg-red-500/10',orange:'text-orange-600 bg-orange-50 dark:bg-orange-500/10'};box.className=`mt-3 rounded-xl px-3 py-2 text-sm leading-6 ${colors[tone]||colors.blue}`;box.style.whiteSpace='pre-line';box.textContent=message;box.classList.remove('hidden');}
function missionCommandDecisionNotice(decision){const box=document.getElementById('mission-command-result');if(!box)return missionCommandNotice(decision?.message||'已完成诊断','green');const actions=decision?.repair_actions||[],toneClass='text-emerald-700 bg-emerald-50 dark:bg-emerald-500/10 dark:text-emerald-200';box.className=`mt-3 rounded-xl px-3 py-3 text-sm leading-6 ${toneClass}`;box.style.whiteSpace='normal';box.innerHTML=`<div class="whitespace-pre-line">${escapeHtml(decision?.message||'已完成诊断')}</div>${actions.length?`<div class="mt-3 flex flex-wrap gap-2">${actions.map(item=>`<button onclick="runMissionRepairAction('${escapeHtml(item.key||'')}','${escapeHtml(item.kind||'open')}','${escapeHtml(item.target||'')}','${encodeURIComponent(item.command||'')}')" title="${escapeHtml(item.summary||'')}" class="px-3 py-1.5 rounded-lg bg-white/80 dark:bg-black/20 border border-emerald-100 dark:border-emerald-500/20 text-xs hover:text-primary-500"><i class="fas ${item.kind==='api'?'fa-wrench':item.kind==='command'?'fa-rotate-right':'fa-arrow-up-right-from-square'} mr-1"></i>${escapeHtml(item.label||'处理')}</button>`).join('')}</div>`:''}`;box.classList.remove('hidden');}
async function runMissionRepairAction(key,kind,target,encodedCommand){if(kind==='command'){missionFillEncoded(encodedCommand||'');await runMissionCommand();return;}if(kind==='open'){if(target==='models'){openSettingsCenter?.();setTimeout(()=>{showSettingsView?.('config','配置管理');switchConfigTab?.('models');},80);return;}if(target==='email'){openSettingsCenter?.();setTimeout(()=>showSettingsView?.('channels','通道与连接'),80);return;}missionControlOpen(target||'agent2');return;}try{missionCommandNotice('正在执行修复动作…','blue');const response=await fetch('/api/mission-control',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'weixin_repair',repair:key})});const data=await response.json();if(data.status!=='success')throw new Error(data.message||'修复失败');missionCommandNotice(data.message||'修复动作已执行','green');setTimeout(()=>loadMissionControl?.(true),500);}catch(error){missionCommandNotice(`修复失败：${error.message||String(error)}`,'red');}}
function renderMissionCommandLearning(learning){const host=document.getElementById('mission-command-learning');if(!host)return;const items=(learning?.items||[]).filter(item=>item.command).slice(0,6);if(!items.length){host.innerHTML='<span class="text-[11px] text-slate-400">使用几次后，这里会自动出现你常用的指挥指令。</span>';return;}const channelName={web:'Web',weixin:'微信',remote_bridge:'远程'};host.innerHTML='<span class="text-[11px] text-slate-400 py-1">推荐指令</span>'+items.map(item=>{const source=channelName[item.top_channel]||item.top_source||item.top_channel||'';return `<button onclick="missionFillEncoded('${encodeURIComponent(item.command||'')}')" class="px-2.5 py-1 rounded-full bg-white/80 dark:bg-white/10 border border-cyan-100 dark:border-cyan-500/20 text-[11px] hover:text-cyan-600"><i class="fas ${item.recommended?'fa-star text-amber-400':'fa-clock-rotate-left text-slate-400'} mr-1"></i>${escapeHtml(item.command||'常用指令')}${item.count?` · ${Number(item.count)}次`:''}${source?` · ${escapeHtml(source)}`:''}</button>`;}).join('');}
function renderMissionWeixinLearning(items=[]){const host=document.getElementById('mission-weixin-learning');if(!host)return;items=(items||[]).slice(0,3);if(!items.length){host.innerHTML='';return;}const labelMap={model_auth:'模型认证',email_config:'邮箱配置',empty_result:'空结果',file_not_found:'文件未找到',permission:'权限不足',network:'网络异常',browser_env:'浏览器环境',empty_reply:'空回复',send_failure:'发送失败',general:'普通失败'};host.innerHTML=`<div class="rounded-xl border border-emerald-100 dark:border-emerald-500/20 bg-white/80 dark:bg-black/10 p-3"><div class="flex items-center justify-between gap-2"><b class="text-xs text-emerald-600"><i class="fab fa-weixin mr-1"></i>微信失败学习</b><button onclick="missionControlOpen('agent2')" class="text-[11px] text-primary-500 hover:underline">查看详情</button></div><div class="mt-2 grid sm:grid-cols-3 gap-2">${items.map(item=>`<div class="rounded-lg bg-emerald-50/70 dark:bg-emerald-500/10 px-3 py-2 text-[11px]"><div class="flex items-center justify-between gap-2"><span class="font-semibold">${escapeHtml(labelMap[item.category]||item.category||'失败')}</span><span class="text-emerald-600">${Number(item.count||0)}次</span></div><p class="mt-1 text-slate-500 line-clamp-2">${escapeHtml(item.recommended_action||item.lesson||'先尝试可用路径，失败后说明原因')}</p></div>`).join('')}</div></div>`;}
function renderMissionInstanceAlert(data){const host=document.getElementById('mission-control-instance-alert');if(!host)return;const alert=data?.maintenance?.instance_guard_alert||{};if(!alert.active){host.classList.add('hidden');host.innerHTML='';return;}host.className='rounded-2xl border border-orange-200 dark:border-orange-500/30 bg-orange-50/90 dark:bg-orange-500/10 p-4 text-orange-800 dark:text-orange-200';host.innerHTML=`<div class="flex flex-wrap items-start justify-between gap-3"><div class="min-w-0"><div class="font-semibold"><i class="fas fa-triangle-exclamation mr-2"></i>${escapeHtml(alert.title||'疑似存在残留后端实例')}</div><p class="mt-1 text-sm leading-6">${escapeHtml(alert.summary||'实例保护已拦截旧实例执行任务，建议检查后端实例并按需安全重启。')}</p>${alert.latest_task?`<p class="mt-1 text-xs opacity-80">最近跳过：${escapeHtml(alert.latest_task)}${alert.latest_at?` · ${escapeHtml(String(alert.latest_at).replace('T',' ').slice(0,19))}`:''}</p>`:''}</div><div class="shrink-0 flex flex-wrap gap-2"><button onclick="missionControlOpen('maintenance');setTimeout(()=>maintenanceDashboardCheckBackend?.(),200)" class="px-3 py-1.5 rounded-lg bg-orange-600 text-white text-xs">检查实例</button><button onclick="missionControlOpen('maintenance');setTimeout(()=>maintenanceDashboardCleanupBackend?.(),300)" class="px-3 py-1.5 rounded-lg bg-white/80 dark:bg-black/20 border border-orange-200 dark:border-orange-500/30 text-xs">清理残留锁</button><button onclick="missionControlOpen('maintenance');setTimeout(()=>maintenanceDashboardRestartBackend?.(),300)" class="px-3 py-1.5 rounded-lg bg-rose-600 text-white text-xs">安全重启</button></div></div>`;}
function renderMissionInstanceAlertV2(data){const host=document.getElementById('mission-control-instance-alert');if(!host)return;const alert=data?.maintenance?.instance_guard_alert||{},fix=alert.auto_remediation||{};if(!alert.active){host.classList.add('hidden');host.innerHTML='';return;}host.className='rounded-2xl border border-orange-200 dark:border-orange-500/30 bg-orange-50/90 dark:bg-orange-500/10 p-4 text-orange-800 dark:text-orange-200';host.innerHTML=`<div class="flex flex-wrap items-start justify-between gap-3"><div class="min-w-0"><div class="font-semibold"><i class="fas fa-triangle-exclamation mr-2"></i>${escapeHtml(alert.title||'疑似存在残留后端实例')}</div><p class="mt-1 text-sm leading-6">${escapeHtml(alert.summary||'实例保护已拦截旧实例执行任务，建议检查后端实例并按需安全重启。')}</p>${fix.summary?`<p class="mt-1 text-xs opacity-90"><i class="fas fa-shield-heart mr-1"></i>${escapeHtml(fix.summary)}</p>`:''}${alert.latest_task?`<p class="mt-1 text-xs opacity-80">最近跳过：${escapeHtml(alert.latest_task)}${alert.latest_at?` · ${escapeHtml(String(alert.latest_at).replace('T',' ').slice(0,19))}`:''}</p>`:''}</div><div class="shrink-0 flex flex-wrap gap-2"><button onclick="missionControlOpen('maintenance');setTimeout(()=>maintenanceDashboardCheckBackend?.(),200)" class="px-3 py-1.5 rounded-lg bg-orange-600 text-white text-xs">检查实例</button><button onclick="missionControlOpen('maintenance');setTimeout(()=>maintenanceDashboardCleanupBackend?.(),300)" class="px-3 py-1.5 rounded-lg bg-white/80 dark:bg-black/20 border border-orange-200 dark:border-orange-500/30 text-xs">清理残留锁</button><button onclick="missionControlOpen('maintenance');setTimeout(()=>maintenanceDashboardRestartBackend?.(),300)" class="px-3 py-1.5 rounded-lg bg-rose-600 text-white text-xs">安全重启</button></div></div>`;}
async function recordMissionCommandOutcome(command,decision,outcome,message=''){try{await fetch('/api/mission-control',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'record_outcome',command,decision,outcome,message})});}catch(_error){}}
function recordMissionQuickAction(target,label=''){recordMissionCommandOutcome(label||`打开${target}`,{target,intent:'quick_action'},'planned','仪表盘推荐动作已打开，后续按真实执行结果加权').catch(()=>{});}
async function runMissionCommand(){const input=document.getElementById('mission-command-input'),button=document.getElementById('mission-command-button'),command=(input?.value||'').trim();if(!command){missionCommandNotice('请输入要执行的指令，例如：帮我检查今天失败的任务并自动重试','orange');return;}const old=button?.innerHTML;let decision={};if(button){button.disabled=true;button.innerHTML='<i class="fas fa-spinner fa-spin mr-2"></i>判断中';}missionCommandNotice('正在判断任务类型，并准备执行…','blue');try{const response=await fetch('/api/mission-control',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({command})});const data=await response.json();if(data.status!=='success')throw new Error(data.message||'指令执行失败');decision=data.decision||{};if(decision.intent==='diagnose_weixin'){missionCommandDecisionNotice(decision);await recordMissionCommandOutcome(command,decision,'success',decision.message||'已完成微信诊断');return;}missionCommandNotice(decision.message||'已识别指令，正在处理…','green');if(decision.intent==='retry_failed_runs'){const ids=(decision.run_ids||[]).filter(Boolean);let ok=0,fail=0;for(const runId of ids){try{await intelligenceRequest('/api/intelligence/runs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({run_id:runId})});ok++;}catch(_error){fail++;}}const message=`失败任务重试完成：成功 ${ok} 个，失败 ${fail} 个。正在刷新仪表盘…`;missionCommandNotice(message,fail?'orange':'green');await recordMissionCommandOutcome(command,decision,fail?'failed':'success',message);await Promise.all([loadMissionControl?.(true),loadAutomationRuns?.().catch(()=>{}),loadAutomationRecords?.(true).catch(()=>{}),loadNotificationCenter?.().catch(()=>{})]);return;}missionControlOpen(decision.target||'intelligence',decision.prefill||'');await recordMissionCommandOutcome(command,decision,'success',decision.message||'已完成跳转处理');setTimeout(()=>loadMissionControl?.(false),350);}catch(error){missionCommandNotice(`执行失败：${error.message||String(error)}`,'red');await recordMissionCommandOutcome(command,decision,'failed',error.message||String(error));}finally{if(button){button.disabled=false;button.innerHTML=old;}}}
function renderMissionSummary(data){const summary=data.summary||{},items=[['今日任务',summary.enabled_tasks||0,`已启用 ${summary.enabled_tasks||0} / 总 ${summary.tasks||0}`,'fa-calendar-day','emerald'],['待审批',summary.pending_approvals||0,'需要你授权的操作','fa-user-check','amber'],['待确认记忆',summary.pending_memories||0,'确认后才影响画像和路由','fa-book-atlas','violet'],['微信/远程',summary.remote_pending_commands||0,'手机、微信、云端指令','fa-tower-cell','cyan'],['消息提醒',summary.unread_messages||0,'任务结果与审批提醒','fa-bell','blue'],['待恢复失败',summary.recent_failures||0,'需要重试或自动兜底','fa-triangle-exclamation','red'],['最新产物',summary.recent_artifacts||0,'报告/记录已沉淀','fa-box-archive','violet']];const tone={emerald:'text-emerald-600 bg-emerald-50 dark:bg-emerald-500/10',amber:'text-amber-600 bg-amber-50 dark:bg-amber-500/10',blue:'text-blue-600 bg-blue-50 dark:bg-blue-500/10',red:'text-red-600 bg-red-50 dark:bg-red-500/10',cyan:'text-cyan-600 bg-cyan-50 dark:bg-cyan-500/10',violet:'text-violet-600 bg-violet-50 dark:bg-violet-500/10'};document.getElementById('mission-control-summary').innerHTML=items.map(item=>`<div class="rounded-2xl border border-slate-200 dark:border-white/10 bg-white dark:bg-[#181818] p-4"><div class="flex items-center justify-between"><span class="text-xs text-slate-400">${escapeHtml(item[0])}</span><span class="w-8 h-8 rounded-xl ${tone[item[4]]} flex items-center justify-center"><i class="fas ${item[3]} text-xs"></i></span></div><div class="mt-3 text-2xl font-bold">${item[1]}</div><p class="mt-1 text-xs text-slate-400">${escapeHtml(item[2])}</p></div>`).join('');}
function renderMissionActions(actions){const host=document.getElementById('mission-control-actions');if(!host)return;host.innerHTML=(actions||[]).map(item=>`<button onclick="recordMissionQuickAction('${escapeHtml(item.target||'')}','${escapeHtml(item.label||'推荐动作')}');missionControlOpen('${escapeHtml(item.target||'')}')" class="rounded-xl border border-slate-200 dark:border-white/10 p-3 text-left hover:border-primary-300 hover:bg-slate-50 dark:hover:bg-white/5 transition"><div class="flex items-center justify-between gap-2"><span class="w-9 h-9 rounded-xl bg-slate-100 dark:bg-white/10 flex items-center justify-center"><i class="fas ${escapeHtml(item.icon||'fa-bolt')} text-primary-500"></i></span><div class="flex items-center gap-1">${item.rank_tag?`<span class="rounded-full bg-cyan-50 text-cyan-600 dark:bg-cyan-500/10 px-2 py-0.5 text-[10px]">${escapeHtml(item.rank_tag)}</span>`:''}${item.badge?`<span class="rounded-full bg-red-500 px-2 py-0.5 text-[10px] text-white">${Number(item.badge)}</span>`:''}</div></div><div class="mt-3 text-sm font-semibold">${escapeHtml(item.label||'快捷动作')}</div><p class="mt-1 text-[11px] leading-5 text-slate-400 line-clamp-2">${escapeHtml(item.reason||'根据今日状态推荐')}</p></button>`).join('');}
function renderMissionTodos(items){const host=document.getElementById('mission-control-todos');if(!host)return;host.innerHTML=(items||[]).map(item=>`<button onclick="missionControlOpen('${escapeHtml(item.target||'')}')" class="w-full rounded-xl border border-slate-200 dark:border-white/10 p-3 text-left hover:bg-slate-50 dark:hover:bg-white/5"><div class="flex items-center gap-2"><span class="px-2 py-0.5 rounded-full text-[10px] ${missionToneClass(item.level)}">${escapeHtml(item.level==='success'?'正常':item.level==='error'?'错误':item.level==='warning'?'警告':'提醒')}</span><b class="text-sm">${escapeHtml(item.title||'待处理')}</b></div><p class="mt-1 text-xs leading-5 text-slate-500">${escapeHtml(item.summary||'')}</p></button>`).join('')||'<div class="py-8 text-center text-slate-400">暂无待处理事项</div>';}
function renderMissionCards(cards){const host=document.getElementById('mission-control-cards');if(!host)return;host.innerHTML=(cards||[]).map(card=>`<button onclick="missionControlOpen('${escapeHtml(card.target||'')}')" class="rounded-xl border border-slate-200 dark:border-white/10 p-4 text-left hover:border-primary-300 transition"><div class="flex items-start justify-between gap-3"><span class="w-10 h-10 rounded-xl bg-slate-100 dark:bg-white/10 flex items-center justify-center"><i class="fas ${escapeHtml(card.icon||'fa-circle')} text-primary-500"></i></span><span class="px-2 py-0.5 rounded-full text-[11px] ${missionToneClass(card.status)}">${escapeHtml(card.label||'待检查')}</span></div><h3 class="mt-3 font-semibold">${escapeHtml(card.title||'能力')}</h3><p class="mt-1 text-xs leading-5 text-slate-500 line-clamp-2">${escapeHtml(card.summary||'')}</p><div class="mt-3 text-xs text-primary-500">${escapeHtml(card.action_label||'打开')} <i class="fas fa-arrow-right ml-1"></i></div></button>`).join('')||'<div class="py-8 text-center text-slate-400">暂无能力状态</div>';}
function missionTodayTaskNotice(message,tone='blue'){const box=document.getElementById('mission-command-result');if(!box)return;missionCommandNotice(message,tone);}
async function runMissionTodayTask(kind,taskId,button){const old=button?.innerHTML;if(button){button.disabled=true;button.innerHTML='<i class="fas fa-spinner fa-spin mr-1"></i>执行中';}try{const response=await fetch('/api/mission-control',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'today_task_run',kind,task_id:taskId})});const data=await response.json();if(data.status!=='success')throw new Error(data.message||'执行失败');missionTodayTaskNotice(data.message||'任务已执行，结果已记录','green');await Promise.all([loadMissionControl?.(true),loadAutomationRuns?.().catch(()=>{}),loadAutomationRecords?.(true).catch(()=>{}),loadNotificationCenter?.().catch(()=>{})]);if(data.run_id)setTimeout(()=>showMissionTodayTaskRun(data.run_id),200);return data;}catch(error){missionTodayTaskNotice(`执行失败：${error.message||String(error)}`,'red');throw error;}finally{if(button){button.disabled=false;button.innerHTML=old;}}}
async function toggleMissionTodayTask(kind,taskId,enabled,button){const old=button?.innerHTML;if(button){button.disabled=true;button.innerHTML='<i class="fas fa-spinner fa-spin mr-1"></i>处理中';}try{const response=await fetch('/api/mission-control',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'today_task_toggle',kind,task_id:taskId,enabled})});const data=await response.json();if(data.status!=='success')throw new Error(data.message||'操作失败');missionTodayTaskNotice(data.message||'任务状态已更新','green');await loadMissionControl?.(true);return data;}catch(error){missionTodayTaskNotice(`操作失败：${error.message||String(error)}`,'red');}finally{if(button){button.disabled=false;button.innerHTML=old;}}}
function showMissionTodayTaskRun(runId){if(!runId){missionControlOpen('runs');return;}navigateTo('intelligence');setTimeout(async()=>{switchAutomationTab?.('runs');await loadAutomationRuns?.();showAutomationRun?.(runId);},120);}
function openMissionTodayTask(kind,taskId){navigateTo('intelligence');setTimeout(async()=>{switchAutomationTab?.('tasks');await loadAutomationTasks?.();const safe=window.CSS&&CSS.escape?CSS.escape(taskId):String(taskId).replace(/["\\]/g,'\\$&');const target=document.querySelector(`[data-automation-task="${safe}"],[data-task-id="${safe}"]`);highlightAutomationLinkedNode?.(target,'已打开对应自动化任务');},120);}
function renderMissionTodayTasks(items){const host=document.getElementById('mission-control-today-tasks');if(!host)return;items=(items||[]).slice(0,5);host.innerHTML=items.length?items.map(item=>{const kind=escapeHtml(item.kind||''),taskId=escapeHtml(item.id||''),runId=escapeHtml(item.latest_run_id||'');return `<div class="w-full py-3 rounded-xl px-2 -mx-2 hover:bg-slate-50 dark:hover:bg-white/5"><div class="flex items-start justify-between gap-3"><button onclick="openMissionTodayTask('${kind}','${taskId}')" class="min-w-0 flex-1 text-left"><div class="flex flex-wrap items-center gap-2"><b class="text-sm truncate">${escapeHtml(item.name||'未命名任务')}</b><span class="px-2 py-0.5 rounded-full text-[10px] ${missionToneClass(item.status||'success')}">${escapeHtml(item.status_label||'已启用')}</span></div><p class="mt-1 text-xs text-slate-500 line-clamp-2">${escapeHtml(item.summary||item.type||'等待下一次执行')}</p></button><span class="shrink-0 text-[11px] text-slate-400">${escapeHtml(item.next_run_text||item.next_run||'待调度')}</span></div><div class="mt-3 flex flex-wrap gap-2"><button onclick="runMissionTodayTask('${kind}','${taskId}',this)" class="px-2.5 py-1 rounded-lg bg-primary-600 text-white text-[11px]"><i class="fas fa-play mr-1"></i>立即执行</button><button onclick="toggleMissionTodayTask('${kind}','${taskId}',false,this)" class="px-2.5 py-1 rounded-lg border border-slate-200 dark:border-white/10 text-[11px]"><i class="fas fa-pause mr-1"></i>暂停</button><button onclick="showMissionTodayTaskRun('${runId}')" class="px-2.5 py-1 rounded-lg border border-slate-200 dark:border-white/10 text-[11px]"><i class="fas fa-clock-rotate-left mr-1"></i>看结果</button></div></div>`;}).join(''):'<div class="py-10 text-center text-slate-400">暂无启用任务，可用一句话创建今天的自动化。</div>';}
function renderMissionMessageStatus(data){const host=document.getElementById('mission-control-message-status');if(!host)return;const remote=data.remote_bridge||{},summary=data.summary||{},maintenance=data.maintenance||{},notifications=maintenance.notifications||{};const weixinFailures=(data.weixin_failure_learning||[]).reduce((n,item)=>n+Number(item.count||0),0);const remoteLabel=remote.pending?`${remote.pending} 条待处理`:(remote.failed?`${remote.failed} 条需复查`:(remote.enabled?'已启用':'待配置'));const remoteSummary=[remote.summary||'手机、云端、多设备指令统一进入任务路由。',remote.devices?`已绑定设备 ${remote.devices} 台，在线 ${remote.active_devices||0} 台。`:'' ].filter(Boolean).join(' ');const items=[{title:'助理小爱',icon:'fab fa-weixin',status:weixinFailures?'warning':'success',label:weixinFailures?`${weixinFailures} 次需关注`:'运行观察中',summary:weixinFailures?'最近微信端有失败学习记录，建议查看 Agent 2.0 学习面板。':'微信端暂无明显高频失败。',target:'weixin-assistant'},{title:'远程 Bridge',icon:'fas fa-tower-cell',status:remote.pending?'warning':(remote.failed?'error':(remote.enabled?'success':'warning')),label:remoteLabel,summary:remoteSummary,target:'remote-bridge'},{title:'通知通道',icon:'fas fa-bell',status:(notifications.status==='warning'||summary.unread_messages)?'warning':'success',label:summary.unread_messages?`${summary.unread_messages} 条提醒`:(notifications.status==='warning'?'需关注':'正常'),summary:notifications.summary||'Web、微信、Webhook、邮箱用于发送任务结果。',target:'channels'}];host.innerHTML=items.map(item=>`<button onclick="missionControlOpen('${escapeHtml(item.target)}')" class="w-full rounded-xl border border-slate-200 dark:border-white/10 p-3 text-left hover:bg-slate-50 dark:hover:bg-white/5"><div class="flex items-center justify-between gap-2"><div class="flex items-center gap-2"><span class="w-8 h-8 rounded-lg bg-slate-100 dark:bg-white/10 flex items-center justify-center"><i class="${item.icon} text-primary-500 text-xs"></i></span><b class="text-sm">${escapeHtml(item.title)}</b></div><span class="px-2 py-0.5 rounded-full text-[10px] ${missionToneClass(item.status)}">${escapeHtml(item.label)}</span></div><p class="mt-2 text-xs leading-5 text-slate-500">${escapeHtml(item.summary)}</p></button>`).join('');}
function renderMissionLearning(data){const host=document.getElementById('mission-control-learning');if(!host)return;const learning=data.agent_learning||{},summary=learning.summary||{},skills=learning.reliable_skills||[],deprioritized=learning.deprioritized_skills||[],recoveries=learning.recovery_paths||[],successes=learning.weixin_success_learning||[],failures=learning.weixin_failure_learning||[];const pct=value=>`${Math.round(Number(value||0)*100)}%`;const bestSkill=skills[0]||null;const weakSkill=deprioritized[0]||skills.find(item=>Number(item.recent_failures||0)>0)||null;const recovery=recoveries.find(item=>Number(item.successes||0)>0)||recoveries[0]||null;const wxSuccess=successes[0]||null,wxFailure=failures[0]||null;const cards=[{title:'可靠能力',icon:'fa-shield-check',tone:'success',label:bestSkill?`${pct(bestSkill.success_rate)} 成功率`:'待积累',body:bestSkill?`${bestSkill.name||'Skill'} 已验证 ${Number(bestSkill.successes||0)}/${Number(bestSkill.total||0)} 次，后续会优先复用。`:`暂无足够 Skill 成功率样本，系统会继续从真实执行里学习。`},{title:'降权提醒',icon:'fa-arrow-trend-down',tone:weakSkill?'warning':'success',label:weakSkill?(weakSkill.rollback_count?`回滚 ${weakSkill.rollback_count} 次`:`失败 ${weakSkill.recent_failures||0} 次`):'暂无降权',body:weakSkill?`${weakSkill.name||'相关能力'} ${weakSkill.last_reason||'近期不够稳定，路由会降低优先级。'}`:'目前没有明显需要降权的 Skill 或工具。'},{title:'有效恢复路径',icon:'fa-route',tone:recovery?'success':'warning',label:recovery?`成功 ${Number(recovery.successes||0)} 次`:'待验证',body:recovery?`${recovery.category||'失败恢复'}：${recovery.action||'已记录可复用恢复动作'}。`:'暂无恢复成功样本，后续任务兜底成功后会自动沉淀。'},{title:'微信端经验',icon:'fa-comments',tone:Number(summary.weixin_failures||0)?'warning':'success',label:`成功 ${Number(summary.weixin_success||0)} / 失败 ${Number(summary.weixin_failures||0)}`,body:wxSuccess?`${wxSuccess.label||wxSuccess.action||'微信成功路径'} 可优先复用。${wxFailure?` 需关注：${wxFailure.label||wxFailure.category||'微信失败'}`:''}`:(wxFailure?`${wxFailure.label||wxFailure.category||'微信失败'} 近期较多，系统会优先尝试恢复路径。`:'微信端暂无明显失败学习记录。')}];const toneClass={success:'bg-emerald-50 text-emerald-600 dark:bg-emerald-500/10',warning:'bg-orange-50 text-orange-600 dark:bg-orange-500/10',error:'bg-red-50 text-red-600 dark:bg-red-500/10',info:'bg-blue-50 text-blue-600 dark:bg-blue-500/10'};host.innerHTML=cards.map(card=>`<button onclick="missionControlOpen('agent2')" class="rounded-2xl border border-white/70 dark:border-white/10 bg-white/85 dark:bg-[#181818]/80 p-4 text-left hover:border-indigo-300 transition"><div class="flex items-center justify-between gap-2"><span class="w-9 h-9 rounded-xl ${toneClass[card.tone]||toneClass.info} flex items-center justify-center"><i class="fas ${escapeHtml(card.icon)} text-xs"></i></span><span class="rounded-full px-2 py-0.5 text-[10px] ${toneClass[card.tone]||toneClass.info}">${escapeHtml(card.label)}</span></div><h3 class="mt-3 text-sm font-semibold">${escapeHtml(card.title)}</h3><p class="mt-1 text-xs leading-5 text-slate-500 line-clamp-3">${escapeHtml(card.body)}</p></button>`).join('');}
function renderMissionRuns(runs){const host=document.getElementById('mission-control-runs');if(!host)return;host.innerHTML=(runs||[]).map(run=>`<div class="py-3"><div class="flex items-start justify-between gap-3"><div class="min-w-0"><div class="flex flex-wrap items-center gap-2"><b class="text-sm truncate">${escapeHtml(run.task_name||'未命名任务')}</b><span class="px-2 py-0.5 rounded-full text-[10px] ${missionToneClass(run.status)}">${escapeHtml(run.status_label||run.status||'未知')}</span>${run.notification_warning?'<span class="px-2 py-0.5 rounded-full text-[10px] bg-orange-50 text-orange-600 dark:bg-orange-500/10">通知兜底</span>':''}</div><p class="mt-1 text-xs leading-5 text-slate-500 line-clamp-2">${escapeHtml(run.summary||'')}</p>${run.recovery_summary?`<p class="mt-1 text-[11px] text-cyan-600"><i class="fas fa-shield-heart mr-1"></i>${escapeHtml(run.recovery_summary)}</p>`:''}</div><span class="shrink-0 text-[11px] text-slate-400">${escapeHtml(missionShortTime(run.at))}</span></div></div>`).join('')||'<div class="py-12 text-center text-slate-400">暂无执行记录</div>';}
function renderMissionArtifacts(items){const host=document.getElementById('mission-control-artifacts');if(!host)return;host.innerHTML=(items||[]).map(item=>`<button onclick="missionControlOpen('artifacts')" class="w-full py-3 text-left"><div class="flex items-start justify-between gap-3"><div class="min-w-0"><div class="flex flex-wrap items-center gap-2"><b class="text-sm truncate">${escapeHtml(item.title||'未命名产物')}</b><span class="px-2 py-0.5 rounded-full bg-slate-100 text-slate-500 dark:bg-white/5 text-[10px]">${escapeHtml(item.type||'产物')}</span>${Number(item.size_kb||0)?`<span class="text-[10px] text-slate-400">${Number(item.size_kb||0)}KB</span>`:''}</div><p class="mt-1 text-xs leading-5 text-slate-500 line-clamp-2">${escapeHtml(item.preview||'')}</p></div><span class="shrink-0 text-[11px] text-slate-400">${escapeHtml(missionShortTime(item.created_at))}</span></div></button>`).join('')||'<div class="py-12 text-center text-slate-400">暂无产物记录</div>';}
async function loadMissionControl(force=false){const subtitle=document.getElementById('mission-control-subtitle');if(!document.getElementById('view-mission-control'))return;if(force){document.getElementById('mission-control-summary').innerHTML='<div class="xl:col-span-6 py-10 text-center text-primary-500"><i class="fas fa-spinner fa-spin mr-2"></i>正在刷新仪表盘…</div>';['mission-control-actions','mission-control-todos','mission-control-cards','mission-control-runs','mission-control-artifacts','mission-control-today-tasks','mission-control-message-status','mission-control-learning','mission-control-instance-alert'].forEach(id=>{const node=document.getElementById(id);if(node)node.innerHTML='';});}try{const response=await fetch('/api/mission-control');const data=await response.json();if(data.status!=='success')throw new Error(data.message||'仪表盘加载失败');if(subtitle)subtitle.textContent=`${data.overall==='success'?'今天整体正常':data.overall==='error'?'存在阻断项':'今天有事项需关注'} · 更新时间 ${missionShortTime(data.checked_at)}`;renderMissionInstanceAlertV2(data);renderMissionSummary(data);renderMissionTodayTasks(data.today_tasks);renderMissionActions(data.quick_actions);renderMissionTodos(data.todos);renderMissionMessageStatus(data);renderMissionLearning(data);renderMissionCards(data.cards);renderMissionRuns(data.recent_runs);renderMissionArtifacts(data.recent_artifacts);renderMissionCommandLearning(data.command_learning);renderMissionWeixinLearning(data.weixin_failure_learning);}catch(error){if(subtitle)subtitle.textContent='仪表盘加载失败';document.getElementById('mission-control-summary').innerHTML=`<div class="xl:col-span-6 rounded-2xl border border-red-200 bg-red-50 dark:bg-red-500/10 p-5 text-red-600">仪表盘加载失败：${escapeHtml(error.message||String(error))}</div>`;}}

let commonFunctionCategory='all';
let commonCapabilitySuggestions=[];
function commonSuggestionScore(target){const item=(commonCapabilitySuggestions||[]).find(x=>x.target===target)||{},stats=item.stats||{};return Number(item.learned_score||0)+Number(stats.opens||0)*3+Number(item.pinned?20:0);}
function recordCommonSuggestionEvent(target,result){try{fetch('/api/agent/capability-summary',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'open',target:target||result||''})}).catch(()=>{});}catch(_){}}
function commonFunctionLearningTarget(id){const map={'network-search':'network-search','deep-research':'profile_briefing','agent-reach':'agent-reach','tool-connector':'agent-reach','website-monitor':'network-search','forex-query':'network-search','ops-agent':'maintenance'};return map[id]||id;}
function showCommonFunctionsHome(){document.getElementById('common-functions-heading')?.classList.remove('hidden');document.getElementById('common-functions-home')?.classList.remove('hidden');document.getElementById('common-function-grid')?.classList.remove('hidden');document.getElementById('common-function-search')?.classList.remove('hidden');document.querySelectorAll('section[id^="common-function-"]').forEach(node=>node.classList.add('hidden'));const input=document.getElementById('common-function-search');if(input)input.value='';commonFunctionCategory='all';document.querySelectorAll('.common-function-filter').forEach(button=>{const active=button.dataset.category==='all';button.classList.toggle('bg-slate-900',active);button.classList.toggle('text-white',active);button.classList.toggle('bg-slate-100',!active);});filterCommonFunctions('');loadCommonCapabilityOverview?.();document.getElementById('view-common-functions')?.querySelector('.overflow-y-auto')?.scrollTo({top:0});}
function commonCapabilityStatusClass(status){if(status==='success')return 'bg-emerald-50 text-emerald-600 dark:bg-emerald-500/10 dark:text-emerald-300';if(status==='error')return 'bg-red-50 text-red-600 dark:bg-red-500/10 dark:text-red-300';return 'bg-orange-50 text-orange-600 dark:bg-orange-500/10 dark:text-orange-300';}
function openCommonCapabilityTarget(target){if(target==='intelligence'){navigateTo('intelligence');return;}if(target==='remote-bridge'){openSettingsCenter?.();setTimeout(()=>showSettingsView?.('remote-bridge','远程 Bridge'),60);return;}if(target==='channels'){openSettingsCenter?.();setTimeout(()=>showSettingsView?.('channels','通道与连接'),60);return;}if(target==='maintenance'){openSettingsCenter?.();setTimeout(()=>showSettingsView?.('maintenance','维护看板'),80);return;}if(target==='agent2'){navigateTo('intelligence');setTimeout(()=>{switchAutomationTab?.('agent2');loadAgent2Dashboard?.();},80);return;}if(target==='agent-reach'){navigateTo('common-functions');setTimeout(()=>openCommonFunction('agent-reach'),80);return;}if(target==='artifacts'){navigateTo('artifacts');return;}}
function recordCommonSuggestionOpen(target){if(!target)return;fetch('/api/agent/capability-summary',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({target,action:'open'})}).then(r=>r.json()).then(data=>{if(data.status==='success')commonCapabilitySuggestions=data.suggestions||commonCapabilitySuggestions;}).catch(()=>{});}
function openCommonSuggestionTarget(target){const suggestion=(commonCapabilitySuggestions||[]).find(item=>item.target===target)||{};recordCommonSuggestionOpen(target);if(suggestion.prompt){navigateTo('intelligence');setTimeout(()=>{openTaskCreator?.();const input=document.getElementById('natural-task-prompt');if(input){input.value=suggestion.prompt;input.dispatchEvent(new Event('input',{bubbles:true}));parseNaturalTask?.();}},120);return;}if(target==='failed_runs'){navigateTo('intelligence');setTimeout(()=>{switchAutomationTab?.('runs');const status=document.getElementById('automation-run-status');if(status)status.value='failed';loadAutomationRuns?.();},100);return;}if(target==='morning_briefing'){navigateTo('intelligence');setTimeout(()=>{openTaskCreator?.();const input=document.getElementById('natural-task-prompt');if(input){input.value='每天早上 08:00 生成个人早间简报，内容包括 AI、科技、创业方向最新重要信息，去重后输出 5 条，结果发送到当前 Web 会话。';input.dispatchEvent(new Event('input',{bubbles:true}));parseNaturalTask?.();}},120);return;}if(target==='network-search'){navigateTo('common-functions');setTimeout(()=>openCommonFunction('network-search'),80);return;}if(target==='templates'){navigateTo('intelligence');setTimeout(()=>switchAutomationTab?.('templates'),100);return;}openCommonCapabilityTarget(target);}
function refreshCommonSuggestionBlocks(data){commonCapabilitySuggestions=data.suggestions||commonCapabilitySuggestions;document.querySelectorAll('#welcome-suggestion-content').forEach(node=>node.innerHTML=renderCommonSuggestions(commonCapabilitySuggestions,true));document.querySelectorAll('#common-capability-overview-actions').forEach(node=>{const quick=(data.quick_actions||[]).map(item=>`<button onclick="openCommonCapabilityTarget('${escapeHtml(item.target||'')}')" class="px-3 py-1.5 rounded-lg bg-slate-900 text-white dark:bg-white dark:text-slate-900 text-xs"><i class="fas ${escapeHtml(item.icon||'fa-bolt')} mr-1"></i>${escapeHtml(item.label||'快捷动作')}</button>`).join('');node.innerHTML=`<div class="w-full text-xs font-semibold text-slate-500 mb-1"><i class="fas fa-lightbulb text-amber-500 mr-1"></i>今天建议你先做</div><div class="w-full grid sm:grid-cols-2 xl:grid-cols-4 gap-2">${renderCommonSuggestions(commonCapabilitySuggestions,false)}</div><div class="w-full mt-1 flex flex-wrap gap-2">${quick}</div>`;});}
async function updateCommonSuggestionPreference(target,action,event){event?.stopPropagation?.();if(!target)return;try{const response=await fetch('/api/agent/capability-summary',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({target,action})}),data=await response.json();if(data.status!=='success')throw new Error(data.message||'建议偏好保存失败');refreshCommonSuggestionBlocks(data);_wsToast?.(action==='pin'?'已置顶建议':action==='unpin'?'已取消置顶':action==='dislike'?'后续将减少类似推荐':'已关闭该建议');}catch(error){alert(error.message||String(error));}}
async function resetCommonSuggestionPreferences(event){event?.stopPropagation?.();try{const response=await fetch('/api/agent/capability-summary',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'reset'})}),data=await response.json();if(data.status!=='success')throw new Error(data.message||'重置推荐失败');refreshCommonSuggestionBlocks(data);_wsToast?.('推荐偏好已重置');}catch(error){alert(error.message||String(error));}}
function renderCommonSuggestions(items,compact=false){items=items||[];if(!items.length)return '<div class="rounded-xl border border-dashed border-slate-200 dark:border-white/10 p-3 text-xs text-slate-400">暂无建议，点击刷新能力状态后再看。</div>';const tone={red:'border-red-100 bg-red-50/70 text-red-600 dark:border-red-500/20 dark:bg-red-500/10',cyan:'border-cyan-100 bg-cyan-50/70 text-cyan-600 dark:border-cyan-500/20 dark:bg-cyan-500/10',amber:'border-amber-100 bg-amber-50/70 text-amber-600 dark:border-amber-500/20 dark:bg-amber-500/10',blue:'border-blue-100 bg-blue-50/70 text-blue-600 dark:border-blue-500/20 dark:bg-blue-500/10',emerald:'border-emerald-100 bg-emerald-50/70 text-emerald-600 dark:border-emerald-500/20 dark:bg-emerald-500/10',indigo:'border-indigo-100 bg-indigo-50/70 text-indigo-600 dark:border-indigo-500/20 dark:bg-indigo-500/10',slate:'border-slate-100 bg-slate-50/70 text-slate-600 dark:border-white/10 dark:bg-white/5'};return items.map(item=>{const target=escapeHtml(item.target||''),pinAction=item.pinned?'unpin':'pin',pinTitle=item.pinned?'取消置顶':'置顶',stats=item.stats||{},opens=Number(stats.opens||0),dismisses=Number(stats.dismisses||0)+Number(stats.dislikes||0),success=Number(stats.outcome_success||0),failed=Number(stats.outcome_failed||0),empty=Number(stats.outcome_empty||0),notifyWarn=Number(stats.outcome_notification_warning||0),outcomeText=success||failed||empty||notifyWarn?`成功 ${success} · 空 ${empty} · 失败 ${failed}${notifyWarn?` · 通知异常 ${notifyWarn}`:''}`:'',statText=opens||dismisses?`已点 ${opens} 次${dismisses?` · 已忽略 ${dismisses} 次`:''}`:'';return `<article class="rounded-xl border ${tone[item.tone]||tone.slate} p-3 text-left hover:shadow-sm transition group"><button onclick="openCommonSuggestionTarget('${target}')" class="w-full text-left"><div class="flex items-start justify-between gap-2"><span class="flex items-center gap-2 min-w-0"><i class="fas ${escapeHtml(item.icon||'fa-bolt')}"></i><b class="${compact?'text-xs':'text-sm'} truncate">${escapeHtml(item.title||'建议操作')}</b>${item.pinned?'<span class="shrink-0 rounded-full bg-white/70 dark:bg-black/10 px-1.5 py-0.5 text-[10px] text-amber-500">置顶</span>':''}</span><i class="fas fa-arrow-right text-[10px] opacity-50 mt-1"></i></div><p class="mt-1 ${compact?'text-[11px]':'text-xs'} leading-5 text-slate-500 dark:text-slate-300 line-clamp-2">${escapeHtml(item.summary||'')}</p><div class="mt-2 flex flex-wrap gap-1.5">${item.reason?`<span class="inline-flex items-center rounded-full bg-white/70 dark:bg-black/10 px-2 py-0.5 text-[10px] text-slate-400"><i class="fas fa-circle-info mr-1"></i>${escapeHtml(item.reason)}</span>`:''}${statText?`<span class="inline-flex items-center rounded-full bg-white/70 dark:bg-black/10 px-2 py-0.5 text-[10px] text-primary-500"><i class="fas fa-chart-simple mr-1"></i>${escapeHtml(statText)}</span>`:''}${outcomeText?`<span class="inline-flex items-center rounded-full bg-white/70 dark:bg-black/10 px-2 py-0.5 text-[10px] ${failed||empty?'text-orange-500':'text-emerald-500'}"><i class="fas fa-check-double mr-1"></i>${escapeHtml(outcomeText)}</span>`:''}</div></button><div class="mt-2 flex flex-wrap gap-1.5 opacity-80"><button onclick="updateCommonSuggestionPreference('${target}','${pinAction}',event)" class="px-2 py-0.5 rounded-md bg-white/70 dark:bg-black/10 text-[10px] text-slate-500 hover:text-primary-500"><i class="fas fa-thumbtack mr-1"></i>${pinTitle}</button><button onclick="updateCommonSuggestionPreference('${target}','dislike',event)" class="px-2 py-0.5 rounded-md bg-white/70 dark:bg-black/10 text-[10px] text-slate-500 hover:text-orange-500">不感兴趣</button><button onclick="updateCommonSuggestionPreference('${target}','dismiss',event)" class="px-2 py-0.5 rounded-md bg-white/70 dark:bg-black/10 text-[10px] text-slate-500 hover:text-red-500">关闭</button></div></article>`;}).join('');}
async function loadCommonCapabilityOverview(force=false){
    const host=document.getElementById('common-capability-overview-content'),subtitle=document.getElementById('common-capability-overview-subtitle'),actions=document.getElementById('common-capability-overview-actions');
    if(!host)return;
    if(force||!host.dataset.loaded)host.innerHTML='<div class="md:col-span-2 xl:col-span-3 text-sm text-primary-500"><i class="fas fa-spinner fa-spin mr-1"></i>正在刷新能力状态…</div>';
    try{
        const data=await apiFetch('/api/agent/capability-summary'),cards=data.cards||[];
        commonCapabilitySuggestions=data.suggestions||[];
        if(subtitle)subtitle.textContent=`${data.overall==='success'?'整体可用':data.overall==='error'?'存在阻断项':'部分能力需关注'} · 更新时间 ${String(data.checked_at||'').replace('T',' ').slice(0,19)}`;
        host.dataset.loaded='1';
        host.innerHTML=cards.map(card=>`<button onclick="openCommonCapabilityTarget('${escapeHtml(card.target||'')}')" class="text-left rounded-xl border border-slate-200 dark:border-white/10 bg-white/80 dark:bg-[#1a1a1a] p-4 hover:border-primary-300 transition"><div class="flex items-start justify-between gap-3"><div class="w-10 h-10 rounded-xl bg-slate-100 dark:bg-white/10 flex items-center justify-center"><i class="fas ${escapeHtml(card.icon||'fa-circle')} text-primary-500"></i></div><span class="rounded-full px-2 py-0.5 text-[11px] ${commonCapabilityStatusClass(card.status)}">${escapeHtml(card.label||'待检查')}</span></div><div class="mt-3 font-semibold">${escapeHtml(card.title||'能力')}</div><p class="mt-1 text-xs leading-5 text-slate-500 line-clamp-2">${escapeHtml(card.summary||'')}</p><div class="mt-3 text-xs text-primary-500">${escapeHtml(card.action_label||'打开')} <i class="fas fa-arrow-right ml-1"></i></div></button>`).join('');
        if(actions){
            const quick=(data.quick_actions||[]).map(item=>`<button onclick="openCommonCapabilityTarget('${escapeHtml(item.target||'')}')" class="px-3 py-1.5 rounded-lg bg-slate-900 text-white dark:bg-white dark:text-slate-900 text-xs"><i class="fas ${escapeHtml(item.icon||'fa-bolt')} mr-1"></i>${escapeHtml(item.label||'快捷动作')}</button>`).join('');
            actions.innerHTML=`<div class="w-full text-xs font-semibold text-slate-500 mb-1"><i class="fas fa-lightbulb text-amber-500 mr-1"></i>今天建议你先做</div><div class="w-full grid sm:grid-cols-2 xl:grid-cols-4 gap-2">${renderCommonSuggestions(commonCapabilitySuggestions,false)}</div><div class="w-full mt-1 flex flex-wrap gap-2">${quick}</div>`;
        }
        filterCommonFunctions(document.getElementById('common-function-search')?.value||'');
    }catch(error){
        if(subtitle)subtitle.textContent='能力看板加载失败，不影响下方常用功能使用';
        host.innerHTML=`<div class="md:col-span-2 xl:col-span-3 rounded-xl bg-orange-50 dark:bg-orange-500/10 p-3 text-sm text-orange-600">能力状态读取失败：${escapeHtml(error.message||String(error))}</div>`;
    }
}
async function loadWelcomeCapabilityOverview(force=false){const host=document.getElementById('welcome-capability-content'),subtitle=document.getElementById('welcome-capability-subtitle'),suggestions=document.getElementById('welcome-suggestion-content');if(!host)return;if(force||!host.dataset.loaded){host.innerHTML='<div class="sm:col-span-2 lg:col-span-3 text-xs text-primary-500"><i class="fas fa-spinner fa-spin mr-1"></i>正在刷新能力状态…</div>';}try{const data=await apiFetch('/api/agent/capability-summary');const cards=(data.cards||[]).slice(0,6);commonCapabilitySuggestions=data.suggestions||[];if(subtitle)subtitle.textContent=`${data.overall==='success'?'整体可用':data.overall==='error'?'有能力需要处理':'部分能力需关注'} · 下方已给出建议动作`;host.dataset.loaded='1';host.innerHTML=cards.map(card=>`<button onclick="openCommonCapabilityTarget('${escapeHtml(card.target||'')}')" class="rounded-xl border border-slate-100 dark:border-white/10 bg-slate-50/70 dark:bg-white/[0.03] p-3 text-left hover:border-primary-300 transition"><div class="flex items-center justify-between gap-2"><span class="inline-flex items-center gap-2 min-w-0"><i class="fas ${escapeHtml(card.icon||'fa-circle')} text-primary-500"></i><b class="text-xs truncate">${escapeHtml(card.title||'能力')}</b></span><span class="shrink-0 rounded-full px-2 py-0.5 text-[10px] ${commonCapabilityStatusClass(card.status)}">${escapeHtml(card.label||'待检查')}</span></div><p class="mt-2 text-[11px] leading-5 text-slate-500 line-clamp-2">${escapeHtml(card.summary||'')}</p></button>`).join('');if(suggestions) suggestions.innerHTML=renderCommonSuggestions(commonCapabilitySuggestions,true);}catch(error){if(subtitle)subtitle.textContent='能力状态暂时读取失败，不影响正常对话';host.innerHTML=`<div class="sm:col-span-2 lg:col-span-3 rounded-xl bg-orange-50 dark:bg-orange-500/10 p-3 text-xs text-orange-600">${escapeHtml(error.message||String(error))}</div>`;if(suggestions)suggestions.innerHTML='';}}
function openCommonFunction(id){const section=document.getElementById(`common-function-${id}`);if(!section)return;document.getElementById('common-functions-heading')?.classList.add('hidden');document.getElementById('common-functions-home')?.classList.add('hidden');document.querySelectorAll('section[id^="common-function-"]').forEach(x=>x.classList.add('hidden'));section.classList.remove('hidden');if(id==='network-search')loadNetworkSearchAgent();if(id==='tech-briefing')loadTechBriefing();if(id==='deep-research')loadDeepResearchAgent();if(id==='agent-reach')loadAgentReach();if(id==='quick-learning')loadQuickLearning();if(id==='fast-reading')loadFastReading();if(id==='media-assistant')loadMediaAssistant();if(id==='tool-connector')loadToolConnectorCenter();if(id==='browser-agent')loadBrowserAgent();if(id==='desktop-agent')loadDesktopAgent();if(id==='code-agent')loadCodeAgent();if(id==='ops-agent')loadOpsAgent();if(id==='website-monitor')loadCommonWebsiteMonitor();if(id==='forex-query'){loadForexTasks();loadForexNotificationChannels();updateForexMode();}section.closest('.overflow-y-auto')?.scrollTo({top:0,behavior:'smooth'});}
function loadQuickLearning(){const status=document.getElementById('quick-learning-status');if(status&&!status.textContent)status.textContent='粘贴公众号文章或网页链接后，点击“立即学习”。';}
function quickLearningPayload(){return {url:(document.getElementById('quick-learning-url')?.value||'').trim(),goal:(document.getElementById('quick-learning-goal')?.value||'').trim(),modes:[...document.querySelectorAll('.quick-learning-mode:checked')].map(x=>x.value),save_artifact:Boolean(document.getElementById('quick-learning-save-artifact')?.checked)};}
function resetQuickLearning(){['quick-learning-url','quick-learning-goal'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});document.querySelectorAll('.quick-learning-mode').forEach(box=>{box.checked=['summary','notes','methods','actions'].includes(box.value);});const save=document.getElementById('quick-learning-save-artifact');if(save)save.checked=true;const result=document.getElementById('quick-learning-result');if(result){result.classList.add('hidden');result.textContent='';}const status=document.getElementById('quick-learning-status');if(status){status.className='min-h-5 mt-3 text-sm text-slate-500';status.textContent='已清空，可继续粘贴新的文章链接。';}}
async function runQuickLearning(){
    const payload=quickLearningPayload(),status=document.getElementById('quick-learning-status'),resultBox=document.getElementById('quick-learning-result');
    if(!payload.url){
        if(status){status.className='min-h-5 mt-3 text-sm text-red-500';status.textContent='请先粘贴公众号文章或网页链接。';}
        document.getElementById('quick-learning-url')?.focus();return;
    }
    const started=Date.now();
    let timer=null;
    const setRunningStatus=()=>{
        if(!status)return;
        const seconds=Math.floor((Date.now()-started)/1000);
        const phase=seconds<10?'正在提取正文':seconds<45?'正在提炼学习笔记':'正在保存产物，马上完成';
        status.className='min-h-5 mt-3 text-sm text-blue-600';
        status.textContent=`${phase}… 已用时 ${seconds}s`;
    };
    setRunningStatus();
    timer=setInterval(setRunningStatus,1000);
    if(resultBox){resultBox.classList.add('hidden');resultBox.textContent='';}
    try{
        const data=await intelligenceRequest('/api/intelligence/quick-learning',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});
        if(resultBox){resultBox.textContent=data.summary_note||data.note||'学习笔记已生成。';resultBox.classList.remove('hidden');}
        if(status){
            status.className='min-h-5 mt-3 text-sm text-emerald-600';
            const t=data.timings||{};
            const detail=t.fetch_seconds!=null?`（提取 ${t.fetch_seconds}s，生成 ${t.note_seconds||0}s）`:'';
            status.textContent=(data.message||'学习完成')+detail;
        }
        recordCommonSuggestionEvent?.('quick-learning','success');
    }catch(error){
        if(status){status.className='min-h-5 mt-3 text-sm text-red-500';status.textContent=`学习失败：${error.message||error}`;}
        recordCommonSuggestionEvent?.('quick-learning','failed');
    }finally{
        if(timer)clearInterval(timer);
    }
}
function copyQuickLearningResult(){const text=document.getElementById('quick-learning-result')?.textContent||'';if(!text.trim()){const status=document.getElementById('quick-learning-status');if(status){status.className='min-h-5 mt-3 text-sm text-amber-600';status.textContent='当前还没有可复制的学习结果。';}return;}navigator.clipboard?.writeText(text);const status=document.getElementById('quick-learning-status');if(status){status.className='min-h-5 mt-3 text-sm text-emerald-600';status.textContent='已复制学习笔记。';}}
function insertQuickLearningPrompt(){const payload=quickLearningPayload();if(!payload.url){document.getElementById('quick-learning-url')?.focus();return;}const modes=payload.modes.length?payload.modes.join('、'):'快速摘要、学习笔记、行动建议';const prompt=`请使用“快速学习 Agent”学习这篇文章：${payload.url}\n学习方式：${modes}\n学习目标：${payload.goal||'帮我缩短学习时间，提炼文章核心信息、值得学习的内容、可以复用的方法，并给出可直接落地的行动。'}\n要求：不要摘抄原文，不要只做摘要；请像 AI 学习助手一样，用自己的话告诉我这篇文章讲什么、我应该学什么、我可以怎么复用，并保存到产物/交付物。`;navigateTo('chat');chatInput.value=prompt;chatInput.dispatchEvent(new Event('input',{bubbles:true}));chatInput.focus();}

