const SHARED_SOURCE_CATALOG_KEY='cow_shared_source_catalog_v1';
function loadSharedSourceCatalog(){try{const saved=JSON.parse(localStorage.getItem(SHARED_SOURCE_CATALOG_KEY)||'null');if(saved&&typeof saved==='object'&&!Array.isArray(saved))return saved;}catch(error){}return JSON.parse(JSON.stringify(DEFAULT_SHARED_SOURCE_CATALOG));}
let sharedSourceCatalog=loadSharedSourceCatalog();
function saveSharedSourceCatalog(){localStorage.setItem(SHARED_SOURCE_CATALOG_KEY,JSON.stringify(sharedSourceCatalog));}
let sharedSourceSelection=new Set();
function sharedSourceEntries(){return Object.entries(sharedSourceCatalog).flatMap(([category,items])=>items.map(([name,url])=>({category,name,url})));}
function openSharedSourceCatalog(){document.getElementById('shared-source-catalog-modal')?.remove();const active=new Set(networkSearchTags.sites.map(normalizeNetworkSite));sharedSourceSelection=new Set(sharedSourceEntries().filter(x=>active.has(normalizeNetworkSite(x.url))).map(x=>x.url));const modal=document.createElement('div');modal.id='shared-source-catalog-modal';modal.className='fixed inset-0 z-[240] bg-black/45 p-4 flex items-center justify-center';modal.innerHTML=`<div class="w-full max-w-5xl max-h-[90vh] rounded-2xl bg-white dark:bg-[#181818] shadow-2xl flex flex-col"><header class="p-5 border-b flex items-center justify-between"><div><h2 class="font-bold"><i class="fas fa-tags mr-2 text-blue-600"></i>来源信息</h2><p class="text-xs text-slate-400 mt-1">标签和来源均可新增、修改、删除；应用时自动合并重复网站</p></div><button onclick="closeSharedSourceCatalog()" class="w-9 h-9 rounded-lg hover:bg-slate-100 dark:hover:bg-white/10"><i class="fas fa-times"></i></button></header><div class="p-4 border-b flex gap-3"><label class="relative flex-1"><i class="fas fa-search absolute left-3 top-3 text-xs text-slate-400"></i><input id="shared-source-search" oninput="renderSharedSourceCatalog(this.value)" class="w-full rounded-xl border bg-transparent py-2.5 pl-9 pr-3 text-sm" placeholder="搜索标签、来源名称或地址"></label><button onclick="addSharedSourceCategory()" class="px-3 py-2 rounded-xl bg-blue-600 text-white text-xs"><i class="fas fa-plus mr-1"></i>新增标签</button><button onclick="clearSharedSourceSelection()" class="px-3 py-2 rounded-xl border text-xs">清空选择</button></div><main id="shared-source-catalog-list" class="flex-1 overflow-y-auto p-5 space-y-4"></main><footer class="p-4 border-t flex items-center justify-between"><span id="shared-source-selected-count" class="text-sm text-slate-500"></span><div class="flex gap-2"><button onclick="closeSharedSourceCatalog()" class="px-4 py-2 text-sm">取消</button><button onclick="applySharedSourceSelection()" class="px-5 py-2 rounded-xl bg-blue-600 text-white text-sm">应用来源</button></div></footer></div>`;document.body.appendChild(modal);renderSharedSourceCatalog('');}
function closeSharedSourceCatalog(){document.getElementById('shared-source-catalog-modal')?.remove();}
function renderSharedSourceCatalog(keyword=''){const host=document.getElementById('shared-source-catalog-list');if(!host)return;const q=String(keyword).trim().toLowerCase(),groups=Object.entries(sharedSourceCatalog).map(([category,items])=>[category,items.filter(([name,url])=>!q||`${category} ${name} ${url}`.toLowerCase().includes(q))]).filter(([category,items])=>!q||items.length||category.toLowerCase().includes(q));host.innerHTML=groups.map(([category,items])=>{const urls=items.map(x=>x[1]),all=urls.length>0&&urls.every(x=>sharedSourceSelection.has(x)),cat=encodeURIComponent(category);return `<section class="rounded-xl border border-slate-200 dark:border-white/10 overflow-hidden"><div class="px-4 py-3 bg-slate-50 dark:bg-white/5 flex items-center gap-2"><label class="font-medium text-sm flex items-center gap-2 min-w-0"><input type="checkbox" ${all?'checked':''} onchange="toggleSharedSourceCategory(decodeURIComponent('${cat}'),this.checked)"><span class="truncate">${escapeHtml(category)}</span></label><span class="text-xs text-slate-400 ml-auto">${items.length} 个来源</span><button title="新增来源" onclick="addSharedSource(decodeURIComponent('${cat}'))" class="w-7 h-7 rounded-md hover:bg-blue-50 text-blue-600"><i class="fas fa-plus"></i></button><button title="修改标签" onclick="editSharedSourceCategory(decodeURIComponent('${cat}'))" class="w-7 h-7 rounded-md hover:bg-slate-200 dark:hover:bg-white/10"><i class="fas fa-pen"></i></button><button title="删除标签" onclick="deleteSharedSourceCategory(decodeURIComponent('${cat}'))" class="w-7 h-7 rounded-md hover:bg-red-50 text-red-500"><i class="fas fa-trash"></i></button></div><div class="grid sm:grid-cols-2 lg:grid-cols-3 gap-px bg-slate-100 dark:bg-white/5">${items.map(([name,url])=>{const checked=sharedSourceSelection.has(url),sourceIndex=(sharedSourceCatalog[category]||[]).findIndex(item=>item[0]===name&&item[1]===url);return `<div class="bg-white dark:bg-[#181818] p-3 flex items-start gap-2"><input type="checkbox" ${checked?'checked':''} onchange="toggleSharedSource(decodeURIComponent('${encodeURIComponent(url)}'),this.checked)"><span class="min-w-0 flex-1"><b class="block text-sm">${escapeHtml(name)}</b><small class="block mt-1 text-slate-400 truncate" title="${escapeHtml(url)}">${escapeHtml(url)}</small></span><span class="flex gap-1"><button title="修改" onclick="editSharedSource(decodeURIComponent('${cat}'),${sourceIndex})" class="text-slate-400 hover:text-blue-600"><i class="fas fa-pen text-[10px]"></i></button><button title="删除" onclick="deleteSharedSource(decodeURIComponent('${cat}'),${sourceIndex})" class="text-slate-400 hover:text-red-500"><i class="fas fa-trash text-[10px]"></i></button></span></div>`;}).join('')}</div></section>`;}).join('')||'<p class="py-16 text-center text-sm text-slate-400">没有匹配的来源</p>';updateSharedSourceCount();}
function toggleSharedSource(url,checked){checked?sharedSourceSelection.add(url):sharedSourceSelection.delete(url);updateSharedSourceCount();}
function toggleSharedSourceCategory(category,checked){(sharedSourceCatalog[category]||[]).forEach(([,url])=>{checked?sharedSourceSelection.add(url):sharedSourceSelection.delete(url);});renderSharedSourceCatalog(document.getElementById('shared-source-search')?.value||'');}
function _sharedSourceRefresh(){saveSharedSourceCatalog();renderSharedSourceCatalog(document.getElementById('shared-source-search')?.value||'');}
function _normalizeSharedSourceUrl(value){try{const url=new URL(String(value||'').trim());if(!/^https?:$/.test(url.protocol))throw new Error();return url.href;}catch(error){alert('请输入以 http:// 或 https:// 开头的有效地址');return '';}}
function addSharedSourceCategory(){const name=(prompt('请输入新标签名称')||'').trim();if(!name)return;if(sharedSourceCatalog[name])return alert('该标签已存在');sharedSourceCatalog[name]=[];_sharedSourceRefresh();}
function editSharedSourceCategory(category){const name=(prompt('修改标签名称',category)||'').trim();if(!name||name===category)return;if(sharedSourceCatalog[name])return alert('该标签已存在');sharedSourceCatalog[name]=sharedSourceCatalog[category]||[];delete sharedSourceCatalog[category];_sharedSourceRefresh();}
function deleteSharedSourceCategory(category){if(!confirm(`确定删除“${category}”及其中全部来源吗？`))return;(sharedSourceCatalog[category]||[]).forEach(([,url])=>sharedSourceSelection.delete(url));delete sharedSourceCatalog[category];_sharedSourceRefresh();}
function addSharedSource(category){const name=(prompt('来源名称')||'').trim();if(!name)return;const url=_normalizeSharedSourceUrl(prompt('来源地址（需包含 https://）')||'');if(!url)return;if(sharedSourceEntries().some(item=>item.url===url))return alert('该来源地址已存在');sharedSourceCatalog[category].push([name,url]);_sharedSourceRefresh();}
function editSharedSource(category,index){const item=sharedSourceCatalog[category]?.[index];if(!item)return;const name=(prompt('修改来源名称',item[0])||'').trim();if(!name)return;const url=_normalizeSharedSourceUrl(prompt('修改来源地址',item[1])||'');if(!url)return;const oldUrl=item[1];sharedSourceCatalog[category][index]=[name,url];if(sharedSourceSelection.delete(oldUrl))sharedSourceSelection.add(url);_sharedSourceRefresh();}
function deleteSharedSource(category,index){const item=sharedSourceCatalog[category]?.[index];if(!item||!confirm(`确定删除来源“${item[0]}”吗？`))return;sharedSourceSelection.delete(item[1]);sharedSourceCatalog[category].splice(index,1);_sharedSourceRefresh();}
function clearSharedSourceSelection(){sharedSourceSelection.clear();renderSharedSourceCatalog(document.getElementById('shared-source-search')?.value||'');}
function updateSharedSourceCount(){const count=document.getElementById('shared-source-selected-count');if(count)count.textContent=`已选择 ${sharedSourceSelection.size} 个来源`;}
function applySharedSourceSelection(){networkSearchTags.sites=[...new Set([...sharedSourceSelection].map(normalizeNetworkSite).filter(Boolean))];networkSourceCategories=Object.entries(sharedSourceCatalog).filter(([,items])=>items.some(([,url])=>sharedSourceSelection.has(url))).map(([category])=>category);networkSourceOrigin=networkSearchTags.sites.length?'catalog':'all';networkSourceMode=networkSearchTags.sites.length?'sites':'all';renderNetworkTags('sites');updateNetworkSourceVisual();saveNetworkSearchAgent();closeSharedSourceCatalog();const status=document.getElementById('network-search-status');if(status){status.className='text-sm text-emerald-600 min-h-5';status.textContent=`已选择 ${sharedSourceSelection.size} 个来源，合并为 ${networkSearchTags.sites.length} 个网站`;}}
window.CowAgentSourceCatalog={entries:sharedSourceEntries,getAll:()=>sharedSourceCatalog,open:openSharedSourceCatalog};
let sharedSourceApplyTarget=null;
function openAutomationSourceCatalog(inputId,mode='raw'){
    const input=document.getElementById(inputId);if(!input)return;
    sharedSourceApplyTarget={inputId,mode};
    const previous=[networkSearchTags.sites,networkSourceMode,networkSourceOrigin,networkSourceCategories];
    networkSearchTags.sites=input.value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean).map(value=>{try{const parsed=new URL(value),site=(parsed.searchParams.get('q')||'').match(/^site:([^\s]+)$/);return site?normalizeNetworkSite(`https://${site[1]}/`):normalizeNetworkSite(value);}catch(error){return normalizeNetworkSite(value);}});
    openSharedSourceCatalog();
    [networkSearchTags.sites,networkSourceMode,networkSourceOrigin,networkSourceCategories]=previous;
}
function applySharedSourceSelection(){
    if(sharedSourceApplyTarget){
        const {inputId,mode}=sharedSourceApplyTarget,input=document.getElementById(inputId);
        let values=[...new Set(sharedSourceSelection)];
        if(mode==='news-feed')values=values.map(url=>{try{return `https://news.google.com/rss/search?q=${encodeURIComponent('site:'+new URL(url).hostname)}&hl=zh-CN&gl=CN&ceid=CN:zh-Hans`;}catch(error){return url;}});
        input.value=values.join('\n');input.dispatchEvent(new Event('input',{bubbles:true}));sharedSourceApplyTarget=null;closeSharedSourceCatalog();return;
    }
    networkSearchTags.sites=[...new Set([...sharedSourceSelection].map(normalizeNetworkSite).filter(Boolean))];networkSourceCategories=Object.entries(sharedSourceCatalog).filter(([,items])=>items.some(([,url])=>sharedSourceSelection.has(url))).map(([category])=>category);networkSourceOrigin=networkSearchTags.sites.length?'catalog':'all';networkSourceMode=networkSearchTags.sites.length?'sites':'all';renderNetworkTags('sites');updateNetworkSourceVisual();saveNetworkSearchAgent();closeSharedSourceCatalog();const status=document.getElementById('network-search-status');if(status){status.className='text-sm text-emerald-600 min-h-5';status.textContent=`已选择 ${sharedSourceSelection.size} 个来源，合并为 ${networkSearchTags.sites.length} 个网站`;}
}
function toggleNetworkAdvancedSettings(){const panel=document.getElementById('network-advanced-settings'),icon=document.getElementById('network-advanced-chevron');if(!panel)return;const opening=panel.classList.contains('hidden');panel.classList.toggle('hidden',!opening);icon?.classList.toggle('fa-chevron-down',!opening);icon?.classList.toggle('fa-chevron-up',opening);}
function parseNetworkTags(value){return [...new Set(String(value||'').split(/[,，、;；\n]+/).map(x=>x.trim()).filter(Boolean))];}
function normalizeNetworkSite(value){let text=String(value||'').trim();if(!text)return '';try{const url=new URL(/^https?:\/\//i.test(text)?text:`https://${text}`);return url.hostname.toLowerCase().replace(/^www\./,'');}catch(_){return '';}}
function normalizeManualNetworkSite(value){let text=String(value||'').trim();if(!text)return '';try{const url=new URL(/^https?:\/\//i.test(text)?text:`https://${text}`);url.hash='';return url.href;}catch(_){return '';}}
function renderNetworkTags(type){const hidden=document.getElementById(`network-search-${type}`),entry=document.getElementById(`network-search-${type}-entry`),host=document.getElementById(`network-search-${type}-tags`);if(!hidden||!entry||!host)return;hidden.value=networkSearchTags[type].join('、');host.querySelectorAll('.network-search-tag').forEach(x=>x.remove());networkSearchTags[type].forEach((tag,index)=>{const chip=document.createElement('span'),palette=type==='include'?'bg-blue-50 text-blue-700 dark:bg-blue-500/10':type==='sites'?'bg-violet-50 text-violet-700 dark:bg-violet-500/10':'bg-rose-50 text-rose-600 dark:bg-rose-500/10';chip.className=`network-search-tag inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-xs ${palette}`;chip.innerHTML=`${type==='sites'?'<i class="fas fa-globe text-[9px]"></i>':''}${escapeHtml(tag)}<button type="button" aria-label="删除标签" class="opacity-60 hover:opacity-100"><i class="fas fa-xmark"></i></button>`;chip.querySelector('button').onclick=e=>{e.stopPropagation();networkSearchTags[type].splice(index,1);if(type==='sites'&&!networkSearchTags.sites.length){networkSourceMode='all';networkSourceOrigin='all';networkSourceCategories=[];}renderNetworkTags(type);updateNetworkSourceVisual();saveNetworkSearchAgent();};host.insertBefore(chip,entry);});}
function commitNetworkTags(type){const entry=document.getElementById(`network-search-${type}-entry`);if(!entry)return;let values=parseNetworkTags(entry.value);if(type==='sites')values=values.map(normalizeManualNetworkSite).filter(Boolean);if(values.length){networkSearchTags[type]=[...new Set([...networkSearchTags[type],...values])];if(type==='sites'){networkSourceMode='sites';networkSourceOrigin='manual';networkSourceCategories=[];}}entry.value='';renderNetworkTags(type);updateNetworkSourceVisual();saveNetworkSearchAgent();}
function initNetworkTagInputs(){['include','exclude','sites'].forEach(type=>{const entry=document.getElementById(`network-search-${type}-entry`);if(!entry||entry.dataset.ready)return;entry.dataset.ready='1';entry.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===','||event.key==='，'){event.preventDefault();commitNetworkTags(type);}else if(event.key==='Backspace'&&!entry.value&&networkSearchTags[type].length){networkSearchTags[type].pop();renderNetworkTags(type);}});entry.addEventListener('blur',()=>commitNetworkTags(type));});}
function updateNetworkSourceVisual(){const kind=networkSourceMode==='all'?'all':networkSourceOrigin==='catalog'?'labels':'manual';document.getElementById('network-search-engine-wrap')?.classList.toggle('hidden',kind!=='all');document.getElementById('network-search-sites-wrap')?.classList.toggle('hidden',kind==='all');['all','sites','labels'].forEach(key=>{const button=document.getElementById(`network-source-${key}-button`),active=key===(kind==='manual'?'sites':kind);button?.classList.toggle('bg-slate-900',active);button?.classList.toggle('text-white',active);button?.classList.toggle('shadow-sm',active);button?.classList.toggle('text-slate-500',!active);});const categories=document.getElementById('network-source-category-tags');if(categories)categories.innerHTML=kind==='labels'?networkSourceCategories.map(x=>`<span class="rounded-full bg-blue-50 dark:bg-blue-500/10 px-2 py-1 text-[10px] text-blue-600"><i class="fas fa-tag mr-1"></i>${escapeHtml(x)}</span>`).join(''):'';}
function selectNetworkSourceKind(kind){if(kind==='all'){networkSourceMode='all';networkSourceOrigin='all';}else{networkSourceMode='sites';networkSourceOrigin='manual';networkSourceCategories=[];}updateNetworkSourceVisual();saveNetworkSearchAgent();if(kind==='manual')document.getElementById('network-search-sites-entry')?.focus();}
function setNetworkSourceMode(mode){networkSourceMode=mode==='sites'?'sites':'all';if(networkSourceMode==='all')networkSourceOrigin='all';else if(networkSourceOrigin!=='catalog')networkSourceOrigin='manual';updateNetworkSourceVisual();saveNetworkSearchAgent();}
const NETWORK_NATURAL_EXAMPLES=['查询最近24小时 AI Agent 的重要新闻，必须包含自动化，排除培训和招聘，输出10条摘要卡片','每天早上8点全网搜索人工智能和个人助手动态，优先官方来源，生成深度报告并发送到当前会话','每个工作日上午9点只从 openai.com、github.com 和 anthropic.com 搜索 Agent 更新，合并重复事件并交叉验证'];
function useNetworkNaturalExample(index){const input=document.getElementById('network-natural-prompt');if(!input)return;input.value=NETWORK_NATURAL_EXAMPLES[index]||NETWORK_NATURAL_EXAMPLES[0];input.focus();}
function networkNaturalSchedule(text){const scheduled=/(每天|每日|每周|工作日|每隔|定时|早上|上午|下午|晚上)/i.test(text)||/(?:^|[，,\s])\d{1,2}(?:点|时|[:：]\d{1,2})/.test(text);let frequency='每天';if(/工作日/.test(text))frequency='工作日';else if(/每周一/.test(text))frequency='每周一';else if(/每隔\s*6\s*小时/.test(text))frequency='每隔6小时';const clock=scheduled?text.match(/(?:早上|上午|下午|晚上)?\s*(\d{1,2})(?:[:：点时](\d{1,2})?)?/):null,period=(clock&&text.slice(Math.max(0,clock.index-3),clock.index+2))||'';let hour=clock?Number(clock[1]):8,minute=clock?Number(clock[2]||0):0;if(/下午|晚上/.test(period)&&hour<12)hour+=12;return {scheduled,frequency,runTime:`${String(Math.min(hour,23)).padStart(2,'0')}:${String(Math.min(minute,59)).padStart(2,'0')}`};}
function networkNaturalTopic(text,draft){const quoted=text.match(/[“"]([^”"]+)[”"]/),focus=text.match(/(?:重点关注|关注)\s*([^，。；;]{2,80}?)(?=优先|必须|排除|只列|输出|发送|发到|通过|$)/),content=text.match(/(?:内容包括|主题为|关于)\s*([^，。；;]{2,80}?)(?=优先|必须|排除|只列|输出|发送|发到|通过|$)/),match=text.match(/(?:搜索|查询|查找|收集|整理|监控)\s*([^，。；;]{2,100}?)(?=，|。|；|必须包含|仅关注|排除|不要|忽略|只从|从\s*https?|输出\d|整理\d|生成|发到|发送到|$)/i);let topic=(quoted?.[1]||focus?.[1]||content?.[1]||match?.[1]||'').replace(/^(?:一下|关于)/,'').replace(/^(?:最近|过去)\s*\d+\s*(?:小时|天)\s*/,'').replace(/(?:方向|领域)$/,'').replace(/(?:的)?(?:重要)?(?:新闻|资讯|动态)$/,'').trim();if(!topic)topic=(draft?.payload?.keywords||[]).filter(x=>!/^(?:早间简报|通过|发给我|内容包括)$/.test(x)).join(' ');return topic||'AI 创业 科技';}
function networkNaturalFilterTerms(text,type,fallback){const prefix=type==='include'?'(?:必须包含|仅关注)':'(?:排除|不要|忽略)',match=text.match(new RegExp(`${prefix}\\s*([^，。；;]{1,80}?)(?=只列|只要|输出|格式|发送|发到|通过|优先|$)`));if(!match)return fallback||[];return match[1].split(/[,，、和]/).map(x=>x.trim()).filter(x=>x&&!/^(?:标题|内容|web|当前会话)$/.test(x));}
async function parseNetworkNaturalPrompt(){const input=document.getElementById('network-natural-prompt'),status=document.getElementById('network-natural-status'),host=document.getElementById('network-natural-draft'),button=document.getElementById('network-natural-parse-button'),text=input?.value.trim()||'';if(text.length<4){status.className='text-xs text-red-500 min-h-5';status.textContent='请先用一句话描述查询需求';input?.focus();return;}status.className='text-xs text-blue-600 min-h-5';status.textContent='Agent 正在识别主题、来源、规则和执行时间…';button.disabled=true;button.classList.add('opacity-60');try{const response=await fetch('/api/intelligence/natural-task',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'parse',prompt:text})}),result=await response.json();if(result.status!=='success')throw new Error(result.message||'识别失败');const draft=result.draft||{},payload=draft.payload||{},urls=[...text.matchAll(/https?:\/\/[^\s，,；;]+/g)].map(x=>normalizeNetworkSite(x[0])),domains=[...text.matchAll(/(?:^|[\s，,、；;])((?:[a-z0-9-]+\.)+[a-z]{2,})(?=$|[\s，,、；;])/ig)].map(x=>normalizeNetworkSite(x[1])),sites=[...new Set([...urls,...domains].filter(Boolean))],schedule=networkNaturalSchedule(text),f=networkSearchAgentFields();f.query.value=networkNaturalTopic(text,draft);networkSearchTags.include=payload.rules?.include||[];networkSearchTags.exclude=payload.rules?.exclude||[];networkSearchTags.sites=sites;renderNetworkTags('include');renderNetworkTags('exclude');renderNetworkTags('sites');if(/最近\s*7\s*天|近一周/.test(text))f.time.value='最近7天';else if(/最近\s*30\s*天|近一个月/.test(text))f.time.value='最近30天';else if(/不限时间|全部时间/.test(text))f.time.value='不限时间';else f.time.value='最近24小时';const limit=text.match(/(?:最多|输出|整理|生成)?\s*(\d{1,2})\s*(?:条|篇|个)/);f.count.value=limit?Math.min(50,Math.max(1,Number(limit[1]))):(payload.max_items||10);f.engine.value=/百度/i.test(text)?'baidu':/(google|谷歌)/i.test(text)?'google':'auto';f.output.value=/表格/.test(text)?'table':/(深度|详细|研究报告)/.test(text)?'report':'brief';f.official.checked=!/(不限制来源|来源不限)/.test(text);f.dedupe.checked=!/(保留重复|不要去重)/.test(text);f.verify.checked=!/(无需核验|不要交叉验证)/.test(text);f.readPages.checked=!/(只看摘要|不读正文)/.test(text);f.expandTerms.checked=!/(严格匹配|不要扩展|仅匹配原词)/.test(text);f.compact.checked=!/(完整过程|详细过程|展示检索过程)/.test(text);f.frequency.value=schedule.frequency;f.runTime.value=schedule.runTime;setNetworkSourceMode(sites.length||/(只从|指定网站|限定网站)/.test(text)?'sites':'all');setNetworkSearchMode(schedule.scheduled?'schedule':'once');updateNetworkOutputPreview();saveNetworkSearchAgent();const sourceSummary=networkSourceMode==='sites'?`指定网站：${sites.join('、')||'待补充'}`:`全网搜索：${f.engine.options[f.engine.selectedIndex].text}`,modeSummary=schedule.scheduled?`${schedule.frequency} ${schedule.runTime} 自动执行`:'单次即时查询';host.classList.remove('hidden');host.innerHTML=`<div class="flex flex-wrap items-start justify-between gap-3"><div><span class="text-[11px] text-blue-600">已生成可编辑配置</span><h4 class="font-semibold mt-1">${escapeHtml(f.query.value)}</h4></div><span class="rounded-full bg-blue-50 dark:bg-blue-500/10 px-3 py-1 text-xs text-blue-600">${escapeHtml(modeSummary)}</span></div><div class="grid sm:grid-cols-2 gap-2 mt-3 text-xs text-slate-500"><p><b>来源：</b>${escapeHtml(sourceSummary)}</p><p><b>时间：</b>${escapeHtml(f.time.value)}</p><p><b>必须包含：</b>${escapeHtml(networkSearchTags.include.join('、')||'无')}</p><p><b>排除：</b>${escapeHtml(networkSearchTags.exclude.join('、')||'无')}</p><p><b>数量：</b>${escapeHtml(f.count.value)} 条</p><p><b>输出：</b>${escapeHtml(f.output.options[f.output.selectedIndex].text)}</p></div><p class="text-[11px] text-slate-400 mt-3">所有识别结果已同步到下方高级配置，可继续手动修改。</p><div class="flex flex-wrap justify-end gap-2 mt-4"><button onclick="document.getElementById('network-search-query').scrollIntoView({behavior:'smooth',block:'center'})" class="px-3 py-2 rounded-lg border text-xs">检查配置</button><button onclick="setNetworkSearchMode('once');runNetworkSearchAgent(true)" class="px-3 py-2 rounded-lg border border-blue-200 text-blue-600 text-xs">立即查询</button><button onclick="setNetworkSearchMode('schedule');createScheduledNetworkSearch()" class="px-3 py-2 rounded-lg bg-blue-600 text-white text-xs">创建定时任务</button></div>`;status.className='text-xs text-emerald-600 min-h-5';status.textContent='识别完成，请检查配置或直接执行。';}catch(error){status.className='text-xs text-red-500 min-h-5';status.textContent=error.message;}finally{button.disabled=false;button.classList.remove('opacity-60');}}
let networkCompositeBriefingDraft=null;
function isCompositeDailyBriefing(text){return /(?:每日|每天).{0,12}(?:早间简报|早报|晨报)/s.test(text)&&(/待办|任务清单/.test(text)||/建议.{0,12}自动完成/.test(text))&&(/新闻|资讯/.test(text));}
function buildCompositeBriefingContent(text){return `生成个人早间简报。优先直接读取本地 RSS 采集结果，只在没有候选时使用一次联网搜索；最多处理和输出5条，不创建专家团，不展示搜索、思考、工具调用、统计、解释或建议。\n\n关注最近24小时的 AI、创业、科技资讯，优先 36氪、少数派、知乎热榜；合并重复事件。摘要直接依据采集器已有标题和摘要生成，不重复打开全部候选网页。\n\n最终必须严格只输出以下正文：\n个人早间简报｜YYYY-MM-DD\n\n栏目一｜隔夜重点\n\n1. 标题 [链接](完整URL)\n10至50字具体摘要。\n\n最多5条。没有合格内容时只输出“当前条件下暂无合格结果”。禁止单独展示完整网址，禁止输出开场、执行过程、检索说明、候选统计、结论和下一步建议。\n\n用户原始要求：${text}`;}
function renderCompositeDailyBriefing(text){const schedule=networkNaturalSchedule(text),status=document.getElementById('network-natural-status'),host=document.getElementById('network-natural-draft');networkCompositeBriefingDraft={name:'每日个人早间简报',content:buildCompositeBriefingContent(text),runTime:schedule.runTime||'08:00',delivery:'web'};status.className='text-xs text-emerald-600 min-h-5';status.textContent='已识别为组合型个人早间简报，不会作为普通网络搜索处理。';host.classList.remove('hidden');host.innerHTML=`<div class="flex flex-wrap items-start justify-between gap-3"><div><span class="text-[11px] text-violet-600">组合自动化任务</span><h4 class="font-semibold mt-1">每日个人早间简报</h4></div><span class="rounded-full bg-violet-50 dark:bg-violet-500/10 px-3 py-1 text-xs text-violet-600">每天 ${escapeHtml(networkCompositeBriefingDraft.runTime)} · Web</span></div><div class="grid sm:grid-cols-2 gap-2 mt-4 text-xs text-slate-500"><p><i class="fas fa-newspaper mr-2 text-blue-500"></i>隔夜新闻：AI、创业、科技</p><p><i class="fas fa-list-check mr-2 text-emerald-500"></i>今日待办：本地任务与连接器</p><p><i class="fas fa-wand-magic-sparkles mr-2 text-violet-500"></i>Agent 可自动完成建议</p><p><i class="fas fa-pen-nib mr-2 text-amber-500"></i>创意内容直接生成完整草稿</p></div><div class="rounded-lg bg-slate-50 dark:bg-white/5 p-3 mt-4 text-[11px] text-slate-500">安全规则：找不到待办来源时明确提示；外部写入和高风险动作仍需审批。</div><div class="flex flex-wrap justify-end gap-2 mt-4"><button onclick="previewCompositeDailyBriefing()" class="px-3 py-2 rounded-lg border text-xs">单次预览</button><button onclick="createCompositeDailyBriefing()" class="px-4 py-2 rounded-lg bg-violet-600 text-white text-xs"><i class="far fa-calendar-plus mr-2"></i>创建每日任务</button></div>`;}
function previewCompositeDailyBriefing(){if(!networkCompositeBriefingDraft)return;newChat(false,false);navigateTo('chat');chatInput.value=networkCompositeBriefingDraft.content;chatInput.dispatchEvent(new Event('input',{bubbles:true}));chatInput.focus();setTimeout(()=>sendMessage(),50);}
async function createCompositeDailyBriefing(){if(!networkCompositeBriefingDraft)return;const status=document.getElementById('network-natural-status'),[hour,minute]=networkCompositeBriefingDraft.runTime.split(':').map(Number),payload={name:networkCompositeBriefingDraft.name,content:networkCompositeBriefingDraft.content,action_type:'agent_task',schedule_type:'cron',cron:`${minute} ${hour} * * *`,run_at:'',interval_seconds:0,silent:false,session_id:sessionId,channel_type:'web',receiver:sessionId,receiver_name:'当前 Web 会话',is_group:false};status.className='text-xs text-blue-600 min-h-5';status.textContent='正在创建每日早间简报…';try{const response=await fetch('/api/scheduler',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),data=await response.json();if(data.status!=='success')throw new Error(data.message||'创建失败');status.className='text-xs text-emerald-600 min-h-5';status.textContent=`创建成功：每天 ${networkCompositeBriefingDraft.runTime} 将结果发送到当前 Web 会话。`;tasksLoaded=false;}catch(error){status.className='text-xs text-red-500 min-h-5';status.textContent=error.message;}}
let networkCompositeTargets=[];
async function openCompositeBriefingEditor(){if(!networkCompositeBriefingDraft)return;document.getElementById('network-composite-editor')?.remove();const modal=document.createElement('div');modal.id='network-composite-editor';modal.className='fixed inset-0 z-[230] bg-slate-100 dark:bg-[#111] flex flex-col';modal.innerHTML=`<header class="h-16 shrink-0 bg-white dark:bg-[#1a1a1a] border-b border-slate-200 dark:border-white/10 px-5 lg:px-8 flex items-center justify-between"><div class="flex items-center gap-2 text-sm"><i class="far fa-clock"></i><span class="text-slate-400">自动化 /</span><b>每日个人早间简报</b></div><div class="flex gap-3"><button onclick="closeCompositeBriefingEditor()" class="px-4 py-2 rounded-lg border text-sm">取消</button><button id="composite-editor-save" onclick="saveCompositeBriefingEditor()" class="px-5 py-2 rounded-lg bg-slate-900 dark:bg-white dark:text-slate-900 text-white text-sm">保存</button></div></header><main class="flex-1 overflow-y-auto"><div class="max-w-6xl mx-auto p-5 lg:p-8 space-y-5"><div class="rounded-xl border border-blue-200 bg-blue-50 dark:bg-blue-500/10 dark:border-blue-500/20 px-4 py-3 text-sm text-blue-600"><i class="fas fa-circle-info mr-2"></i>保存后 CowAgent 需要保持运行，任务到点后会自动生成简报并发送。</div><label class="block text-sm font-medium">名称<input id="composite-editor-name" value="${escapeHtml(networkCompositeBriefingDraft.name)}" class="mt-2 w-full rounded-xl border border-slate-200 dark:border-white/10 bg-white dark:bg-[#1a1a1a] px-4 py-3"></label><label class="block text-sm font-medium">任务内容<textarea id="composite-editor-content" rows="14" class="mt-2 w-full rounded-xl border border-slate-200 dark:border-white/10 bg-white dark:bg-[#1a1a1a] px-4 py-3 leading-6">${escapeHtml(networkCompositeBriefingDraft.content)}</textarea><span class="block text-xs text-slate-400 mt-2">Agent 已根据一句话自动拆分栏目，可以直接修改自然语言内容。</span></label><label class="block text-sm font-medium">结果发送到<select id="composite-editor-target" class="mt-2 w-full rounded-xl border border-slate-200 dark:border-white/10 bg-white dark:bg-[#1a1a1a] px-4 py-3"><option value="web">当前 Web 会话</option></select><span class="block text-xs text-slate-400 mt-2">已配置的微信、企业微信、邮箱或 Webhook 会自动显示在这里。</span></label><section><div class="text-sm font-medium mb-2">执行频率</div><div class="inline-flex rounded-xl bg-slate-200/70 dark:bg-white/5 p-1"><button id="composite-mode-daily" onclick="setCompositeScheduleMode('daily')" class="px-4 py-2 rounded-lg bg-white dark:bg-[#292929] shadow-sm text-sm">周期</button><button id="composite-mode-interval" onclick="setCompositeScheduleMode('interval')" class="px-4 py-2 rounded-lg text-slate-500 text-sm">按间隔</button><button id="composite-mode-once" onclick="setCompositeScheduleMode('once')" class="px-4 py-2 rounded-lg text-slate-500 text-sm">单次</button></div><div id="composite-schedule-daily" class="mt-4 flex flex-wrap gap-3"><select id="composite-editor-frequency" class="rounded-xl border bg-white dark:bg-[#1a1a1a] px-4 py-3 text-sm"><option value="daily">每天</option><option value="weekday">每个工作日</option></select><input id="composite-editor-time" type="time" value="${escapeHtml(networkCompositeBriefingDraft.runTime)}" class="rounded-xl border bg-white dark:bg-[#1a1a1a] px-4 py-3 text-sm"></div><div id="composite-schedule-interval" class="hidden mt-4 flex gap-3"><input id="composite-editor-interval" type="number" min="1" value="24" class="w-28 rounded-xl border bg-white dark:bg-[#1a1a1a] px-4 py-3 text-sm"><select id="composite-editor-interval-unit" class="rounded-xl border bg-white dark:bg-[#1a1a1a] px-4 py-3 text-sm"><option value="3600">小时</option><option value="60">分钟</option><option value="86400">天</option></select></div><div id="composite-schedule-once" class="hidden mt-4"><input id="composite-editor-once" type="datetime-local" class="rounded-xl border bg-white dark:bg-[#1a1a1a] px-4 py-3 text-sm"></div></section><details class="rounded-xl border border-slate-200 dark:border-white/10 bg-white dark:bg-[#1a1a1a] p-4"><summary class="cursor-pointer text-sm font-medium">高级设置</summary><div class="mt-4 grid sm:grid-cols-2 gap-3 text-sm text-slate-500"><label class="flex gap-2"><input type="checkbox" checked disabled> 自动读取新闻来源并去重</label><label class="flex gap-2"><input type="checkbox" checked disabled> 高风险操作执行前审批</label><label class="flex gap-2"><input type="checkbox" checked disabled> 无待办来源时禁止编造</label><label class="flex gap-2"><input type="checkbox" checked disabled> 仅展示最终简报</label></div></details><p id="composite-editor-status" class="text-sm min-h-5"></p></div></main>`;document.body.appendChild(modal);modal.dataset.scheduleMode='daily';try{const response=await fetch('/api/scheduler/targets'),data=await response.json();networkCompositeTargets=(data.targets||[]).filter(x=>x.channel&&x.receiver&&x.channel!=='web');const select=document.getElementById('composite-editor-target');networkCompositeTargets.forEach((target,index)=>{const option=document.createElement('option');option.value=`target:${index}`;option.textContent=`${target.channel_label}${target.receiver_name?' · '+target.receiver_name:''}`;select.appendChild(option);});}catch(_){} }
function closeCompositeBriefingEditor(){document.getElementById('network-composite-editor')?.remove();}
function setCompositeScheduleMode(mode){const modal=document.getElementById('network-composite-editor');if(!modal)return;modal.dataset.scheduleMode=mode;['daily','interval','once'].forEach(key=>{document.getElementById(`composite-schedule-${key}`)?.classList.toggle('hidden',key!==mode);const button=document.getElementById(`composite-mode-${key}`),active=key===mode;button?.classList.toggle('bg-white',active);button?.classList.toggle('dark:bg-[#292929]',active);button?.classList.toggle('shadow-sm',active);button?.classList.toggle('text-slate-500',!active);});}
async function saveCompositeBriefingEditor(){const modal=document.getElementById('network-composite-editor'),status=document.getElementById('composite-editor-status'),button=document.getElementById('composite-editor-save'),name=document.getElementById('composite-editor-name').value.trim(),content=document.getElementById('composite-editor-content').value.trim(),mode=modal?.dataset.scheduleMode||'daily';if(!name||!content){status.className='text-sm text-red-500 min-h-5';status.textContent='请填写名称和任务内容';return;}const targetValue=document.getElementById('composite-editor-target').value,target=targetValue.startsWith('target:')?networkCompositeTargets[Number(targetValue.split(':')[1])]:null,payload={name,content,action_type:'agent_task',schedule_type:mode==='daily'?'cron':mode,silent:false,session_id:sessionId,channel_type:target?.channel||'web',receiver:target?.receiver||sessionId,receiver_name:target?.receiver_name||'当前 Web 会话',is_group:!!target?.is_group,cron:'',interval_seconds:0,run_at:''};if(mode==='daily'){const time=document.getElementById('composite-editor-time').value||'08:00',[hour,minute]=time.split(':').map(Number),frequency=document.getElementById('composite-editor-frequency').value;payload.cron=`${minute} ${hour} ${frequency==='weekday'?'* * 1-5':'* * *'}`;}else if(mode==='interval'){payload.interval_seconds=Number(document.getElementById('composite-editor-interval').value||1)*Number(document.getElementById('composite-editor-interval-unit').value||3600);}else payload.run_at=document.getElementById('composite-editor-once').value;if(mode==='once'&&!payload.run_at){status.className='text-sm text-red-500 min-h-5';status.textContent='请选择单次执行时间';return;}button.disabled=true;button.textContent='保存中…';status.className='text-sm text-blue-600 min-h-5';status.textContent='正在创建任务…';try{const response=await fetch('/api/scheduler',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),data=await response.json();if(data.status!=='success')throw new Error(data.message||'创建失败');tasksLoaded=false;closeCompositeBriefingEditor();const naturalStatus=document.getElementById('network-natural-status');naturalStatus.className='text-xs text-emerald-600 min-h-5';naturalStatus.textContent='每日个人早间简报已创建，可在“定时任务”中编辑。';}catch(error){button.disabled=false;button.textContent='保存';status.className='text-sm text-red-500 min-h-5';status.textContent=error.message;}}
createCompositeDailyBriefing=openCompositeBriefingEditor;
const parseNetworkNaturalPromptCore=parseNetworkNaturalPrompt;
parseNetworkNaturalPrompt=async function(){const text=document.getElementById('network-natural-prompt')?.value.trim()||'';if(isCompositeDailyBriefing(text)){renderCompositeDailyBriefing(text);return;}networkCompositeBriefingDraft=null;await parseNetworkNaturalPromptCore();const f=networkSearchAgentFields();networkSearchTags.include=networkNaturalFilterTerms(text,'include',networkSearchTags.include);networkSearchTags.exclude=networkNaturalFilterTerms(text,'exclude',networkSearchTags.exclude);renderNetworkTags('include');renderNetworkTags('exclude');if(/只列标题|只要标题|仅标题/.test(text)&&!/不要只列标题/.test(text))f.output.value='titles';if(/通过\s*web|发到当前会话|发送到当前会话/i.test(text))f.delivery.value='当前 Web 会话';updateNetworkOutputPreview();saveNetworkSearchAgent();};
function setNetworkSearchMode(mode){networkSearchMode=mode==='schedule'?'schedule':'once';document.getElementById('network-search-schedule-fields')?.classList.toggle('hidden',networkSearchMode!=='schedule');document.getElementById('network-search-once-actions')?.classList.toggle('hidden',networkSearchMode==='schedule');document.getElementById('network-search-schedule-action')?.classList.toggle('hidden',networkSearchMode!=='schedule');['once','schedule'].forEach(key=>{const button=document.getElementById(`network-mode-${key}`),active=key===networkSearchMode;button?.classList.toggle('bg-white',active);button?.classList.toggle('dark:bg-[#292929]',active);button?.classList.toggle('shadow-sm',active);button?.classList.toggle('text-slate-500',!active);});saveNetworkSearchAgent();}
function resetNetworkSearchAgent(){const f=networkSearchAgentFields();if(!f.query)return;f.query.value='AI Agent';networkSearchTags={include:['Agent','自动化','个人助手'],exclude:['培训','广告','招聘'],sites:[]};networkSourceMode='all';networkSourceOrigin='all';networkSourceCategories=[];renderNetworkTags('include');renderNetworkTags('exclude');renderNetworkTags('sites');f.engine.value='auto';f.time.value='最近24小时';f.count.value='5';f.rules.value='';f.readPages.checked=true;f.official.checked=true;f.dedupe.checked=true;f.verify.checked=true;f.expandTerms.checked=true;f.compact.checked=true;f.output.value='brief';f.sort.value='重要性和时效性';f.frequency.value='每天';f.runTime.value='08:00';f.delivery.value='当前 Web 会话';updateNetworkSourceVisual();setNetworkSearchMode('once');localStorage.removeItem(NETWORK_SEARCH_AGENT_KEY);document.getElementById('network-search-status').textContent='';updateNetworkOutputPreview();}
function saveNetworkSearchAgent(){const f=networkSearchAgentFields();if(!f.query)return {};const data={mode:networkSearchMode,sourceMode:networkSourceMode,sourceOrigin:networkSourceOrigin,sourceCategories:networkSourceCategories,query:f.query.value||'',include:networkSearchTags.include.join('、'),exclude:networkSearchTags.exclude.join('、'),sites:networkSearchTags.sites.join('、'),engine:f.engine?.value||'auto',time:f.time?.value||'最近24小时',count:f.count?.value||'5',rules:f.rules?.value||'',readPages:!!f.readPages?.checked,official:!!f.official?.checked,dedupe:!!f.dedupe?.checked,verify:!!f.verify?.checked,expandTerms:!!f.expandTerms?.checked,compact:!!f.compact?.checked,output:f.output?.value||'brief',sort:f.sort?.value||'重要性和时效性',frequency:f.frequency?.value||'每天',runTime:f.runTime?.value||'08:00',delivery:f.delivery?.value||'当前 Web 会话'};localStorage.setItem(NETWORK_SEARCH_AGENT_KEY,JSON.stringify(data));return data;}
function updateNetworkOutputPreview(){const type=document.getElementById('network-search-output')?.value||'brief',host=document.getElementById('network-search-output-preview');if(!host)return;host.innerHTML=type==='table'?'<div class="grid grid-cols-3 gap-1 text-xs"><b>日期 / 标题</b><b>摘要</b><b>来源</b><span>08-28｜示例</span><span>关键信息…</span><span class="text-blue-600">原文</span></div>':type==='report'?'<b>AI Agent 行业研究报告</b><p>执行摘要、关键动态、趋势判断、风险与建议</p><span class="text-blue-600">附：全部来源链接</span>':type==='titles'?'<b>2026-08-28｜OpenAI 发布 XXX</b><p class="text-blue-600">查看原文</p>':'<b>2026-08-28｜OpenAI 发布 XXX</b><p>OpenAI 新增了 XXX 能力……</p><span class="text-blue-600">查看原文</span>';}
function renderNetworkSearchHistory(){const host=document.getElementById('network-search-history');if(!host)return;let items=[];try{items=JSON.parse(localStorage.getItem(NETWORK_SEARCH_HISTORY_KEY)||'[]');}catch(_){}host.innerHTML=items.length?items.slice(0,5).map((x,index)=>`<button onclick="reuseNetworkSearchHistory(${index})" class="block w-full text-left rounded-xl border border-slate-100 dark:border-white/5 p-3 hover:border-blue-200"><b class="block truncate text-xs text-slate-700 dark:text-slate-200">${escapeHtml(x.query)}</b><span class="block mt-1 text-[10px] text-slate-400">${escapeHtml(x.time)} · ${escapeHtml(x.createdAt)}</span></button>`).join(''):'<p class="py-5 text-center text-xs text-slate-400">暂无搜索记录</p>';}
function rememberNetworkSearch(data){let items=[];try{items=JSON.parse(localStorage.getItem(NETWORK_SEARCH_HISTORY_KEY)||'[]');}catch(_){}items.unshift({...data,createdAt:new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date())});localStorage.setItem(NETWORK_SEARCH_HISTORY_KEY,JSON.stringify(items.slice(0,10)));renderNetworkSearchHistory();}
function reuseNetworkSearchHistory(index){let items=[];try{items=JSON.parse(localStorage.getItem(NETWORK_SEARCH_HISTORY_KEY)||'[]');}catch(_){}const data=items[index];if(!data)return;const f=networkSearchAgentFields();Object.keys(data).forEach(k=>{if(f[k]){if(f[k].type==='checkbox')f[k].checked=!!data[k];else f[k].value=data[k];}});const manual=data.sourceOrigin!=='catalog';networkSearchTags={include:parseNetworkTags(data.include),exclude:parseNetworkTags(data.exclude),sites:parseNetworkTags(data.sites).map(manual?normalizeManualNetworkSite:normalizeNetworkSite).filter(Boolean)};networkSourceMode=data.sourceOrigin?data.sourceMode:(networkSearchTags.sites.length?'sites':'all');networkSourceOrigin=data.sourceOrigin||(networkSearchTags.sites.length?'manual':'all');networkSourceCategories=Array.isArray(data.sourceCategories)?data.sourceCategories:[];renderNetworkTags('include');renderNetworkTags('exclude');renderNetworkTags('sites');updateNetworkSourceVisual();setNetworkSearchMode(data.mode||'once');updateNetworkOutputPreview();}
