async function createTechBriefingTask(button){
    const status=document.getElementById('tech-briefing-status'),old=button?.innerHTML;
    if(status){status.className='mt-3 min-h-5 text-sm text-blue-600';status.textContent='正在创建定时任务…';}
    if(button){button.disabled=true;button.innerHTML='<i class="fas fa-spinner fa-spin mr-2"></i>创建中';}
    try{
        await intelligenceRequest('/api/intelligence/news',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(techBriefingPayload())});
        if(status){status.className='mt-3 min-h-5 text-sm text-emerald-600';status.textContent='已创建：每日 09:00（Asia/Shanghai）自动生成科技热点简报。';}
        _wsToast?.('每日国内外科技热点简报已创建');
        loadAutomationTasks?.();
    }catch(error){
        if(status){status.className='mt-3 min-h-5 text-sm text-red-500';status.textContent=`创建失败：${error.message||error}`;}
    }finally{
        if(button){button.disabled=false;button.innerHTML=old;}
    }
}

