let artifactCache=[],artifactCategories=[],artifactCategoryFilter='全部',currentArtifact=null,artifactSearchTimer=null;const expandedArtifactRows=new Set(),selectedArtifactRows=new Set();
function initializeArtifactDate(){const input=document.getElementById('artifact-date');if(!input||input.dataset.initialized)return;const now=new Date(),local=new Date(now.getTime()-now.getTimezoneOffset()*60000);input.value=local.toISOString().slice(0,10);input.dataset.initialized='1';}
