async function loadArtifacts(){const host=document.getElementById('artifacts-list');if(!host)return;initializeArtifactDate();host.innerHTML='<div class="py-16 text-center text-slate-400">正在整理产物…</div>';const query=document.getElementById('artifact-search')?.value||'',field=document.getElementById('artifact-search-field')?.value||'all',date=document.getElementById('artifact-date')?.value||'',params=new URLSearchParams({query,field,date});try{const response=await fetch(`/api/artifacts?${params}`),data=await response.json();if(data.status!=='success')throw new Error(data.message);artifactCache=data.artifacts||[];artifactCategories=data.categories||[];if(artifactCategoryFilter!=='全部'&&!artifactCategories.some(x=>x.name===artifactCategoryFilter))artifactCategoryFilter='全部';selectedArtifactRows.forEach(id=>{if(!artifactCache.some(x=>x.id===id))selectedArtifactRows.delete(id)});const titleFilter=document.getElementById('artifact-title-filter'),current=titleFilter?.value||'',titles=[...new Set(artifactCache.map(x=>x.title).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'zh-CN'));if(titleFilter){titleFilter.innerHTML='<option value="">全部标题</option>'+titles.map(title=>`<option value="${escapeHtml(title)}">${escapeHtml(title)}</option>`).join('');if(titles.includes(current))titleFilter.value=current;}renderArtifactCategoryFilter();renderArtifacts();}catch(error){host.innerHTML=`<div class="py-12 text-center text-red-500">${escapeHtml(error.message)}</div>`;}}
