function artifactMatchesQuickFilter(item){
    if(artifactQuickFilter==='success')return item.run_status==='success';
    if(artifactQuickFilter==='empty')return item.run_status==='empty';
    if(artifactQuickFilter==='failed')return item.run_status==='failed';
    if(artifactQuickFilter==='manual')return item.trigger==='manual';
    if(artifactQuickFilter==='scheduled')return item.trigger==='scheduled'||item.trigger==='scheduled_agent'||(item.tags||[]).includes('定时任务');
    if(artifactQuickFilter.startsWith('p1-'))return matchesP1Filter(item,artifactQuickFilter);
    return true;
}
