function visibleArtifacts(){refreshArtifactCenterTypeFilter();const type=document.getElementById('artifact-type')?.value||'',title=document.getElementById('artifact-title-filter')?.value||'';return artifactCache.filter(x=>(!type||x.type===type)&&(!title||x.title===title)&&(!artifactCategoryFilter||artifactCategoryFilter==='全部'||String(x.artifact_category||'其他')===artifactCategoryFilter)&&artifactMatchesQuickFilter(x));}
