        const state=automationStatusBadge(x.run_status,'text-[10px]');
        const delivery=x.notification_summary?automationDeliveryBadge(automationDeliveryStatusMeta({notificationSummary:x.notification_summary}),'text-[10px]'):'';
        const sourceTitle=x.task_name?`${x.kind_label||'自动任务'} · ${x.task_name}`:(x.source||'任务');
        const sourceButton=(x.source_url||x.source_entry||x.conversation_id)?`<button onclick="openArtifactSourceFromList('${encodeURIComponent(JSON.stringify({source_url:x.source_url||'',source_entry:x.source_entry||'',conversation_id:x.conversation_id||''}))}')" class="px-3 py-1.5 rounded-lg border text-emerald-600">原始来源</button>`:'';
