function weixinAssistantChannelLabel(channel){
    const map={weixin:'微信',wecom_bot:'企微机器人',wechatcom_app:'企微应用'};
    return map[channel]||channel||'会话';
}
function weixinAssistantDisplayLabel(){
    return activeWeixinAssistantTab==='wecom'?'企业微信会话':'微信会话';
}
function updateWeixinSimulatePanel(){
    const title=document.querySelector('#weixin-simulate-box b'),desc=document.querySelector('#weixin-simulate-box p'),input=document.getElementById('weixin-simulate-input'),status=document.getElementById('weixin-simulate-status');
    if(!title)return;
    const isWecom=activeWeixinAssistantTab==='wecom';
    title.innerHTML=`<i class="${isWecom?'fas fa-building-user':'fab fa-weixin'} text-emerald-500 mr-2"></i>${isWecom?'模拟企业微信发送':'模拟微信发送'}`;
    if(desc)desc.textContent=isWecom?'选择左侧企业微信会话后发送，消息将按企业微信相同的 Agent 链路处理。':'选择左侧会话后发送，消息将按手机微信相同的 Agent 链路处理。';
    if(input)input.placeholder=isWecom?'输入企业微信指令，Enter 发送，Shift+Enter 换行':'输入指令，Enter 发送，Shift+Enter 换行';
    if(status)status.textContent='';
}
function setWeixinAssistantTab(tab){
    activeWeixinAssistantTab=tab==='wecom'?'wecom':'weixin';
    selectedWeixinConversation='';
    selectedWeixinAssistantChannel=activeWeixinAssistantTab==='wecom'?'wecom_bot':'weixin';
    const wx=document.getElementById('weixin-assistant-tab-weixin'),wc=document.getElementById('weixin-assistant-tab-wecom');
    const active='px-4 py-2 rounded-lg text-sm font-medium bg-white dark:bg-[#2A2A2A] text-emerald-600 shadow-sm';
    const inactive='px-4 py-2 rounded-lg text-sm font-medium text-slate-500 hover:text-emerald-600';
    if(wx)wx.className=activeWeixinAssistantTab==='weixin'?active:inactive;
    if(wc)wc.className=activeWeixinAssistantTab==='wecom'?active:inactive;
    const tip=document.getElementById('weixin-assistant-record-tip');
    if(tip)tip.textContent=activeWeixinAssistantTab==='wecom'?'企业微信会话按周归档，合并展示企微智能机器人和企微自建应用记录。':'旧会话按设置中的归档周期自动分组，点击左侧归档分组可查看历史。';
    updateWeixinSimulatePanel();
    const detail=document.getElementById('weixin-assistant-detail');
    if(detail)detail.innerHTML=`<p class="text-sm text-slate-400 text-center py-24">从左侧历史归档中选择一个${weixinAssistantDisplayLabel()}</p>`;
    loadWeixinAssistantConversations();
}
async function loadWeixinAssistantConversations(){
    const list=document.getElementById('weixin-assistant-list'),detail=document.getElementById('weixin-assistant-detail'),total=document.getElementById('weixin-assistant-total');if(!list||!detail)return;
    list.innerHTML='<p class="text-xs text-slate-400 py-4"><i class="fas fa-spinner fa-spin mr-2"></i>读取会话...</p>';
    try{
        const channels=activeWeixinAssistantTab==='wecom'?['wecom_bot','wechatcom_app']:['weixin'];
        const results=await Promise.all(channels.map(async channel=>{try{const response=await fetch(`/api/channel-conversations?channel=${encodeURIComponent(channel)}&page_size=100`),data=await response.json();if(data.status!=='success')throw new Error(data.message||'读取失败');return (data.sessions||[]).map(item=>({...item,_channel:channel}));}catch(error){return [{_error:error.message||String(error),_channel:channel,session_id:`__error_${channel}`,display_name:`${weixinAssistantChannelLabel(channel)}读取失败`,last_active:new Date().toISOString(),msg_count:0}];}}));
        const sessions=results.flat().sort((a,b)=>normalizeChannelDate(b.last_active)-normalizeChannelDate(a.last_active));
        weixinAssistantSessions=sessions;
        if(total)total.textContent=`${sessions.filter(item=>!item._error).length} 个会话`;
        const period=localStorage.getItem(WEIXIN_ARCHIVE_PERIOD_KEY)||'week',selector=document.getElementById('settings-weixin-archive-period');if(selector)selector.value=period;
        renderWeixinAssistantArchive();
        if(selectedWeixinConversation&&!sessions.some(item=>item.session_id===selectedWeixinConversation&&item._channel===selectedWeixinAssistantChannel)){selectedWeixinConversation='';detail.innerHTML=`<p class="text-sm text-slate-400 text-center py-24">选择一个${weixinAssistantDisplayLabel()}查看记录</p>`;}
        if(activeWeixinAssistantTab==='weixin')renderSidebarWeixinSessions(sessions.filter(item=>!item._error));
    }catch(error){list.innerHTML=`<p class="text-xs text-red-400 py-4">${escapeHtml(error.message)}</p>`;}
}
function renderWeixinAssistantArchive(){
    const list=document.getElementById('weixin-assistant-list');if(!list)return;const sessions=weixinAssistantSessions||[],label=weixinAssistantDisplayLabel();
    if(!sessions.length){list.innerHTML=`<p class="text-xs text-slate-400 py-10 text-center">暂无${label}记录</p>`;return;}
    const period=activeWeixinAssistantTab==='wecom'?'week':(localStorage.getItem(WEIXIN_ARCHIVE_PERIOD_KEY)||'week'),groups=new Map();
    sessions.forEach(item=>{const key=weixinArchiveKey(item.last_active||item.created_at,period);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(item);});
    list.innerHTML=[...groups.values()].map((items,groupIndex)=>`<section class="weixin-archive-group rounded-xl border border-slate-100 dark:border-white/10 overflow-hidden"><button onclick="toggleWeixinArchiveGroup(this)" class="w-full flex items-center justify-between px-3 py-2 text-left bg-slate-50 dark:bg-white/5"><span class="text-xs font-medium"><i class="fas fa-box-archive text-emerald-500 mr-2"></i>${escapeHtml(weixinArchiveRange(items))}</span><span class="text-[11px] text-slate-400">${items.filter(x=>!x._error).length} 个 <i class="fas ${groupIndex===0?'fa-chevron-down':'fa-chevron-right'} ml-1"></i></span></button><div class="weixin-archive-items ${groupIndex===0?'':'hidden'} p-2 space-y-2">${items.sort((a,b)=>normalizeChannelDate(b.last_active)-normalizeChannelDate(a.last_active)).map((item,index)=>item._error?`<div class="rounded-lg border border-red-100 dark:border-red-500/20 bg-red-50 dark:bg-red-500/10 p-3 text-xs text-red-500">${escapeHtml(item.display_name)}：${escapeHtml(item._error)}</div>`:`<div class="weixin-assistant-row rounded-lg border border-slate-100 dark:border-white/10 p-2 flex items-center gap-2 hover:border-emerald-300"><button onclick="openWeixinAssistantConversation('${encodeURIComponent(item.session_id)}',this,'${escapeHtml(item._channel||'weixin')}')" class="weixin-assistant-open min-w-0 flex-1 text-left px-1 py-1"><span class="block text-sm font-medium truncate">${escapeHtml(item.display_name||`${label} ${index+1}`)}</span><span class="block text-[11px] text-slate-400 mt-1">${weixinAssistantChannelLabel(item._channel)} · ${item.msg_count||0} 条 · ${formatChannelAccessTime(item.last_active)}</span></button><button onclick="deleteWeixinConversation('${encodeURIComponent(item.session_id)}','${escapeHtml(item._channel||'weixin')}')" title="删除会话" class="shrink-0 w-8 h-8 rounded-lg text-slate-400 hover:bg-red-50 hover:text-red-500 dark:hover:bg-red-500/10"><i class="fas fa-trash-can text-xs"></i></button></div>`).join('')}</div></section>`).join('');
}
function changeWeixinArchivePeriod(selectedValue){const value=selectedValue||document.getElementById('settings-weixin-archive-period')?.value||'week';localStorage.setItem(WEIXIN_ARCHIVE_PERIOD_KEY,value);const selector=document.getElementById('settings-weixin-archive-period');if(selector)selector.value=value;renderWeixinAssistantArchive();}
async function openWeixinAssistantConversation(encodedId,button,channelName){
    const sessionId=decodeURIComponent(encodedId),detail=document.getElementById('weixin-assistant-detail');if(!detail)return;selectedWeixinConversation=sessionId;selectedWeixinAssistantChannel=channelName||selectedWeixinAssistantChannel||'weixin';
    document.querySelectorAll('.weixin-assistant-row').forEach(node=>node.classList.remove('border-emerald-400','bg-emerald-50','dark:bg-emerald-900/10'));button?.closest('.weixin-assistant-row')?.classList.add('border-emerald-400','bg-emerald-50','dark:bg-emerald-900/10');
    detail.innerHTML='<p class="text-sm text-slate-400 text-center py-24"><i class="fas fa-spinner fa-spin mr-2"></i>读取消息...</p>';
    try{const response=await fetch(`/api/channel-conversations?channel=${encodeURIComponent(selectedWeixinAssistantChannel)}&session_id=${encodeURIComponent(sessionId)}&page_size=100`),data=await response.json();if(data.status!=='success')throw new Error(data.message||'读取失败');const actor=selectedWeixinAssistantChannel==='weixin'?'微信用户':'企业微信用户';detail.innerHTML=(data.messages||[]).map(message=>{const assistant=message.role==='assistant';return `<div class="mb-4 flex ${assistant?'justify-start':'justify-end'}"><div class="max-w-[88%]"><div class="text-[11px] text-slate-400 mb-1 ${assistant?'':'text-right'}">${assistant?'Agent':actor} · ${formatChannelAccessTime(message.created_at)}</div><div class="rounded-xl px-3 py-2 text-sm whitespace-pre-wrap select-text ${assistant?'bg-white dark:bg-[#202020] border border-slate-100 dark:border-white/10':'bg-emerald-500 text-white'}">${escapeHtml(String(message.content||''))}</div></div></div>`;}).join('')||'<p class="text-sm text-slate-400 text-center py-24">暂无可显示消息</p>';detail.scrollTop=detail.scrollHeight;}catch(error){detail.innerHTML=`<p class="text-sm text-red-400 text-center py-24">${escapeHtml(error.message)}</p>`;}
}
async function deleteWeixinConversation(encodedId,channelName){
    const sessionId=decodeURIComponent(encodedId),channel=channelName||'weixin',label=channel==='weixin'?'微信会话':'企业微信会话';if(!confirm(`确定删除这条${label}记录吗？删除后无法恢复。`))return;
    try{const response=await fetch('/api/channel-conversations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'delete',channel,session_id:sessionId})}),data=await response.json();if(data.status!=='success')throw new Error(data.message||'删除失败');if(selectedWeixinConversation===sessionId&&selectedWeixinAssistantChannel===channel)selectedWeixinConversation='';await loadWeixinAssistantConversations();if(channel==='weixin')loadWeixinConversations();}catch(error){alert(`删除失败：${error.message}`);}
}
function renderSidebarWeixinSessions(sessions){const host=document.getElementById('sidebar-weixin-list');if(!host)return;host.innerHTML=sessions.length?sessions.slice(0,10).map(item=>`<div class="group flex items-center gap-1"><button onclick="navigateTo('weixin-assistant');setTimeout(()=>openWeixinAssistantConversation('${encodeURIComponent(item.session_id)}',null,'weixin'),0)" class="min-w-0 flex-1 text-left px-2 py-1.5 rounded text-[11px] text-neutral-400 hover:bg-white/5 hover:text-white truncate"><i class="fas fa-comment-dots text-emerald-400 mr-1.5"></i>${escapeHtml(item.display_name||'微信会话')}</button><button onclick="deleteWeixinConversation('${encodeURIComponent(item.session_id)}','weixin')" class="hidden group-hover:block w-6 h-6 text-neutral-500 hover:text-red-400"><i class="fas fa-trash-can text-[9px]"></i></button></div>`).join(''):'<p class="px-2 py-2 text-[11px] text-neutral-500">暂无微信会话记录</p>';}
async function sendSimulatedWeixinMessage(){
    const input=document.getElementById('weixin-simulate-input'),button=document.getElementById('weixin-simulate-send'),status=document.getElementById('weixin-simulate-status'),content=input?.value.trim()||'',channel=selectedWeixinAssistantChannel||'weixin',label=channel==='weixin'?'微信':'企业微信';
    if(!selectedWeixinConversation){status.textContent=`请先选择左侧${label}会话`;status.className='text-xs text-orange-500';return;}
    if(!content){status.textContent='请输入消息内容';status.className='text-xs text-orange-500';return;}
    button.disabled=true;status.textContent='已发送，Agent 正在处理…';status.className='text-xs text-blue-500';
    try{
        const response=await fetch('/api/channel-conversations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'simulate',channel,session_id:selectedWeixinConversation,content})}),data=await response.json();
        if(data.status!=='success')throw new Error(data.message||'发送失败');
        input.value='';
        let attempts=0;
        const refresh=async()=>{attempts+=1;await openWeixinAssistantConversation(encodeURIComponent(selectedWeixinConversation),null,channel);if(attempts<20){setTimeout(refresh,1500);}else{status.textContent='消息已提交，可稍后刷新查看回复';status.className='text-xs text-emerald-500';button.disabled=false;}};
        setTimeout(refresh,700);
        setTimeout(()=>{button.disabled=false;status.textContent='消息已提交';status.className='text-xs text-emerald-500';},4500);
    }catch(error){status.textContent=error.message;status.className='text-xs text-red-500';button.disabled=false;}
}

async function refreshChannelHealth(){
    try{
        const response=await fetch('/api/channels/health');
        const data=await response.json();
        if(data.status!=='success')throw new Error(data.message||'通道健康检查失败');
        channelHealthData={};
        (data.channels||[]).forEach(item=>{channelHealthData[item.channel]=item;});
        renderChannelConnectionOverview(data.channels||[]);
        channelsData.filter(ch=>ch.active).forEach(ch=>renderChannelHealth(ch.name));
    }catch(error){
        const overview=document.getElementById('channel-connection-overview');
        if(overview)overview.innerHTML=`<div class="text-red-500"><i class="fas fa-circle-exclamation mr-2"></i>${escapeHtml(error.message||'通道状态汇总失败')}</div>`;
        channelsData.filter(ch=>ch.active).forEach(ch=>{const box=document.getElementById(`channel-health-${ch.name}`);if(box)box.innerHTML=`<span class="text-red-500"><i class="fas fa-circle-exclamation mr-2"></i>${escapeHtml(error.message||'健康检查失败')}</span>`;});
    }
}
function renderChannelConnectionOverview(items){
    const host=document.getElementById('channel-connection-overview');if(!host)return;
    const enabled=(items||[]).filter(x=>x.active!==false);
    const connected=enabled.filter(x=>x.connection_state==='connected'||x.ok).length;
    const expired=enabled.filter(x=>['expired','error'].includes(String(x.connection_state||''))).length;
    const cannotSend=enabled.filter(x=>x.can_send===false&&x.channel!=='web').length;
    const pending=enabled.reduce((sum,x)=>sum+Number(x.pending_delivery?.pending||0),0);
    const lastSuccess=enabled.map(x=>x.last_success_at||x.last_sent_at||'').filter(Boolean).sort().pop()||'暂无';
    const cards=[
        ['已连接',connected,'fa-circle-check','emerald'],
        ['会话异常/过期',expired,'fa-triangle-exclamation','red'],
        ['不可主动发送',cannotSend,'fa-paper-plane','orange'],
        ['待补发',pending,'fa-clock-rotate-left','amber'],
    ];
    const toneCls={emerald:'bg-emerald-50 text-emerald-700 dark:bg-emerald-500/10 dark:text-emerald-300',red:'bg-red-50 text-red-700 dark:bg-red-500/10 dark:text-red-300',orange:'bg-orange-50 text-orange-700 dark:bg-orange-500/10 dark:text-orange-300',amber:'bg-amber-50 text-amber-700 dark:bg-amber-500/10 dark:text-amber-300'};
    const problem=enabled.find(x=>x.can_send===false&&x.channel!=='web')||{};
    host.innerHTML=`<div class="flex flex-wrap items-start justify-between gap-3"><div><h3 class="font-semibold text-blue-800 dark:text-blue-200"><i class="fas fa-link mr-2"></i>通道与连接总览</h3><p class="mt-1 text-xs text-blue-700/80 dark:text-blue-200/80">集中展示连接状态、主动发送能力、失败原因和待补发数量。保存任务前也会使用这些状态做预检。</p></div><div class="flex flex-wrap gap-2"><button onclick="refreshChannelHealth()" class="px-3 py-1.5 rounded-lg bg-white/70 dark:bg-black/10 border border-blue-200/60 dark:border-blue-500/20 text-xs"><i class="fas fa-rotate mr-1"></i>刷新状态</button>${pending?`<button onclick="navigateTo('intelligence');setTimeout(()=>switchAutomationTab('pending'),80)" class="px-3 py-1.5 rounded-lg bg-amber-500 text-white text-xs"><i class="fas fa-clock-rotate-left mr-1"></i>查看补发队列</button>`:''}</div></div><div class="mt-4 grid grid-cols-2 lg:grid-cols-4 gap-2">${cards.map(([label,value,icon,tone])=>`<div class="rounded-xl ${toneCls[tone]} px-3 py-2"><div class="text-[11px] opacity-80"><i class="fas ${icon} mr-1"></i>${label}</div><div class="text-xl font-bold mt-1">${Number(value||0)}</div></div>`).join('')}</div><div class="mt-3 text-xs text-blue-700/80 dark:text-blue-200/80">最近成功：${escapeHtml(String(lastSuccess).replace('T',' ').slice(0,19))}${problem.message?`；当前优先处理：${escapeHtml(problem.label||problem.channel)} · ${escapeHtml(problem.message)}`:''}</div>`;
}
async function loadNotificationPolicies(){
    const host=document.getElementById('notification-policy-center');if(!host)return;
    try{
        const response=await fetch('/api/notification-policies'),data=await response.json();
        if(data.status!=='success')throw new Error(data.message||'读取通知策略失败');
        renderNotificationPolicies(data);
    }catch(error){
        host.innerHTML=`<div class="text-red-500"><i class="fas fa-circle-exclamation mr-2"></i>${escapeHtml(error.message||'通知策略加载失败')}</div>`;
    }
}
function notificationPolicyInput(id,profile,field,value,placeholder=''){
    return `<input data-policy-profile="${escapeHtml(id)}" data-policy-field="${escapeHtml(field)}" value="${escapeHtml(value)}" placeholder="${escapeHtml(placeholder)}" class="mt-1 w-full px-2.5 py-1.5 rounded-lg border border-indigo-100 dark:border-indigo-500/20 bg-white/70 dark:bg-black/10 text-xs">`;
}
function renderNotificationPolicies(data){
    const host=document.getElementById('notification-policy-center');if(!host)return;
    const profiles=data.profiles||{},enabled=data.enabled!==false;
    const recommendations=Array.isArray(data.recommendations)?data.recommendations:[];
    const recommendationHtml=recommendations.length?`<div class="mt-4 grid gap-2">${recommendations.map(item=>`
        <div class="rounded-xl border border-amber-200/70 dark:border-amber-500/30 bg-amber-50/80 dark:bg-amber-500/10 p-3 text-sm">
            <div class="flex flex-wrap items-start justify-between gap-2">
                <div><b class="text-amber-800 dark:text-amber-200"><i class="fas fa-lightbulb mr-1"></i>${escapeHtml(item.title||'策略建议')}</b><p class="mt-1 text-xs text-amber-700 dark:text-amber-200/80">${escapeHtml(item.summary||'根据最近失败记录生成的优化建议。')}</p></div>
                <button onclick="applyNotificationPolicyRecommendation('${escapeHtml(item.id||'')}',this)" class="px-3 py-1.5 rounded-lg bg-amber-500 text-white text-xs"><i class="fas fa-wand-magic-sparkles mr-1"></i>应用建议</button>
            </div>
        </div>`).join('')}</div>`:'';
    const order=['briefing','reminder','alert','query','default'];
    const rows=order.filter(id=>profiles[id]).map(id=>{
        const p=profiles[id]||{},channels=(p.channels||[]).join(','),exclude=(p.exclude||[]).join(',');
        return `<div class="rounded-xl border border-indigo-100 dark:border-indigo-500/20 bg-white/75 dark:bg-black/10 p-3">
            <div class="flex flex-wrap items-center justify-between gap-2"><b>${escapeHtml(p.label||id)}</b><span class="text-[11px] text-indigo-500">${escapeHtml(id)}</span></div>
            <div class="grid md:grid-cols-5 gap-2 mt-2">
                <label class="text-[11px] text-slate-500">主备通道${notificationPolicyInput(id,p,'channels',channels,'wecom_bot,weixin,web')}</label>
                <label class="text-[11px] text-slate-500">排除通道${notificationPolicyInput(id,p,'exclude',exclude,'weixin')}</label>
                <label class="text-[11px] text-slate-500">兜底通道${notificationPolicyInput(id,p,'fallback',p.fallback||'web','web')}</label>
                <label class="text-[11px] text-slate-500">补发有效期/分钟${notificationPolicyInput(id,p,'expire_minutes',p.expire_minutes??1440,'1440')}</label>
                <div class="flex flex-col gap-2 text-[11px] text-slate-500 pt-1">
                    <label class="inline-flex items-center gap-2"><input type="checkbox" data-policy-profile="${escapeHtml(id)}" data-policy-field="allow_retry" ${p.allow_retry!==false?'checked':''}>允许补发</label>
                    <label class="inline-flex items-center gap-2"><input type="checkbox" data-policy-profile="${escapeHtml(id)}" data-policy-field="replace_same_task" ${p.replace_same_task!==false?'checked':''}>只保留最新</label>
                </div>
            </div>
        </div>`;
    }).join('');
    host.innerHTML=`<div class="flex flex-wrap items-start justify-between gap-3"><div><h3 class="font-semibold text-indigo-800 dark:text-indigo-200"><i class="fas fa-route mr-2"></i>通知策略中心</h3><p class="mt-1 text-xs text-indigo-700/80 dark:text-indigo-200/80">按任务类型决定主备通道、是否补发和补发有效期，避免所有任务都走同一套发送逻辑。</p></div><div class="flex flex-wrap gap-2"><label class="inline-flex items-center gap-2 px-3 py-1.5 rounded-lg bg-white/70 dark:bg-black/10 border border-indigo-100 dark:border-indigo-500/20 text-xs"><input id="notification-policy-enabled" type="checkbox" ${enabled?'checked':''}>启用策略</label><button onclick="saveNotificationPolicies(this)" class="px-3 py-1.5 rounded-lg bg-indigo-600 text-white text-xs"><i class="fas fa-floppy-disk mr-1"></i>保存策略</button></div></div>${recommendationHtml}<div class="mt-4 grid gap-3">${rows}</div><div id="notification-policy-status" class="mt-2 text-xs"></div>`;
}
async function applyNotificationPolicyRecommendation(recommendationId,button){
    if(!recommendationId)return;
    const old=button?.innerHTML;if(button){button.disabled=true;button.innerHTML='<i class="fas fa-spinner fa-spin mr-1"></i>应用中';}
    const status=document.getElementById('notification-policy-status');
    try{
        const response=await fetch('/api/notification-policies',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'apply_recommendation',recommendation_id:recommendationId})});
        const data=await response.json();if(data.status!=='success')throw new Error(data.message||'应用建议失败');
        renderNotificationPolicies(data);_wsToast?.('策略建议已应用');
        if(status){status.textContent='已应用建议，后续任务会按新的通道策略执行。';status.className='mt-2 text-xs text-emerald-600';}
    }catch(error){if(status){status.textContent=`应用失败：${error.message||error}`;status.className='mt-2 text-xs text-red-500';}}
    finally{if(button){button.disabled=false;button.innerHTML=old;}}
}
async function saveNotificationPolicies(button){
    const old=button?.innerHTML;if(button){button.disabled=true;button.innerHTML='<i class="fas fa-spinner fa-spin mr-1"></i>保存中';}
    const profiles={};
    document.querySelectorAll('[data-policy-profile]').forEach(node=>{
        const id=node.dataset.policyProfile,field=node.dataset.policyField;if(!id||!field)return;
        profiles[id]=profiles[id]||{};
        if(node.type==='checkbox')profiles[id][field]=node.checked;
        else if(field==='channels'||field==='exclude')profiles[id][field]=String(node.value||'').split(/[,，]/).map(x=>x.trim()).filter(Boolean);
        else if(field==='expire_minutes')profiles[id][field]=Number(node.value||0);
        else profiles[id][field]=node.value;
    });
    const status=document.getElementById('notification-policy-status');
    try{
        const response=await fetch('/api/notification-policies',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled:document.getElementById('notification-policy-enabled')?.checked!==false,profiles})});
        const data=await response.json();if(data.status!=='success')throw new Error(data.message||'保存失败');
        renderNotificationPolicies(data);_wsToast?.('通知策略已保存');
        if(status){status.textContent='已保存，后续任务发送会按新策略执行。';status.className='mt-2 text-xs text-emerald-600';}
    }catch(error){if(status){status.textContent=`保存失败：${error.message||error}`;status.className='mt-2 text-xs text-red-500';}}
    finally{if(button){button.disabled=false;button.innerHTML=old;}}
}
function renderChannelHealth(channelName){
    const box=document.getElementById(`channel-health-${channelName}`);if(!box)return;
    const item=channelHealthData[channelName]||{level:'warning',message:'暂未获取到状态',ok:false};
    const cls=item.ok?'bg-emerald-50 text-emerald-700 dark:bg-emerald-500/10 dark:text-emerald-300':item.level==='error'?'bg-red-50 text-red-700 dark:bg-red-500/10 dark:text-red-300':'bg-orange-50 text-orange-700 dark:bg-orange-500/10 dark:text-orange-300';
    const icon=item.ok?'fa-circle-check':item.level==='error'?'fa-circle-exclamation':'fa-triangle-exclamation';
    const runtime=item.runtime||{};
    const reconnectButton=channelName==='wecom_bot'&&(!item.ok||runtime.recently_taken_over||runtime.owner_matches_current===false)?`<button onclick="reconnectWecomBot(this)" class="px-3 py-1.5 rounded-lg bg-white/70 dark:bg-black/10 border border-current/10 text-xs">重连企业微信</button>`:'';
    const repairWeixinButton=channelName==='weixin'&&(!item.ok||item.token_ready===false)?`<button onclick="repairWeixinChannel(this)" class="px-3 py-1.5 rounded-lg bg-white/70 dark:bg-black/10 border border-current/10 text-xs"><i class="fas fa-qrcode mr-1"></i>重新扫码修复</button>`:'';
    const pending=item.pending_delivery||{};
    const state=item.connection_state||'unknown';
    const stateTone=state==='connected'?'bg-emerald-100/80 text-emerald-700 dark:bg-emerald-500/20 dark:text-emerald-200':state==='expired'||state==='error'?'bg-red-100/80 text-red-700 dark:bg-red-500/20 dark:text-red-200':state==='connecting'?'bg-blue-100/80 text-blue-700 dark:bg-blue-500/20 dark:text-blue-200':'bg-slate-100/80 text-slate-600 dark:bg-white/10 dark:text-slate-200';
    const sendTone=item.can_send?'bg-emerald-100/80 text-emerald-700 dark:bg-emerald-500/20 dark:text-emerald-200':'bg-orange-100/80 text-orange-700 dark:bg-orange-500/20 dark:text-orange-200';
    const statusChips=`<span class="inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[11px] ${stateTone}"><i class="fas ${state==='connected'?'fa-circle-check':state==='connecting'?'fa-arrows-rotate':state==='expired'||state==='error'?'fa-circle-exclamation':'fa-circle'}"></i>${escapeHtml(item.connection_state_label||'待检查')}</span><span class="inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[11px] ${sendTone}"><i class="fas fa-paper-plane"></i>${escapeHtml(item.active_send_label||(item.can_send?'可主动发送':'不可主动发送'))}</span>${Number(pending.pending||0)>0?`<span class="inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[11px] bg-amber-100/80 text-amber-700 dark:bg-amber-500/20 dark:text-amber-200"><i class="fas fa-clock-rotate-left"></i>待补发 ${Number(pending.pending||0)}</span>`:''}`;
    const pendingButton=Number(pending.pending||0)>0?`<button onclick="retryPendingDeliveries('${channelName}',this)" class="px-3 py-1.5 rounded-lg bg-white/70 dark:bg-black/10 border border-current/10 text-xs"><i class="fas fa-paper-plane mr-1"></i>立即补发 ${Number(pending.pending||0)}</button>`:'';
    const pendingLatest=(pending.latest||[]).slice(0,3).map(row=>`<div class="rounded-lg bg-white/50 dark:bg-black/10 border border-current/10 px-2 py-1"><b>${escapeHtml(row.task_name||'待补发通知')}</b><span class="ml-1 opacity-70">${escapeHtml(row.status||'pending')} · ${Number(row.attempts||0)}次</span>${row.reason?`<div class="mt-0.5 opacity-75">${escapeHtml(row.reason)}</div>`:''}</div>`).join('');
    const pendingHtml=(Number(pending.pending||0)||Number(pending.failed||0)||Number(pending.delivered||0))?`<div class="mt-3 rounded-lg bg-white/50 dark:bg-black/10 border border-current/10 p-2 text-[11px] leading-5"><div class="font-semibold mb-1"><i class="fas fa-clock-rotate-left mr-1"></i>自动补发队列</div><div>待补发 ${Number(pending.pending||0)} 条 · 已补发 ${Number(pending.delivered||0)} 条 · 失败 ${Number(pending.failed||0)} 条</div>${pendingLatest?`<div class="mt-2 space-y-1">${pendingLatest}</div>`:''}</div>`:'';
    const authModes=(item.auth_modes||[]).map(mode=>`<span class="inline-flex items-center gap-1 px-2 py-1 rounded-lg bg-white/60 dark:bg-black/10 border border-current/10">${mode.recommended?'<i class="fas fa-star text-amber-400"></i>':''}${escapeHtml(mode.name||'授权方式')}</span>`).join('');
    const scopes=(item.scopes||[]).map(scope=>`<li><b>${escapeHtml(scope.name||'权限')}</b>：${escapeHtml(scope.reason||'用于连接和发送通知。')}</li>`).join('');
    const fallback=(item.fallback_modes||[]).map(mode=>escapeHtml(mode.name||'备用方式')).join(' / ');
    const guidanceHtml=`<div class="mt-3 grid md:grid-cols-2 gap-3 text-[11px] leading-5">
        <div class="rounded-lg bg-white/50 dark:bg-black/10 border border-current/10 p-2">
            <div class="font-semibold mb-1">连接方式</div>
            <div class="flex flex-wrap gap-1.5">${authModes||'<span>手动配置</span>'}</div>
            ${fallback?`<div class="mt-1 opacity-80">备用：${fallback}</div>`:''}
        </div>
        <div class="rounded-lg bg-white/50 dark:bg-black/10 border border-current/10 p-2">
            <div class="font-semibold mb-1">状态建议</div>
            <div>风险：${escapeHtml(item.risk||'待检查')}</div>
            <div>下一步：${escapeHtml(item.next_action||'保存后发送测试。')}</div>
        </div>
        ${scopes?`<details class="md:col-span-2 rounded-lg bg-white/50 dark:bg-black/10 border border-current/10 p-2"><summary class="font-semibold cursor-pointer select-none">为什么需要这些权限</summary><ul class="list-disc pl-4 space-y-0.5 mt-1">${scopes}</ul>${item.lifecycle?`<div class="mt-1 opacity-80">${escapeHtml(item.lifecycle)}</div>`:''}</details>`:''}
    </div>`;
    const decisionHtml=renderDecisionCard(channelDecisionFromHealth(item),{kind:'notification',title:'系统发送判断',compact:true});
    box.className=`mb-5 rounded-xl px-4 py-3 text-xs ${cls}`;
    box.innerHTML=`<div class="flex flex-wrap items-center justify-between gap-2"><div class="min-w-0"><div><i class="fas ${icon} mr-2"></i>${escapeHtml(item.message||'状态未知')}${item.receiver_hint?` · ${escapeHtml(item.receiver_hint)}`:''}</div><div class="mt-2 flex flex-wrap gap-1.5">${statusChips}</div></div><span class="flex flex-wrap gap-2">${pendingButton}${reconnectButton}${repairWeixinButton}<button onclick="testChannelHealth('${channelName}',this)" class="px-3 py-1.5 rounded-lg bg-white/70 dark:bg-black/10 border border-current/10 text-xs">发送测试</button></span></div>${decisionHtml}${pendingHtml}${guidanceHtml}`;
}
async function retryPendingDeliveries(channelName,button){
    const old=button?.innerHTML;if(button){button.disabled=true;button.innerHTML='<i class="fas fa-spinner fa-spin mr-1"></i>补发中';}
    try{
        const response=await fetch('/api/channels/health',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({channel:channelName,action:'retry_pending',limit:10})});
        const data=await response.json();
        if(data.status!=='success')throw new Error(data.message||'补发失败');
        _wsToast?.(data.message||'已尝试补发');
        await refreshChannelHealth();
        loadAutomationNotifications?.();
    }catch(error){_wsToast?.(`补发失败：${error.message||error}`);}
    finally{if(button){button.disabled=false;button.innerHTML=old;}}
}
async function repairWeixinChannel(button){
    const old=button?.innerHTML;
    if(button){button.disabled=true;button.innerHTML='<i class="fas fa-spinner fa-spin mr-1"></i>准备扫码';}
    try{
        stopWeixinQrPoll();
        stopWeixinStatusPoll();
        const response=await fetch('/api/weixin/qrlogin',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'unbind'})});
        const data=await response.json();
        if(data.status!=='success')throw new Error(data.message||'无法重置微信登录');
        const box=document.getElementById('channel-health-weixin');
        if(box){
            box.className='mb-5 rounded-xl px-4 py-3 text-xs bg-orange-50 text-orange-700 dark:bg-orange-500/10 dark:text-orange-300';
            box.innerHTML='<div id="weixin-qr-panel" class="flex flex-col items-center py-3"><p class="text-sm mb-3"><i class="fas fa-spinner fa-spin mr-2"></i>正在生成新的绿微信二维码...</p></div>';
        }
        startWeixinQrLogin();
    }catch(error){
        _wsToast?.(`微信修复失败：${error.message||error}`);
        if(button){button.disabled=false;button.innerHTML=old;}
    }
}
async function reconnectWecomBot(button){
    const old=button?.innerHTML;if(button){button.disabled=true;button.innerHTML='<i class="fas fa-spinner fa-spin mr-1"></i>重连中';}
    try{
        const response=await fetch('/api/channels/health',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({channel:'wecom_bot',action:'reconnect'})});
        const data=await response.json();
        if(data.status!=='success')throw new Error(data.message||'重连失败');
        _wsToast?.(data.message||'已触发企业微信重连');
        setTimeout(()=>refreshChannelHealth(),1500);
    }catch(error){_wsToast?.(`企业微信重连失败：${error.message||error}`);}
    finally{if(button){button.disabled=false;button.innerHTML=old;}}
}
async function testChannelHealth(channelName,button){
    const old=button?.innerHTML;
    let receiver='';
    if(channelName==='wechatcom_app'){
        const hint='请输入企业微信成员 UserID，用于发送一条测试消息';
        receiver=(prompt(hint)||'').trim();
        if(!receiver){_wsToast?.('已取消测试发送');return;}
    }
    if(button){button.disabled=true;button.innerHTML='<i class="fas fa-spinner fa-spin mr-1"></i>测试中';}
    try{
        const response=await fetch('/api/channels/health',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({channel:channelName,receiver})});
        const data=await response.json();
        if(data.status!=='success')throw new Error(data.message||'测试发送失败');
        _wsToast?.('测试消息已发送');
        await refreshChannelHealth();
    }catch(error){
        _wsToast?.(`测试失败：${error.message||error}`);
    }finally{
        if(button){button.disabled=false;button.innerHTML=old;}
    }
}

async function testChannelHealthWithRetry(channelName, attempts=3){
    let lastData=null,lastError=null;
    for(let i=0;i<attempts;i++){
        try{
            const response=await fetch('/api/channels/health',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({channel:channelName})});
            const data=await response.json();
            lastData=data;
            if(data.status==='success')return data;
            lastError=new Error(data.message||'测试发送失败');
        }catch(error){
            lastError=error;
        }
        if(i<attempts-1)await new Promise(resolve=>setTimeout(resolve,1200+i*900));
    }
    if(lastData)return lastData;
    throw lastError||new Error('测试发送失败');
}

function buildChannelFieldsHtml(chName, fields) {
    let html = '';
    fields.forEach(f => {
        const inputId = `ch-${chName}-${f.key}`;
        let inputHtml = '';
        if (f.type === 'bool') {
            const checked = f.value ? 'checked' : '';
            inputHtml = `<label class="relative inline-flex items-center cursor-pointer">
                <input id="${inputId}" type="checkbox" ${checked} class="sr-only peer" data-field="${f.key}" data-ch="${chName}">
                <div class="w-9 h-5 bg-slate-200 dark:bg-slate-700 peer-checked:bg-primary-400 rounded-full
                            after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white
                            after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked:after:translate-x-full"></div>
            </label>`;
        } else if (f.type === 'secret') {
            inputHtml = `<input id="${inputId}" type="text" value="${escapeHtml(String(f.value || ''))}"
                data-field="${f.key}" data-ch="${chName}" data-masked="${f.value ? '1' : ''}"
                class="w-full px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-600
                       bg-slate-50 dark:bg-white/5 text-sm text-slate-800 dark:text-slate-100
                       focus:outline-none focus:border-primary-500 font-mono transition-colors
                       ${f.value ? 'cfg-key-masked' : ''}"
                placeholder="${escapeHtml(f.label)}">`;
        } else {
            const inputType = f.type === 'number' ? 'number' : 'text';
            inputHtml = `<input id="${inputId}" type="${inputType}" value="${escapeHtml(String(f.value ?? f.default ?? ''))}"
                data-field="${f.key}" data-ch="${chName}"
                class="w-full px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-600
                       bg-slate-50 dark:bg-white/5 text-sm text-slate-800 dark:text-slate-100
                       focus:outline-none focus:border-primary-500 font-mono transition-colors"
                placeholder="${escapeHtml(f.label)}">`;
        }
        html += `<div>
            <label class="block text-sm font-medium text-slate-600 dark:text-slate-400 mb-1.5">${escapeHtml(f.label)}</label>
            ${inputHtml}
        </div>`;
    });
    return html;
}

function bindSecretFieldEvents(container) {
    container.querySelectorAll('input[data-masked="1"]').forEach(inp => {
        inp.addEventListener('focus', function() {
            if (this.dataset.masked === '1') {
                this.value = '';
                this.dataset.masked = '';
                this.classList.remove('cfg-key-masked');
            }
        });
    });
}

function showChannelStatus(chName, msgKey, isError) {
    const el = document.getElementById(`ch-status-${chName}`);
    if (!el) return;
    el.textContent = t(msgKey);
    el.classList.toggle('text-red-500', !!isError);
    el.classList.toggle('text-primary-500', !isError);
    el.classList.remove('opacity-0');
    setTimeout(() => el.classList.add('opacity-0'), 2500);
}

async function saveChannelConfig(chName) {
    const card = document.getElementById(`channel-card-${chName}`);
    if (!card) return;

    const updates = {};
    card.querySelectorAll('input[data-ch="' + chName + '"]').forEach(inp => {
        const key = inp.dataset.field;
        if (inp.type === 'checkbox') {
            updates[key] = inp.checked;
        } else {
            if (inp.dataset.masked === '1') return;
            updates[key] = inp.value;
        }
    });

    const btn = document.getElementById(`ch-save-${chName}`);
    const old=btn?.innerHTML;
    if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin mr-1"></i>保存并测试'; }
    try {
        const response = await fetch('/api/channels', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ action: 'save', channel: chName, config: updates })
        });
        const data = await response.json();
        if (data.status !== 'success') throw new Error(data.message || '保存失败');
        showChannelStatus(chName, data.restarted ? 'channels_restarted' : 'channels_saved', false);
        await new Promise(resolve=>setTimeout(resolve, data.restarted ? 1800 : 300));
        await refreshChannelHealth();
        const testData = await testChannelHealthWithRetry(chName, data.restarted ? 4 : 2);
        if(testData.status==='success'){
            _wsToast?.('配置已保存，测试消息已发送');
            showChannelStatus(chName, 'channels_saved', false);
        }else{
            _wsToast?.(`已保存，但测试失败：${testData.message||'请检查接收目标'}`);
            showChannelStatus(chName, 'channels_save_error', true);
        }
        await refreshChannelHealth();
    } catch(error) {
        _wsToast?.(`保存或测试失败：${error.message||error}`);
        showChannelStatus(chName, 'channels_save_error', true);
    } finally {
        if (btn) { btn.disabled = false; btn.innerHTML = old || '保存并测试连接'; }
    }
}

function disconnectChannel(chName) {
    const ch = channelsData.find(c => c.name === chName);
    const label = ch ? ((typeof ch.label === 'object') ? (ch.label[currentLang] || ch.label.en) : ch.label) : chName;

    showConfirmDialog({
        title: t('channels_disconnect'),
        message: t('channels_disconnect_confirm'),
        okText: t('channels_disconnect'),
        cancelText: t('channels_cancel'),
        onConfirm: () => {
            fetch('/api/channels', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ action: 'disconnect', channel: chName })
            })
            .then(r => r.json())
            .then(data => {
                if (data.status === 'success') {
                    if (ch) ch.active = false;
                    renderActiveChannels();
                }
            })
            .catch(() => {});
        }
    });
}

function unbindWecomBot() {
    showConfirmDialog({
        title: '解绑企业微信',
        message: '解绑后将停止企业微信智能机器人通道，并清除 Bot ID、Secret、Token 和 AES Key。历史会话记录会保留。',
        okText: '确认解绑',
        cancelText: t('channels_cancel'),
        onConfirm: () => {
            fetch('/api/channels', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ action: 'unbind', channel: 'wecom_bot' })
            })
            .then(r => r.json())
            .then(data => {
                if (data.status !== 'success') throw new Error(data.message || '解绑失败');
                const ch = channelsData.find(c => c.name === 'wecom_bot');
                if (ch) {
                    ch.active = false;
                    (ch.fields || []).forEach(f => {
                        if (['wecom_bot_id','wecom_bot_secret','wecom_bot_token','wecom_bot_encoding_aes_key'].includes(f.key)) f.value = '';
                    });
                }
                renderActiveChannels();
                _wsToast?.('企业微信已解绑');
            })
            .catch(error => _wsToast?.(`解绑失败：${error.message || error}`));
        }
    });
}

function unbindWeixin() {
    showConfirmDialog({
        title: '解绑微信',
        message: '解绑后将清除当前微信登录凭证并停止接收消息，之后可以重新扫码绑定。用户授权记录会保留。',
        okText: '确认解绑',
        cancelText: t('channels_cancel'),
        onConfirm: async () => {
            try {
                stopWeixinQrPoll();
                stopWeixinStatusPoll();
                const response = await fetch('/api/weixin/qrlogin', {
                    method: 'POST', headers: {'Content-Type':'application/json'},
                    body: JSON.stringify({action:'unbind'})
                });
                const data = await response.json();
                if (data.status !== 'success') throw new Error(data.message || '解绑失败');
                await new Promise(resolve => setTimeout(resolve, 400));
                loadChannelsView();
            } catch (error) {
                alert(error.message || '解绑失败');
            }
        }
    });
}

// --- Add channel panel ---
function openAddChannelPanel(preselected='') {
    const panel = document.getElementById('channels-add-panel');
    const activeNames = new Set(channelsData.filter(c => c.active).map(c => c.name));
    const available = channelsData.filter(c => !activeNames.has(c.name));

    const content = document.getElementById('channels-content');
    if (activeNames.size === 0 && content) content.classList.add('hidden');

    if (available.length === 0) {
        panel.innerHTML = `<div class="bg-white dark:bg-[#1A1A1A] rounded-xl border border-slate-200 dark:border-white/10 p-6 text-center">
            <p class="text-sm text-slate-500 dark:text-slate-400">${currentLang === 'zh' ? '所有通道均已接入' : 'All channels are already connected'}</p>
            <button onclick="closeAddChannelPanel()" class="mt-3 text-xs text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 cursor-pointer">${t('channels_cancel')}</button>
        </div>`;
        panel.classList.remove('hidden');
        return;
    }

    const ddOptions = [
        { value: '', label: t('channels_select_placeholder') },
        ...available.map(ch => {
            const label = (typeof ch.label === 'object') ? (ch.label[currentLang] || ch.label.en) : ch.label;
            return { value: ch.name, label: `${label} (${ch.name})` };
        })
    ];

    panel.innerHTML = `
        <div class="bg-white dark:bg-[#1A1A1A] rounded-xl border border-primary-200 dark:border-primary-800 p-6">
            <div class="flex items-center gap-3 mb-5">
                <div class="w-9 h-9 rounded-lg bg-primary-50 dark:bg-primary-900/30 flex items-center justify-center">
                    <i class="fas fa-plus text-primary-500 text-sm"></i>
                </div>
                <h3 class="font-semibold text-slate-800 dark:text-slate-100">${t('channels_add')}</h3>
            </div>
            <div class="mb-4">
                <div id="add-channel-select" class="cfg-dropdown" tabindex="0">
                    <div class="cfg-dropdown-selected">
                        <span class="cfg-dropdown-text">--</span>
                        <i class="fas fa-chevron-down cfg-dropdown-arrow"></i>
                    </div>
                    <div class="cfg-dropdown-menu"></div>
                </div>
            </div>
            <div id="add-channel-fields" class="space-y-4"></div>
            <div id="add-channel-actions" class="hidden flex items-center justify-end gap-3 pt-4">
                <button onclick="closeAddChannelPanel()"
                    class="px-4 py-2 rounded-lg border border-slate-200 dark:border-white/10
                           text-slate-600 dark:text-slate-300 text-sm font-medium
                           hover:bg-slate-50 dark:hover:bg-white/5
                           cursor-pointer transition-colors duration-150">${t('channels_cancel')}</button>
                <button id="add-channel-submit" onclick="submitAddChannel()"
                    class="px-4 py-2 rounded-lg bg-primary-500 hover:bg-primary-600 text-white text-sm font-medium
                           cursor-pointer transition-colors duration-150 disabled:opacity-50 disabled:cursor-not-allowed">${t('channels_connect_btn')}</button>
            </div>
        </div>`;
    panel.classList.remove('hidden');
    panel.scrollIntoView({ behavior: 'smooth', block: 'nearest' });

    const ddEl = document.getElementById('add-channel-select');
    initDropdown(ddEl, ddOptions, preselected, onAddChannelSelect);
    if(preselected)onAddChannelSelect(preselected);
}

function closeAddChannelPanel() {
    stopWeixinQrPoll();
    stopFeishuRegisterPoll();
    const panel = document.getElementById('channels-add-panel');
    if (panel) {
        panel.classList.add('hidden');
        panel.innerHTML = '';
    }
    const content = document.getElementById('channels-content');
    if (content) content.classList.remove('hidden');
}

function onAddChannelSelect(chName) {
    stopWeixinQrPoll();
    stopFeishuRegisterPoll();
    const fieldsContainer = document.getElementById('add-channel-fields');
    const actions = document.getElementById('add-channel-actions');

    if (!chName) {
        fieldsContainer.innerHTML = '';
        actions.classList.add('hidden');
        return;
    }

    if (chName === 'weixin') {
        actions.classList.add('hidden');
        fieldsContainer.innerHTML = `
            <div id="weixin-qr-panel" class="flex flex-col items-center py-4">
                <p class="text-sm text-slate-500 dark:text-slate-400 mb-4">${t('weixin_scan_loading')}</p>
            </div>`;
        startWeixinQrLogin();
        return;
    }

    if (chName === 'wecom_bot') {
        actions.classList.add('hidden');
        const ch = channelsData.find(c => c.name === chName);
        fieldsContainer.innerHTML = buildWecomBotPanel(ch);
        return;
    }

    if (chName === 'feishu') {
        actions.classList.add('hidden');
        const ch = channelsData.find(c => c.name === chName);
        fieldsContainer.innerHTML = buildFeishuPanel(ch);
        return;
    }

    if (chName === 'wechatcom_app') {
        const ch = channelsData.find(c => c.name === chName);
        fieldsContainer.innerHTML = buildWechatComAppPanel(ch);
        bindSecretFieldEvents(fieldsContainer);
        actions.classList.remove('hidden');
        return;
    }

    const ch = channelsData.find(c => c.name === chName);
    if (!ch) return;

    fieldsContainer.innerHTML = buildChannelFieldsHtml(chName, ch.fields || []);
    bindSecretFieldEvents(fieldsContainer);
    actions.classList.remove('hidden');
}

function submitAddChannel() {
    const ddEl = document.getElementById('add-channel-select');
    const chName = getDropdownValue(ddEl);
    if (!chName) return;

    const fieldsContainer = document.getElementById('add-channel-fields');
    const updates = {};
    fieldsContainer.querySelectorAll('input[data-ch="' + chName + '"]').forEach(inp => {
        const key = inp.dataset.field;
        if (inp.type === 'checkbox') {
            updates[key] = inp.checked;
        } else {
            if (inp.dataset.masked === '1') return;
            updates[key] = inp.value;
        }
    });

    const btn = document.getElementById('add-channel-submit');
    if (btn) { btn.disabled = true; btn.textContent = t('channels_connecting'); }

    fetch('/api/channels', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'connect', channel: chName, config: updates })
    })
    .then(r => r.json())
    .then(data => {
        if (data.status === 'success') {
            const ch = channelsData.find(c => c.name === chName);
            if (ch) {
                ch.active = true;
                (ch.fields || []).forEach(f => {
                    if (updates[f.key] !== undefined) {
                        f.value = f.type === 'secret' ? ChannelsHandler_maskSecret(updates[f.key]) : updates[f.key];
                    }
                });
            }
            renderActiveChannels();
            refreshChannelHealth();
        } else {
            if (btn) { btn.disabled = false; btn.textContent = t('channels_connect_btn'); }
        }
    })
    .catch(() => {
        if (btn) { btn.disabled = false; btn.textContent = t('channels_connect_btn'); }
    });
}

// =====================================================================
// WeChat QR Login
// =====================================================================
let _weixinQrPollTimer = null;
let _weixinStatusPollTimer = null;

function stopWeixinStatusPoll() {
    if (_weixinStatusPollTimer) {
        clearTimeout(_weixinStatusPollTimer);
        _weixinStatusPollTimer = null;
    }
}

function startWeixinActiveStatusPoll() {
    stopWeixinStatusPoll();
    _weixinStatusPollTimer = setTimeout(() => {
        fetch('/api/channels').then(r => r.json()).then(data => {
            if (data.status !== 'success') return;
            const wx = (data.channels || []).find(c => c.name === 'weixin');
            if (!wx || !wx.active) return;
            if (wx.login_status === 'logged_in') {
                channelsData = data.channels;
                renderActiveChannels();
            } else {
                const ch = channelsData.find(c => c.name === 'weixin');
                if (ch) ch.login_status = wx.login_status;
                startWeixinActiveStatusPoll();
            }
        }).catch(() => { startWeixinActiveStatusPoll(); });
    }, 3000);
}

function showWeixinActiveQr() {
    const container = document.getElementById('weixin-active-qr');
    if (!container) return;
    container.innerHTML = `
        <div id="weixin-qr-panel" class="flex flex-col items-center py-2">
            <p class="text-sm text-slate-500 dark:text-slate-400 mb-4">${t('weixin_scan_loading')}</p>
        </div>`;
    stopWeixinStatusPoll();
    startWeixinQrLogin();
}

function stopWeixinQrPoll() {
    if (_weixinQrPollTimer) {
        clearTimeout(_weixinQrPollTimer);
        _weixinQrPollTimer = null;
    }
}

function startWeixinQrLogin() {
    stopWeixinQrPoll();
    fetch('/api/weixin/qrlogin')
        .then(r => r.json())
        .then(data => {
            const panel = document.getElementById('weixin-qr-panel');
            if (!panel) return;
            if (data.status !== 'success') {
                panel.innerHTML = `<p class="text-sm text-red-500">${t('weixin_scan_fail')}: ${data.message || ''}</p>`;
                return;
            }
            renderWeixinQr(data.qr_image || data.qrcode_url, 'waiting');
            if (data.source === 'channel') {
                startWeixinActiveStatusPoll();
            } else {
                pollWeixinQrStatus();
            }
        })
        .catch(() => {
            const panel = document.getElementById('weixin-qr-panel');
            if (panel) panel.innerHTML = `<p class="text-sm text-red-500">${t('weixin_scan_fail')}</p>`;
        });
}

function renderWeixinQr(qrcodeUrl, status) {
    const panel = document.getElementById('weixin-qr-panel');
    if (!panel) return;

    let statusText = t('weixin_scan_waiting');
    let statusColor = 'text-slate-500 dark:text-slate-400';
    if (status === 'scanned') {
        statusText = t('weixin_scan_scanned');
        statusColor = 'text-primary-500';
    } else if (status === 'expired') {
        statusText = t('weixin_scan_expired');
        statusColor = 'text-amber-500';
    } else if (status === 'confirmed') {
        statusText = t('weixin_scan_success');
        statusColor = 'text-primary-500';
    }

    panel.innerHTML = `
        <div class="flex flex-col items-center">
            <p class="text-sm font-medium text-slate-700 dark:text-slate-200 mb-1">${t('weixin_scan_title')}</p>
            <p class="text-xs text-slate-400 dark:text-slate-500 mb-4">${t('weixin_scan_desc')}</p>
            <div class="bg-white p-3 rounded-xl shadow-sm border border-slate-100 dark:border-slate-700 mb-3">
                <img src="${escapeHtml(qrcodeUrl)}" alt="QR Code" class="w-52 h-52" style="image-rendering: pixelated;"/>
            </div>
            <p class="text-xs ${statusColor} mb-1">${statusText}</p>
            <p class="text-xs text-slate-400 dark:text-slate-500">${t('weixin_qr_tip')}</p>
        </div>`;
}

function pollWeixinQrStatus() {
    _weixinQrPollTimer = setTimeout(() => {
        fetch('/api/weixin/qrlogin', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ action: 'poll' })
        })
        .then(r => r.json())
        .then(data => {
            const panel = document.getElementById('weixin-qr-panel');
            if (!panel) { stopWeixinQrPoll(); return; }

            if (data.status !== 'success') {
                panel.innerHTML = `<div class="py-5 text-center text-sm text-red-500">${escapeHtml(data.message || '微信登录失败，请刷新二维码后重试')}</div>`;
                stopWeixinQrPoll();
                return;
            }

            const qrStatus = data.qr_status;
            if (qrStatus === 'confirmed') {
                renderWeixinQr('', 'confirmed');
                panel.innerHTML = `
                    <div class="flex flex-col items-center py-4">
                        <div class="w-12 h-12 rounded-full bg-primary-50 dark:bg-primary-900/30 flex items-center justify-center mb-3">
                            <i class="fas fa-check text-primary-500 text-lg"></i>
                        </div>
                        <p class="text-sm font-medium text-primary-600 dark:text-primary-400">${t('weixin_scan_success')}</p>
                    </div>`;
                connectWeixinAfterQr();
            } else if (qrStatus === 'expired' && (data.qr_image || data.qrcode_url)) {
                renderWeixinQr(data.qr_image || data.qrcode_url, 'waiting');
                pollWeixinQrStatus();
            } else if (qrStatus === 'scaned') {
                const img = panel.querySelector('img');
                const currentSrc = img ? img.src : '';
                renderWeixinQr(currentSrc, 'scanned');
                pollWeixinQrStatus();
            } else {
                pollWeixinQrStatus();
            }
        })
        .catch(() => {
            pollWeixinQrStatus();
        });
    }, 2000);
}

function connectWeixinAfterQr() {
    fetch('/api/channels', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'connect', channel: 'weixin', config: {} })
    })
    .then(r => r.json())
    .then(data => {
        if (data.status === 'success') {
            const ch = channelsData.find(c => c.name === 'weixin');
            if (ch) ch.active = true;
            setTimeout(() => renderActiveChannels(), 1500);
        }
    })
    .catch(() => {});
}

// =====================================================================
// WeCom Bot QR Auth
// =====================================================================
// NOTE: This is the only remaining external script in the Web Console.
// Tencent's WeCom Bot SDK must be loaded from their official CDN — it
// performs runtime origin/signature checks and will not work if
// self-hosted. The SDK is fetched lazily, only when the user opens the
// "WeCom Bot" channel QR-login flow, so the rest of the console works
// fully offline.
const WECOM_BOT_SDK_URL = 'https://wwcdn.weixin.qq.com/node/wework/js/wecom-aibot-sdk@0.1.0.min.js';
const WECOM_BOT_SOURCE = 'cowagent';
let _wecomSdkLoaded = false;

function ensureWecomSdkLoaded() {
    return new Promise((resolve, reject) => {
        if (_wecomSdkLoaded && window.WecomAIBotSDK) { resolve(); return; }
        if (document.querySelector(`script[src="${WECOM_BOT_SDK_URL}"]`)) {
            _wecomSdkLoaded = true; resolve(); return;
        }
        const s = document.createElement('script');
        s.src = WECOM_BOT_SDK_URL;
        s.onload = () => { _wecomSdkLoaded = true; resolve(); };
        s.onerror = () => reject(new Error('Failed to load WecomAIBotSDK'));
        document.head.appendChild(s);
    });
}

function _wecomBotHasCreds(ch) {
    if (!ch || !ch.fields) return false;
    const idField = ch.fields.find(f => f.key === 'wecom_bot_id');
    const secretField = ch.fields.find(f => f.key === 'wecom_bot_secret');
    return !!(idField && idField.value && secretField && secretField.value);
}

function _wecomFieldValue(ch,key){
    return (ch?.fields||[]).find(f=>f.key===key)?.value||'';
}

function buildWecomBotPanel(ch) {
    const scanLabel = t('wecom_mode_scan');
    const manualLabel = t('wecom_mode_manual');
    const hasCreds = _wecomBotHasCreds(ch);
    const defaultMode = hasCreds ? 'manual' : 'scan';
    return `
        <div id="wecom-bot-panel" data-default-mode="${defaultMode}">
            <div class="mb-4 rounded-xl border border-emerald-100 dark:border-emerald-500/20 bg-emerald-50/70 dark:bg-emerald-500/10 p-4 text-sm text-emerald-800 dark:text-emerald-200">
                <div class="font-semibold mb-1"><i class="fas fa-building-user mr-2"></i>企业微信智能机器人</div>
                <p class="text-xs leading-6">推荐先用扫码创建，适合“在企业微信里直接给 Agent 发消息”。如果企业后台不能扫码创建，可切换到手动配置 webhook 回调。</p>
            </div>
            <div class="flex items-center justify-center gap-1 mb-5 bg-slate-100 dark:bg-white/5 rounded-lg p-1">
                <button id="wecom-tab-scan" onclick="switchWecomBotMode('scan')"
                    class="flex-1 px-3 py-1.5 rounded-md text-xs font-medium transition-colors
                           bg-white dark:bg-slate-700 text-slate-800 dark:text-slate-100 shadow-sm">
                    ${scanLabel}
                </button>
                <button id="wecom-tab-manual" onclick="switchWecomBotMode('manual')"
                    class="flex-1 px-3 py-1.5 rounded-md text-xs font-medium transition-colors
                           text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200">
                    ${manualLabel}
                </button>
            </div>
            <div id="wecom-mode-content"></div>
        </div>`;
}

function switchWecomBotMode(mode) {
    const scanTab = document.getElementById('wecom-tab-scan');
    const manualTab = document.getElementById('wecom-tab-manual');
    const content = document.getElementById('wecom-mode-content');
    const actions = document.getElementById('add-channel-actions');
    if (!scanTab || !manualTab || !content) return;

    const activeClasses = 'bg-white dark:bg-slate-700 text-slate-800 dark:text-slate-100 shadow-sm';
    const inactiveClasses = 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200';

    if (mode === 'scan') {
        scanTab.className = scanTab.className.replace(/text-slate-500[^\s]*/g, '').replace(/hover:\S+/g, '');
        scanTab.className = `flex-1 px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${activeClasses}`;
        manualTab.className = `flex-1 px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${inactiveClasses}`;
        actions.classList.add('hidden');
        content.innerHTML = `
            <div class="flex flex-col items-center py-4">
                <p class="text-sm text-slate-600 dark:text-slate-300 mb-2">${t('wecom_scan_desc')}</p>
                <p class="text-xs text-slate-400 dark:text-slate-500 text-center max-w-lg leading-6">扫码成功后会自动写入 Bot ID 和 Secret；后续企业微信消息会进入统一任务路由、审批、执行、回传和学习记录。</p>
                <button onclick="startWecomBotAuth()"
                    class="mt-3 px-6 py-2.5 rounded-lg bg-emerald-500 hover:bg-emerald-600 text-white text-sm font-medium
                           cursor-pointer transition-colors duration-150">
                    <i class="fas fa-qrcode mr-2"></i>${t('wecom_scan_btn')}
                </button>
                <div id="wecom-scan-status" class="mt-3"></div>
            </div>`;
    } else {
        manualTab.className = `flex-1 px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${activeClasses}`;
        scanTab.className = `flex-1 px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${inactiveClasses}`;
        const ch = channelsData.find(c => c.name === 'wecom_bot');
        content.innerHTML = `
            <div class="rounded-xl bg-blue-50 dark:bg-blue-500/10 border border-blue-100 dark:border-blue-500/20 p-4 text-xs text-blue-700 dark:text-blue-200 leading-6 mb-4">
                <div class="font-semibold text-sm mb-1"><i class="fas fa-sliders mr-2"></i>手动接入说明</div>
                <p>websocket：填写 Bot ID / Secret 后启动长连接，适合智能机器人。</p>
                <p>webhook：填写 Token / Encoding AES Key / 端口，企业微信后台回调地址填 <code class="px-1 rounded bg-white/70 dark:bg-black/20">http://你的电脑或服务器IP:9892/wecom-bot/callback</code>。</p>
            </div>
            <div class="space-y-4">${buildChannelFieldsHtml('wecom_bot', ch ? ch.fields || [] : [])}</div>`;
        bindSecretFieldEvents(content);
        actions.classList.remove('hidden');
    }
}

function buildWechatComAppPanel(ch) {
    const port = _wecomFieldValue(ch,'wechatcomapp_port') || '9898';
    return `
        <div class="space-y-4">
            <div class="rounded-xl border border-emerald-100 dark:border-emerald-500/20 bg-emerald-50/70 dark:bg-emerald-500/10 p-4 text-sm text-emerald-800 dark:text-emerald-200">
                <div class="font-semibold mb-2"><i class="fas fa-building-shield mr-2"></i>企业微信自建应用</div>
                <div class="grid md:grid-cols-3 gap-3 text-xs leading-6">
                    <div class="rounded-lg bg-white/70 dark:bg-black/10 p-3"><span class="font-semibold">1. 企业后台建应用</span><br>获取 Corp ID、Agent ID、Secret。</div>
                    <div class="rounded-lg bg-white/70 dark:bg-black/10 p-3"><span class="font-semibold">2. 配置接收消息</span><br>设置 Token、Encoding AES Key。</div>
                    <div class="rounded-lg bg-white/70 dark:bg-black/10 p-3"><span class="font-semibold">3. 填写回调地址</span><br><code class="break-all">http://你的域名或IP:${escapeHtml(String(port))}/wxcomapp/</code></div>
                </div>
                <p class="mt-3 text-xs text-emerald-700/80 dark:text-emerald-100/80">适合企业内部员工直接给 Agent 发消息。登录、删除、支付、发布等高风险动作仍会进入审批中心。</p>
            </div>
            ${buildChannelFieldsHtml('wechatcom_app', ch ? ch.fields || [] : [])}
        </div>`;
}

function startWecomBotAuth() {
    const statusEl = document.getElementById('wecom-scan-status');
    ensureWecomSdkLoaded().then(() => {
        WecomAIBotSDK.openBotInfoAuthWindow({
            source: WECOM_BOT_SOURCE,
            onCreated: function(bot) {
                if (statusEl) {
                    statusEl.innerHTML = `
                        <div class="flex flex-col items-center py-2">
                            <div class="w-10 h-10 rounded-full bg-emerald-50 dark:bg-emerald-900/30 flex items-center justify-center mb-2">
                                <i class="fas fa-check text-emerald-500 text-lg"></i>
                            </div>
                            <p class="text-sm font-medium text-emerald-600 dark:text-emerald-400">${t('wecom_scan_success')}</p>
                        </div>`;
                }
                connectWecomBotAfterAuth(bot.botid, bot.secret);
            },
            onError: function(err) {
                if (statusEl) {
                    statusEl.innerHTML = `<p class="text-sm text-red-500">${t('wecom_scan_fail')}: ${err.message || err.code || ''}</p>`;
                }
            }
        });
    }).catch(err => {
        if (statusEl) {
            statusEl.innerHTML = `<p class="text-sm text-red-500">SDK load failed: ${err.message}</p>`;
        }
    });
}

function connectWecomBotAfterAuth(botId, secret) {
    fetch('/api/channels', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            action: 'connect',
            channel: 'wecom_bot',
            config: { wecom_bot_id: botId, wecom_bot_secret: secret }
        })
    })
    .then(r => r.json())
    .then(data => {
        if (data.status === 'success') {
            const ch = channelsData.find(c => c.name === 'wecom_bot');
            if (ch) {
                ch.active = true;
                (ch.fields || []).forEach(f => {
                    if (f.key === 'wecom_bot_id') f.value = botId;
                    if (f.key === 'wecom_bot_secret') f.value = ChannelsHandler_maskSecret(secret);
                });
            }
            setTimeout(() => renderActiveChannels(), 1500);
        }
    })
    .catch(() => {});
}

function startWecomBotAuthInCard() {
    const statusEl = document.getElementById('wecom-card-scan-status');
    ensureWecomSdkLoaded().then(() => {
        WecomAIBotSDK.openBotInfoAuthWindow({
            source: WECOM_BOT_SOURCE,
            onCreated: function(bot) {
                if (statusEl) {
                    statusEl.innerHTML = `
                        <div class="flex flex-col items-center py-2">
                            <div class="w-10 h-10 rounded-full bg-emerald-50 dark:bg-emerald-900/30 flex items-center justify-center mb-2">
                                <i class="fas fa-check text-emerald-500 text-lg"></i>
                            </div>
                            <p class="text-sm font-medium text-emerald-600 dark:text-emerald-400">${t('wecom_scan_success')}</p>
                        </div>`;
                }
                connectWecomBotAfterAuth(bot.botid, bot.secret);
            },
            onError: function(err) {
                if (statusEl) {
                    statusEl.innerHTML = `<p class="text-sm text-red-500">${t('wecom_scan_fail')}: ${err.message || err.code || ''}</p>`;
                }
            }
        });
    }).catch(err => {
        if (statusEl) {
            statusEl.innerHTML = `<p class="text-sm text-red-500">SDK load failed: ${err.message}</p>`;
        }
    });
}

// Initialize wecom bot panel with correct default mode when inserted into DOM
document.addEventListener('DOMContentLoaded', function() {
    const observer = new MutationObserver(function() {
        const wecomPanel = document.getElementById('wecom-bot-panel');
        if (wecomPanel && !wecomPanel.dataset.initialized) {
            wecomPanel.dataset.initialized = '1';
            switchWecomBotMode(wecomPanel.dataset.defaultMode || 'scan');
        }
        const feishuPanel = document.getElementById('feishu-panel');
        if (feishuPanel && !feishuPanel.dataset.initialized) {
            feishuPanel.dataset.initialized = '1';
            switchFeishuMode(feishuPanel.dataset.defaultMode || 'scan');
        }
    });
    observer.observe(document.body, { childList: true, subtree: true });
});

// =====================================================================
// Feishu One-click App Registration (lark-oapi register_app)
// =====================================================================
let _feishuRegisterPollTimer = null;

function _feishuHasCreds(ch) {
    if (!ch || !ch.fields) return false;
    const idField = ch.fields.find(f => f.key === 'feishu_app_id');
    const secretField = ch.fields.find(f => f.key === 'feishu_app_secret');
    return !!(idField && idField.value && secretField && secretField.value);
}

function buildFeishuPanel(ch, isActive) {
    const scanLabel = t('feishu_mode_scan');
    const manualLabel = t('feishu_mode_manual');
    // 已有凭据时默认进入手动 Tab，方便修改；否则推荐扫码
    const defaultMode = _feishuHasCreds(ch) ? 'manual' : 'scan';
    const activeAttr = isActive ? 'data-active="1"' : '';
    return `
        <div id="feishu-panel" data-default-mode="${defaultMode}" ${activeAttr}>
            <div class="flex items-center justify-center gap-1 mb-5 bg-slate-100 dark:bg-white/5 rounded-lg p-1">
                <button id="feishu-tab-scan" onclick="switchFeishuMode('scan')"
                    class="flex-1 px-3 py-1.5 rounded-md text-xs font-medium transition-colors
                           bg-white dark:bg-slate-700 text-slate-800 dark:text-slate-100 shadow-sm">
                    ${scanLabel}
                </button>
                <button id="feishu-tab-manual" onclick="switchFeishuMode('manual')"
                    class="flex-1 px-3 py-1.5 rounded-md text-xs font-medium transition-colors
                           text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200">
                    ${manualLabel}
                </button>
            </div>
            <div id="feishu-mode-content"></div>
        </div>`;
}

function switchFeishuMode(mode) {
    const panel = document.getElementById('feishu-panel');
    const scanTab = document.getElementById('feishu-tab-scan');
    const manualTab = document.getElementById('feishu-tab-manual');
    const content = document.getElementById('feishu-mode-content');
    if (!scanTab || !manualTab || !content) return;

    // 已激活通道卡片中嵌入此 panel 时，没有 add-channel-actions（保存按钮就近渲染）
    const isActive = panel && panel.dataset.active === '1';
    const actions = isActive ? null : document.getElementById('add-channel-actions');

    const activeClasses = 'bg-white dark:bg-slate-700 text-slate-800 dark:text-slate-100 shadow-sm';
    const inactiveClasses = 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200';

    stopFeishuRegisterPoll();

    if (mode === 'scan') {
        scanTab.className = `flex-1 px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${activeClasses}`;
        manualTab.className = `flex-1 px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${inactiveClasses}`;
        if (actions) actions.classList.add('hidden');
        // active 卡片下扫码替换的提示文案，强调"创建新机器人会覆盖现有配置"
        const desc = isActive
            ? t('feishu_scan_replace_desc')
            : t('feishu_scan_desc');
        content.innerHTML = `
            <div id="feishu-scan-panel" class="flex flex-col items-center py-4">
                <p class="text-sm text-slate-600 dark:text-slate-300 mb-3 text-center">${desc}</p>
                <button onclick="startFeishuRegister()"
                    class="mt-2 px-6 py-2.5 rounded-lg bg-emerald-500 hover:bg-emerald-600 text-white text-sm font-medium
                           cursor-pointer transition-colors duration-150">
                    <i class="fas fa-qrcode mr-2"></i>${t('feishu_scan_btn')}
                </button>
                <div id="feishu-scan-status" class="mt-4 w-full"></div>
            </div>`;
    } else {
        manualTab.className = `flex-1 px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${activeClasses}`;
        scanTab.className = `flex-1 px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${inactiveClasses}`;
        const ch = channelsData.find(c => c.name === 'feishu');
        const fieldsHtml = buildChannelFieldsHtml('feishu', ch ? ch.fields || [] : []);
        if (isActive) {
            // 已接入卡片：内置保存按钮，复用 saveChannelConfig 走 update 流程
            content.innerHTML = `
                <div class="space-y-4">
                    ${fieldsHtml}
                    <div class="flex items-center justify-end gap-3 pt-1">
                        <span id="ch-status-feishu" class="text-xs text-primary-500 opacity-0 transition-opacity duration-300"></span>
                        <button onclick="saveChannelConfig('feishu')"
                            class="px-4 py-2 rounded-lg bg-primary-500 hover:bg-primary-600 text-white text-sm font-medium
                                   cursor-pointer transition-colors duration-150 disabled:opacity-50 disabled:cursor-not-allowed"
                            id="ch-save-feishu">保存并测试连接</button>
                    </div>
                </div>`;
        } else {
            content.innerHTML = `<div class="space-y-4">${fieldsHtml}</div>`;
            if (actions) actions.classList.remove('hidden');
        }
        bindSecretFieldEvents(content);
    }
}

function stopFeishuRegisterPoll() {
    if (_feishuRegisterPollTimer) {
        clearTimeout(_feishuRegisterPollTimer);
        _feishuRegisterPollTimer = null;
    }
}

function startFeishuRegister(targetStatusId) {
    const statusId = targetStatusId || 'feishu-scan-status';
    const statusEl = document.getElementById(statusId);
    if (statusEl) {
        statusEl.innerHTML = `<p class="text-sm text-slate-500 dark:text-slate-400 text-center">${t('feishu_scan_loading')}</p>`;
    }
    stopFeishuRegisterPoll();
    fetch('/api/feishu/register')
        .then(r => r.json())
        .then(data => {
            if (data.status !== 'success') {
                renderFeishuRegisterError(statusId, data.message || t('feishu_scan_fail'));
                return;
            }
            if (data.register_status === 'downloading') {
                // Desktop first run: the SDK bundle lands before the QR exists.
                renderFeishuSdkDownloading(statusId);
            } else {
                renderFeishuQr(statusId, data.qr_image, data.qrcode_url);
            }
            pollFeishuRegisterStatus(statusId);
        })
        .catch(err => {
            renderFeishuRegisterError(statusId, err.message || t('feishu_scan_fail'));
        });
}

function renderFeishuQr(statusId, qrImage, qrUrl) {
    const statusEl = document.getElementById(statusId);
    if (!statusEl) return;
    const imgHtml = qrImage
        ? `<img src="${qrImage}" alt="QR" class="w-44 h-44 rounded-lg border border-slate-200 dark:border-white/10 bg-white p-2"/>`
        : `<div class="w-44 h-44 rounded-lg border border-dashed border-slate-300 flex items-center justify-center text-xs text-slate-400">QR</div>`;
    statusEl.innerHTML = `
        <div class="flex flex-col items-center gap-3">
            ${imgHtml}
            <p class="text-xs text-amber-500">${t('feishu_scan_waiting')}</p>
            <p class="text-xs text-slate-400 dark:text-slate-500">${t('feishu_scan_tip')}</p>
            ${qrUrl ? `<a href="${qrUrl}" target="_blank" rel="noopener"
                class="text-xs text-blue-500 hover:text-blue-600 underline">${t('feishu_scan_open_link')}</a>` : ''}
        </div>`;
}

function renderFeishuSdkDownloading(statusId) {
    const statusEl = document.getElementById(statusId);
    if (!statusEl) return;
    statusEl.innerHTML = `
        <div class="flex flex-col items-center gap-2 py-6">
            <i class="fas fa-spinner fa-spin text-slate-400"></i>
            <p class="text-sm text-slate-500 dark:text-slate-400">${t('feishu_sdk_downloading')}</p>
            <p class="text-xs text-slate-400 dark:text-slate-500">${t('feishu_sdk_downloading_tip')}</p>
        </div>`;
}

function renderFeishuRegisterError(statusId, message) {
    const statusEl = document.getElementById(statusId);
    if (!statusEl) return;
    statusEl.innerHTML = `
        <div class="flex flex-col items-center gap-2 py-2">
            <p class="text-sm text-red-500 text-center">${message}</p>
            <button onclick="startFeishuRegister('${statusId}')"
                class="mt-1 px-4 py-1.5 rounded-md text-xs font-medium
                       bg-slate-100 dark:bg-white/10 text-slate-700 dark:text-slate-200
                       hover:bg-slate-200 dark:hover:bg-white/20 cursor-pointer">
                <i class="fas fa-rotate-right mr-1"></i>${t('feishu_scan_retry')}
            </button>
        </div>`;
}

function pollFeishuRegisterStatus(statusId) {
    stopFeishuRegisterPoll();
    _feishuRegisterPollTimer = setTimeout(() => {
        fetch('/api/feishu/register', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ action: 'poll' })
        })
        .then(r => r.json())
        .then(data => {
            if (data.status !== 'success') {
                renderFeishuRegisterError(statusId, data.message || t('feishu_scan_fail'));
                return;
            }
            const rs = data.register_status;
            if (rs === 'downloading') {
                renderFeishuSdkDownloading(statusId);
                pollFeishuRegisterStatus(statusId);
                return;
            }
            // The QR may only be generated after the bundle downloaded, in
            // which case the initial GET could not carry it. Render it once;
            // repainting on every poll would make it flicker.
            const shown = document.getElementById(statusId);
            if ((data.qr_image || data.qrcode_url) && shown && !shown.querySelector('img')) {
                renderFeishuQr(statusId, data.qr_image, data.qrcode_url);
            }
            if (rs === 'done') {
                const statusEl = document.getElementById(statusId);
                if (statusEl) {
                    statusEl.innerHTML = `
                        <div class="flex flex-col items-center py-2">
                            <div class="w-10 h-10 rounded-full bg-emerald-50 dark:bg-emerald-900/30 flex items-center justify-center mb-2">
                                <i class="fas fa-check text-emerald-500 text-lg"></i>
                            </div>
                            <p class="text-sm font-medium text-emerald-600 dark:text-emerald-400">${t('feishu_scan_success')}</p>
                        </div>`;
                }
                connectFeishuAfterRegister(data.app_id, data.app_secret);
            } else if (rs === 'expired') {
                renderFeishuRegisterError(statusId, t('feishu_scan_expired'));
            } else if (rs === 'denied') {
                renderFeishuRegisterError(statusId, t('feishu_scan_denied'));
            } else if (rs === 'error') {
                renderFeishuRegisterError(statusId, data.message || t('feishu_scan_fail'));
            } else {
                pollFeishuRegisterStatus(statusId);
            }
        })
        .catch(() => {
            pollFeishuRegisterStatus(statusId);
        });
    }, 2000);
}

function connectFeishuAfterRegister(appId, appSecret) {
    fetch('/api/channels', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            action: 'connect',
            channel: 'feishu',
            config: { feishu_app_id: appId, feishu_app_secret: appSecret }
        })
    })
    .then(r => r.json())
    .then(data => {
        if (data.status === 'success') {
            const ch = channelsData.find(c => c.name === 'feishu');
            if (ch) {
                ch.active = true;
                (ch.fields || []).forEach(f => {
                    if (f.key === 'feishu_app_id') f.value = appId;
                    if (f.key === 'feishu_app_secret') f.value = ChannelsHandler_maskSecret(appSecret);
                });
            }
            setTimeout(() => renderActiveChannels(), 1500);
        }
    })
    .catch(() => {});
}

// =====================================================================
// Scheduler View
// =====================================================================
let tasksLoaded = false;
let schedulerTaskFilter = 'all';
let schedulerDeliveryTargets = [];
async function openSchedulerCreator(){
    const modal=document.getElementById('scheduler-creator-modal');document.getElementById('scheduler-create-status').textContent='';modal.classList.remove('hidden');modal.classList.add('flex');toggleSchedulerCreateFields();
    const select=document.getElementById('scheduler-create-target');select.innerHTML='<option value="">正在读取可用通道...</option>';
    try{
        const response=await fetch('/api/scheduler/targets'),data=await response.json();if(data.status!=='success')throw new Error(data.message||'读取通道失败');
        schedulerDeliveryTargets=[];(data.targets||[]).forEach(target=>schedulerDeliveryTargets.push({...target,manual:false}));(data.manual_channels||[]).forEach(item=>schedulerDeliveryTargets.push({channel:item.channel,channel_label:item.label,receiver:'',receiver_name:item.label,is_group:false,manual:true}));
        select.innerHTML=schedulerDeliveryTargets.map((target,index)=>`<option value="${index}">${escapeHtml(target.channel_label)}${target.receiver_name&&target.channel!=='web'?' · '+escapeHtml(target.receiver_name):''}${target.manual?'（填写接收目标）':''}</option>`).join('');toggleSchedulerManualTarget();
    }catch(error){select.innerHTML='<option value="">通道读取失败</option>';document.getElementById('scheduler-create-status').textContent=error.message;}
}
function closeSchedulerCreator(){const modal=document.getElementById('scheduler-creator-modal');modal.classList.add('hidden');modal.classList.remove('flex');}
function toggleSchedulerCreateFields(){const type=document.getElementById('scheduler-create-type').value;document.getElementById('scheduler-create-interval-wrap').classList.toggle('hidden',type!=='interval');document.getElementById('scheduler-create-cron-wrap').classList.toggle('hidden',type!=='cron');document.getElementById('scheduler-create-once-wrap').classList.toggle('hidden',type!=='once');}
function toggleSchedulerManualTarget(){const target=schedulerDeliveryTargets[Number(document.getElementById('scheduler-create-target').value)],wrap=document.getElementById('scheduler-create-manual-wrap'),input=document.getElementById('scheduler-create-receiver');wrap.classList.toggle('hidden',!target?.manual);if(input)input.placeholder=target?.channel==='webhook'?'https://example.com/webhook':'用户、群聊、邮箱或通道要求的 ID';}
function renderSchedulerCreatePreview(preview){
    const box=document.getElementById('scheduler-create-preview');if(!box)return;
    if(!preview){box.classList.add('hidden');box.innerHTML='';return;}
    const checks=preview.checks||[],warnings=preview.warnings||[];
    const tone=preview.status==='success'?'text-emerald-600 bg-emerald-50 dark:bg-emerald-500/10':'text-orange-600 bg-orange-50 dark:bg-orange-500/10';
    box.className=`mt-4 rounded-xl border border-slate-200 dark:border-white/10 p-3 text-xs leading-5 ${tone}`;
    box.innerHTML=`<div class="font-semibold mb-1"><i class="fas fa-list-check mr-1"></i>保存前预演</div><div>${escapeHtml(preview.summary||'已完成预演')}</div>${checks.length?`<div class="mt-2 grid sm:grid-cols-2 gap-2">${checks.map(item=>`<div class="rounded-lg bg-white/70 dark:bg-black/10 px-2 py-1"><b>${escapeHtml(item.name||item.label||'检查')}</b> · ${escapeHtml(item.status==='success'?'正常':item.status==='warning'?'需关注':'异常')}<div class="text-[11px] opacity-80">${escapeHtml(item.label||item.channel||'')} ${item.receiver_name?`/ ${escapeHtml(item.receiver_name)}`:''}</div><div class="text-[11px] opacity-80">${escapeHtml(item.message||'')}</div></div>`).join('')}</div>`:''}${warnings.length?`<ul class="mt-2 list-disc pl-5">${warnings.map(x=>`<li>${escapeHtml(x)}</li>`).join('')}</ul>`:''}`;
    box.classList.remove('hidden');
}
async function createSchedulerTask(){
    const type=document.getElementById('scheduler-create-type').value,status=document.getElementById('scheduler-create-status'),target=schedulerDeliveryTargets[Number(document.getElementById('scheduler-create-target').value)];if(!target){status.textContent='请选择结果发送通道';return;}
    const receiver=target.channel==='web'?sessionId:(target.manual?document.getElementById('scheduler-create-receiver').value.trim():target.receiver);
    const payload={name:document.getElementById('scheduler-create-name').value.trim(),content:document.getElementById('scheduler-create-content').value.trim(),action_type:document.getElementById('scheduler-create-action').value,schedule_type:type,interval_seconds:Number(document.getElementById('scheduler-create-interval').value||0)*Number(document.getElementById('scheduler-create-unit').value||60),cron:document.getElementById('scheduler-create-cron').value.trim(),run_at:document.getElementById('scheduler-create-once').value,silent:document.getElementById('scheduler-create-silent').checked,session_id:sessionId,channel_type:target.channel,receiver,receiver_name:target.manual?receiver:target.receiver_name,is_group:target.manual?document.getElementById('scheduler-create-is-group').checked:!!target.is_group};
    if(!payload.name||!payload.content){status.textContent='请填写任务名称和执行内容';return;}if(!payload.receiver){status.textContent='请填写消息接收目标';return;}status.className='text-sm text-blue-600 mt-4';status.textContent='正在预演下一次执行和通知通道…';try{const previewResponse=await fetch('/api/scheduler',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...payload,preview_only:true})}),previewData=await previewResponse.json();if(previewData.status!=='success')throw new Error(previewData.message||'预演失败');renderSchedulerCreatePreview(previewData.preview);status.textContent='预演完成，正在创建任务…';const r=await fetch('/api/scheduler',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),d=await r.json();if(d.status!=='success')throw new Error(d.message);renderSchedulerCreatePreview(d.preview);status.className='text-sm text-emerald-600 mt-4';status.textContent='任务已创建，已记录预演结果。';setTimeout(()=>{closeSchedulerCreator();tasksLoaded=false;loadTasksView();},650);}catch(error){status.className='text-sm text-red-500 mt-4';status.textContent=error.message;}
}
function refreshTasksView() {
    const btn = document.getElementById('task-refresh-btn');
    const icon = btn.querySelector('i');
    
    // Add spin animation
    icon.classList.add('fa-spin');
    btn.disabled = true;
    
    tasksLoaded = false;
    const listEl = document.getElementById('tasks-list');
    listEl.innerHTML = '';
    document.getElementById('scheduler-table-header')?.classList.add('hidden');
    
    if(schedulerTaskFilter==='history')loadSchedulerRunHistory();else loadTasksView();
    
    // Restore button after animation ends
    setTimeout(() => {
        icon.classList.remove('fa-spin');
        btn.disabled = false;
    }, 500);
}

function schedulerTaskPlanText(schedule) {
    schedule = schedule || {};
    if (schedule.type === 'cron') return `Cron ${schedule.expression || '未设置'}`;
    if (schedule.type === 'interval') {
        const seconds = Number(schedule.seconds || 0);
        const hours = Math.floor(seconds / 3600);
        const mins = Math.floor((seconds % 3600) / 60);
        const secs = seconds % 60;
        const parts = [];
        if (hours > 0) parts.push(`${hours}小时`);
        if (mins > 0) parts.push(`${mins}分钟`);
        if ((secs > 0 || !parts.length) && seconds > 0) parts.push(`${secs}秒`);
        return `Every ${parts.join('') || '未设置'}`;
    }
    return schedule.type === 'once' ? '单次执行' : (schedule.type || '未设置');
}

function schedulerTaskTimeText(value, empty = '不适用') {
    if (!value) return empty;
    if (typeof automationTaskRelativeTime === 'function') return automationTaskRelativeTime(value, empty);
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) return String(value).replace('T', ' ').slice(0, 16);
    return date.toLocaleString('zh-CN', {month:'2-digit', day:'2-digit', hour:'2-digit', minute:'2-digit', hour12:false});
}

let schedulerBulkMode=false;
function toggleSchedulerBulkMode(force){
    schedulerBulkMode=typeof force==='boolean'?force:!schedulerBulkMode;
    document.getElementById('scheduler-bulk-bar')?.classList.toggle('hidden',!schedulerBulkMode);
    document.getElementById('scheduler-bulk-toggle')?.classList.toggle('active',schedulerBulkMode);
    document.querySelectorAll('#tasks-list .scheduler-bulk-check').forEach(box=>{box.classList.toggle('hidden',!schedulerBulkMode);if(!schedulerBulkMode)box.checked=false;});
    const all=document.getElementById('scheduler-select-all');if(all)all.checked=false;
    updateSchedulerBulkCount();
}
function updateSchedulerBulkCount(){const count=document.querySelectorAll('#tasks-list .scheduler-bulk-check:checked').length;const node=document.getElementById('scheduler-selected-count');if(node)node.textContent=`已选 ${count} 项`;}
function selectAllSchedulerTasks(checked){document.querySelectorAll('#tasks-list .scheduler-task-row:not(.hidden) .scheduler-bulk-check').forEach(box=>{box.checked=checked;});updateSchedulerBulkCount();}
async function bulkToggleSchedulerTasks(enabled){
    const ids=[...document.querySelectorAll('#tasks-list .scheduler-bulk-check:checked')].map(box=>box.closest('[data-task-id]')?.dataset.taskId).filter(Boolean);
    if(!ids.length){alert('请先选择任务');return;}
    let failed=0;
    for(const taskId of ids){try{const response=await fetch('/api/scheduler/toggle',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({task_id:taskId,enabled})});const result=await response.json();if(result.status!=='success')failed++;}catch(_){failed++;}}
    tasksLoaded=false;toggleSchedulerBulkMode(false);loadTasksView();
    if(failed)alert(`${ids.length-failed} 项已更新，${failed} 项失败，请刷新后重试。`);
}

function setSchedulerTaskFilter(filter) {
    schedulerTaskFilter = filter || 'all';
    ['all','enabled','paused','history'].forEach(key => {
        document.getElementById(`scheduler-filter-${key}`)?.classList.toggle('active', key === schedulerTaskFilter);
    });
    document.getElementById('scheduler-history-controls')?.classList.toggle('hidden', schedulerTaskFilter !== 'history');
    document.getElementById('scheduler-new-button')?.classList.toggle('hidden', schedulerTaskFilter === 'history');
    document.getElementById('scheduler-bulk-toggle')?.classList.toggle('hidden', schedulerTaskFilter === 'history');
    document.getElementById('scheduler-bulk-bar')?.classList.toggle('hidden',schedulerTaskFilter==='history'||!schedulerBulkMode);
    const search = document.getElementById('scheduler-task-query');
    if (search) search.placeholder = schedulerTaskFilter === 'history' ? '搜索运行历史' : '搜索自动化';
    document.getElementById('scheduler-filter-toggle')?.classList.toggle('hidden', schedulerTaskFilter === 'history');
    document.getElementById('scheduler-advanced-filters')?.classList.toggle('hidden', schedulerTaskFilter === 'history' || !schedulerAdvancedFiltersOpen);
    if (schedulerTaskFilter === 'history') {
        loadSchedulerRunHistory();
        return;
    }
    if (tasksLoaded) {
        const listEl = document.getElementById('tasks-list');
        if (listEl?.dataset.mode === 'history') {
            tasksLoaded = false;
            listEl.innerHTML = '';
            loadTasksView();
            return;
        }
    }
    filterSchedulerTasks();
}

let schedulerAdvancedFiltersOpen = false;
function toggleSchedulerAdvancedFilters() {
    schedulerAdvancedFiltersOpen = !schedulerAdvancedFiltersOpen;
    document.getElementById('scheduler-advanced-filters')?.classList.toggle('hidden', !schedulerAdvancedFiltersOpen);
    document.getElementById('scheduler-filter-toggle')?.setAttribute('aria-expanded', String(schedulerAdvancedFiltersOpen));
}
function clearSchedulerAdvancedFilters() {
    for (const id of ['scheduler-schedule-filter', 'scheduler-channel-filter']) {
        const field = document.getElementById(id);
        if (field) field.value = '';
    }
    filterSchedulerTasks();
}

function filterSchedulerTasks() {
    if (schedulerTaskFilter === 'history') {
        loadSchedulerRunHistory();
        return;
    }
    const query = (document.getElementById('scheduler-task-query')?.value || '').trim().toLowerCase();
    const scheduleFilter = document.getElementById('scheduler-schedule-filter')?.value || '';
    const channelFilter = document.getElementById('scheduler-channel-filter')?.value || '';
    const rows = [...document.querySelectorAll('#tasks-list > [data-task-id]')];
    let visible = 0;
    rows.forEach(row => {
        const enabled = row.dataset.enabled === '1';
        const hasHistory = row.dataset.history === '1';
        const statusMatch = schedulerTaskFilter === 'all'
            || (schedulerTaskFilter === 'enabled' && enabled)
            || (schedulerTaskFilter === 'paused' && !enabled)
            || (schedulerTaskFilter === 'history' && hasHistory);
        const textMatch = !query || (row.textContent || '').toLowerCase().includes(query);
        const show = statusMatch && textMatch
            && (!scheduleFilter || row.dataset.scheduleType === scheduleFilter)
            && (!channelFilter || row.dataset.channel === channelFilter);
        row.classList.toggle('hidden', !show);
        if (show) visible++;
    });
    const emptyEl = document.getElementById('tasks-empty');
    const listEl = document.getElementById('tasks-list');
    const header = document.getElementById('scheduler-table-header');
    if (!rows.length) return;
    emptyEl?.classList.toggle('hidden', visible > 0);
    listEl?.classList.toggle('hidden', visible === 0);
    header?.classList.toggle('hidden', visible === 0);
    const emptyText = emptyEl?.querySelector('p');
    if (emptyText && visible === 0) {
        emptyText.textContent = schedulerTaskFilter === 'history'
            ? '暂无运行历史，手动执行或定时执行后会显示在这里'
            : '当前分类下没有定时任务';
    }
}

function schedulerFriendlyStatusLabel(status) {
    return {
        success: '执行完成',
        failed: '执行失败',
        empty: '本次无合格内容',
        skipped_duplicate: '已合并重复结果',
        skipped_instance: '旧实例已拦截',
        retrying: '等待自动重试',
        running: '执行中',
    }[status] || '等待执行';
}

function schedulerFriendlySummary(task) {
    const status = task?.last_run_status || '';
    const raw = task?.last_result_summary || task?.last_error || '';
    if (status === 'empty') {
        if (/当前条件下暂无合格结果|暂无内容|无合格结果/.test(raw)) {
            return '本次没有找到符合条件的内容，后续可自动放宽时间范围、补充关键词或切换来源。';
        }
        return raw || '本次没有找到符合条件的内容，可尝试放宽筛选条件。';
    }
    if (status === 'failed') {
        if (/查询主题偏泛|主题偏泛|关注方向/.test(raw)) {
            return '主题较泛，建议补充关注方向、关键词、行业或指定来源后重试。';
        }
        return raw || '执行失败，可查看运行记录，或按推荐参数重试。';
    }
    if (status === 'skipped_duplicate') return raw || '本次结果与近期内容重复，已自动合并，避免重复通知。';
    if (status === 'skipped_instance') return raw || '检测到旧后端实例触发，已拦截以避免重复执行。';
    if (status === 'retrying') return raw || '通道暂未就绪，系统会在当前执行窗口内自动重试。';
    if (status === 'success') return raw || '任务执行完成，结果已记录。';
    return raw || '尚未产生执行结果。';
}

function schedulerFriendlyWarning(text) {
    const value = String(text || '');
    if (/查询主题偏泛|主题偏泛|关注方向/.test(value)) return '主题较泛：请补充关注方向、关键词、行业或指定来源';
    if (/暂无内容|无合格结果|当前条件下暂无合格结果/.test(value)) return '本次无合格内容：后续可放宽时间范围或切换来源';
    if (/重复|重复通知/.test(value)) return '已启用去重：相似结果会合并，避免重复通知';
    if (/执行失败|失败/.test(value)) return '执行失败：可查看运行记录或按推荐参数重试';
    return value;
}

function schedulerFriendlyTaskPreview(text) {
    const value = String(text || '').trim();
    if (!value) return '';
    if (/当前条件下暂无合格结果|查询主题偏泛|建议补充关注方向/.test(value)) {
        return '任务条件需要优化：建议补充关注方向、关键词或指定来源。';
    }
    if (/生成个人早间简报/.test(value) && /主题：/.test(value)) {
        const topic = value.match(/主题：([^；。\n]+)/)?.[1] || '';
        return `生成个人早间简报${topic ? `：${topic}` : ''}`;
    }
    return value.replace(/\s+/g, ' ');
}

function setSchedulerTableHeaders(labels) {
    const header = document.getElementById('scheduler-table-header');
    if (!header) return;
    [...header.children].forEach((node, index) => {
        node.textContent = labels[index] || '';
    });
}

async function loadSchedulerRunHistory() {
    const emptyEl = document.getElementById('tasks-empty');
    const listEl = document.getElementById('tasks-list');
    const header = document.getElementById('scheduler-table-header');
    if (!listEl || !emptyEl) return;
    setSchedulerTableHeaders(['任务名称', '状态', '运行时间', '耗时', '任务类型', '操作']);
    if (header) header.dataset.mode = 'history';
    listEl.dataset.mode = 'history';
    listEl.classList.add('hidden');
    header?.classList.add('hidden');
    emptyEl.classList.remove('hidden');
    const emptyText = emptyEl.querySelector('p');
    if (emptyText) emptyText.textContent = '正在读取运行历史…';
    try {
        const response = await fetch('/api/scheduler');
        const data = await response.json();
        if (data.status !== 'success') throw new Error(data.message || '运行历史加载失败');
        let runs = data.history || [];
        const taskSelect = document.getElementById('scheduler-history-task');
        if(taskSelect){
            const selected=taskSelect.value;
            const taskNames=[...new Set(runs.map(run=>run.task_name||'').filter(Boolean))].sort((a,b)=>a.localeCompare(b,'zh-CN'));
            taskSelect.innerHTML='<option value="">全部任务</option>'+taskNames.map(name=>`<option value="${escapeHtml(name)}">${escapeHtml(name)}</option>`).join('');
            taskSelect.value=taskNames.includes(selected)?selected:'';
        }
        const query = (document.getElementById('scheduler-task-query')?.value || '').trim().toLowerCase();
        const statusFilter=document.getElementById('scheduler-history-status')?.value||'';
        const triggerFilter=document.getElementById('scheduler-history-trigger')?.value||'';
        const taskFilter=taskSelect?.value||'';
        const date = (document.getElementById('scheduler-history-date')?.value || '').trim();
        if (query) runs = runs.filter(run => JSON.stringify(run).toLowerCase().includes(query));
        if (statusFilter) runs=runs.filter(run=>run.status===statusFilter);
        if (triggerFilter) runs=runs.filter(run=>run.trigger===triggerFilter);
        if (taskFilter) runs=runs.filter(run=>run.task_name===taskFilter);
        if (date) runs = runs.filter(run => String(run.started_at || run.finished_at || '').slice(0, 10) === date);
        if (!runs.length) {
            if (emptyText) emptyText.textContent = date || query ? '当前筛选条件下暂无运行历史' : '暂无运行历史，手动执行或定时执行后会显示在这里';
            return;
        }
        emptyEl.classList.add('hidden');
        header?.classList.remove('hidden');
        listEl.classList.remove('hidden');
        listEl.innerHTML = runs.slice(0, 50).map(run => {
            const summary = schedulerFriendlyRunSummary(run);
            const triggerLabel = schedulerHistoryTriggerLabel(run.trigger);
            const startText = String(run.started_at || run.finished_at || '').replace('T',' ').slice(0,19) || '未记录';
            const statusLabel = schedulerFriendlyStatusLabel(run.status);
            const canRun = !!run.task_id;
            const started=Date.parse(run.started_at||'');
            const finished=Date.parse(run.finished_at||'');
            const duration=Number.isFinite(started)&&Number.isFinite(finished)&&finished>=started?`${Math.round((finished-started)/1000)}s`:'—';
            return `<div data-run-id="${escapeHtml(run.id || '')}" data-task-id="${escapeHtml(run.task_id || '')}" class="automation-table-row scheduler-history-row">
                <div class="automation-row-name"><div>${schedulerRunStatusIcon(run.status)}<b>${escapeHtml(run.task_name || '未命名任务')}</b></div><p title="${escapeHtml(summary)}">${escapeHtml(statusLabel)}${summary ? ` · ${escapeHtml(summary)}` : ''}${run.execution_audit_summary?` · ${escapeHtml(run.execution_audit_summary)}`:''}</p>${automationExecutionAuditHtml(run,{title:'定时任务发送轨迹'})}</div>
                <div class="automation-row-plan scheduler-run-status">${schedulerRunStatusIcon(run.status)} ${escapeHtml(statusLabel)}</div>
                <div class="automation-row-next">${escapeHtml(startText)}</div>
                <div class="automation-row-last">${escapeHtml(duration)}</div>
                <div class="automation-row-plan" title="${escapeHtml(triggerLabel)}">${escapeHtml(run.task_type || '本地')}</div>
                <div class="automation-row-control"><div class="automation-row-actions"><button ${canRun ? '' : 'disabled'} onclick="runSchedulerHistoryTask('${escapeHtml(run.task_id || '')}', this)" title="再次执行"><i class="fas fa-play"></i><span>执行</span></button><button class="text-rose-500" onclick="deleteSchedulerHistory('${escapeHtml(run.id || '')}', '${escapeHtml(run.task_id || '')}', this)" title="删除历史记录"><i class="far fa-trash-can"></i><span>删除</span></button></div></div>
            </div>`;
        }).join('');
    } catch (error) {
        if (emptyText) emptyText.textContent = `运行历史加载失败：${error.message || error}`;
    }
}

function schedulerHistoryTriggerLabel(trigger) {
    const value = String(trigger || '');
    if (value === 'manual') return '手动执行';
    if (value === 'scheduled') return '定时触发';
    if (value === 'recovery') return '失败恢复';
    if (value === 'scheduled_duplicate') return '重复跳过';
    return value || '运行';
}

function runSchedulerHistoryTask(taskId, button) {
    if (!taskId || !button) return;
    const originalHtml = button.innerHTML;
    button.disabled = true;
    button.innerHTML = '<i class="fas fa-spinner fa-spin mr-1"></i>执行中';
    fetch('/api/scheduler/run', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({task_id: taskId})
    }).then(r => r.json()).then(res => {
        if (res.status !== 'success') throw new Error(res.message || '手动执行失败');
        pollSchedulerManualRun(taskId, res.run_id || '', button, originalHtml, Date.now());
    }).catch(error => {
        button.innerHTML = `<i class="fas fa-triangle-exclamation mr-1"></i>${escapeHtml(error.message || '执行失败')}`;
        setTimeout(() => {
            button.innerHTML = originalHtml;
            button.disabled = false;
        }, 2500);
    });
}

function deleteSchedulerHistory(historyId, taskId, button) {
    if (!historyId) return;
    const doDelete = () => {
        const originalHtml = button?.innerHTML || '';
        if (button) {
            button.disabled = true;
            button.innerHTML = '<i class="fas fa-spinner fa-spin"></i><span>删除中</span>';
        }
        fetch('/api/scheduler/history/delete', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({id: historyId, task_id: taskId || ''})
        }).then(r => r.json()).then(res => {
            if (res.status !== 'success') throw new Error(res.message || '删除失败');
            tasksLoaded = false;
            loadSchedulerRunHistory();
        }).catch(error => {
            if (button) {
                button.innerHTML = `<i class="fas fa-triangle-exclamation"></i><span>${escapeHtml(error.message || '删除失败')}</span>`;
                setTimeout(() => {
                    button.innerHTML = originalHtml;
                    button.disabled = false;
                }, 2500);
            }
        });
    };
    if (typeof showConfirmDialog === 'function') {
        showConfirmDialog({
            title: '删除运行历史',
            message: '确定删除这条运行历史吗？不会删除定时任务本身。',
            okText: '删除',
            onConfirm: doDelete,
        });
    } else if (confirm('确定删除这条运行历史吗？不会删除定时任务本身。')) {
        doDelete();
    }
}

function schedulerFriendlyRunSummary(run) {
    const raw = run.result_summary || run.empty_reason || run.failure_reason || run.error || run.notification_summary || '';
    if (run.status === 'empty') return schedulerFriendlySummary({last_run_status:'empty', last_result_summary:raw});
    if (run.status === 'failed') return schedulerFriendlySummary({last_run_status:'failed', last_error:raw});
    return raw || (run.status === 'success' ? '执行完成，结果已记录。' : '正在执行或等待结果。');
}

function schedulerRunStatusIcon(status) {
    if (status === 'success') return '<i class="fas fa-circle automation-row-ok"></i>';
    if (status === 'failed' || status === 'empty') return '<i class="fas fa-triangle-exclamation automation-row-warn"></i>';
    if (status === 'running' || status === 'retrying') return '<i class="fas fa-spinner automation-row-paused"></i>';
    return '<i class="fas fa-clock automation-row-paused"></i>';
}

function closeSchedulerRowMenus(except = null) {
    document.querySelectorAll('#tasks-list .scheduler-row-menu').forEach(menu => {
        if (menu !== except) menu.classList.add('hidden');
    });
}
document.addEventListener('click', event => {
    if (!event.target.closest('#tasks-list .scheduler-row-menu-wrap')) closeSchedulerRowMenus();
});

async function cloneSchedulerTask(task) {
    await openSchedulerCreator();
    document.getElementById('scheduler-create-name').value = `${task.name || '自动化'}（副本）`;
    document.getElementById('scheduler-create-content').value = task.action?.content || task.action?.task_description || '';
    document.getElementById('scheduler-create-action').value = task.action?.type || 'agent_task';
    const schedule = task.schedule || {};
    const type = ['cron', 'interval', 'once'].includes(schedule.type) ? schedule.type : 'cron';
    document.getElementById('scheduler-create-type').value = type;
    document.getElementById('scheduler-create-cron').value = schedule.expression || '0 9 * * *';
    const seconds = Number(schedule.seconds || 0);
    const unit = seconds >= 86400 && seconds % 86400 === 0 ? 86400 : seconds >= 3600 && seconds % 3600 === 0 ? 3600 : 60;
    document.getElementById('scheduler-create-unit').value = String(unit);
    document.getElementById('scheduler-create-interval').value = String(Math.max(1, Math.round(seconds / unit)));
    document.getElementById('scheduler-create-once').value = String(schedule.run_at || task.next_run_at || '').slice(0, 16);
    document.getElementById('scheduler-create-silent').checked = !!task.action?.silent;
    const targetSelect = document.getElementById('scheduler-create-target');
    const channel = task.action?.channel_type || 'web';
    const receiver = task.action?.receiver || '';
    const targetIndex = schedulerDeliveryTargets.findIndex(item => item.channel === channel && item.receiver === receiver);
    const manualIndex = schedulerDeliveryTargets.findIndex(item => item.channel === channel && item.manual);
    const selectedIndex = targetIndex >= 0 ? targetIndex : manualIndex;
    if (selectedIndex >= 0) targetSelect.value = String(selectedIndex);
    toggleSchedulerManualTarget();
    if (selectedIndex === manualIndex && manualIndex >= 0) document.getElementById('scheduler-create-receiver').value = receiver;
    document.getElementById('scheduler-create-is-group').checked = !!task.action?.is_group;
    toggleSchedulerCreateFields();
}

function deleteSchedulerTaskFromRow(task) {
    showConfirmDialog({
        title: '移除自动化',
        message: `确定移除「${task.name || task.id}」吗？此操作不会删除既有运行记录。`,
        okText: '移除',
        onConfirm: async () => {
            try {
                const response = await fetch('/api/scheduler/delete', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({task_id:task.id})});
                const result = await response.json();
                if (result.status !== 'success') throw new Error(result.message || '移除失败');
                tasksLoaded = false;
                loadTasksView();
            } catch (error) { alert(error.message || '移除失败'); }
        }
    });
}

function runTaskNow(task, button) {
    showConfirmDialog({
        title: t('task_run_confirm_title'),
        message: `${task.name || task.id}: ${t('task_run_confirm_msg')}`,
        okText: t('task_run_now'),
        onConfirm: () => {
            const originalHtml = button.innerHTML;
            button.disabled = true;
            button.innerHTML = `<i class="fas fa-spinner fa-spin mr-1"></i>${t('task_run_now')}`;
            fetch('/api/scheduler/run', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({task_id: task.id})
            }).then(r => r.json()).then(res => {
                if (res.status !== 'success') throw new Error(res.message || t('task_run_failed'));
                button.innerHTML = `<i class="fas fa-spinner fa-spin mr-1"></i>执行中`;
                pollSchedulerManualRun(task.id, res.run_id || '', button, originalHtml, Date.now());
            }).catch(() => {
                button.innerHTML = `<i class="fas fa-triangle-exclamation mr-1"></i>${t('task_run_failed')}`;
                setTimeout(() => {
                    button.innerHTML = originalHtml;
                    button.disabled = false;
                }, 2000);
            });
        }
    });
}

function pollSchedulerManualRun(taskId, runId, button, originalHtml, startedAt) {
    const timeoutMs = 45000;
    const done = (html, delay = 2200) => {
        button.innerHTML = html;
        tasksLoaded = false;
        loadTasksView();
        setTimeout(() => {
            button.innerHTML = originalHtml;
            button.disabled = false;
        }, delay);
    };
    fetch(`/api/scheduler?task_id=${encodeURIComponent(taskId)}`)
        .then(r => r.json())
        .then(res => {
            if (res.status !== 'success') throw new Error(res.message || 'status error');
            const task = Array.isArray(res.tasks) ? (res.tasks.find(item => item.id === taskId) || {}) : (res.task || {});
            const currentRunId = task.last_manual_run_id || res.last_manual_run_id || '';
            const status = task.last_manual_run_status || task.last_run_status || res.last_run_status || '';
            const summary = task.last_manual_run_summary || task.last_result_summary || task.last_error || res.last_result_summary || '';
            const finished = !!(task.last_manual_run_finished_at || res.last_manual_run_finished_at);
            const matched = !runId || currentRunId === runId;
            if (matched && finished && status) {
                if (status === 'success') return done(`<i class="fas fa-check mr-1"></i>执行完成`);
                if (status === 'empty') return done(`<i class="fas fa-circle-info mr-1"></i>暂无内容`);
                if (status === 'skipped_duplicate') return done(`<i class="fas fa-copy mr-1"></i>已跳过重复`);
                return done(`<i class="fas fa-triangle-exclamation mr-1"></i>${escapeHtml(summary || '执行失败')}`, 3000);
            }
            if (Date.now() - startedAt > timeoutMs) {
                return done(`<i class="fas fa-clock mr-1"></i>后台执行中`, 2500);
            }
            setTimeout(() => pollSchedulerManualRun(taskId, runId, button, originalHtml, startedAt), 1500);
        })
        .catch(() => {
            if (Date.now() - startedAt > timeoutMs) {
                return done(`<i class="fas fa-clock mr-1"></i>后台执行中`, 2500);
            }
            setTimeout(() => pollSchedulerManualRun(taskId, runId, button, originalHtml, startedAt), 2000);
        });
}

function loadTasksView() {
    if (tasksLoaded) return;
    fetch('/api/scheduler').then(r => r.json()).then(data => {
        if (data.status !== 'success') return;
        const emptyEl = document.getElementById('tasks-empty');
        const listEl = document.getElementById('tasks-list');
        const tableHeader = document.getElementById('scheduler-table-header');
        setSchedulerTableHeaders(['名称', '计划', '下次运行', '上次运行', '']);
        if (tableHeader) tableHeader.dataset.mode = 'tasks';
        if (listEl) listEl.dataset.mode = 'tasks';
        const allTasks = data.tasks || [];
        const enabledCount=allTasks.filter(task=>task.enabled!==false).length;
        [['all',allTasks.length],['enabled',enabledCount],['paused',allTasks.length-enabledCount]].forEach(([key,count])=>{const node=document.getElementById(`scheduler-count-${key}`);if(node)node.textContent=`(${count})`;});
        // Backend already sorted by enabled and next_run_at, no need to re-sort on frontend
        if (allTasks.length === 0) {
            emptyEl.querySelector('p').textContent = currentLang === 'zh' ? '暂无定时任务' : 'No scheduled tasks';
            emptyEl.classList.remove('hidden');
            listEl.classList.add('hidden');
            tableHeader?.classList.add('hidden');
            tasksLoaded = true;
            return;
        }
        emptyEl.classList.add('hidden');
        listEl.classList.remove('hidden');
        tableHeader?.classList.add('hidden');
        listEl.innerHTML = '';

        allTasks.forEach((task, index) => {
            const isEnabled = task.enabled !== false;
            const card = document.createElement('div');
            card.className = 'automation-table-row scheduler-task-row';
            card.dataset.taskId = task.id;
            card.dataset.enabled = isEnabled ? '1' : '0';
            card.dataset.scheduleType = task.schedule?.type || '';
            card.dataset.channel = task.action?.channel_type || 'web';
            card.dataset.history = (task.last_run_at || task.last_run_status || task.last_manual_run_status || task.last_manual_run_summary || task.last_result_summary || task.last_error) ? '1' : '0';
            if (!isEnabled) card.classList.add('opacity-50');
            const schedule = task.schedule || {};
            const planText = schedulerTaskPlanText(schedule);
            const nextRun = isEnabled ? schedulerTaskTimeText(task.next_run_at, '待计算') : '不适用';
            const action = task.action || {};
            const taskContent = schedulerFriendlyTaskPreview(action.content || action.task_description || '');
            const statusLabel=schedulerFriendlyStatusLabel(task.last_run_status);
            const statusClass=task.last_run_status==='failed'?'text-red-500':task.last_run_status==='empty'?'text-orange-500':task.last_run_status==='skipped_duplicate'||task.last_run_status==='skipped_instance'||task.last_run_status==='retrying'?'text-blue-500':task.last_run_status==='success'?'text-emerald-600':'text-slate-400';
            const statusSummary=schedulerFriendlySummary(task);
            const qualityWarnings=Array.isArray(task.quality_warnings)?task.quality_warnings:[];
            const qualityHtml=qualityWarnings.length?`<div class="mb-2 flex flex-wrap gap-1">${qualityWarnings.slice(0,3).map(item=>`<span class="rounded-full bg-amber-50 text-amber-600 dark:bg-amber-500/10 dark:text-amber-300 px-2 py-0.5 text-[11px]"><i class="fas fa-screwdriver-wrench mr-1"></i>${escapeHtml(schedulerFriendlyWarning(item))}</span>`).join('')}</div>`:'';
            const manualStatus=task.last_manual_run_status||'';
            const manualSummary=task.last_manual_run_summary||'';
            const manualText=manualStatus?`最近手动执行：${(({running:'执行中',success:'执行完成',failed:'执行失败',empty:'暂无内容',skipped_duplicate:'已跳过重复',skipped_instance:'实例保护跳过'})[manualStatus]||manualStatus)}${manualSummary?` · ${manualSummary}`:''}`:'';
            const toggleId = `toggle-${index}-${String(task.id || 'task').replace(/[^a-zA-Z0-9_-]/g, '-')}`;
            const lastRunPrefix = task.last_run_status === 'success' ? '✓' : task.last_run_status === 'retrying' ? '↻' : task.last_run_status ? '×' : '↪';
            const lastRun = task.last_run_at ? `${lastRunPrefix} ${schedulerTaskTimeText(task.last_run_at)}` : '不适用';
            const statusIcon = task.last_run_status === 'failed' || task.last_run_status === 'empty'
                ? '<i class="fas fa-triangle-exclamation automation-row-warn"></i>'
                : task.last_run_status === 'retrying'
                ? '<i class="fas fa-spinner automation-row-paused"></i>'
                : (isEnabled ? '<i class="fas fa-circle automation-row-ok"></i>' : '<i class="fas fa-pause automation-row-paused"></i>');
            const channelLabel=escapeHtml(({web:'网页会话',weixin:'微信',webhook:'Webhook',email:'邮箱'})[action.channel_type]||action.channel_type||'网页会话');
            card.innerHTML = `
                <div class="automation-row-name">
                    <div title="${escapeHtml(statusLabel + '：' + statusSummary)}"><input type="checkbox" class="scheduler-bulk-check ${schedulerBulkMode?'':'hidden'}" aria-label="选择任务" onclick="event.stopPropagation()" onchange="updateSchedulerBulkCount()">${statusIcon}<b>${escapeHtml(task.name || task.id || '--')}</b></div>
                    <p title="${escapeHtml(taskContent || channelLabel)}">${escapeHtml(taskContent || channelLabel).slice(0, 110)}</p>
                    <div class="scheduler-row-status ${statusClass}"><span>${escapeHtml(statusLabel)}</span><em>${escapeHtml(statusSummary)}</em></div>
                    ${manualText?`<div class="scheduler-row-manual">${escapeHtml(manualText)}</div>`:''}
                    ${qualityHtml}
                </div>
                <div class="automation-row-plan">${escapeHtml(planText)}</div>
                <div class="automation-row-next">${escapeHtml(nextRun)}</div>
                <div class="automation-row-last ${task.last_run_status==='failed'||task.last_run_status==='empty'?'is-bad':task.last_run_status==='success'?'is-ok':''}">${escapeHtml(lastRun)}</div>
                <div class="automation-row-control">
                    <div class="automation-row-actions">
                        <button type="button" class="task-run-now" title="${t('task_run_now')}"><i class="fas fa-play"></i><span>${t('task_run_now')}</span></button>
                        <label class="scheduler-row-toggle relative inline-flex items-center cursor-pointer" for="${toggleId}" title="${isEnabled ? '已启用' : '已暂停'}">
                            <input type="checkbox" id="${toggleId}" class="sr-only peer" ${isEnabled ? 'checked' : ''}>
                            <span class="scheduler-toggle-track"></span>
                        </label>
                        <div class="scheduler-row-menu-wrap"><button type="button" class="task-menu-toggle" title="更多操作" aria-label="更多操作" aria-expanded="false"><i class="fas fa-ellipsis"></i></button><div class="scheduler-row-menu hidden"><button type="button" data-action="edit">编辑</button><button type="button" data-action="clone">克隆</button>${action.channel_type === 'web' ? '<button type="button" data-action="result">查看结果</button>' : ''}<button type="button" data-action="history">运行历史</button><button type="button" data-action="delete" class="danger">移除</button></div></div>
                    </div>
                </div>`;
            const runButton = card.querySelector('.task-run-now');
            runButton.addEventListener('click', function(e) {
                e.stopPropagation();
                runTaskNow(task, runButton);
            });
            const menu = card.querySelector('.scheduler-row-menu');
            const menuToggle = card.querySelector('.task-menu-toggle');
            menuToggle.addEventListener('click', e => { e.stopPropagation(); const opening=menu.classList.contains('hidden'); closeSchedulerRowMenus(menu); menu.classList.toggle('hidden',!opening); menuToggle.setAttribute('aria-expanded',String(opening)); });
            menu.querySelectorAll('[data-action]').forEach(button => button.addEventListener('click', e => {
                e.stopPropagation(); menu.classList.add('hidden'); menuToggle.setAttribute('aria-expanded','false');
                const actionName=button.dataset.action;
                if(actionName==='edit') openTaskEditModal(task);
                else if(actionName==='clone') cloneSchedulerTask(task);
                else if(actionName==='delete') deleteSchedulerTaskFromRow(task);
                else if(actionName==='history') { document.getElementById('scheduler-task-query').value=task.name||''; setSchedulerTaskFilter('history'); }
                else if(actionName==='result') { const sid=action.notify_session_id||action.receiver; navigateTo('chat'); if(sid&&sid!=='web_user') switchSession(sid); }
            }));
            const checkbox = card.querySelector('.scheduler-row-toggle input[type="checkbox"]');
            checkbox.addEventListener('change', function() {
                const newEnabled = this.checked;
                fetch('/api/scheduler/toggle', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({task_id: task.id, enabled: newEnabled})
                }).then(r => r.json()).then(res => {
                    if (res.status === 'success') {
                        card.dataset.enabled = newEnabled ? '1' : '0';
                        if (newEnabled) {
                            card.classList.remove('opacity-50');
                        } else {
                            card.classList.add('opacity-50');
                        }
                        filterSchedulerTasks();
                    } else {
                        this.checked = !newEnabled;
                    }
                }).catch(() => { this.checked = !newEnabled; });
            });
            // Card click event (excluding toggle switch clicks)
            card.addEventListener('click', function(e) {
                if (!e.target.closest('button') && !e.target.closest('label') && !e.target.closest('input[type="checkbox"]')) {
                    openTaskEditModal(task);
                }
            });
            card.style.cursor = 'pointer';
            listEl.appendChild(card);
        });
        filterSchedulerTasks();
        tasksLoaded = true;
    }).catch(() => {});
}

