let logEventSource = null;
let logsFullscreen = false;
let dataManagementFullscreen = false;
let tasksFullscreen = false;

function applySettingsFullscreen(active,button){
    const dialog=document.getElementById('settings-dialog');if(!dialog)return;
    dialog.classList.toggle('max-w-5xl',!active);dialog.classList.toggle('h-[86vh]',!active);dialog.classList.toggle('rounded-2xl',!active);
    dialog.classList.toggle('max-w-none',active);dialog.classList.toggle('h-full',active);dialog.classList.toggle('rounded-none',active);
    document.getElementById('settings-center')?.classList.toggle('p-3',!active);
    if(button)button.innerHTML=`<i class="fas ${active?'fa-compress':'fa-expand'}"></i>`;
}

function toggleDataManagementFullscreen(force){
    const button=document.getElementById('settings-data-fullscreen-button');
    dataManagementFullscreen=force===undefined?!dataManagementFullscreen:!!force;
    applySettingsFullscreen(dataManagementFullscreen,button);
    if(button)button.title=dataManagementFullscreen?(currentLang==='en'?'Exit full screen':'退出全屏'):(currentLang==='en'?'Full-screen data management':'全屏显示数据管理');
}

function toggleLogsFullscreen() {
    const dialog=document.getElementById('settings-dialog'),button=document.getElementById('logs-fullscreen-button');
    if(!dialog)return;
    logsFullscreen=!logsFullscreen;
    dialog.classList.toggle('max-w-5xl',!logsFullscreen);
    dialog.classList.toggle('h-[86vh]',!logsFullscreen);
    dialog.classList.toggle('rounded-2xl',!logsFullscreen);
    dialog.classList.toggle('max-w-none',logsFullscreen);
    dialog.classList.toggle('h-full',logsFullscreen);
    dialog.classList.toggle('rounded-none',logsFullscreen);
    document.getElementById('settings-center')?.classList.toggle('p-3',!logsFullscreen);
    if(button){button.innerHTML=`<i class="fas ${logsFullscreen?'fa-compress':'fa-expand'}"></i>`;button.title=logsFullscreen?(currentLang==='en'?'Exit full screen':'退出全屏'):t('logs_fullscreen');}
}

function logLevelClass(line) {
    if (/\[CRITICAL\]/.test(line)) return 'log-line-critical';
    if (/\[ERROR\]/.test(line))    return 'log-line-error';
    if (/\[WARNING\]/.test(line))  return 'log-line-warning';
    if (/\[INFO\]/.test(line))     return 'log-line-info';
    if (/\[DEBUG\]/.test(line))    return 'log-line-debug';
    return '';
}

function getHiddenLevels() {
    const hidden = new Set();
    document.querySelectorAll('.log-filter-cb').forEach(function(cb) {
        if (!cb.checked) hidden.add('log-line-' + cb.dataset.level);
    });
    return hidden;
}

function applyLogFilter() {
    const hidden = getHiddenLevels();
    document.querySelectorAll('#log-output .log-line').forEach(function(span) {
        const level = span.classList[1] || '';
        span.style.display = hidden.has(level) ? 'none' : '';
    });
}

function appendLogLines(output, text) {
    const hidden = getHiddenLevels();
    let lastLevelClass = '';
    const lines = text.split('\n');
    lines.forEach(function(line, i) {
        if (i === lines.length - 1 && line === '') return;
        const span = document.createElement('span');
        const levelClass = logLevelClass(line) || lastLevelClass;
        if (logLevelClass(line)) lastLevelClass = levelClass;
        span.className = 'log-line ' + levelClass;
        span.textContent = line + '\n';
        if (hidden.has(levelClass)) span.style.display = 'none';
        output.appendChild(span);
    });
}

document.addEventListener('change', function(e) {
    if (e.target.classList.contains('log-filter-cb')) applyLogFilter();
});

function startLogStream() {
    if (logEventSource) return;
    const output = document.getElementById('log-output');
    output.innerHTML = '';
    let closed=false;
    const refresh=async()=>{if(closed)return;try{const response=await fetch('/api/logs/snapshot?lines=500',{cache:'no-store'}),data=await response.json();if(data.status!=='success')throw new Error(data.message||'日志加载失败');output.innerHTML='';appendLogLines(output,data.content||'暂无日志');applyLogFilter();output.scrollTop=output.scrollHeight;}catch(error){output.textContent=error.message||'日志加载失败';}};
    refresh();const timer=setInterval(refresh,2500);logEventSource={close(){closed=true;clearInterval(timer);}};
}

function stopLogStream() {
    if (logEventSource) {
        logEventSource.close();
        logEventSource = null;
    }
}

// =====================================================================
// View Navigation Hook
// =====================================================================
const _origNavigateTo = navigateTo;
navigateTo = function(viewId) {
    // Stop log stream when leaving logs view
    if (currentView === 'logs' && viewId !== 'logs') stopLogStream();

    // Back-compat: the standalone "models" view is now a tab inside "config".
    // Redirect any legacy navigateTo('models') to config + models tab.
    if (viewId === 'models') {
        _origNavigateTo('config');
        loadConfigView();
        switchConfigTab('models');
        return;
    }

    _origNavigateTo(viewId);

    // Chat execution is intentionally independent from the visible module.
    // Never close its EventSource here: while another module is open, expose
    // a compact global status instead and let the stream finish normally.
    if (viewId === 'chat') {
        hideBackgroundChatNotice();
    } else if (activeRequestId) {
        showBackgroundChatNotice('running', '切换模块不会中断，点击可返回会话', sessionId);
    }

    // Lazy-load view data
    if (viewId === 'config') { loadConfigView(); switchConfigTab('basic'); }
    else if (viewId === 'skills') loadSkillsView();
    else if (viewId === 'memory') {
        document.getElementById('memory-panel-viewer').classList.add('hidden');
        document.getElementById('memory-panel-list').classList.remove('hidden');
        switchMemoryTab('files');
    }
    else if (viewId === 'knowledge') loadKnowledgeView();
    else if (viewId === 'channels') loadChannelsView();
    else if (viewId === 'tasks') loadTasksView();
    else if (viewId === 'intelligence') loadAutomationTasks();
    else if (viewId === 'api') loadApiKeys();
    else if (viewId === 'logs') startLogStream();
};

async function loadApiKeys() {
    const container = document.getElementById('api-keys-list');
    try {
        const response = await fetch('/api/access-keys');
        const data = await response.json();
        if (data.status !== 'success') throw new Error(data.message || '加载失败');
        if (!data.keys.length) { container.innerHTML = '<div class="py-12 text-center text-slate-400">暂无访问密钥</div>'; return; }
        container.innerHTML = data.keys.map(key => `<div class="rounded-xl border border-slate-200 dark:border-white/10 bg-white dark:bg-[#202020] p-4 flex items-center justify-between gap-3"><div><div class="font-medium text-slate-800 dark:text-slate-100">${escapeHtml(key.name)}</div><div class="text-xs text-slate-400 mt-1 font-mono">${escapeHtml(key.prefix)}... · ${key.last_used_at ? '最近使用 ' + escapeHtml(key.last_used_at) : '尚未使用'}</div></div><button onclick="revokeApiKey('${key.id}')" class="text-red-500 text-sm px-3 py-1.5">撤销</button></div>`).join('');
    } catch (error) { container.innerHTML = `<div class="py-12 text-center text-red-500">${escapeHtml(error.message)}</div>`; }
}

async function createApiKey() {
    const name = prompt('请输入密钥名称，例如：内部自动化');
    if (!name) return;
    const response = await fetch('/api/access-keys', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({action:'create', name})});
    const data = await response.json();
    if (data.status !== 'success') { alert(data.message || '创建失败'); return; }
    document.getElementById('api-key-token').textContent = data.key.token;
    document.getElementById('api-key-created').classList.remove('hidden');
    loadApiKeys();
}

async function revokeApiKey(id) {
    if (!confirm('撤销后使用该密钥的程序会立即失效，确定继续吗？')) return;
    const response = await fetch('/api/access-keys', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({action:'revoke', id})});
    const data = await response.json();
    if (data.status !== 'success') { alert(data.message || '撤销失败'); return; }
    loadApiKeys();
}

