    Object.values(TASK_CREATOR_TYPES).forEach(item=>document.getElementById(item.form).classList.add('hidden'));
    document.getElementById('task-notification-config').classList.add('hidden');
    document.getElementById('task-artifact-config').classList.add('hidden');
