function showSettingsView(view,title){if(view==='data')view='knowledge';restoreSettingsMountedView();updateSettingsDataFullscreenButton(view==='knowledge');document.querySelectorAll('.settings-section').forEach(x=>x.classList.add('hidden'));const host=document.getElementById('settings-embedded'),node=document.getElementById(`view-${view}`);if(!host||!node)return;settingsMountedView={node,parent:node.parentNode,next:node.nextSibling,className:node.className};host.classList.remove('hidden');node.className=`block w-full min-h-full settings-mounted-view settings-mounted-${view}`;host.appendChild(node);const enTitles={config:'Agent & models',memory:'Memory','memory-wiki':'Memory Wiki',channels:'Channels & connections',knowledge:'Data management',api:'API management',tasks:'Scheduled tasks',logs:'System logs',maintenance:'Maintenance dashboard','remote-bridge':'Remote Bridge'};document.getElementById('settings-title').textContent=currentLang==='en'?(enTitles[view]||title):(title||'设置');setSettingsNavActive(view);document.querySelector('#settings-center main').scrollTop=0;if(view==='config'){loadConfigView();switchConfigTab('basic');}else if(view==='memory'){document.getElementById('memory-panel-viewer')?.classList.add('hidden');document.getElementById('memory-panel-list')?.classList.remove('hidden');switchMemoryTab('files');}else if(view==='memory-wiki'){setTimeout(()=>loadMemoryWiki?.(),60);}else if(view==='knowledge'){mountStorageControlsIntoKnowledge();loadRetentionSettings();loadKnowledgeArchiveSettings();loadKnowledgeView();}else if(view==='channels')loadChannelsView();else if(view==='tasks')loadTasksView();else if(view==='api')loadApiKeys();else if(view==='logs')startLogStream();else if(view==='maintenance')setTimeout(()=>loadMaintenanceDashboard?.(true),60);else if(view==='remote-bridge')setTimeout(()=>loadRemoteBridge?.(true),60);}
