const AGENT_PROCESS_VISIBILITY_KEY='cow_show_agent_process';
function agentProcessVisible(){return localStorage.getItem(AGENT_PROCESS_VISIBILITY_KEY)==='1';}
function syncAgentProcessSetting(){const visible=agentProcessVisible();document.documentElement.classList.toggle('hide-agent-process',!visible);const input=document.getElementById('settings-show-agent-process');if(input)input.checked=visible;}
function setAgentProcessVisibility(visible){localStorage.setItem(AGENT_PROCESS_VISIBILITY_KEY,visible?'1':'0');syncAgentProcessSetting();}
async function loadRetentionSettings(){try{const response=await fetch('/api/storage-retention',{cache:'no-store'}),data=await response.json();if(data.status!=='success')throw new Error(data.message);Object.entries(data.settings||{}).forEach(([key,value])=>{const field=document.getElementById(`retention-${key}`);if(field)field.value=String(value);});const auto=document.getElementById('retention-auto-cleanup');if(auto)auto.checked=data.settings?.auto_cleanup_enabled!==false;}catch(error){const status=document.getElementById('retention-status');if(status)status.textContent=currentLang==='en'?'Could not load retention settings.':'无法读取存储设置。';}}
async function saveRetentionSettings(){const status=document.getElementById('retention-status');const payload={};['conversations','logs','uploads','artifacts','cache'].forEach(key=>payload[key]=Number(document.getElementById(`retention-${key}`)?.value||0));payload.auto_cleanup_enabled=document.getElementById('retention-auto-cleanup')?.checked!==false;if(status)status.textContent=currentLang==='en'?'Saving and cleaning expired files…':'正在保存并清理过期文件…';try{const response=await fetch('/api/storage-retention',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),data=await response.json();if(data.status!=='success')throw new Error(data.message);const count=Object.values(data.cleaned||{}).reduce((sum,value)=>sum+Number(value||0),0);if(status)status.textContent=currentLang==='en'?`Saved. ${count} expired items removed.`:`已保存，本次清理 ${count} 项过期数据。`;}catch(error){if(status)status.textContent=(currentLang==='en'?'Save failed: ':'保存失败：')+(error.message||error);}}
function formatKnowledgeArchiveMoment(value){const text=String(value||'').replace('T',' ').slice(0,19);return text||'暂无';}
function summarizeKnowledgeArchiveItem(item){if(!item||!item.knowledge_path)return '待生成';return item.period_key||'已生成';}
function renderKnowledgeArchiveDashboard(archive={},settings={}){
    const host=document.getElementById('knowledge-archive-dashboard-card');if(!host)return;
    const retry=settings.retry||{},pending=Number(archive.pending_retry_count||Object.keys(archive.pending_retries||{}).length||0),enabled=settings.enabled!==false;
    const lastFailures=Array.isArray(archive.last_failures)?archive.last_failures:[],failureText=lastFailures.length?String(lastFailures[0]?.message||lastFailures[0]||'最近有归档失败'):'暂无失败';
    const card=(label,value,hint,icon,tone='emerald')=>`<div class="rounded-xl bg-white/80 dark:bg-black/10 border border-white/70 dark:border-white/10 px-4 py-3"><div class="flex items-center justify-between gap-3"><span class="text-xs text-slate-400">${label}</span><i class="fas ${icon} text-${tone}-500"></i></div><b class="block mt-2 text-sm">${escapeHtml(value)}</b><p class="mt-1 text-[11px] text-slate-400 line-clamp-2">${escapeHtml(hint||'')}</p></div>`;
    host.innerHTML=`<div class="flex flex-wrap items-start justify-between gap-3">
        <div><h3 class="font-semibold"><i class="fas fa-book-open text-emerald-500 mr-2"></i>知识库归档状态</h3><p class="text-xs text-slate-500 mt-1">每天汇总产物、会话和故障问题；失败会按设置自动重试，也可以手动一键归档。</p></div>
        <div class="flex flex-wrap items-center gap-2"><span class="px-2.5 py-1 rounded-full text-xs ${enabled?'bg-emerald-100 text-emerald-700 dark:bg-emerald-500/10 dark:text-emerald-300':'bg-slate-100 text-slate-500 dark:bg-white/10'}">${enabled?'自动归档已启用':'自动归档已停用'}</span><button onclick="runKnowledgeArchiveNow(this)" class="px-3 py-2 rounded-lg bg-emerald-600 text-white text-xs"><i class="fas fa-box-archive mr-1"></i>手动归档今天</button></div>
    </div>
    <div class="grid sm:grid-cols-2 lg:grid-cols-4 gap-3 mt-4">
        ${card('最近日归档',summarizeKnowledgeArchiveItem(archive.last_daily),archive.last_daily?.knowledge_path?'已同步到知识库':'今天还没有生成','fa-calendar-day')}
        ${card('最近周归档',summarizeKnowledgeArchiveItem(archive.last_weekly),archive.last_weekly?.knowledge_path?'周归档按最新周排在上方':'本周还没有生成','fa-calendar-week')}
        ${card('下次归档',enabled?`每天 ${settings.run_time||'18:00'}`:'已停用',`最近运行：${formatKnowledgeArchiveMoment(archive.last_run_at)}`,'fa-clock','blue')}
        ${card('失败重试',pending?`${pending} 个待重试`:'暂无待重试',pending?`下次重试：${formatKnowledgeArchiveMoment(archive.next_retry_at)}`:`失败后每 ${retry.interval_hours||2} 小时重试，最多 ${retry.max_retries??2} 次`,'fa-rotate','amber')}
    </div>
    <div class="mt-3 flex flex-wrap items-center justify-between gap-3 text-xs text-slate-500">
        <span>知识库目录：${escapeHtml(archive.knowledge_dir||'未创建')}</span>
        <span class="${lastFailures.length?'text-amber-600':'text-slate-400'}">最近失败：${escapeHtml(failureText)}</span>
        <div class="flex flex-wrap gap-2"><button onclick="runKnowledgeArchivePeriod('week',this)" class="px-3 py-1.5 rounded-lg border text-xs">归档本周</button><button onclick="runKnowledgeArchivePeriod('month',this)" class="px-3 py-1.5 rounded-lg border text-xs">归档本月</button><button onclick="runKnowledgeArchivePeriod('year',this)" class="px-3 py-1.5 rounded-lg border text-xs">归档今年</button></div>
    </div>`;
}
async function loadKnowledgeArchiveSettings(){const status=document.getElementById('knowledge-archive-settings-status');try{const response=await fetch('/api/knowledge/archive-settings',{cache:'no-store'}),data=await response.json();if(data.status!=='success')throw new Error(data.message||'load failed');const settings=data.settings||{},retention=settings.retention||{},retry=settings.retry||{},quality=settings.quality||{};const enabled=document.getElementById('knowledge-archive-enabled');if(enabled)enabled.checked=settings.enabled!==false;const runTime=document.getElementById('knowledge-archive-run-time');if(runTime)runTime.value=settings.run_time||'18:00';const setValue=(id,value)=>{const el=document.getElementById(id);if(el)el.value=String(value);};setValue('knowledge-retention-day',retention.day_months||3);setValue('knowledge-retention-week',retention.week_months||6);setValue('knowledge-retention-month',retention.month_years||3);setValue('knowledge-retention-year',retention.year_years||0);setValue('knowledge-archive-retry-max',retry.max_retries??2);setValue('knowledge-archive-retry-hours',retry.interval_hours||2);setValue('knowledge-archive-catch-up-days',settings.catch_up_days||7);setValue('knowledge-archive-min-group-count',quality.min_group_count||2);const finalNotify=document.getElementById('knowledge-archive-final-notify');if(finalNotify)finalNotify.checked=retry.notify_on_final_failure!==false;const dedupe=document.getElementById('knowledge-archive-dedupe-enabled');if(dedupe)dedupe.checked=quality.dedupe_enabled!==false;const summarize=document.getElementById('knowledge-archive-summarize-repeated');if(summarize)summarize.checked=quality.summarize_repeated!==false;const modelSummary=document.getElementById('knowledge-archive-model-summary');if(modelSummary)modelSummary.checked=quality.model_summary_enabled!==false;const qualityHint=document.getElementById('knowledge-archive-quality-hint');if(qualityHint)qualityHint.textContent=quality.dedupe_enabled===false?'未开启去重':`去重已开启 · ${quality.min_group_count||2} 条起合并`;const categories=document.getElementById('knowledge-archive-categories');if(categories)categories.value=(settings.categories||['问题类','知识类','学习类','进化类','任务产物类']).join('\n');const archive=data.archive||{},pending=Object.keys(archive.pending_retries||{}).length;renderKnowledgeArchiveDashboard(archive,settings);if(status)status.textContent=`当前：每天 ${settings.run_time||'18:00'} 自动归档；失败后每 ${retry.interval_hours||2} 小时重试，最多 ${retry.max_retries??2} 次${pending?`；待重试 ${pending} 个`:''}；归档去重${quality.dedupe_enabled===false?'未开启':'已开启'}。`;const archiveStat=document.getElementById('knowledge-stat-archive');if(archiveStat)archiveStat.textContent=settings.enabled===false?'已停用':(settings.run_time||'18:00');}catch(error){if(status)status.textContent='无法读取知识库归档设置。';renderKnowledgeArchiveDashboard({},{});}}
async function saveKnowledgeArchiveSettings(){const status=document.getElementById('knowledge-archive-settings-status');const payload={enabled:document.getElementById('knowledge-archive-enabled')?.checked!==false,run_time:document.getElementById('knowledge-archive-run-time')?.value||'18:00',catch_up_days:Number(document.getElementById('knowledge-archive-catch-up-days')?.value||7),retry:{enabled:true,max_retries:Number(document.getElementById('knowledge-archive-retry-max')?.value||2),interval_hours:Number(document.getElementById('knowledge-archive-retry-hours')?.value||2),notify_on_final_failure:document.getElementById('knowledge-archive-final-notify')?.checked!==false},retention:{day_months:Number(document.getElementById('knowledge-retention-day')?.value||3),week_months:Number(document.getElementById('knowledge-retention-week')?.value||6),month_years:Number(document.getElementById('knowledge-retention-month')?.value||3),year_years:Number(document.getElementById('knowledge-retention-year')?.value||0)},quality:{dedupe_enabled:document.getElementById('knowledge-archive-dedupe-enabled')?.checked!==false,summarize_repeated:document.getElementById('knowledge-archive-summarize-repeated')?.checked!==false,model_summary_enabled:document.getElementById('knowledge-archive-model-summary')?.checked!==false,min_group_count:Number(document.getElementById('knowledge-archive-min-group-count')?.value||2)},categories:(document.getElementById('knowledge-archive-categories')?.value||'').split(/\n+/).map(x=>x.trim()).filter(Boolean)};if(status)status.textContent='正在保存知识库归档设置…';try{const response=await fetch('/api/knowledge/archive-settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),data=await response.json();if(data.status!=='success')throw new Error(data.message||'save failed');const removed=Object.values(data.cleaned||{}).reduce((sum,value)=>sum+Number(value||0),0);if(status)status.textContent=`已保存。已清理 ${removed} 个过期归档文件。`;await loadKnowledgeArchiveSettings();}catch(error){if(status)status.textContent=`保存失败：${error.message||error}`;}}
async function runKnowledgeArchiveNow(button){const status=document.getElementById('knowledge-archive-settings-status');if(status)status.textContent='正在执行手动归档…';if(button){button.disabled=true;button.dataset.oldHtml=button.innerHTML;button.innerHTML='<i class="fas fa-spinner fa-spin mr-1"></i>归档中…';}try{const response=await fetch('/api/knowledge/archive-run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({period:'day',force:true})}),data=await response.json();if(data.status!=='success')throw new Error(data.archive?.message||data.message||'归档失败');const archive=data.archive||{},summary=archive.summary||{};if(status)status.textContent=`手动归档完成：会话 ${summary.conversations||0}，产物 ${summary.artifacts||0}，自动化 ${summary.automation||0}，异常 ${summary.failures||0}。`;const refreshes=[loadKnowledgeArchiveSettings()];if(typeof loadKnowledgeView==='function')refreshes.push(loadKnowledgeView());if(typeof loadArtifactCenter==='function')refreshes.push(loadArtifactCenter(true).catch(()=>{}));await Promise.all(refreshes);}catch(error){if(status)status.textContent=`手动归档失败：${error.message||error}`;}finally{if(button){button.disabled=false;button.innerHTML=button.dataset.oldHtml||'手动一键归档';}}}
async function runKnowledgeArchivePeriod(period,button){const labels={day:'今天',week:'本周',month:'本月',year:'今年'},status=document.getElementById('knowledge-archive-settings-status');if(status)status.textContent=`正在归档${labels[period]||'当前周期'}…`;if(button){button.disabled=true;button.dataset.oldHtml=button.innerHTML;button.innerHTML='<i class="fas fa-spinner fa-spin mr-1"></i>归档中…';}try{const response=await fetch('/api/knowledge/archive-run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({period,force:true})}),data=await response.json();if(data.status!=='success')throw new Error(data.archive?.message||data.message||'归档失败');const archive=data.archive||{},summary=archive.summary||{};if(status)status.textContent=`${labels[period]||'手动'}归档完成：会话 ${summary.conversations||0}，产物 ${summary.artifacts||0}，自动化 ${summary.automation||0}，异常 ${summary.failures||0}。`;const refreshes=[loadKnowledgeArchiveSettings()];if(typeof loadKnowledgeView==='function')refreshes.push(loadKnowledgeView());if(typeof loadArtifactCenter==='function')refreshes.push(loadArtifactCenter(true).catch(()=>{}));await Promise.all(refreshes);}catch(error){if(status)status.textContent=`归档失败：${error.message||error}`;}finally{if(button){button.disabled=false;button.innerHTML=button.dataset.oldHtml||'归档';}}}
async function runSystemSmokeCheck(){const status=document.getElementById('system-smoke-status'),host=document.getElementById('system-smoke-result');if(status)status.textContent=currentLang==='en'?'Checking system…':'正在执行系统自检…';if(host)host.innerHTML='<div class="sm:col-span-2 py-4 text-center text-slate-400">检查中...</div>';try{const response=await fetch('/api/system-smoke',{cache:'no-store'}),data=await response.json();if(!response.ok||!['success','warning'].includes(data.status))throw new Error(data.message||'系统自检失败');const checks=data.checks||[];if(host)host.innerHTML=checks.map(x=>`<div class="rounded-lg border ${x.ok?'border-emerald-100 bg-emerald-50/60 text-emerald-700 dark:border-emerald-500/20 dark:bg-emerald-500/10 dark:text-emerald-300':'border-red-100 bg-red-50/60 text-red-700 dark:border-red-500/20 dark:bg-red-500/10 dark:text-red-300'} px-3 py-2"><div class="flex items-center justify-between gap-2"><b>${escapeHtml(x.name)}</b><span class="text-[10px]">${x.ok?'正常':'异常'}</span></div><p class="text-xs mt-1 opacity-80">${escapeHtml(x.message||'')}</p>${x.fix?`<p class="text-xs mt-1 text-orange-600">${escapeHtml(x.fix)}</p>`:''}</div>`).join('');if(status)status.textContent=`自检完成：${data.summary?.ok||0}/${data.summary?.total||0} 项正常 · ${data.checked_at||''}`;}catch(error){if(host)host.innerHTML='';if(status)status.textContent=`自检失败：${error.message||error}`;}}
function storageCleanupSummary(cleaned={}){const labels={cache:'缓存',conversations:'历史会话',logs:'日志',uploads:'上传/临时文件',artifacts:'自动化产物'};return Object.entries(cleaned).filter(([,v])=>Number(v||0)>0).map(([k,v])=>`${labels[k]||k} ${v} 项`).join('，')||'0 项';}
async function runStorageCleanup(){const status=document.getElementById('storage-cleanup-status'),scopes=[...document.querySelectorAll('.storage-clean-scope:checked')].map(x=>x.value),allCache=document.getElementById('storage-clean-cache-all')?.checked;if(!scopes.length){if(status){status.className='text-xs text-red-500 mt-3';status.textContent='请至少选择一个清理范围。';}return;}if(allCache&&scopes.includes('cache')&&!confirm('确定清空 CowAgent 缓存数据吗？不会删除授权目录里的原始文件。'))return;if(status){status.className='text-xs text-blue-600 mt-3';status.textContent='正在清理，请稍等…';}try{const response=await fetch('/api/storage-retention',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scopes,mode:allCache?'all_cache':'expired'})}),data=await response.json();if(data.status!=='success')throw new Error(data.message||'清理失败');if(status){status.className='text-xs text-emerald-600 mt-3';status.textContent=`清理完成：${storageCleanupSummary(data.cleaned)}。`;}}catch(error){if(status){status.className='text-xs text-red-500 mt-3';status.textContent=`清理失败：${error.message||error}`;}}}

let fileSearchRoots=[];
function renderFileSearchRoots(){const host=document.getElementById('file-search-roots-list');if(!host)return;host.innerHTML=fileSearchRoots.length?fileSearchRoots.map((entry,index)=>`<div class="flex items-center gap-3 rounded-lg border border-slate-200 dark:border-white/10 px-3 py-2"><i class="fas fa-folder text-amber-500"></i><span class="flex-1 min-w-0 truncate text-sm" title="${escapeHtml(entry.path)}">${escapeHtml(entry.path)}</span><select onchange="setFileSearchRootPermission(${index},this.value)" class="rounded-lg border border-slate-200 dark:border-white/10 bg-transparent px-2 py-1 text-xs"><option value="read" ${entry.permission!=='read_write'?'selected':''}>${currentLang==='en'?'Read only':'只读'}</option><option value="read_write" ${entry.permission==='read_write'?'selected':''}>${currentLang==='en'?'Read & write':'读写'}</option></select><button onclick="removeFileSearchRoot(${index})" class="text-xs text-red-500">${currentLang==='en'?'Remove':'删除'}</button></div>`).join(''):`<div class="rounded-lg border border-dashed p-4 text-center text-xs text-slate-400">${currentLang==='en'?'No custom directory. System defaults will be used.':'未指定目录，将使用系统默认的桌面、文档和下载目录。'}</div>`;}
async function loadFileSearchRoots(){const status=document.getElementById('file-search-roots-status');try{const response=await fetch('/api/file-search-roots',{cache:'no-store'}),data=await response.json();if(data.status!=='success')throw new Error(data.message);fileSearchRoots=(data.entries||data.roots||[]).map(entry=>typeof entry==='string'?{path:entry,permission:'read'}:{path:entry.path,permission:entry.permission==='read_write'?'read_write':'read'});renderFileSearchRoots();if(status)status.textContent=currentLang==='en'?`${data.file_count||0} files indexed.`:`已建立 ${data.file_count||0} 个文件的索引。`;}catch(error){if(status)status.textContent=(currentLang==='en'?'Load failed: ':'读取失败：')+(error.message||error);}}
async function chooseFileSearchRoot(){const input=document.getElementById('file-search-root-input'),status=document.getElementById('file-search-roots-status');const acceptPath=path=>{if(!path)return;if(input)input.value=path;addFileSearchRoot();if(status)status.textContent=currentLang==='en'?'Directory added. Click Save to apply.':'目录已添加，请点击“保存并重建索引”使其生效。';};if(window.electronAPI?.selectDirectory){if(status)status.textContent=currentLang==='en'?'Opening folder picker…':'正在打开目录选择器…';try{acceptPath(await window.electronAPI.selectDirectory()||'');}catch(error){if(status)status.textContent=(currentLang==='en'?'Could not open folder picker: ':'无法打开目录选择器：')+(error.message||error);}}else{if(status)status.textContent=currentLang==='en'?'Select a disk or folder.':'请选择磁盘或目录。';openLocalDirectoryPicker(acceptPath);}}
function addFileSearchRoot(){const input=document.getElementById('file-search-root-input'),path=(input?.value||'').trim();if(!path)return input?.focus();if(!fileSearchRoots.some(entry=>entry.path===path))fileSearchRoots.push({path,permission:'read'});input.value='';renderFileSearchRoots();}
function setFileSearchRootPermission(index,permission){if(fileSearchRoots[index])fileSearchRoots[index].permission=permission==='read_write'?'read_write':'read';}
function removeFileSearchRoot(index){fileSearchRoots.splice(index,1);renderFileSearchRoots();const status=document.getElementById('file-search-roots-status');if(status)status.textContent=currentLang==='en'?'Directory removed from the list. Click Save to apply.':'目录已从列表移除，点击“保存并重建索引”后生效。';}
async function waitForFileIndexReady(){const status=document.getElementById('file-search-roots-status'),button=document.getElementById('file-search-roots-save');for(let attempt=0;attempt<120;attempt+=1){await new Promise(resolve=>setTimeout(resolve,1000));try{const response=await fetch('/api/file-search-roots',{cache:'no-store'}),data=await response.json();if(data.status!=='success')continue;if(!data.refreshing){if(status){status.className='text-xs text-emerald-600 mt-3';status.textContent=currentLang==='en'?`Index rebuilt: ${data.file_count||0} files.`:`索引重建完成，共 ${data.file_count||0} 个文件。`;}if(button){button.disabled=false;button.innerHTML=currentLang==='en'?'Save and rebuild index':'保存并重建索引';}_wsToast(currentLang==='en'?'File index rebuilt.':'文件索引重建完成');return;}if(status)status.textContent=currentLang==='en'?`Rebuilding index… ${data.file_count||0} files indexed.`:`正在重建索引… 当前已收录 ${data.file_count||0} 个文件。`;}catch(_error){}}if(button){button.disabled=false;button.innerHTML=currentLang==='en'?'Save and rebuild index':'保存并重建索引';}if(status){status.className='text-xs text-amber-600 mt-3';status.textContent=currentLang==='en'?'Rebuild continues in background.':'索引仍在后台重建，可继续使用其他功能。';}}
async function saveFileSearchRoots(){const status=document.getElementById('file-search-roots-status'),button=document.getElementById('file-search-roots-save');if(button){button.disabled=true;button.innerHTML=`<i class="fas fa-spinner fa-spin mr-2"></i>${currentLang==='en'?'Saving…':'正在保存…'}`;}if(status){status.className='text-xs text-blue-600 mt-3';status.textContent=currentLang==='en'?'Saving directory permissions…':'正在保存目录权限…';}try{const response=await fetch('/api/file-search-roots',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({entries:fileSearchRoots})});const raw=await response.text();let data=null;try{data=JSON.parse(raw);}catch(_error){if(response.status===404||/^not found$/i.test(raw.trim()))throw new Error(currentLang==='en'?'The local backend is not ready. Refresh the page and try again.':'本地后台接口暂不可用，请刷新页面后重试。');throw new Error(raw.trim()||`${currentLang==='en'?'Request failed':'请求失败'}（HTTP ${response.status}）`);}if(!response.ok||data.status!=='success')throw new Error(data.message||`${currentLang==='en'?'Request failed':'请求失败'}（HTTP ${response.status}）`);fileSearchRoots=(data.entries||[]).map(entry=>({path:entry.path,permission:entry.permission==='read_write'?'read_write':'read'}));renderFileSearchRoots();if(button)button.innerHTML=`<i class="fas fa-spinner fa-spin mr-2"></i>${currentLang==='en'?'Rebuilding…':'正在重建索引…'}`;if(status)status.textContent=currentLang==='en'?'Saved. Rebuilding the file index…':'目录权限保存成功，正在重建文件索引…';_wsToast(currentLang==='en'?'Directory permissions saved.':'目录权限已保存');waitForFileIndexReady();}catch(error){if(button){button.disabled=false;button.innerHTML=currentLang==='en'?'Save and rebuild index':'保存并重建索引';}if(status){status.className='text-xs text-red-500 mt-3';status.textContent=(currentLang==='en'?'Save failed: ':'保存失败：')+(error.message||error);}_wsToast((currentLang==='en'?'Save failed: ':'保存失败：')+(error.message||error));}}
function readQuickTags(){try{return JSON.parse(localStorage.getItem(QUICK_TAGS_KEY)||'[]');}catch(_){return [];}}
function addQuickTag(){const name=document.getElementById('quick-tag-name').value.trim();const content=document.getElementById('quick-tag-content').value.trim();if(!name||!content)return;const tags=readQuickTags();tags.push({id:Date.now().toString(36),name,content});localStorage.setItem(QUICK_TAGS_KEY,JSON.stringify(tags));document.getElementById('quick-tag-name').value='';document.getElementById('quick-tag-content').value='';renderQuickTags();}
function deleteQuickTag(id){localStorage.setItem(QUICK_TAGS_KEY,JSON.stringify(readQuickTags().filter(x=>x.id!==id)));renderQuickTags();}
function insertQuickTag(id){const tag=readQuickTags().find(x=>x.id===id);const input=document.getElementById('chat-input');if(!tag||!input)return;const start=input.selectionStart??input.value.length;const end=input.selectionEnd??start;input.value=input.value.slice(0,start)+tag.content+input.value.slice(end);input.dispatchEvent(new Event('input',{bubbles:true}));input.focus();input.setSelectionRange(start+tag.content.length,start+tag.content.length);}
function renderQuickTags(){const tags=readQuickTags();const bar=document.getElementById('quick-tags-bar');bar.classList.toggle('hidden',!tags.length);bar.innerHTML=tags.map(x=>`<button type="button" onclick="insertQuickTag('${x.id}')" class="px-2.5 py-1 rounded-full bg-primary-50 dark:bg-primary-500/10 text-primary-600 dark:text-primary-300 text-xs">${escapeHtml(x.name)}</button>`).join('');const list=document.getElementById('quick-tags-settings-list');if(list)list.innerHTML=tags.length?tags.map(x=>`<div class="p-3 rounded-xl border flex gap-3 items-center"><div class="flex-1 min-w-0"><b>${escapeHtml(x.name)}</b><p class="text-sm text-slate-500 truncate mt-1">${escapeHtml(x.content)}</p></div><button onclick="insertQuickTag('${x.id}')" class="text-primary-500 text-sm">插入</button><button onclick="deleteQuickTag('${x.id}')" class="text-red-500 text-sm">删除</button></div>`).join(''):'<div class="py-12 text-center text-slate-400">暂无快捷标签</div>';}
document.addEventListener('DOMContentLoaded',()=>{const size=localStorage.getItem('cow_font_size');if(size){document.getElementById('settings-font-size').value=size;applyConsoleFontSize(size);}syncAgentProcessSetting();renderQuickTags();});

let personalTodoCache = [];
let personalReminderCache = [];
let personalTodoFilter = '';
let personalProductivityTab = 'todos';

async function personalTodoRequest(payload) {
    const response = await fetch('/api/personal/todos', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify(payload || {})
    });
    const data = await response.json();
    if (!response.ok || data.status !== 'success') throw new Error(data.message || '任务清单操作失败');
    return data;
}

async function personalReminderRequest(payload) {
    const response = await fetch('/api/personal/reminders', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify(payload || {})
    });
    const data = await response.json();
    if (!response.ok || data.status !== 'success') throw new Error(data.message || '提醒操作失败');
    return data;
}

async function loadPersonalTodoList() {
    const host = document.getElementById('personal-todo-list');
    if (host) host.innerHTML = '<div class="py-8 text-center text-slate-400">正在加载任务清单...</div>';
    try {
        const response = await fetch('/api/personal/todos?include_archived=1', {cache: 'no-store'});
        const data = await response.json();
        if (!response.ok || data.status !== 'success') throw new Error(data.message || '读取任务清单失败');
        personalTodoCache = data.todos || [];
        renderPersonalTodoList();
        loadPersonalReminders();
    } catch (error) {
        if (host) host.innerHTML = `<div class="rounded-xl border border-red-500/20 bg-red-500/10 p-4 text-red-500 text-sm">读取失败：${escapeHtml(error.message || error)}</div>`;
    }
}

function setPersonalProductivityTab(tab) {
    personalProductivityTab = tab === 'reminders' ? 'reminders' : 'todos';
    document.getElementById('personal-todo-section')?.classList.toggle('hidden', personalProductivityTab !== 'todos');
    document.getElementById('personal-reminder-section')?.classList.toggle('hidden', personalProductivityTab !== 'reminders');
    const todoBtn = document.getElementById('personal-productivity-tab-todos');
    const reminderBtn = document.getElementById('personal-productivity-tab-reminders');
    if (todoBtn) {
        todoBtn.classList.toggle('bg-white', personalProductivityTab === 'todos');
        todoBtn.classList.toggle('dark:bg-[#292929]', personalProductivityTab === 'todos');
        todoBtn.classList.toggle('shadow-sm', personalProductivityTab === 'todos');
        todoBtn.classList.toggle('text-slate-400', personalProductivityTab !== 'todos');
    }
    if (reminderBtn) {
        reminderBtn.classList.toggle('bg-white', personalProductivityTab === 'reminders');
        reminderBtn.classList.toggle('dark:bg-[#292929]', personalProductivityTab === 'reminders');
        reminderBtn.classList.toggle('shadow-sm', personalProductivityTab === 'reminders');
        reminderBtn.classList.toggle('text-slate-400', personalProductivityTab !== 'reminders');
    }
    if (personalProductivityTab === 'reminders') loadPersonalReminders();
}

function setPersonalTodoFilter(status) {
    personalTodoFilter = status || '';
    ['all','todo','doing','done','archived'].forEach(name => {
        const button = document.getElementById(`personal-todo-filter-${name}`);
        if (!button) return;
        const active = (name === 'all' && !personalTodoFilter) || name === personalTodoFilter;
        button.classList.toggle('text-white', active);
        button.classList.toggle('text-slate-400', !active);
    });
    renderPersonalTodoList();
}

function togglePersonalTodoMenu(id) {
    document.querySelectorAll('.personal-todo-menu').forEach(menu => {
        if (menu.id !== `todo-menu-${id}`) menu.classList.add('hidden');
    });
    document.getElementById(`todo-menu-${id}`)?.classList.toggle('hidden');
}

function renderPersonalTodoList() {
    const host = document.getElementById('personal-todo-list');
    if (!host) return;
    const labels = {todo:'待办', doing:'进行中', done:'已完成', archived:'已归档'};
    const items = personalTodoCache.filter(item => !personalTodoFilter || item.status === personalTodoFilter);
    if (!items.length) {
        host.innerHTML = '<div class="rounded-xl border border-dashed p-8 text-center text-slate-400 text-sm">暂无任务。你可以在微信/企业微信发送“任务：内容”，或在上方手动新增。</div>';
        return;
    }
    host.innerHTML = items.map(item => {
        const id = escapeHtml(item.id || '');
        const done = item.status === 'done' || item.completed;
        const text = item.content || item.title || '';
        const created = String(item.created_at || '').replace('T',' ').replace(/\+\d\d:\d\d$/, '');
        return `<div class="relative rounded-lg border border-slate-400/60 bg-transparent p-4 md:p-5" data-todo-id="${id}">
            <div class="flex items-center gap-4">
                <input type="checkbox" ${done?'checked':''} onchange="togglePersonalTodo('${id}', this.checked)" class="h-4 w-4 rounded border-slate-400 bg-transparent shrink-0">
                <div class="flex-1 min-w-0">
                    <input id="todo-title-${id}" value="${escapeHtml(text)}" class="hidden">
                    <input id="todo-content-${id}" value="${escapeHtml(text)}" onkeydown="if(event.key==='Enter')savePersonalTodo('${id}')" class="w-full min-w-0 bg-transparent border-0 outline-none text-sm md:text-base font-semibold ${done?'line-through opacity-60':''}" placeholder="任务内容">
                    <div class="mt-1 text-xs text-slate-500">创建日期：${escapeHtml(created || '-')}</div>
                </div>
                <select id="todo-status-${id}" onchange="savePersonalTodo('${id}')" class="rounded-lg border border-slate-400/60 bg-transparent px-3 py-2 text-sm shrink-0">
                    ${Object.entries(labels).map(([key,label])=>`<option value="${key}" ${item.status===key?'selected':''}>${label}</option>`).join('')}
                </select>
                <button onclick="togglePersonalTodoMenu('${id}')" class="rounded-lg bg-slate-700/70 hover:bg-slate-600 text-white px-3 py-2 shrink-0"><i class="fas fa-ellipsis-v"></i></button>
            </div>
            <div id="todo-menu-${id}" class="personal-todo-menu hidden absolute right-3 top-16 z-20 w-28 overflow-hidden rounded-lg border border-blue-500/30 bg-slate-800 text-blue-100 shadow-xl">
                <button onclick="savePersonalTodo('${id}');togglePersonalTodoMenu('${id}')" class="w-full text-left px-3 py-2 text-sm hover:bg-blue-500/20"><i class="far fa-save mr-2"></i>保存</button>
                <button onclick="archivePersonalTodo('${id}')" class="w-full text-left px-3 py-2 text-sm hover:bg-blue-500/20"><i class="far fa-window-minimize mr-2"></i>归档</button>
                <button onclick="deletePersonalTodo('${id}')" class="w-full text-left px-3 py-2 text-sm hover:bg-blue-500/20"><i class="far fa-trash-alt mr-2"></i>删除</button>
            </div>
        </div>`;
    }).join('');
}

async function createPersonalTodo() {
    const input = document.getElementById('personal-todo-content');
    const status = 'todo';
    const content = (input?.value || '').trim();
    if (!content) return input?.focus();
    try {
        await personalTodoRequest({action:'create', content, status});
        if (input) input.value = '';
        await loadPersonalTodoList();
        _wsToast?.('任务已新增');
    } catch (error) {
        _wsToast?.(`新增失败：${error.message || error}`);
    }
}

async function savePersonalTodo(id) {
    try {
        const content = document.getElementById(`todo-content-${id}`)?.value || '';
        await personalTodoRequest({
            action:'update',
            id,
            title: content,
            content,
            status: document.getElementById(`todo-status-${id}`)?.value || 'todo'
        });
        await loadPersonalTodoList();
        _wsToast?.('任务已保存');
    } catch (error) {
        _wsToast?.(`保存失败：${error.message || error}`);
    }
}

async function togglePersonalTodo(id, completed) {
    try {
        await personalTodoRequest({action:'toggle', id, completed});
        await loadPersonalTodoList();
    } catch (error) {
        _wsToast?.(`更新失败：${error.message || error}`);
    }
}

async function archivePersonalTodo(id) {
    try {
        await personalTodoRequest({action:'update', id, status:'archived'});
        await loadPersonalTodoList();
    } catch (error) {
        _wsToast?.(`归档失败：${error.message || error}`);
    }
}

async function deletePersonalTodo(id) {
    if (!confirm('确定删除这条任务吗？')) return;
    try {
        await personalTodoRequest({action:'delete', id});
        await loadPersonalTodoList();
    } catch (error) {
        _wsToast?.(`删除失败：${error.message || error}`);
    }
}

async function loadPersonalReminders() {
    const host = document.getElementById('personal-reminder-list');
    if (host) host.innerHTML = '<div class="py-6 text-center text-slate-400 text-sm">正在加载提醒...</div>';
    try {
        const response = await fetch('/api/personal/reminders', {cache:'no-store'});
        const data = await response.json();
        if (!response.ok || data.status !== 'success') throw new Error(data.message || '读取提醒失败');
        personalReminderCache = data.reminders || [];
        renderPersonalReminders();
    } catch (error) {
        if (host) host.innerHTML = `<div class="rounded-xl border border-red-500/20 bg-red-500/10 p-4 text-red-500 text-sm">读取失败：${escapeHtml(error.message || error)}</div>`;
    }
}

function renderPersonalReminders() {
    const host = document.getElementById('personal-reminder-list');
    if (!host) return;
    const items = personalReminderCache;
    if (!items.length) {
        host.innerHTML = '<div class="rounded-xl border border-dashed p-8 text-center text-slate-400 text-sm">暂无提醒。试试在微信/企业微信发送“明天上午 9 点提醒我开会”，或在上方手动新增。</div>';
        return;
    }
    host.innerHTML = items.map(item => {
        const id = escapeHtml(item.id || '');
        const sent = item.status === 'sent';
        const content = item.content || item.title || '提醒';
        const due = String(item.due_at || item.schedule || '').replace('T',' ').replace(/\+\d\d:\d\d$/, '');
        const created = String(item.created_at || '').replace('T',' ').replace(/\+\d\d:\d\d$/, '');
        return `<div class="relative rounded-lg border border-slate-400/60 bg-transparent p-4 md:p-5 ${sent?'opacity-70':''}" data-reminder-id="${id}">
            <div class="flex items-center gap-4">
                <input type="checkbox" ${sent?'checked':''} onchange="if(this.checked)runPersonalReminder('${id}')" class="h-4 w-4 rounded border-slate-400 bg-transparent shrink-0" title="立即标记/发送提醒">
                <div class="flex-1 min-w-0">
                    <div class="text-sm md:text-base font-semibold">${escapeHtml(content)}</div>
                    <div class="mt-1 text-xs text-slate-500">提醒时间：${escapeHtml(due || '-')}</div>
                    <div class="mt-1 text-xs text-slate-500">创建日期：${escapeHtml(created || '-')} · 状态：${sent?'已发送':(item.enabled?'待提醒':'已暂停')} · 来源：${escapeHtml(item.source_channel || 'web')}</div>
                </div>
                <select onchange="togglePersonalReminder('${id}', this.value==='enabled')" class="rounded-lg border border-slate-400/60 bg-transparent px-3 py-2 text-sm shrink-0" ${sent?'disabled':''}>
                    <option value="enabled" ${item.enabled&&!sent?'selected':''}>待提醒</option>
                    <option value="paused" ${!item.enabled&&!sent?'selected':''}>已暂停</option>
                    <option value="sent" ${sent?'selected':''}>已发送</option>
                </select>
                <button onclick="togglePersonalReminderMenu('${id}')" class="rounded-lg bg-slate-700/70 hover:bg-slate-600 text-white px-3 py-2 shrink-0"><i class="fas fa-ellipsis-v"></i></button>
            </div>
            <div id="reminder-menu-${id}" class="personal-reminder-menu hidden absolute right-3 top-16 z-20 w-28 overflow-hidden rounded-lg border border-blue-500/30 bg-slate-800 text-blue-100 shadow-xl">
                ${!sent?`<button onclick="runPersonalReminder('${id}')" class="w-full text-left px-3 py-2 text-sm hover:bg-blue-500/20"><i class="far fa-bell mr-2"></i>立即提醒</button>`:''}
                <button onclick="togglePersonalReminder('${id}', ${item.enabled?'false':'true'})" class="w-full text-left px-3 py-2 text-sm hover:bg-blue-500/20"><i class="far fa-circle-pause mr-2"></i>${item.enabled?'暂停':'启用'}</button>
                <button onclick="deletePersonalReminder('${id}')" class="w-full text-left px-3 py-2 text-sm hover:bg-blue-500/20"><i class="far fa-trash-alt mr-2"></i>删除</button>
            </div>
        </div>`;
    }).join('');
}

function togglePersonalReminderMenu(id) {
    document.querySelectorAll('.personal-reminder-menu').forEach(menu => {
        if (menu.id !== `reminder-menu-${id}`) menu.classList.add('hidden');
    });
    document.getElementById(`reminder-menu-${id}`)?.classList.toggle('hidden');
}

async function createPersonalReminder() {
    const contentInput = document.getElementById('personal-reminder-content');
    const dueInput = document.getElementById('personal-reminder-due');
    const content = (contentInput?.value || '').trim();
    const dueAt = (dueInput?.value || '').trim();
    if (!content) return contentInput?.focus();
    if (!dueAt) return dueInput?.focus();
    try {
        await personalReminderRequest({action:'create', content, due_at: dueAt, source_channel:'web', source_receiver:'web_user'});
        if (contentInput) contentInput.value = '';
        if (dueInput) dueInput.value = '';
        await loadPersonalReminders();
        _wsToast?.('提醒已新增');
    } catch (error) {
        _wsToast?.(`新增提醒失败：${error.message || error}`);
    }
}

async function runPersonalReminder(id) {
    try {
        await personalReminderRequest({action:'run', id});
        await loadPersonalReminders();
        _wsToast?.('提醒已发送');
    } catch (error) {
        _wsToast?.(`发送失败：${error.message || error}`);
    }
}

async function togglePersonalReminder(id, enabled) {
    try {
        await personalReminderRequest({action:'toggle', id, enabled});
        await loadPersonalReminders();
    } catch (error) {
        _wsToast?.(`操作失败：${error.message || error}`);
    }
}

async function deletePersonalReminder(id) {
    if (!confirm('确定删除这条提醒吗？')) return;
    try {
        await personalReminderRequest({action:'delete', id});
        await loadPersonalReminders();
    } catch (error) {
        _wsToast?.(`删除失败：${error.message || error}`);
    }
}

function switchAutomationTab(tab) {
    if(tab==='agent2')loadHarnessEvolution();
    ['tasks','records','runs','notifications','pending','selfhealing','approvals','templates','explore','personal','todolist','agent2'].forEach(name=>{document.getElementById(`automation-${name}-panel`)?.classList.toggle('hidden',name!==tab);const btn=document.getElementById(`automation-tab-${name}`);if(btn){btn.classList.toggle('bg-white',name===tab);btn.classList.toggle('dark:bg-[#292929]',name===tab);btn.classList.toggle('shadow-sm',name===tab);}});
    if(tab==='records')loadAutomationRecords(); if(tab==='runs')loadAutomationRuns(); if(tab==='notifications')loadAutomationNotifications(); if(tab==='pending')loadPendingDeliveries(); if(tab==='selfhealing')loadSelfHealingLogs(); if(tab==='approvals')loadAutomationApprovals(); if(tab==='templates')loadAutomationTemplates(); if(tab==='explore')loadExplorationDrafts(); if(tab==='personal')loadPersonalAgentProfile(); if(tab==='todolist')loadPersonalTodoList(); if(tab==='agent2')loadAgent2Dashboard().then(async()=>{try{const data=await agent2Request();renderAgent2RuntimeEvidence(data.capabilities||[]);renderAgent2LimitedLists(data);renderAgent2HomeLearning(data);renderAgent2WeixinSuccessLearning(data);await loadAgent2ApprovalTargets(data.settings?.approval_notifications||[]);await loadAgentRoutingPreview();await loadHarnessEvolution();}catch(_error){}});
}

async function agent2Request(options){const response=await fetch('/api/agent2',{cache:'no-store',...(options||{})}),data=await response.json();if(!response.ok||data.status!=='success')throw new Error(data.message||'Agent 2.0 服务异常');return data;}
async function harnessEvolutionRequest(options){
    const response=await fetch('/api/harness-evolution',{cache:'no-store',...(options||{}),signal:AbortSignal.timeout(30000)});
    const raw=await response.text();let data;
    try{data=JSON.parse(raw);}catch(_){throw new Error(`服务未返回有效数据（HTTP ${response.status}），请检查当前后端版本。`);}
    if(!response.ok||data.status!=='success')throw new Error(data.message||'自我进化服务异常');return data;
}

async function testChatModel(button) {
    const box = document.getElementById('chat-model-probe');
    const en = currentLang === 'en';
    const labels = {
        ok: ['模型已返回有效回复，可以使用。', 'Valid model reply received.'],
        codex_login_required: ['当前选择的是 OpenAI Codex，需要单独登录。已配置 API 密钥请改选 OpenAI 并保存；两种认证不通用。', 'Codex requires a separate login. To use your API key, select OpenAI and save.'],
        missing_model: ['请先选择模型。', 'Select a model first.'],
        missing_provider: ['请选择已配置的厂商。', 'Select a configured provider.'],
        missing_key: ['该厂商尚未保存 API 密钥，请先配置并保存。', 'Save this provider’s API key first.'],
        unsupported_protocol: ['该厂商的专用协议暂未接入检测，不能据此判定模型不可用。', 'This provider’s protocol is not yet supported by this test.'],
        invalid_url: ['厂商接口地址格式不正确。', 'Invalid provider URL.'],
        authentication_failed: ['认证失败，请检查该厂商的密钥或登录状态。', 'Authentication failed. Check credentials.'],
        permission_denied: ['无访问权限，请检查模型授权。', 'Permission denied. Check model access.'],
        model_or_endpoint_missing: ['模型或接口不存在，请检查模型名称和接口地址。', 'Model or endpoint not found.'],
        quota_or_rate_limit: ['额度不足或请求限流，请检查账户额度后重试。', 'Quota exhausted or rate limited.'],
        invalid_request: ['检测方式或模型参数不被接口接受，请核对模型名称、接口地址和该模型是否支持当前账户。', 'The test request was rejected. Check the model name, endpoint, and account access.'],
        tls_error: ['证书校验失败，请检查网络代理和证书；未跳过安全校验。', 'TLS verification failed. Check proxy and certificates.'],
        timeout: ['检测超时，暂不能确认模型是否可用。', 'Test timed out; availability is unconfirmed.'],
        connection_error: ['无法连接厂商，请检查网络或代理。', 'Cannot connect. Check network/proxy.'],
        empty_reply: ['接口已响应，但未返回文字，尚未通过检测。', 'Endpoint responded without text; test not passed.'],
        upstream_error: ['厂商返回异常，请稍后重试。', 'Provider error. Try again later.'],
        invalid_response: ['检测响应异常，暂不能确认可用性。', 'Invalid response; availability unconfirmed.']
    };
    button.disabled = true;
    box.style.color = '#2563eb';
    box.textContent = en ? 'Testing with one short message (may incur a small API charge)…' : '正在发送一条简短测试消息（可能产生少量 API 费用），不发送会话或个人数据…';
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 30000);
    try {
        const def = MODELS_CAPABILITY_DEFS.find(d => d.id === 'chat');
        const provider = getDropdownValue(document.getElementById('cap-chat-provider'));
        const model = getCapabilityModelValue(def);
        const response = await fetch('/api/models', {method: 'POST', headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({action: 'test_model', provider_id: provider, model}), signal: controller.signal});
        if (!response.ok) throw new Error('http');
        const data = await response.json();
        box.style.color = data.available ? '#16a34a' : '#ea580c';
        box.textContent = (labels[data.code] || labels.invalid_response)[en ? 1 : 0] +
            (data.elapsed_ms !== undefined ? ` (${(data.elapsed_ms / 1000).toFixed(1)}s)` : '') +
            (en ? ' Test only; settings unchanged.' : ' 仅检测，未修改配置。');
    } catch (error) {
        box.style.color = '#dc2626';
        box.textContent = error.name === 'AbortError' ? labels.timeout[en ? 1 : 0] :
            (en ? 'Cannot reach the test endpoint. Check the service and refresh the page.' : '检测接口不可达，请检查服务并刷新页面；这不代表模型认证失败。');
    } finally { clearTimeout(timer); button.disabled = false; }
}
let harnessEvolutionLoading=false,harnessEvolutionActionRunning=false;
function renderHarnessEvolution(data){
    const panel=document.getElementById('agent2-harness-panel');if(!panel)return;
    const e=value=>escapeHtml(String(value??'')), empty='<p class="text-sm text-slate-400">暂无记录</p>';
    const section=(title,body)=>`<details class="rounded-xl border p-4 bg-white dark:bg-[#202020]"><summary class="cursor-pointer font-semibold text-sm">${title}</summary><div class="mt-3 space-y-3">${body||empty}</div></details>`;
    const row=body=>`<article class="rounded-lg border p-3 text-xs leading-6 break-words">${body}</article>`;
    const field=(label,value)=>`<div><span class="text-slate-400">${label}：</span>${e(Array.isArray(value)?value.join('、'):value||'暂无证据')}</div>`;
    const flag=value=>value===true?'已确认':value===false?'未成功':'暂无证据';
    panel.innerHTML=`<div class="text-xs text-slate-500">统计基于已有运行记录与工具审计。诊断为待验证判断；改进草稿审批后再应用。每日扫描随 Agent 2.0 后台运行。</div>`+
        `<div class="flex flex-wrap gap-4 text-sm">${[['组件',data.summary?.components],['最近执行',data.summary?.traces],['待诊断',data.summary?.diagnostics],['版本',data.summary?.snapshots],['训练用例',data.summary?.training_cases],['训练均分',data.summary?.training_avg_score],['知识归档',data.summary?.knowledge_archived]].map(([k,v])=>`<span>${k} <b>${e(v||0)}</b></span>`).join('')}</div>`+
        renderKnowledgeArchiveStatus(data.knowledge_archive||{})+
        renderAgentTrainingLab(data.training_lab||{})+
        section('能力组件', (data.components||[]).map(x=>row(`<b>${e(x.name)}</b> <span class="text-slate-400">${e(x.type)}</span>${field('状态',x.enabled===null?'待检测':x.enabled?'启用':'未启用')}${field('使用次数',x.usage_count??'暂无数据')}${field('成功率',x.success_rate==null?'暂无数据':x.success_rate+'%')}${field('最近失败',x.last_failure||'暂无')}${field('历史版本',x.version_count||'暂无')}`)).join(''))+
        section('执行 Trace · 最近20条',(data.traces||[]).map(x=>row(`<b>${e(x.user_request)}</b>${field('时间',x.created_at)}${field('结果',x.agent_decision)}${field('工具',x.tools)}${field(x.sources_label||'来源',x.sources)}${field('失败步骤',x.failed_step||'未记录失败')}${field('恢复',x.fallback)}${field('交付状态',`产物：${flag(x.artifact_written)}；通知接口：${flag(x.notification_written)}；微信接口：${flag(x.weixin_written)}；设备确认收到：${flag(x.device_received)}`)}${field('运行编号',x.id)}${field('原始请求编号',x.source_id)}${x.session_id?field('来源会话',x.session_id):''}<details class="mt-2"><summary class="cursor-pointer text-blue-600">查看执行步骤（${(x.stages||[]).length}）</summary><ol class="border-l pl-4 mt-2 space-y-2">${(x.stages||[]).map(s=>`<li><b>${e(s.name)}</b> · ${e(s.status)}${field('时间',s.at)}${field('说明',s.message)}${s.duration_seconds!=null?field('用时',s.duration_seconds+' 秒'):''}</li>`).join('')||empty}</ol></details>`)).join(''))+
        section('失败诊断 · 最近20条',(data.diagnostics||[]).map(x=>row(`<b>${e(x.phenomenon)}</b>${field('可能原因（待验证）',x.root_cause)}${field('证据',x.evidence)}${field('建议',x.fix)}${field('恢复路径',x.next_path)}${field('自动修复',x.auto_fixable?'存在候选恢复方案，需检查任务授权':'需核查')}`)).join(''))+
        section('自我优化建议',(data.suggestions||[]).map(x=>row(`<b>${e(x.title)}</b>${field('类型',x.kind)}${field('证据',x.failure_evidence)}${field('拟议修改',x.targeted_fix)}${field('预期影响',x.predicted_impact)}<button type="button" class="text-blue-600 underline" data-harness-proposal="${e(x.id)}">生成待审改进草稿</button>`)).join(''))+
        section('待细化改进草稿',(data.proposals||[]).map(x=>row(`<b>${e(x.title)}</b>${field('证据',x.reason)}${field('建议修改',x.change)}${field('状态',x.status)}`)).join(''))+
        section('任务规则版本 · 最近30条',(data.task_versions||[]).map(x=>row(`<b>${e(x.task_name)}</b>${field('任务类型',x.kind==='scheduler'?'普通定时任务':'自动化任务')}${field('时间',x.created_at)}${field('记录',x.reason)}${field('变更字段',x.changed_fields)}<button type="button" class="text-blue-600 underline" data-harness-task-rollback="${e(x.id)}">恢复本次修改前的配置</button>`)).join(''))+
        section('配置版本与回滚',(data.snapshots||[]).map(x=>row(`<b>${e(x.label)}</b>${field('时间',x.created_at)}${field('覆盖配置',x.files)}<button type="button" class="text-blue-600 underline" data-harness-rollback="${e(x.id)}">回滚到此版本</button>`)).join(''));
    panel.querySelectorAll('[data-harness-rollback]').forEach(button=>button.addEventListener('click',()=>rollbackHarnessSnapshot(button.dataset.harnessRollback)));
    panel.querySelectorAll('[data-harness-proposal]').forEach(button=>button.addEventListener('click',()=>runHarnessAction('propose',{id:button.dataset.harnessProposal})));
    panel.querySelectorAll('[data-harness-task-rollback]').forEach(button=>button.addEventListener('click',()=>{if(confirm('恢复此任务修改前的配置？包括执行时间、启用状态和发送目标。当前配置将先备份，运行记录和其他任务不变。'))runHarnessAction('rollback_task_version',{id:button.dataset.harnessTaskRollback});}));
}
function renderKnowledgeArchiveStatus(data={}){
    const e=value=>escapeHtml(String(value??'')), daily=data.last_daily||{}, weekly=data.last_weekly||{}, monthly=data.last_monthly||{}, yearly=data.last_yearly||{}, settings=data.settings||{};
    return `<section class="rounded-2xl border border-emerald-100 dark:border-emerald-500/20 bg-emerald-50/60 dark:bg-emerald-500/5 p-4">
        <div class="flex flex-wrap items-start justify-between gap-3">
            <div><h3 class="font-semibold"><i class="fas fa-book-open text-emerald-500 mr-2"></i>知识库自动归档</h3><p class="text-xs text-slate-400 mt-1">每天 ${e(settings.run_time||'18:00')} 自动把会话、产物/交付物、定时任务结果按问题/知识/学习/进化分类总结，目录按 年/月/归档文件 自动创建。</p></div>
            <div class="flex flex-wrap gap-2"><button onclick="runHarnessAction('knowledge_archive_day',{force:true},this)" class="px-3 py-2 rounded-lg bg-emerald-600 text-white text-xs"><i class="fas fa-calendar-day mr-1"></i>归档今天</button><button onclick="runHarnessAction('knowledge_archive_week',{force:true},this)" class="px-3 py-2 rounded-lg border border-emerald-200 dark:border-emerald-500/20 text-xs"><i class="fas fa-calendar-week mr-1"></i>归档本周</button><button onclick="runHarnessAction('knowledge_archive_month',{force:true},this)" class="px-3 py-2 rounded-lg border border-emerald-200 dark:border-emerald-500/20 text-xs"><i class="fas fa-calendar-days mr-1"></i>归档本月</button><button onclick="runHarnessAction('knowledge_archive_year',{force:true},this)" class="px-3 py-2 rounded-lg border border-emerald-200 dark:border-emerald-500/20 text-xs"><i class="fas fa-calendar mr-1"></i>归档今年</button></div>
        </div>
        <div class="mt-3 grid md:grid-cols-5 gap-2 text-xs">
            <div class="rounded-xl bg-white/80 dark:bg-black/10 px-3 py-2"><span class="text-slate-400">知识库目录</span><b class="ml-2">${e(data.knowledge_dir||'未创建')}</b></div>
            <div class="rounded-xl bg-white/80 dark:bg-black/10 px-3 py-2"><span class="text-slate-400">今日归档</span><b class="ml-2">${daily.knowledge_path?'已生成':'待生成'}</b></div>
            <div class="rounded-xl bg-white/80 dark:bg-black/10 px-3 py-2"><span class="text-slate-400">本周归档</span><b class="ml-2">${weekly.knowledge_path?'已生成':'待生成'}</b></div>
            <div class="rounded-xl bg-white/80 dark:bg-black/10 px-3 py-2"><span class="text-slate-400">年度归档</span><b class="ml-2">${yearly.knowledge_path?'已生成':'待生成'}</b></div>
            <div class="rounded-xl bg-white/80 dark:bg-black/10 px-3 py-2"><span class="text-slate-400">最近运行</span><b class="ml-2">${e(String(data.last_run_at||'暂无').replace('T',' ').slice(0,19))}</b></div>
        </div>
    </section>`;
}
function renderAgentTrainingLab(lab={}){
    const e=value=>escapeHtml(String(value??'')), summary=lab.summary||{}, cases=lab.cases||[], ranking=lab.ranking||[], samples=lab.failure_samples||[], runs=lab.recent_runs||[], lastIngest=lab.last_ingest||{};
    const scoreTone=score=>Number(score||0)>=75?'emerald':Number(score||0)>=55?'amber':'red';
    const caseCard=x=>`<article class="rounded-xl border border-violet-100 dark:border-violet-500/20 bg-white dark:bg-[#202020] p-4">
        <div class="flex flex-wrap items-start justify-between gap-3"><div><h4 class="font-semibold text-sm">${e(x.name)}</h4><p class="mt-1 text-[11px] text-slate-400">${e(x.agent)} · ${e(x.scenario)}</p></div><span class="rounded-full bg-violet-50 dark:bg-violet-500/10 px-2 py-0.5 text-[11px] text-violet-600">${x.enabled===false?'停用':'启用'}</span></div>
        <p class="mt-3 text-xs text-slate-500 leading-5">${e(x.input)}</p>
        <p class="mt-2 text-[11px] text-slate-400">预期：${e(x.expected)}</p>
        <div class="mt-3 flex flex-wrap gap-2"><button onclick="runHarnessAction('training_run_case',{id:'${e(x.id)}'},this)" class="px-3 py-1.5 rounded-lg bg-violet-600 text-white text-xs"><i class="fas fa-play mr-1"></i>执行评测</button></div>
    </article>`;
    const rankCard=x=>{const tone=scoreTone(x.score);return `<article class="rounded-xl border p-4 bg-white dark:bg-[#202020]"><div class="flex items-center justify-between gap-3"><b class="text-sm">${e(x.agent)}</b><span class="rounded-full bg-${tone}-50 dark:bg-${tone}-500/10 px-2 py-0.5 text-[11px] text-${tone}-600">${e(x.score)}分</span></div><div class="mt-3 text-xs text-slate-500">成功率 ${e(x.success_rate)}% · 通过 ${e(x.passed)}/${e(x.total)} · 失败 ${e(x.failed)}</div><p class="mt-2 text-[11px] text-slate-400">常见问题：${e(x.most_common_failure)}</p></article>`;};
    const runRow=x=>{const tone=scoreTone(x.score);return `<article class="rounded-lg border p-3 text-xs"><div class="flex flex-wrap items-center justify-between gap-2"><b>${e(x.case_name)}</b><span class="rounded-full bg-${tone}-50 dark:bg-${tone}-500/10 px-2 py-0.5 text-${tone}-600">${e(x.score)}分 · ${e(x.status)}</span></div><p class="mt-2 text-slate-500">${e(x.diagnosis)}</p><p class="mt-1 text-slate-400">失败维度：${e((x.failed_dimensions||[]).join('、')||'暂无')}</p></article>`;};
    const sampleRow=x=>`<article class="rounded-lg border border-orange-100 dark:border-orange-500/20 bg-orange-50/50 dark:bg-orange-500/5 p-3 text-xs"><b>${e(x.agent)} · ${e(x.scenario)}</b><p class="mt-2 text-slate-600 dark:text-slate-300">输入：${e(x.user_input)}</p><p class="mt-1 text-orange-700 dark:text-orange-300">错误：${e(x.bad_output)}</p><p class="mt-1 text-emerald-700 dark:text-emerald-300">期望：${e(x.expected_output)}</p><p class="mt-1 text-slate-400">建议：${e(x.patch_hint)}</p></article>`;
    return `<section class="rounded-2xl border border-violet-100 dark:border-violet-500/20 bg-violet-50/60 dark:bg-violet-500/5 p-5">
        <div class="flex flex-wrap items-start justify-between gap-3">
            <div><h3 class="font-semibold"><i class="fas fa-dumbbell text-violet-500 mr-2"></i>Agent 训练场</h3><p class="text-xs text-slate-400 mt-1">自动吸收会话、产物、定时任务和自动化运行，沉淀为测试集、失败样本和能力排行榜。当前为安全模拟评测，不会真实发送微信/企微消息。</p></div>
            <div class="flex flex-wrap gap-2"><button onclick="runHarnessAction('training_auto_ingest',{},this)" class="px-3 py-2 rounded-lg bg-white dark:bg-[#202020] border border-violet-200 dark:border-violet-500/20 text-xs"><i class="fas fa-wand-magic-sparkles mr-1"></i>自动吸收训练数据</button><button onclick="runHarnessAction('training_auto_cycle',{},this)" class="px-3 py-2 rounded-lg bg-violet-600 text-white text-xs"><i class="fas fa-play mr-1"></i>吸收并回放</button><button onclick="runHarnessAction('training_run_suite',{},this)" class="px-3 py-2 rounded-lg border border-violet-200 dark:border-violet-500/20 text-xs"><i class="fas fa-rotate mr-1"></i>只回放</button><button onclick="runHarnessAction('training_reset_defaults',{},this)" class="px-3 py-2 rounded-lg border border-violet-200 dark:border-violet-500/20 text-xs"><i class="fas fa-rotate-left mr-1"></i>恢复默认测试集</button></div>
        </div>
        <div class="mt-4 grid md:grid-cols-6 gap-2 text-xs">
            ${[['测试用例',summary.cases],['已启用',summary.enabled_cases],['评测次数',summary.runs],['失败样本',summary.failure_samples],['平均分',summary.avg_score],['已吸收来源',summary.ingested_sources]].map(([k,v])=>`<div class="rounded-xl bg-white/80 dark:bg-black/10 px-3 py-2"><span class="text-slate-400">${k}</span><b class="ml-2">${e(v||0)}</b></div>`).join('')}
        </div>
        <div class="mt-3 rounded-xl bg-white/70 dark:bg-black/10 px-3 py-2 text-xs text-slate-500">最近自动吸收：${lastIngest.created_at?e(String(lastIngest.created_at).replace('T',' ').slice(0,19)):'尚未执行'} · 新增用例 ${e(summary.last_ingest_new_cases||0)} · 新增失败样本 ${e(summary.last_ingest_failure_samples||0)}。需要真实发送、改配置、补发通知时会进入审批。</div>
        <details open class="mt-4"><summary class="cursor-pointer text-sm font-semibold">真实任务测试集</summary><div class="mt-3 grid md:grid-cols-2 xl:grid-cols-3 gap-3">${cases.map(caseCard).join('')||'<p class="text-sm text-slate-400">暂无测试用例</p>'}</div></details>
        <details class="mt-4"><summary class="cursor-pointer text-sm font-semibold">Agent 能力排行榜</summary><div class="mt-3 grid md:grid-cols-2 xl:grid-cols-3 gap-3">${ranking.map(rankCard).join('')||'<p class="text-sm text-slate-400">完成一次回放后生成排行榜</p>'}</div></details>
        <details class="mt-4"><summary class="cursor-pointer text-sm font-semibold">最近评测结果</summary><div class="mt-3 grid gap-2">${runs.map(runRow).join('')||'<p class="text-sm text-slate-400">暂无评测结果</p>'}</div></details>
        <details class="mt-4"><summary class="cursor-pointer text-sm font-semibold">失败样本库</summary><div class="mt-3 grid gap-2">${samples.map(sampleRow).join('')||'<p class="text-sm text-slate-400">暂无失败样本</p>'}</div></details>
    </section>`;
}
async function loadHarnessEvolution(force=false){
    const panel=document.getElementById('agent2-harness-panel');if(!panel||harnessEvolutionLoading)return;
    if(force)panel.innerHTML='<div class="rounded-xl border border-sky-100 dark:border-sky-500/20 bg-sky-50 dark:bg-sky-500/10 p-4 text-sm text-sky-700 dark:text-sky-300"><i class="fas fa-spinner fa-spin mr-2"></i>正在刷新 Harness 观测数据…</div>';
    harnessEvolutionLoading=true;panel.setAttribute('aria-busy','true');
    try{renderHarnessEvolution(await harnessEvolutionRequest());}
    catch(error){panel.innerHTML=`<p class="text-red-600 text-sm" role="alert">加载失败：${escapeHtml(error.message)}</p>`;}
    finally{harnessEvolutionLoading=false;panel.removeAttribute('aria-busy');}
}
async function runHarnessAction(action,extra={},button=null){
    if(harnessEvolutionActionRunning)return;
    harnessEvolutionActionRunning=true;
    const status=document.getElementById('harness-action-status');
    const buttons=[...new Set([button,document.getElementById('harness-review-button')].filter(Boolean))];
    buttons.forEach(btn=>{btn.disabled=true;btn.dataset.oldHtml=btn.innerHTML;btn.innerHTML='<i class="fas fa-spinner fa-spin mr-1"></i>处理中…';});
    if(status){status.className='text-xs text-blue-600';status.textContent=action==='review'?'正在扫描失败记录并生成诊断报告…':'正在处理…';}
    try{
        const data=await harnessEvolutionRequest({method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,...extra})});
        await loadHarnessEvolution(true);
        if(status){status.className='text-xs text-emerald-600';status.textContent=data.message||'操作完成';}
        if(window._wsToast)window._wsToast(data.message||'操作完成');
    }
    catch(error){if(status){status.className='text-xs text-red-600';status.textContent='操作失败：'+error.message;}}
    finally{
        buttons.forEach(btn=>{btn.disabled=false;btn.innerHTML=btn.dataset.oldHtml||'立即扫描失败并生成建议';delete btn.dataset.oldHtml;});
        harnessEvolutionActionRunning=false;
    }
}
async function createHarnessSnapshot(){return runHarnessAction('create_snapshot');}
async function rollbackHarnessSnapshot(id){if(!confirm('回滚将恢复所列配置，当前配置会先自动备份。是否继续？'))return;return runHarnessAction('rollback_snapshot',{id});}
async function loadAgent2ApprovalTargets(selected){const box=document.getElementById('agent2-approval-targets');if(!box)return;try{const response=await fetch('/api/scheduler/targets'),data=await response.json();if(data.status!=='success')throw new Error(data.message||'读取通道失败');const selectedKeys=new Set((selected||[]).map(x=>`${x.channel}|${x.receiver}`));const targets=(data.targets||[]).filter(x=>x.channel&&x.channel!=='web'&&x.channel!=='webhook'&&x.receiver);box.innerHTML='<div class="rounded-lg bg-slate-50 dark:bg-white/5 px-3 py-2"><i class="fas fa-display mr-2"></i>应用内审批中心（始终启用）</div>'+(targets.length?targets.map((x,i)=>`<label class="flex items-center gap-2 rounded-lg border px-3 py-2"><input class="agent2-approval-target" type="checkbox" data-index="${i}" ${selectedKeys.has(`${x.channel}|${x.receiver}`)?'checked':''}><span>${escapeHtml(x.channel_label||x.channel)}${x.receiver_name?' · '+escapeHtml(x.receiver_name):''}</span></label>`).join(''):'<p class="text-xs text-slate-400">暂无可用消息通道，请先在设置 → 通道中配置邮箱、微信或企业微信。</p>');box._targets=targets;}catch(error){box.innerHTML=`<p class="text-xs text-amber-600">${escapeHtml(error.message)}</p>`;}}
function collectAgent2ApprovalTargets(){const box=document.getElementById('agent2-approval-targets'),targets=box?._targets||[];return [...document.querySelectorAll('.agent2-approval-target:checked')].map(input=>{const x=targets[Number(input.dataset.index)];return {type:'channel',channel:x.channel,receiver:x.receiver,receiver_name:x.receiver_name||''};}).filter(x=>x.channel&&x.receiver);}
let agent2ShowAllErrors=false,agent2ShowAllEvents=false,agent2LastDashboard=null;
function renderAgent2RuntimeEvidence(cards){document.querySelectorAll('#agent2-capabilities article').forEach((article,index)=>{const x=(cards||[])[index];if(!x)return;const row=article.querySelector('select')?.parentElement,status=row?.querySelector('span');if(status)status.textContent=x.state==='active'?'已生效 · 运行中':x.state==='disabled'?'已停用':'待触发';article.querySelector('.agent2-inline-evidence')?.remove();const evidence=document.createElement('p');evidence.className='agent2-inline-evidence text-[11px] text-slate-400 mt-2';evidence.textContent=x.evidence+(x.last_activity?` · 最近活动 ${x.last_activity}`:'');row?.before(evidence);});}
function renderAgent2HomeLearning(data={}){const host=document.getElementById('agent2-home-learning');if(!host)return;const learning=data.home_learning||{},items=learning.top||[],stats=learning.stats||{};const allTargets=[...new Set([...items.map(x=>x.target),...Object.keys(stats||{})])];if(!allTargets.length){host.innerHTML='<div class="rounded-xl border border-dashed border-slate-200 dark:border-white/10 p-8 text-center text-sm text-slate-400">还没有推荐学习数据。后续你点击、置顶、关闭首页建议，或执行相关任务后，这里会自动更新。</div>';return;}const cards=allTargets.map(target=>{const top=items.find(x=>x.target===target)||{},s=stats[target]||{},label=top.label||target,score=Number(top.score||0),success=Number(s.outcome_success||0),empty=Number(s.outcome_empty||0),failed=Number(s.outcome_failed||0),notify=Number(s.outcome_notification_warning||0),opens=Number(s.opens||0),pins=Number(s.pins||0),dismisses=Number(s.dismisses||0),dislikes=Number(s.dislikes||0),total=success+empty+failed+notify,rate=total?Math.round(success/total*100):0,tone=score>=8?'emerald':score>=1?'blue':'orange',advice=score>=8?'优先推荐':score>=1?'继续观察':'已降权';return `<article class="rounded-xl border border-slate-200 dark:border-white/10 bg-slate-50/70 dark:bg-white/5 p-4"><div class="flex flex-wrap items-start justify-between gap-3"><div><h4 class="font-semibold text-sm">${escapeHtml(label)}</h4><p class="text-[11px] text-slate-400 mt-1">最后动作：${escapeHtml(s.last_action||s.last_outcome||'暂无')} ${s.last_at?`· ${escapeHtml(String(s.last_at).replace('T',' ').slice(0,19))}`:''}</p></div><span class="rounded-full bg-${tone}-50 dark:bg-${tone}-500/10 px-2 py-0.5 text-[11px] text-${tone}-600">${advice} · ${score}</span></div><div class="mt-3 grid grid-cols-4 gap-2 text-center text-[11px]"><div class="rounded-lg bg-white/70 dark:bg-black/10 p-2"><b class="block text-slate-700 dark:text-slate-100">${opens}</b><span class="text-slate-400">点击</span></div><div class="rounded-lg bg-white/70 dark:bg-black/10 p-2"><b class="block text-amber-500">${pins}</b><span class="text-slate-400">置顶</span></div><div class="rounded-lg bg-white/70 dark:bg-black/10 p-2"><b class="block text-emerald-500">${success}</b><span class="text-slate-400">成功</span></div><div class="rounded-lg bg-white/70 dark:bg-black/10 p-2"><b class="block text-red-500">${failed}</b><span class="text-slate-400">失败</span></div></div><div class="mt-3 flex items-center gap-3 text-xs"><div class="flex-1 h-2 rounded-full bg-slate-200 dark:bg-white/10 overflow-hidden"><div class="${rate>=60?'bg-emerald-500':rate>0?'bg-blue-500':'bg-orange-400'} h-full" style="width:${Math.max(total?6:0,Math.min(100,rate))}%"></div></div><span class="text-slate-500">成功率 ${rate}%</span></div><p class="mt-2 text-[11px] text-slate-400">空结果 ${empty} · 通知异常 ${notify} · 关闭/不感兴趣 ${dismisses+dislikes}</p>${s.last_task_name?`<p class="mt-1 text-[11px] text-slate-400">最近关联任务：${escapeHtml(s.last_task_name)}</p>`:''}</article>`;}).join('');host.innerHTML=`<div class="grid md:grid-cols-4 gap-2 mb-4 text-xs"><div class="rounded-xl bg-emerald-50 dark:bg-emerald-500/10 px-3 py-2"><span class="text-slate-400">已学习建议</span><b class="ml-2 text-emerald-600">${allTargets.length}</b></div><div class="rounded-xl bg-blue-50 dark:bg-blue-500/10 px-3 py-2"><span class="text-slate-400">优先推荐</span><b class="ml-2 text-blue-600">${items.filter(x=>Number(x.score||0)>=8).length}</b></div><div class="rounded-xl bg-orange-50 dark:bg-orange-500/10 px-3 py-2"><span class="text-slate-400">观察/降权</span><b class="ml-2 text-orange-600">${allTargets.length-items.filter(x=>Number(x.score||0)>=8).length}</b></div><div class="rounded-xl bg-slate-50 dark:bg-white/5 px-3 py-2 truncate"><span class="text-slate-400">学习摘要</span><b class="ml-2">${escapeHtml(learning.summary||'持续学习中')}</b></div></div><div class="grid md:grid-cols-2 xl:grid-cols-3 gap-3">${cards}</div>`;}
function renderAgent2WeixinLearning(data={}){const host=document.getElementById('agent2-weixin-learning'),summary=document.getElementById('agent2-weixin-learning-summary');if(!host)return;const items=data.weixin_failure_patterns||data.weixin_failure_learning||[];const labelMap={model_auth:'模型认证失败',email_config:'邮箱配置缺失',empty_result:'搜索/任务空结果',file_not_found:'本地文件未找到',permission:'权限不足',network:'网络异常',browser_env:'浏览器环境不可用',empty_reply:'空回复',send_failure:'微信发送失败',worker_failure:'执行中断',general:'普通失败'};const iconMap={model_auth:'fa-key',email_config:'fa-envelope',empty_result:'fa-magnifying-glass-minus',file_not_found:'fa-folder-open',permission:'fa-shield-halved',network:'fa-wifi',browser_env:'fa-window-maximize',empty_reply:'fa-comment-slash',send_failure:'fa-paper-plane',worker_failure:'fa-triangle-exclamation',general:'fa-circle-question'};if(summary)summary.textContent=items.length?`已识别 ${items.length} 类，优先处理 ${escapeHtml(labelMap[items[0].category]||items[0].category||'失败')}`:'等待微信端失败样本';if(!items.length){host.innerHTML='<div class="md:col-span-2 xl:col-span-3 rounded-xl border border-dashed border-emerald-200 dark:border-emerald-500/20 p-8 text-center text-sm text-slate-400">还没有微信失败学习数据。后续出现空回复、邮箱未配置、模型认证失败或搜索无结果时，会自动沉淀在这里。</div>';return;}host.innerHTML=items.slice(0,9).map(item=>{const count=Number(item.count||0),category=item.category||'general',tone=count>=3?'orange':'emerald',routes=item.routes?Object.entries(item.routes).map(([k,v])=>`${k} ${v}`).join(' / '):'';return `<article class="rounded-xl border border-emerald-100 dark:border-emerald-500/20 bg-white dark:bg-[#202020] p-4"><div class="flex items-start justify-between gap-3"><div class="flex items-center gap-2 min-w-0"><span class="w-9 h-9 rounded-xl bg-emerald-50 dark:bg-emerald-500/10 text-emerald-500 flex items-center justify-center"><i class="fas ${iconMap[category]||iconMap.general}"></i></span><div class="min-w-0"><h4 class="font-semibold text-sm truncate">${escapeHtml(labelMap[category]||category)}</h4><p class="text-[11px] text-slate-400 mt-0.5">${escapeHtml(String(item.last_seen||'').replace('T',' ').slice(0,19)||'暂无时间')}</p></div></div><span class="rounded-full bg-${tone}-50 dark:bg-${tone}-500/10 px-2 py-0.5 text-[11px] text-${tone}-600">${count} 次</span></div><p class="mt-3 text-xs text-slate-500 leading-5">${escapeHtml(item.lesson||'已记录为微信端失败经验。')}</p><div class="mt-3 rounded-lg bg-emerald-50/70 dark:bg-emerald-500/10 p-3 text-xs text-emerald-700 dark:text-emerald-300"><b>下次自救：</b>${escapeHtml(item.recommended_action||'先尝试确定性工具，失败后再说明原因')}</div>${routes?`<p class="mt-2 text-[11px] text-slate-400">路径：${escapeHtml(routes)}</p>`:''}</article>`;}).join('');}
function renderAgent2WeixinLearning(data={}){
    const host=document.getElementById('agent2-weixin-learning'),summary=document.getElementById('agent2-weixin-learning-summary');
    if(!host)return;
    const items=data.weixin_failure_patterns||data.weixin_failure_learning||[];
    const labelMap={model_auth:'模型认证失败',email_config:'邮箱配置缺失',empty_result:'搜索/任务空结果',file_not_found:'本地文件未找到',permission:'权限不足',network:'网络异常',browser_env:'浏览器环境不可用',empty_reply:'空回复',send_failure:'微信发送失败',worker_failure:'执行中断',general:'普通失败'};
    const iconMap={model_auth:'fa-key',email_config:'fa-envelope',empty_result:'fa-magnifying-glass-minus',file_not_found:'fa-folder-open',permission:'fa-shield-halved',network:'fa-wifi',browser_env:'fa-window-maximize',empty_reply:'fa-comment-slash',send_failure:'fa-paper-plane',worker_failure:'fa-triangle-exclamation',general:'fa-circle-question'};
    const routeLabel={weixin_send:'微信发送',send:'发送通道',news_task_first:'资讯任务',email_task_first:'邮件任务',file_fast_path:'文件快查',model:'模型回复'};
    const formatTime=value=>escapeHtml(String(value||'').replace('T',' ').slice(0,19)||'暂无时间');
    const compact=value=>escapeHtml(String(value||'').replace(/\s+/g,' ').trim().slice(0,220));
    if(summary)summary.textContent=items.length?`已识别 ${items.length} 类，优先处理 ${labelMap[items[0].category]||items[0].category||'失败'}`:'等待微信端失败样本';
    if(!items.length){
        host.innerHTML='<div class="md:col-span-2 xl:col-span-3 rounded-xl border border-dashed border-emerald-200 dark:border-emerald-500/20 p-8 text-center text-sm text-slate-400">还没有微信失败学习数据。后续出现空回复、邮箱未配置、模型认证失败或搜索无结果时，会自动沉淀在这里。</div>';
        return;
    }
    host.innerHTML=items.slice(0,9).map(item=>{
        const count=Number(item.count||0),category=item.category||'general',tone=count>=3?'orange':'emerald';
        const examples=(item.examples&&item.examples.length?item.examples:[{command:item.latest_command||'',message:item.latest_message||'',route:item.latest_route||'',at:item.last_seen||''}]).filter(x=>x.command||x.message||x.route||x.at).slice(0,5);
        const routes=item.routes?Object.entries(item.routes).map(([k,v])=>`${routeLabel[k]||k} ${v}次`).join(' / '):'';
        const lastMessage=item.latest_message||(examples[0]&&examples[0].message)||'';
        const lastCommand=item.latest_command||(examples[0]&&examples[0].command)||'';
        return `<article class="rounded-xl border border-emerald-100 dark:border-emerald-500/20 bg-white dark:bg-[#202020] p-4">
            <div class="flex items-start justify-between gap-3">
                <div class="flex items-center gap-2 min-w-0">
                    <span class="w-9 h-9 rounded-xl bg-emerald-50 dark:bg-emerald-500/10 text-emerald-500 flex items-center justify-center"><i class="fas ${iconMap[category]||iconMap.general}"></i></span>
                    <div class="min-w-0">
                        <h4 class="font-semibold text-sm truncate">${escapeHtml(labelMap[category]||category)}</h4>
                        <p class="text-[11px] text-slate-400 mt-0.5">最近：${formatTime(item.last_seen)}</p>
                    </div>
                </div>
                <span class="rounded-full bg-${tone}-50 dark:bg-${tone}-500/10 px-2 py-0.5 text-[11px] text-${tone}-600">${count} 次</span>
            </div>
            <p class="mt-3 text-xs text-slate-500 leading-5">${escapeHtml(item.lesson||'已记录为微信端失败经验。')}</p>
            <div class="mt-3 rounded-lg bg-emerald-50/70 dark:bg-emerald-500/10 p-3 text-xs text-emerald-700 dark:text-emerald-300"><b>下次自救：</b>${escapeHtml(item.recommended_action||'先尝试确定性工具，失败后给出最短原因和可重试方式')}</div>
            <div class="mt-3 grid grid-cols-1 gap-2 text-[11px] text-slate-500">
                ${routes?`<div class="rounded-lg bg-slate-50 dark:bg-white/5 p-2"><b>失败路径：</b>${escapeHtml(routes)}</div>`:''}
                ${lastMessage?`<div class="rounded-lg bg-slate-50 dark:bg-white/5 p-2"><b>最近原因：</b>${compact(lastMessage)}</div>`:''}
                ${lastCommand?`<div class="rounded-lg bg-slate-50 dark:bg-white/5 p-2"><b>最近内容：</b>${compact(lastCommand)}</div>`:''}
            </div>
            <details class="mt-3 rounded-lg border border-slate-100 dark:border-white/10 bg-slate-50/60 dark:bg-white/5">
                <summary class="cursor-pointer px-3 py-2 text-xs text-primary-500 select-none">查看详情</summary>
                <div class="px-3 pb-3 space-y-2">
                    ${examples.length?examples.map((sample,index)=>`<div class="rounded-lg bg-white dark:bg-black/10 p-3 text-[11px] leading-5">
                        <div class="flex flex-wrap items-center justify-between gap-2 text-slate-400"><span>样本 ${index+1} · ${escapeHtml(routeLabel[sample.route]||sample.route||'未知路径')}</span><span>${formatTime(sample.at)}</span></div>
                        ${sample.message?`<p class="mt-1"><b>原因：</b>${compact(sample.message)}</p>`:''}
                        ${sample.command?`<p class="mt-1 text-slate-500"><b>内容：</b>${compact(sample.command)}</p>`:''}
                    </div>`).join(''):'<p class="text-xs text-slate-400">暂无可展开样本，后续失败会自动补充。</p>'}
                </div>
            </details>
        </article>`;
    }).join('');
}
function renderAgent2WeixinSuccessLearning(data={}){const host=document.getElementById('agent2-weixin-success-learning'),summary=document.getElementById('agent2-weixin-success-summary');if(!host)return;const items=data.weixin_success_patterns||data.weixin_success_learning||[];const iconMap={email:'fa-envelope-circle-check',news:'fa-newspaper',file:'fa-folder-tree',send:'fa-paper-plane',general:'fa-route'};if(summary)summary.textContent=items.length?`已记录 ${items.length} 条成功路径`:'等待成功样本';if(!items.length){host.innerHTML='<div class="md:col-span-2 xl:col-span-3 rounded-xl border border-dashed border-blue-200 dark:border-blue-500/20 p-8 text-center text-sm text-slate-400">还没有微信成功路径。后续通过微信成功查邮件、查资讯、找文件或自动兜底成功后，会记录在这里。</div>';return;}host.innerHTML=items.slice(0,9).map(item=>{const type=item.task_type||'general',routes=item.routes?Object.entries(item.routes).map(([k,v])=>`${k} ${v}`).join(' / '):'';return `<article class="rounded-xl border border-blue-100 dark:border-blue-500/20 bg-white dark:bg-[#202020] p-4"><div class="flex items-start justify-between gap-3"><div class="flex items-center gap-2 min-w-0"><span class="w-9 h-9 rounded-xl bg-blue-50 dark:bg-blue-500/10 text-blue-500 flex items-center justify-center"><i class="fas ${iconMap[type]||iconMap.general}"></i></span><div class="min-w-0"><h4 class="font-semibold text-sm truncate">${escapeHtml(item.label||`${type} / ${item.action||'success'}`)}</h4><p class="text-[11px] text-slate-400 mt-0.5">${escapeHtml(String(item.last_seen||'').replace('T',' ').slice(0,19)||'暂无时间')}</p></div></div><span class="rounded-full bg-blue-50 dark:bg-blue-500/10 px-2 py-0.5 text-[11px] text-blue-600">${Number(item.count||0)} 次</span></div><div class="mt-3 rounded-lg bg-blue-50/70 dark:bg-blue-500/10 p-3 text-xs text-blue-700 dark:text-blue-300"><b>下次优先：</b>${escapeHtml(item.action||'复用成功路径')}</div>${routes?`<p class="mt-2 text-[11px] text-slate-400">路径：${escapeHtml(routes)}</p>`:''}</article>`;}).join('');}
function renderAgent2WeixinToolReliability(data={}){const host=document.getElementById('agent2-weixin-tool-reliability'),summary=document.getElementById('agent2-weixin-tool-summary');if(!host)return;const tools=(data.tool_reliability||{}).tools||{};const labelMap={'weixin:email_task_first':'微信查邮件','weixin:news_task_first':'微信查资讯/政策','weixin:file_fast_path':'微信找文件','weixin:file_send':'微信发文件','weixin:mission_control':'微信仪表盘指令'};const iconMap={'weixin:email_task_first':'fa-envelope-circle-check','weixin:news_task_first':'fa-newspaper','weixin:file_fast_path':'fa-folder-tree','weixin:file_send':'fa-paper-plane','weixin:mission_control':'fa-tower-cell'};let rows=Object.entries(tools).filter(([name])=>String(name||'').startsWith('weixin:')).map(([name,item])=>({name,label:labelMap[name]||name.replace('weixin:','微信 '),icon:iconMap[name]||'fa-route',score:Number(item.score||0),success_rate:Number(item.success_rate||0),successes:Number(item.successes||0),total:Number(item.total||0),recent_failures:Number(item.recent_failures||0)}));rows.sort((a,b)=>(b.score-a.score)||(b.total-a.total)||a.label.localeCompare(b.label));if(summary){const total=rows.reduce((n,x)=>n+x.total,0),success=rows.reduce((n,x)=>n+x.successes,0);summary.textContent=rows.length?`已统计 ${rows.length} 条微信工具路径 · 成功 ${success}/${total}`:'等待微信工具执行样本';}if(!rows.length){host.innerHTML='<div class="md:col-span-2 xl:col-span-3 rounded-xl border border-dashed border-cyan-200 dark:border-cyan-500/20 p-8 text-center text-sm text-slate-400">还没有微信工具成功率样本。后续通过微信查邮件、查政策、找文件或发送文件后，会自动统计在这里。</div>';return;}host.innerHTML=rows.slice(0,9).map(item=>{const pct=Math.round(item.success_rate*100),fail=item.recent_failures,tone=fail>=2?'red':pct>=70?'emerald':pct>=45?'blue':'orange',advice=fail>=2?'近期降权':pct>=70?'优先复用':pct>=45?'继续观察':'谨慎使用';const width=Math.max(item.total?6:0,Math.min(100,pct));return `<article class="rounded-xl border border-cyan-100 dark:border-cyan-500/20 bg-white dark:bg-[#202020] p-4"><div class="flex items-start justify-between gap-3"><div class="flex items-center gap-2 min-w-0"><span class="w-9 h-9 rounded-xl bg-${tone}-50 dark:bg-${tone}-500/10 text-${tone}-600 flex items-center justify-center"><i class="fas ${item.icon}"></i></span><div class="min-w-0"><h4 class="font-semibold text-sm truncate">${escapeHtml(item.label)}</h4><p class="text-[11px] text-slate-400 mt-0.5">${escapeHtml(item.name)}</p></div></div><span class="rounded-full bg-${tone}-50 dark:bg-${tone}-500/10 px-2 py-0.5 text-[11px] text-${tone}-600">${advice}</span></div><div class="mt-3 flex items-center gap-3 text-xs"><div class="flex-1 h-2 rounded-full bg-slate-200 dark:bg-white/10 overflow-hidden"><div class="bg-${tone}-500 h-full" style="width:${width}%"></div></div><b class="text-${tone}-600">${pct}%</b></div><div class="mt-3 grid grid-cols-3 gap-2 text-center text-[11px]"><div class="rounded-lg bg-slate-50 dark:bg-white/5 p-2"><b class="block text-emerald-500">${item.successes}</b><span class="text-slate-400">成功</span></div><div class="rounded-lg bg-slate-50 dark:bg-white/5 p-2"><b class="block text-slate-700 dark:text-slate-100">${item.total}</b><span class="text-slate-400">总次数</span></div><div class="rounded-lg bg-slate-50 dark:bg-white/5 p-2"><b class="block text-red-500">${fail}</b><span class="text-slate-400">近期失败</span></div></div><p class="mt-3 text-xs text-slate-500">${fail>=2?'后续路由会降低该路径优先级，优先尝试替代方案。':'后续同类微信任务会根据成功率自动排序。'}</p></article>`;}).join('');}
function renderAgent2RecoveryPaths(data={}){const host=document.getElementById('agent2-recovery-paths'),summary=document.getElementById('agent2-recovery-summary');if(!host)return;const reliability=data.tool_reliability||{},paths=reliability.recovery_paths||[],sum=reliability.summary||{},patterns=data.recovery_patterns||[];if(summary)summary.textContent=`工具 ${sum.successful_calls||0}/${sum.calls||0} 成功 · 自动化恢复 ${patterns.filter(x=>(x.successes||0)>0).length}/${patterns.length} 条有效`;const cards=[];patterns.slice(0,4).forEach(x=>{const rate=Math.round(Number(x.success_rate||0)*100);cards.push(`<div class="rounded-xl bg-slate-50 dark:bg-white/5 px-4 py-3 text-xs"><div class="flex items-center justify-between gap-3"><b>${escapeHtml(x.action||'恢复动作')}</b><span class="rounded-full ${rate>=50?'bg-emerald-50 text-emerald-600 dark:bg-emerald-500/10':'bg-amber-50 text-amber-600 dark:bg-amber-500/10'} px-2 py-0.5 text-[10px]">成功率 ${rate}%</span></div><div class="mt-2 text-slate-400">${escapeHtml(x.kind||'automation')} · ${escapeHtml(x.category||'general')} · 成功 ${x.successes||0}/${x.attempts||0} · 最近 ${escapeHtml(x.last_seen||'')}</div></div>`);});paths.slice(0,Math.max(0,4-cards.length)).forEach(x=>cards.push(`<div class="rounded-xl bg-slate-50 dark:bg-white/5 px-4 py-3 text-xs"><div class="flex items-center justify-between gap-3"><b>${escapeHtml(x.from||'未知工具')} <i class="fas fa-arrow-right mx-1 text-primary-500"></i> ${escapeHtml(x.to||'替代工具')}</b><span class="rounded-full bg-emerald-50 dark:bg-emerald-500/10 px-2 py-0.5 text-[10px] text-emerald-600">成功 ${x.count||0} 次</span></div><div class="mt-2 text-slate-400">${x.error_code?`错误类型：${escapeHtml(x.error_code)} · `:''}${x.last_seen?`最近：${escapeHtml(x.last_seen)}`:'来自本机历史审计'}</div></div>`));host.innerHTML=cards.length?cards.join(''):'<div class="md:col-span-2 rounded-xl border border-dashed border-slate-200 dark:border-white/10 p-5 text-center text-sm text-slate-400">还没有形成稳定恢复路径；后续任务重试成功后会自动沉淀。</div>';}
function normalizeAgent2FailureText(text=''){let value=String(text||'').replace(/\\r\\n|\\n|\\r/g,' ').replace(/<n>/g,'数字').replace(/\s+/g,' ').trim();if(/CERTIFICATE_VERIFY_FAILED|certificate verify failed|SSLCertVerificationError/i.test(value))return '联网请求证书校验失败，通常是本机证书链、代理或安全软件拦截导致。建议优先切换可用搜索源，或检查网络代理/证书配置。';if(/通知通道发送失败|发送令牌|context_token|可用发送令牌/i.test(value))return '通知通道发送失败：微信会话缺少可用发送令牌。建议先让手机微信给 Agent 发送一条消息刷新令牌，失败时自动补发到 Web 并写入交付物。';if(/not found|未找到|command/i.test(value)&&/agent-reach|plugin|skill/i.test(value))return '工具或插件入口未生效：系统记录了配置，但当前运行环境没有找到可执行命令。建议检查安装路径、PATH 或在技能中心执行一键修复。';if(/No module named|ModuleNotFoundError/i.test(value))return '运行依赖缺失：当前环境缺少必要模块。建议在健康中心修复依赖，修复失败时走降级路径。';return value.slice(0,260);}
function agent2FailureCategory(x={}){const raw=String(x.fingerprint||x.lesson||'');if(/CERTIFICATE|SSL|证书/i.test(raw))return ['网络证书异常','fa-certificate','red'];if(/通知|发送令牌|context_token|微信/i.test(raw))return ['通知发送异常','fa-bell-slash','orange'];if(/No module|ModuleNotFound|依赖/i.test(raw))return ['运行依赖缺失','fa-cubes','orange'];if(/not found|未找到|command|plugin|skill/i.test(raw))return ['工具入口缺失','fa-plug-circle-xmark','orange'];return ['重复失败经验','fa-bug','amber'];}
function agent2FailureCard(x={},full=false){const [label,icon,tone]=agent2FailureCategory(x),summary=normalizeAgent2FailureText(x.fingerprint||x.lesson),lesson=normalizeAgent2FailureText(x.lesson||summary),raw=String(x.fingerprint||'');const toneCls={red:'border-red-100 bg-red-50/60 dark:border-red-500/20 dark:bg-red-500/10 text-red-600',orange:'border-orange-100 bg-orange-50/60 dark:border-orange-500/20 dark:bg-orange-500/10 text-orange-600',amber:'border-amber-100 bg-amber-50/60 dark:border-amber-500/20 dark:bg-amber-500/10 text-amber-600'}[tone]||'border-slate-100 bg-slate-50 dark:bg-white/5 text-slate-600';return `<article class="rounded-xl border ${toneCls} p-4 text-xs ${x.status==='ignored'?'opacity-70':''}"><div class="flex flex-wrap items-start justify-between gap-3"><div class="flex items-center gap-2"><span class="w-8 h-8 rounded-lg bg-white/70 dark:bg-black/10 flex items-center justify-center"><i class="fas ${icon}"></i></span><div><b class="text-sm">${label}</b><div class="text-[11px] opacity-75 mt-0.5">出现 ${Number(x.count||0)} 次 · ${x.status==='ignored'?'已隔离':'待分析'}</div></div></div><span class="text-[11px] opacity-75">${escapeHtml(String(x.last_seen||'').replace('T',' ').slice(0,19))}</span></div><p class="mt-3 leading-5 text-slate-600 dark:text-slate-300">${escapeHtml(summary)}</p><p class="mt-2 leading-5 ${x.status==='ignored'?'text-slate-500':'text-orange-600 dark:text-orange-300'}"><b>建议：</b>${escapeHtml(lesson)}</p>${full&&raw&&raw!==summary?`<details class="mt-3"><summary class="cursor-pointer text-slate-400">查看原始错误</summary><pre class="mt-2 rounded-lg bg-white/70 dark:bg-black/10 p-3 text-[11px] whitespace-pre-wrap break-all text-slate-500">${escapeHtml(raw)}</pre></details>`:''}</article>`;}
function renderAgent2LimitedLists(data){agent2LastDashboard=data;const errors=data.error_patterns||[],events=data.events||[],errorHost=document.getElementById('agent2-errors'),eventHost=document.getElementById('agent2-events');const errorTitle=errorHost?.parentElement?.querySelector('h3'),eventTitle=eventHost?.parentElement?.querySelector('h3');if(errorTitle)errorTitle.innerHTML=`<span>失败经验学习</span>${errors.length>5?`<button onclick="toggleAgent2Errors()" class="float-right text-xs text-primary-500 font-normal">${agent2ShowAllErrors?'收起':'查看全部'}</button>`:''}`;if(eventTitle)eventTitle.innerHTML=`<span>审批与审计记录</span>${events.length>5?`<button onclick="toggleAgent2Events()" class="float-right text-xs text-primary-500 font-normal">${agent2ShowAllEvents?'收起':'查看全部'}</button>`:''}`;const shownErrors=agent2ShowAllErrors?errors:errors.slice(0,5),shownEvents=agent2ShowAllEvents?events:events.slice(0,5);if(errorHost)errorHost.innerHTML=shownErrors.length?shownErrors.map(x=>`<div class="rounded-xl border p-3 text-xs ${x.status==='ignored'?'opacity-70':''}"><div class="flex justify-between"><b>出现 ${x.count} 次 · ${x.status==='ignored'?'已隔离':'待分析'}</b><span class="text-slate-400">${escapeHtml(x.last_seen)}</span></div><p class="font-mono text-slate-500 mt-2 break-all">${escapeHtml(x.fingerprint)}</p><p class="${x.status==='ignored'?'text-slate-500':'text-amber-600'} mt-2">${escapeHtml(x.lesson)}</p></div>`).join(''):'<div class="rounded-xl border border-dashed p-8 text-center text-slate-400 text-sm">尚未发现达到阈值的重复错误</div>';if(eventHost)eventHost.innerHTML=shownEvents.length?shownEvents.map(x=>`<div class="rounded-xl border p-3"><div class="flex justify-between gap-3"><b class="text-sm">${escapeHtml(x.summary)}</b><span class="text-[11px] text-slate-400">${escapeHtml(x.created_at)}</span></div><div class="text-xs text-slate-400 mt-1">${escapeHtml(x.action)} · 风险 ${x.risk}</div></div>`).join(''):'<div class="rounded-xl border border-dashed p-8 text-center text-slate-400 text-sm">暂无审计记录</div>';}
const renderAgent2LimitedListsBase=renderAgent2LimitedLists;
renderAgent2LimitedLists=function(data){agent2ShowAllErrors=false;agent2ShowAllEvents=false;renderAgent2LimitedListsBase(data);const errorHost=document.getElementById('agent2-errors'),eventHost=document.getElementById('agent2-events'),errorTitle=errorHost?.parentElement?.querySelector('h3'),eventTitle=eventHost?.parentElement?.querySelector('h3');if(errorTitle)errorTitle.innerHTML='<span>失败经验学习</span><button onclick="openAgent2FullView(\'errors\')" class="float-right text-xs text-primary-500 font-normal"><i class="fas fa-expand mr-1"></i>查看全部</button>';if(eventTitle)eventTitle.innerHTML='<span>审批与审计记录</span><button onclick="openAgent2FullView(\'events\')" class="float-right text-xs text-primary-500 font-normal"><i class="fas fa-expand mr-1"></i>查看全部</button>';}
