function agentRoutingIntentLabel(intent){return {weather:'天气',email:'邮件',file:'本地文件',web:'联网搜索',browser:'浏览器操作',automation:'自动化',code:'代码/开发',memory:'记忆',general:'普通问答'}[intent]||intent||'普通问答';}
function agentRoutingCard(item){const d=item.decision||{},agents=(d.agent_candidates||[]).slice(0,3),tools=(d.tool_candidates||[]).slice(0,5),skills=(d.skill_candidates||[]).slice(0,3),fallbacks=(d.fallback_chain||[]).slice(0,5),reasons=(d.reasons||[]).slice(0,5),memoryHints=(d.memory_hints||[]).slice(0,5);const riskTone=d.risk==='high'?'red':d.risk==='medium'?'amber':'emerald';const learned=fallbacks.filter(x=>/事实库|成功路径|失败经验|偏好|恢复|微信|仪表盘/.test(String(x||'')));const backup=fallbacks.filter(x=>!learned.includes(x));return `<article class="rounded-2xl border border-slate-200 dark:border-white/10 p-4 bg-slate-50/60 dark:bg-white/5"><div class="flex items-start justify-between gap-3"><div class="min-w-0"><b class="text-sm leading-5 block truncate" title="${escapeHtml(item.query||'')}">${escapeHtml(item.query||'')}</b><p class="text-[11px] text-slate-400 mt-1">${escapeHtml(reasons.join(' · ')||'直接问答')}</p></div><span class="shrink-0 rounded-full bg-${riskTone}-50 dark:bg-${riskTone}-500/10 px-2 py-0.5 text-[10px] text-${riskTone}-600">${d.risk==='high'?'高风险':d.risk==='medium'?'需确认':'低风险'}</span></div><div class="mt-3 flex flex-wrap gap-2 text-[11px]"><span class="rounded-full bg-blue-50 dark:bg-blue-500/10 px-2 py-1 text-blue-600">${escapeHtml(agentRoutingIntentLabel(d.intent))}</span><span class="rounded-full bg-purple-50 dark:bg-purple-500/10 px-2 py-1 text-purple-600">${d.level==='strong'?'强模型':'快速模型'}</span><span class="rounded-full bg-slate-100 dark:bg-white/10 px-2 py-1 text-slate-500">评分 ${d.score||0}</span></div><div class="mt-4 grid gap-2 text-xs"><div class="rounded-xl bg-white/80 dark:bg-black/10 px-3 py-2"><b class="text-slate-700 dark:text-slate-200">优先 Agent</b><p class="mt-1 text-slate-500 leading-5">${agents.length?agents.map(escapeHtml).join('<br>'):'暂无匹配，直接由当前 Agent 处理'}</p></div><div class="rounded-xl bg-white/80 dark:bg-black/10 px-3 py-2"><b class="text-slate-700 dark:text-slate-200">优先工具</b><p class="mt-1 text-slate-500 leading-5">${tools.length?tools.map(x=>`<span class="inline-block mr-1 mb-1 rounded-full bg-slate-100 dark:bg-white/10 px-2 py-0.5">${escapeHtml(x)}</span>`).join(''):'直接回答'}</p></div>${skills.length?`<div class="rounded-xl bg-white/80 dark:bg-black/10 px-3 py-2"><b class="text-slate-700 dark:text-slate-200">候选技能</b><p class="mt-1 text-slate-500 leading-5">${skills.map(escapeHtml).join(' / ')}</p></div>`:''}${memoryHints.length?`<div class="rounded-xl bg-indigo-50 dark:bg-indigo-500/10 px-3 py-2"><b class="text-indigo-700 dark:text-indigo-300"><i class="fas fa-book-atlas mr-1"></i>个人认知库</b><p class="mt-1 text-slate-500 dark:text-slate-300 leading-5">${memoryHints.map(escapeHtml).join('<br>')}</p></div>`:''}<div class="rounded-xl ${learned.length?'bg-emerald-50 dark:bg-emerald-500/10':'bg-slate-100/70 dark:bg-white/5'} px-3 py-2"><b class="${learned.length?'text-emerald-700 dark:text-emerald-300':'text-slate-500'}"><i class="fas fa-brain mr-1"></i>经验依据</b><p class="mt-1 text-slate-500 dark:text-slate-300 leading-5">${learned.length?learned.map(escapeHtml).join('<br>'):'暂无可复用经验，执行后会自动沉淀'}</p></div><div class="rounded-xl bg-amber-50/70 dark:bg-amber-500/10 px-3 py-2"><b class="text-amber-700 dark:text-amber-300"><i class="fas fa-life-ring mr-1"></i>失败兜底</b><p class="mt-1 text-slate-500 dark:text-slate-300 leading-5">${backup.length?backup.map(escapeHtml).join(' → '):'失败时先换同类工具，再用通用模型给出最短说明'}</p></div></div></article>`;}
async function loadAgentRoutingPreview(query){const host=document.getElementById('agent2-routing-preview');if(!host)return;const custom=(query!==undefined?query:(document.getElementById('agent2-routing-query')?.value||'')).trim();host.innerHTML='<div class="md:col-span-2 xl:col-span-3 py-8 text-center text-slate-400 text-sm">正在读取智能路由策略…</div>';try{const url=custom?`/api/agent-routing?q=${encodeURIComponent(custom)}`:'/api/agent-routing';const response=await fetch(url,{cache:'no-store'}),data=await response.json();if(!response.ok||data.status!=='success')throw new Error(data.message||'路由策略读取失败');const items=custom?[{query:custom,decision:data.decision||{}}]:(data.samples||[]);host.innerHTML=items.map(agentRoutingCard).join('')||'<div class="py-8 text-center text-slate-400 text-sm">暂无路由样例</div>';}catch(error){host.innerHTML=`<div class="md:col-span-2 xl:col-span-3 rounded-xl border border-amber-200 bg-amber-50 dark:bg-amber-500/10 p-4 text-sm text-amber-700 dark:text-amber-300">智能路由读取失败：${escapeHtml(error.message)}</div>`;}}
function renderAgent2SelfTraining(data){
    const root=data.self_training||{},settings=root.settings||{},summary=root.summary||{},host=document.getElementById('agent2-self-training-panel');
    const setCheck=(id,value)=>{const el=document.getElementById(id);if(el)el.checked=value!==false;};
    const setValue=(id,value)=>{const el=document.getElementById(id);if(el)el.value=value??'';};
    setCheck('agent2-self-training-enabled',settings.enabled);
    setCheck('agent2-self-training-review',settings.auto_review);
    setCheck('agent2-self-training-success',settings.learn_success_paths);
    setCheck('agent2-self-training-failure',settings.learn_failure_lessons);
    setCheck('agent2-self-training-skill',settings.suggest_skill_candidates);
    setValue('agent2-self-training-min-success',settings.min_success_count||2);
    setValue('agent2-self-training-min-failure',settings.min_failure_count||2);
    if(!host)return;
    const latest=root.latest_review,skills=root.skill_candidates||[],exports=root.training_exports||[],drafts=root.skill_drafts||[],usage=root.skill_usage||[],patches=root.skill_patch_candidates||[],versions=root.skill_versions||[],rollbackSummary=root.skill_rollback_summary||[];
    const skillHtml=skills.length?skills.slice(0,6).map(x=>{
        const state=x.status==='approved'?'已采纳':x.status==='ignored'?'已忽略':'候选';
        const stateClass=x.status==='approved'?'text-emerald-600 bg-emerald-50 dark:bg-emerald-500/10':x.status==='ignored'?'text-slate-500 bg-slate-100 dark:bg-white/10':'text-violet-600 bg-violet-50 dark:bg-violet-500/10';
        const actions=x.status==='ignored'?'<span class="text-[11px] text-slate-400">已不再推荐</span>':x.status==='approved'?`<button onclick="createAgent2SkillDraft('${escapeHtml(x.proposal_id||'')}')" class="px-2.5 py-1.5 rounded-lg bg-emerald-600 text-white text-[11px]" ${x.proposal_id?'':'disabled'}>生成草稿</button><button onclick="resolveAgent2SkillCandidate('${escapeHtml(x.id)}','ignored')" class="px-2.5 py-1.5 rounded-lg border text-[11px]">忽略</button>`:`<button onclick="resolveAgent2SkillCandidate('${escapeHtml(x.id)}','approved')" class="px-2.5 py-1.5 rounded-lg bg-violet-600 text-white text-[11px]">采纳为提案</button><button onclick="resolveAgent2SkillCandidate('${escapeHtml(x.id)}','ignored')" class="px-2.5 py-1.5 rounded-lg border text-[11px]">忽略</button>`;
        return `<div class="rounded-lg bg-violet-50/70 dark:bg-violet-500/10 p-3"><div class="flex items-start justify-between gap-3"><div><div class="font-medium text-sm">${escapeHtml(x.title||'候选 Skill')}</div><p class="text-xs text-slate-500 mt-1 line-clamp-2">${escapeHtml(x.description||'')}</p><div class="mt-2 text-[11px] text-slate-400">${escapeHtml(x.task_type||'general')} · ${escapeHtml(x.action||'execute')} · ${Number(x.count||0)} 次</div></div><span class="shrink-0 px-2 py-0.5 rounded-full text-[11px] ${stateClass}">${state}</span></div><div class="mt-3 flex justify-end gap-2">${actions}</div></div>`;
    }).join(''):'<p class="text-xs text-slate-400 mt-2">还没有达到重复阈值的任务模式。</p>';
    const draftHtml=drafts.length?drafts.slice(0,6).map(x=>`<div class="rounded-lg bg-emerald-50 dark:bg-emerald-500/10 p-3 text-xs"><div class="flex items-start justify-between gap-3"><div class="min-w-0"><div class="font-medium text-emerald-700 dark:text-emerald-300 truncate">${escapeHtml(x.title||x.name||'Skill 草稿')}</div><div class="text-slate-500 mt-1 line-clamp-2">${escapeHtml(x.description||x.path||'')}</div><div class="text-[11px] text-slate-400 mt-2">${escapeHtml(x.status==='installed'?'已安装为正式 Skill':'待编辑/安装')} · ${escapeHtml(x.updated_at||x.created_at||'')}</div></div><span class="shrink-0 rounded-full px-2 py-0.5 ${x.status==='installed'?'bg-emerald-100 text-emerald-700 dark:bg-emerald-500/20':'bg-amber-100 text-amber-700 dark:bg-amber-500/20'}">${x.status==='installed'?'正式':'草稿'}</span></div><div class="mt-3 flex justify-end gap-2"><button onclick="openAgent2SkillDraftEditor('${escapeHtml(x.id)}')" class="px-2.5 py-1.5 rounded-lg border text-[11px]">查看/编辑</button><button onclick="installAgent2SkillDraft('${escapeHtml(x.id)}')" class="px-2.5 py-1.5 rounded-lg bg-emerald-600 text-white text-[11px]">安装为正式 Skill</button></div></div>`).join(''):'<p class="text-xs text-slate-400 mt-2">采纳并批准 Skill 提案后，可在这里生成草稿。</p>';
    const usageHtml=usage.length?usage.slice(0,5).map(x=>{const rate=Math.round(Number(x.success_rate||0)*100),tone=rate>=70?'emerald':rate>=45?'blue':'orange';return `<div class="rounded-lg bg-slate-50 dark:bg-white/5 p-3 text-xs"><div class="flex items-center justify-between gap-3"><b class="truncate">${escapeHtml(x.name||'Skill')}</b><span class="rounded-full bg-${tone}-50 dark:bg-${tone}-500/10 px-2 py-0.5 text-${tone}-600">${rate}%</span></div><div class="mt-2 h-1.5 rounded-full bg-slate-200 dark:bg-white/10 overflow-hidden"><div class="h-full bg-${tone}-500" style="width:${Math.max(5,Math.min(100,rate))}%"></div></div><p class="mt-2 text-slate-400">成功 ${Number(x.successes||0)} / ${Number(x.total||0)} · 最近失败 ${Number(x.recent_failures||0)}</p></div>`;}).join(''):'<p class="text-xs text-slate-400 mt-2">暂未积累 Skill 使用效果。后续每次命中技能并完成任务后会自动统计。</p>';
    const patchHtml=patches.length?patches.slice(0,5).map(x=>{const approved=x.status==='approved';return `<div class="rounded-lg bg-orange-50 dark:bg-orange-500/10 p-3 text-xs"><div class="flex items-start justify-between gap-3"><div class="min-w-0"><div class="font-medium text-orange-700 dark:text-orange-300 truncate">${escapeHtml(x.title||'Skill 修补建议')}</div><p class="text-slate-500 mt-1 line-clamp-2">${escapeHtml(x.reason||'')}</p><p class="text-[11px] text-slate-400 mt-2">${escapeHtml(x.created_at||'')}</p></div><span class="shrink-0 rounded-full px-2 py-0.5 ${approved?'bg-emerald-100 text-emerald-700 dark:bg-emerald-500/20':'bg-orange-100 text-orange-700 dark:bg-orange-500/20'}">${approved?'已批准':'待审批'}</span></div><div class="mt-3 flex justify-end gap-2">${approved?`<button onclick="createAgent2SkillDraft('${escapeHtml(x.id)}')" class="px-2.5 py-1.5 rounded-lg bg-emerald-600 text-white text-[11px]">生成修补草稿</button>`:`<button onclick="resolveAgent2Proposal('${escapeHtml(x.id)}','approved')" class="px-2.5 py-1.5 rounded-lg bg-orange-600 text-white text-[11px]">批准修补</button><button onclick="resolveAgent2Proposal('${escapeHtml(x.id)}','rejected')" class="px-2.5 py-1.5 rounded-lg border text-[11px]">拒绝</button>`}</div></div>`;}).join(''):'<p class="text-xs text-slate-400 mt-2">当某个 Skill 多次失败，会在这里自动生成修补建议。</p>';
    const versionHtml=versions.length?versions.slice(0,5).map(x=>{const active=x.status==='active',rollback=x.kind==='rollback';return `<div class="rounded-lg bg-slate-50 dark:bg-white/5 p-3 text-xs"><div class="flex items-start justify-between gap-3"><div class="min-w-0"><div class="font-medium text-slate-700 dark:text-slate-200 truncate">${escapeHtml(x.skill_name||'Skill')}</div><p class="text-slate-500 mt-1 line-clamp-2">${escapeHtml(x.summary||'')}</p><p class="text-[11px] text-slate-400 mt-2">${escapeHtml(x.created_at||'')} · ${rollback?'回滚版本':x.kind==='skill_patch'?'修补安装':'安装记录'}</p></div><span class="shrink-0 rounded-full px-2 py-0.5 ${active?'bg-emerald-100 text-emerald-700 dark:bg-emerald-500/20':'bg-slate-100 text-slate-500 dark:bg-white/10'}">${active?'当前生效':'历史'}</span></div><div class="mt-3 flex justify-end gap-2">${x.can_rollback?`<button onclick="rollbackAgent2SkillVersion('${escapeHtml(x.id)}')" class="px-2.5 py-1.5 rounded-lg bg-blue-600 text-white text-[11px]">回滚到上一版</button>`:'<span class="text-[11px] text-slate-400">暂无可回滚备份</span>'}</div></div>`;}).join(''):'<p class="text-xs text-slate-400 mt-2">安装或修补 Skill 后，会在这里保留版本历史和回滚入口。</p>';
    const rollbackHtml=rollbackSummary.length?rollbackSummary.slice(0,5).map(x=>`<div class="rounded-lg bg-red-50/70 dark:bg-red-500/10 p-3 text-xs"><div class="flex items-center justify-between gap-3"><b class="truncate text-red-700 dark:text-red-300">${escapeHtml(x.skill_name||'Skill')}</b><span class="rounded-full bg-red-100 dark:bg-red-500/20 px-2 py-0.5 text-red-600">回滚 ${Number(x.rollback_count||0)} 次</span></div><p class="mt-2 text-slate-500 line-clamp-2">${escapeHtml(x.last_reason||'该 Skill 曾被回滚，后续推荐会自动降权。')}</p><p class="mt-2 text-[11px] text-slate-400">${escapeHtml(x.last_rollback_at||'')}</p></div>`).join(''):'<p class="text-xs text-slate-400 mt-2">暂无回滚经验；如果修补效果不好，回滚后会在这里沉淀。</p>';
    host.innerHTML=`<div class="grid md:grid-cols-4 gap-2">${[['复盘次数',summary.reviews||0,'fa-rotate'],['成功样本',summary.success_samples||0,'fa-circle-check'],['失败样本',summary.failure_samples||0,'fa-triangle-exclamation'],['Skill回滚',summary.skill_rollbacks||0,'fa-clock-rotate-left']].map(x=>`<div class="rounded-xl bg-white/80 dark:bg-black/10 border border-violet-100 dark:border-violet-500/10 p-3"><i class="fas ${x[2]} text-violet-500"></i><div class="text-xl font-bold mt-2">${x[1]}</div><div class="text-[11px] text-slate-400">${x[0]}</div></div>`).join('')}</div><div class="rounded-xl bg-white/80 dark:bg-black/10 border border-violet-100 dark:border-violet-500/10 p-4"><div class="flex items-center justify-between gap-3"><b class="text-sm">最近复盘</b><span class="text-[11px] text-slate-400">${escapeHtml(latest?.created_at||'尚未执行')}</span></div><p class="mt-2 text-sm text-slate-600 dark:text-slate-300">${escapeHtml(latest?.summary||'点击“立即复盘学习”后，会把本机成功路径和失败经验沉淀为可复用经验。')}</p>${latest?.learned?.length?`<div class="mt-3 flex flex-wrap gap-1.5">${latest.learned.slice(0,6).map(x=>`<span class="px-2 py-0.5 rounded-full bg-violet-100 dark:bg-violet-500/10 text-violet-600 text-[11px]">${escapeHtml(x.kind)} · ${escapeHtml(x.title||'经验')}</span>`).join('')}</div>`:''}</div><div class="grid md:grid-cols-3 gap-3"><div class="rounded-xl bg-white/80 dark:bg-black/10 border border-violet-100 dark:border-violet-500/10 p-4"><b class="text-sm">Skill 候选</b><div class="mt-3 grid gap-2">${skillHtml}</div></div><div class="rounded-xl bg-white/80 dark:bg-black/10 border border-violet-100 dark:border-violet-500/10 p-4"><b class="text-sm">Skill 草稿</b><div class="mt-3 grid gap-2">${draftHtml}</div></div><div class="rounded-xl bg-white/80 dark:bg-black/10 border border-violet-100 dark:border-violet-500/10 p-4"><b class="text-sm">Skill 使用效果</b><div class="mt-3 grid gap-2">${usageHtml}</div></div></div><div class="grid md:grid-cols-3 gap-3"><div class="rounded-xl bg-white/80 dark:bg-black/10 border border-orange-100 dark:border-orange-500/10 p-4"><b class="text-sm">Skill 修补建议</b><div class="mt-3 grid gap-2">${patchHtml}</div></div><div class="rounded-xl bg-white/80 dark:bg-black/10 border border-blue-100 dark:border-blue-500/10 p-4"><b class="text-sm">Skill 版本历史</b><div class="mt-3 grid gap-2">${versionHtml}</div></div><div class="rounded-xl bg-white/80 dark:bg-black/10 border border-red-100 dark:border-red-500/10 p-4"><b class="text-sm">回滚学习</b><div class="mt-3 grid gap-2">${rollbackHtml}</div></div></div><div class="rounded-xl bg-white/80 dark:bg-black/10 border border-violet-100 dark:border-violet-500/10 p-4"><b class="text-sm">训练数据导出</b><div class="mt-3 grid md:grid-cols-3 gap-2">${exports.length?exports.slice(0,3).map(x=>`<div class="rounded-lg bg-slate-50 dark:bg-white/5 p-3 text-xs"><div>${escapeHtml(x.created_at||'')}</div><div class="text-slate-500 mt-1">${Number(x.count||0)} 条 · ${escapeHtml(x.format||'jsonl')}</div></div>`).join(''):'<p class="text-xs text-slate-400 mt-2">需要时可导出 JSONL，用于后续微调或本地模型训练。</p>'}</div></div>`;
}
async function rollbackAgent2SkillVersion(id){
    if(!confirm('确定回滚这个 Skill 吗？系统会先备份当前版本，再恢复到该记录安装前的内容。'))return;
    const status=document.getElementById('agent2-status');
    if(status)status.textContent='正在回滚 Skill 版本…';
    try{
        const result=await agent2Request({method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'rollback_skill_version',id})});
        await loadAgent2Dashboard();
        if(document.getElementById('skills-list')&&!document.getElementById('capability-panel-skills')?.classList.contains('hidden'))await loadSkillsSection();
        if(status)status.textContent=`已回滚：${result.version?.skill_name||'Skill'}`;
    }catch(error){
        if(status)status.textContent=`回滚失败：${error.message}`;
    }
}

function toggleWecomBotEdit(show){
    const panel=document.getElementById('wecom-bot-edit-panel');
    if(!panel)return;
    panel.classList.toggle('hidden', !show);
    if(show)panel.scrollIntoView({behavior:'smooth',block:'nearest'});
}

async function updateMemoryFactStatus(event, factIdEncoded, action) {
    event?.stopPropagation?.();
    const factId = decodeURIComponent(factIdEncoded || '');
    if (!factId) return;
    const label = action === 'delete' ? '删除' : action === 'disable' ? '禁用' : action === 'approve' ? '确认生效' : '恢复';
    if (action === 'delete' && !confirm('确定删除这条记忆吗？删除后默认不会再参与记忆树和路由。')) return;
    setMemoryWikiStatus(`正在${label}记忆…`);
    try {
        const response = await fetch('/api/fact-store', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ id: factId, action })
        });
        const data = await response.json();
        if (data.status !== 'success') throw new Error(data.message || `${label}失败`);
        memoryWikiSelectedFacts.delete(factId);
        await refreshMemoryFactStore();
        await loadMemoryWiki(true);
        setMemoryWikiStatus(`${label}成功，记忆树已更新`, 'success');
    } catch (error) {
        setMemoryWikiStatus(`${label}失败：${error.message}`, 'error');
    }
}
async function resolveAgent2Proposal(id,decision){
    const status=document.getElementById('agent2-status');
    if(status)status.textContent=decision==='approved'?'正在批准修补提案…':'正在拒绝修补提案…';
    try{
        await agent2Request({method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'resolve_proposal',id,decision})});
        await loadAgent2Dashboard();
        if(status)status.textContent=decision==='approved'?'修补提案已批准，可生成草稿':'修补提案已拒绝';
    }catch(error){
        if(status)status.textContent=`处理失败：${error.message}`;
    }
}
async function resolveAgent2SkillCandidate(id,decision){
    const status=document.getElementById('agent2-status');
    if(status)status.textContent=decision==='approved'?'正在生成 Skill 审批提案…':'正在忽略该候选…';
    try{
        await agent2Request({method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'resolve_skill_candidate',id,decision})});
        await loadAgent2Dashboard();
        if(document.getElementById('skills-list')&&!document.getElementById('capability-panel-skills')?.classList.contains('hidden'))await loadSkillsSection();
        if(status)status.textContent=decision==='approved'?'已生成待审批 Skill 提案':'已忽略该 Skill 候选';
    }catch(error){
        if(status)status.textContent=`处理失败：${error.message}`;
    }
}
async function createAgent2SkillDraft(proposalId){
    const status=document.getElementById('agent2-status');
    if(!proposalId){if(status)status.textContent='请先采纳候选并生成审批提案';return;}
    if(status)status.textContent='正在生成 Skill 草稿…';
    try{
        const result=await agent2Request({method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'create_skill_draft',id:proposalId})});
        await loadAgent2Dashboard();
        if(document.getElementById('skills-list')&&!document.getElementById('capability-panel-skills')?.classList.contains('hidden'))await loadSkillsSection();
        if(status)status.textContent=`Skill 草稿已生成：${result.draft?.name||''}`;
    }catch(error){
        if(status)status.textContent=`生成失败：${error.message}`;
    }
}
function closeAgent2SkillDraftEditor(){
    const modal=document.getElementById('skill-draft-modal');
    if(modal){modal.classList.add('hidden');modal.classList.remove('flex');}
}
async function openAgent2SkillDraftEditor(id){
    const modal=document.getElementById('skill-draft-modal'),status=document.getElementById('skill-draft-status');
    if(!modal)return;
    modal.classList.remove('hidden');modal.classList.add('flex');
    if(status)status.textContent='正在读取 Skill 草稿…';
    try{
        const result=await agent2Request({method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'get_skill_draft',id})});
        const draft=result.draft||{};
        document.getElementById('skill-draft-id').value=draft.id||id;
        document.getElementById('skill-draft-title').value=draft.title||draft.name||'';
        document.getElementById('skill-draft-description').value=draft.description||'';
        document.getElementById('skill-draft-content').value=draft.content||'';
        document.getElementById('skill-draft-path').textContent=draft.installed_path?`正式 Skill：${draft.installed_path}`:`草稿文件：${draft.path||''}`;
        if(status)status.textContent=draft.status==='installed'?'该草稿已安装为正式 Skill，修改后可再次安装同步。':'可先检查并修改，再安装为正式 Skill。';
    }catch(error){
        if(status)status.textContent=`读取失败：${error.message}`;
    }
}
async function saveAgent2SkillDraft(){
    const status=document.getElementById('skill-draft-status'),id=document.getElementById('skill-draft-id')?.value;
    if(!id)return;
    if(status)status.textContent='正在保存 Skill 草稿…';
    try{
        const result=await agent2Request({method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'update_skill_draft',id,title:document.getElementById('skill-draft-title')?.value||'',description:document.getElementById('skill-draft-description')?.value||'',content:document.getElementById('skill-draft-content')?.value||''})});
        if(status)status.textContent='Skill 草稿已保存。';
        const path=document.getElementById('skill-draft-path');
        if(path)path.textContent=`草稿文件：${result.draft?.path||''}`;
        await loadAgent2Dashboard();
        if(document.getElementById('skills-list')&&!document.getElementById('capability-panel-skills')?.classList.contains('hidden'))await loadSkillsSection();
    }catch(error){
        if(status)status.textContent=`保存失败：${error.message}`;
    }
}
async function installAgent2SkillDraft(id){
    const draftId=id||document.getElementById('skill-draft-id')?.value;
    const status=document.getElementById('skill-draft-status')||document.getElementById('agent2-status');
    if(!draftId)return;
    if(!confirm('确认安装为正式 Skill？安装后会出现在技能列表中，同名正式技能不会被覆盖。'))return;
    if(status)status.textContent='正在安装为正式 Skill…';
    try{
        await agent2Request({method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'install_skill_draft',id:draftId})});
        if(status)status.textContent='已安装为正式 Skill。';
        await loadAgent2Dashboard();
        if(document.getElementById('skills-list'))await loadSkillsSection();
    }catch(error){
        if(status)status.textContent=`安装失败：${error.message}`;
    }
}
async function loadAgent2Dashboard(){const status=document.getElementById('agent2-status');try{const data=await agent2Request();const summary=data.summary||{};document.getElementById('agent2-summary').innerHTML=[['已启用能力',`${summary.enabled||0} / ${summary.total||10}`,'fa-circle-check'],['待审批',summary.pending_approvals||0,'fa-shield-halved'],['待确认记忆',summary.pending_memories||0,'fa-book-atlas'],['可学习失败',summary.learned_errors||0,'fa-bug'],['最近审计',(data.events||[]).length,'fa-clipboard-list']].map(x=>`<div class="rounded-xl border p-4 bg-white dark:bg-[#202020]"><i class="fas ${x[2]} text-primary-500"></i><div class="text-2xl font-bold mt-3">${x[1]}</div><div class="text-xs text-slate-400 mt-1">${x[0]}</div></div>`).join('');document.getElementById('agent2-capabilities').innerHTML=(data.capabilities||[]).map(x=>`<article class="rounded-xl border p-4 bg-white dark:bg-[#202020]"><div class="flex justify-between items-center"><span class="text-[10px] px-2 py-1 rounded-full bg-slate-100 dark:bg-white/10">${x.priority}</span><label class="flex items-center gap-2 text-xs"><input class="agent2-cap-enabled" data-key="${x.key}" type="checkbox" ${x.enabled?'checked':''}>启用</label></div><h3 class="font-semibold text-sm mt-3">${escapeHtml(x.name)}</h3><p class="text-xs text-slate-400 mt-2 leading-5 min-h-10">${escapeHtml(x.description)}</p><div class="flex items-center justify-between gap-3 mt-3"><span class="text-xs ${x.state==='active'?'text-emerald-600':x.state==='disabled'?'text-slate-400':'text-amber-600'}">${x.state==='active'?'运行中':x.state==='disabled'?'已停用':'等待首次数据'}</span><select class="agent2-cap-approval text-xs rounded-lg border px-2 py-1.5 bg-transparent" data-key="${x.key}"><option value="risk_based" ${x.approval==='risk_based'?'selected':''}>按风险审批</option><option value="always" ${x.approval==='always'?'selected':''}>始终审批</option><option value="auto_low_risk" ${x.approval==='auto_low_risk'?'selected':''}>低风险自动</option></select></div></article>`).join('');const s=data.settings||{},rp=s.recovery_policy||{};document.getElementById('agent2-idle').value=s.review_idle_minutes||10;document.getElementById('agent2-turns').value=s.review_min_turns||6;document.getElementById('agent2-error-threshold').value=s.error_threshold||3;document.getElementById('agent2-heartbeat-enabled').checked=!!s.heartbeat_enabled;document.getElementById('agent2-heartbeat-minutes').value=s.heartbeat_minutes||30;document.getElementById('agent2-skill-approval').value=s.skill_approval||'always';document.getElementById('agent2-recovery-enabled').checked=rp.enabled!==false;document.getElementById('agent2-recovery-expand-time').checked=rp.allow_expand_time!==false;document.getElementById('agent2-recovery-switch-sources').checked=rp.allow_switch_sources!==false;document.getElementById('agent2-recovery-web-fallback').checked=rp.allow_web_fallback!==false;document.getElementById('agent2-recovery-max-retries').value=Number.isFinite(Number(rp.max_auto_retries))?Number(rp.max_auto_retries):1;renderAgent2OpenHumanSettings(data);document.getElementById('agent2-errors').innerHTML=(data.error_patterns||[]).length?(data.error_patterns||[]).map(x=>`<div class="rounded-xl border p-3 text-xs ${x.status==='ignored'?'opacity-70':''}"><div class="flex justify-between"><b>出现 ${x.count} 次 · ${x.status==='ignored'?'已隔离':'待分析'}</b><span class="text-slate-400">${escapeHtml(x.last_seen)}</span></div><p class="font-mono text-slate-500 mt-2 break-all">${escapeHtml(x.fingerprint)}</p><p class="${x.status==='ignored'?'text-slate-500':'text-amber-600'} mt-2">${escapeHtml(x.lesson)}</p></div>`).join(''):'<div class="rounded-xl border border-dashed p-8 text-center text-slate-400 text-sm">尚未发现达到阈值的重复错误</div>';document.getElementById('agent2-events').innerHTML=(data.events||[]).length?(data.events||[]).slice(0,20).map(x=>`<div class="rounded-xl border p-3"><div class="flex justify-between gap-3"><b class="text-sm">${escapeHtml(x.summary)}</b><span class="text-[11px] text-slate-400">${escapeHtml(x.created_at)}</span></div><div class="text-xs text-slate-400 mt-1">${escapeHtml(x.action)} · 风险 ${x.risk}</div></div>`).join(''):'<div class="rounded-xl border border-dashed p-8 text-center text-slate-400 text-sm">暂无审计记录</div>';renderAgent2RecoveryPaths(data);renderAgent2HomeLearning(data);renderAgent2SelfTraining(data);renderAgent2WeixinToolReliability(data);renderAgent2WeixinLearning(data);renderAgent2WeixinSuccessLearning(data);if(status)status.textContent='';}catch(error){if(status)status.textContent=error.message;}}
async function saveAgent2Settings(){const status=document.getElementById('agent2-status');status.textContent='正在保存策略…';const capabilities={};document.querySelectorAll('.agent2-cap-enabled').forEach(input=>capabilities[input.dataset.key]={enabled:input.checked});document.querySelectorAll('.agent2-cap-approval').forEach(select=>{capabilities[select.dataset.key]??={};capabilities[select.dataset.key].approval=select.value;});const recovery_policy={enabled:document.getElementById('agent2-recovery-enabled')?.checked!==false,allow_expand_time:document.getElementById('agent2-recovery-expand-time')?.checked!==false,allow_switch_sources:document.getElementById('agent2-recovery-switch-sources')?.checked!==false,allow_web_fallback:document.getElementById('agent2-recovery-web-fallback')?.checked!==false,max_auto_retries:Number(document.getElementById('agent2-recovery-max-retries')?.value||1)};const self_training={enabled:document.getElementById('agent2-self-training-enabled')?.checked!==false,auto_review:document.getElementById('agent2-self-training-review')?.checked!==false,learn_success_paths:document.getElementById('agent2-self-training-success')?.checked!==false,learn_failure_lessons:document.getElementById('agent2-self-training-failure')?.checked!==false,suggest_skill_candidates:document.getElementById('agent2-self-training-skill')?.checked!==false,min_success_count:Number(document.getElementById('agent2-self-training-min-success')?.value||2),min_failure_count:Number(document.getElementById('agent2-self-training-min-failure')?.value||2)};const openhuman=collectAgent2OpenHumanSettings();try{await agent2Request({method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'configure',settings:{review_idle_minutes:Number(document.getElementById('agent2-idle').value),review_min_turns:Number(document.getElementById('agent2-turns').value),error_threshold:Number(document.getElementById('agent2-error-threshold').value),heartbeat_enabled:document.getElementById('agent2-heartbeat-enabled').checked,heartbeat_minutes:Number(document.getElementById('agent2-heartbeat-minutes').value),skill_approval:document.getElementById('agent2-skill-approval').value,approval_notifications:collectAgent2ApprovalTargets(),recovery_policy,self_training,capabilities,...openhuman}})});status.textContent='全部能力配置已保存并写入审计记录';await loadAgent2Dashboard();}catch(error){status.textContent=error.message;}}
