async function runAgent2Action(action){const status=document.getElementById('agent2-status'),notice=document.getElementById('agent2-action-status'),labels={heartbeat:'正在执行 Heartbeat 主动检查…',health_check:'正在验证全部能力的运行条件…',scan_errors:'正在扫描并归类失败经验…',self_training_review:'正在复盘本机成功/失败经验…',export_training_dataset:'正在导出本地训练样本…'};if(status)status.textContent=labels[action]||'正在执行…';if(notice)notice.textContent=labels[action]||'正在执行…';try{const result=await agent2Request({method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action})});await loadAgent2Dashboard();const data=await agent2Request();renderAgent2RuntimeEvidence(data.capabilities||[]);renderAgent2LimitedLists(data);const done=action==='health_check'?`验证完成：${result.summary?.active||0} 项已生效，${result.summary?.ready||0} 项待触发，${result.summary?.disabled||0} 项已停用`:action==='heartbeat'?'Heartbeat 检查完成，结果已写入审计记录':action==='self_training_review'?`自我训练复盘完成：${result.review?.learned?.length||0} 条经验已沉淀`:action==='export_training_dataset'?`训练样本导出完成：${result.export?.count||0} 条`:'失败经验扫描完成，列表已更新';if(status)status.textContent=done;if(notice)notice.textContent=`✓ ${done}`;}catch(error){const message=`执行失败：${error.message}`;if(status)status.textContent=message;if(notice)notice.textContent=message;}}

function renderAgent2OpenHumanSettings(data){
    const s=data?.settings||{},split=s.split_brain||{},compact=s.output_compaction||{},privacy=s.privacy_mode||{},caps=data?.capabilities||[];
    const byKey=Object.fromEntries(caps.map(x=>[x.key,x]));
    const openKeys=['memory_tree','tool_result_compact','split_brain_router','auto_fetch_context','workflow_canvas','checkpoint_graph','multi_channel_router','privacy_mode'];
    const active=openKeys.filter(key=>byKey[key]?.enabled&&byKey[key]?.state!=='disabled').length;
    const summary=document.getElementById('agent2-openhuman-summary');
    if(summary)summary.textContent=`已接入 ${active}/${openKeys.length} 项`;
    const setChecked=(id,value)=>{const el=document.getElementById(id);if(el)el.checked=!!value;};
    const setValue=(id,value)=>{const el=document.getElementById(id);if(el)el.value=value??'';};
    setChecked('agent2-split-enabled',split.enabled!==false);
    setValue('agent2-split-timeout',split.fast_timeout_seconds||5);
    setValue('agent2-split-deep-keywords',(split.deep_task_keywords||[]).join('\n'));
    setChecked('agent2-compact-enabled',compact.enabled!==false);
    setChecked('agent2-compact-hide-urls',compact.hide_raw_urls!==false);
    setChecked('agent2-compact-strip-logs',compact.strip_process_logs!==false);
    setValue('agent2-compact-max-chars',compact.summary_max_chars||80);
    setChecked('agent2-privacy-enabled',privacy.enabled!==false);
    setChecked('agent2-privacy-local-first',privacy.local_first!==false);
    setChecked('agent2-privacy-redact',privacy.redact_credentials!==false);
    setChecked('agent2-privacy-approval',privacy.approval_for_external_send!==false);
}
function collectAgent2OpenHumanSettings(){
    const lines=id=>(document.getElementById(id)?.value||'').split(/\r?\n|[,，]/).map(x=>x.trim()).filter(Boolean);
    return {
        split_brain:{
            enabled:document.getElementById('agent2-split-enabled')?.checked!==false,
            fast_timeout_seconds:Number(document.getElementById('agent2-split-timeout')?.value||5),
            deep_task_keywords:lines('agent2-split-deep-keywords')
        },
        output_compaction:{
            enabled:document.getElementById('agent2-compact-enabled')?.checked!==false,
            hide_raw_urls:document.getElementById('agent2-compact-hide-urls')?.checked!==false,
            strip_process_logs:document.getElementById('agent2-compact-strip-logs')?.checked!==false,
            summary_max_chars:Number(document.getElementById('agent2-compact-max-chars')?.value||80)
        },
        privacy_mode:{
            enabled:document.getElementById('agent2-privacy-enabled')?.checked!==false,
            local_first:document.getElementById('agent2-privacy-local-first')?.checked!==false,
            redact_credentials:document.getElementById('agent2-privacy-redact')?.checked!==false,
            approval_for_external_send:document.getElementById('agent2-privacy-approval')?.checked!==false
        }
    };
}

