async function runReleaseNotesGenerator(button){const panel=document.getElementById('release-notes-generator-result');const old=button?.innerHTML;if(button){button.disabled=true;button.innerHTML='<i class="fas fa-spinner fa-spin mr-1"></i>生成中';}if(panel)panel.innerHTML='<div class="text-sky-600"><i class="fas fa-spinner fa-spin mr-1"></i>正在生成中文版本说明...</div>';try{const data=await intelligenceRequest('/api/release/notes');if(panel)panel.innerHTML=renderReleaseNotesGenerator(data);_wsToast?.('交付版本说明已生成');if(typeof loadArtifactCenter==='function')loadArtifactCenter(true);else if(typeof loadArtifacts==='function')loadArtifacts();}catch(error){const message=error.message||String(error);if(panel)panel.innerHTML=`<div class="rounded-xl bg-red-50 dark:bg-red-500/10 p-3 text-red-600">生成失败：${escapeHtml(message)}</div>`;_wsToast?.(`生成失败：${message}`);}finally{if(button){button.disabled=false;button.innerHTML=old;}}}
