function renderPackageIntegrityCheck(data){const statusMap={success:['完整性通过','bg-emerald-50 text-emerald-700 dark:bg-emerald-500/10 dark:text-emerald-300','fa-circle-check'],warning:['存在可补齐项','bg-orange-50 text-orange-700 dark:bg-orange-500/10 dark:text-orange-300','fa-triangle-exclamation'],error:['交付包不完整','bg-red-50 text-red-700 dark:bg-red-500/10 dark:text-red-300','fa-circle-xmark']};const meta=statusMap[data.status]||statusMap.warning;const checks=(data.checks||[]).map(item=>{const icon=item.status==='ok'?'fa-circle-check text-emerald-500':item.status==='warning'?'fa-triangle-exclamation text-orange-500':'fa-circle-xmark text-red-500';return `<div class="rounded-xl border border-slate-200 dark:border-white/10 bg-white dark:bg-[#202020] p-3"><div class="flex items-start gap-2"><i class="fas ${icon} mt-0.5"></i><div class="min-w-0 flex-1"><div class="font-medium">${escapeHtml(item.label||'检查项')}</div><div class="text-xs text-slate-500 mt-1">${escapeHtml(item.message||'')}</div>${item.fix?`<div class="text-xs text-orange-600 mt-2">${escapeHtml(item.fix)}</div>`:''}</div></div></div>`;}).join('');const artifact=data.artifact?.id?`<div class="mt-3 rounded-xl bg-emerald-50 dark:bg-emerald-500/10 p-3 text-xs text-emerald-700 dark:text-emerald-300"><i class="far fa-file-lines mr-1"></i>完整性检查报告已保存到产物/交付物中心：${escapeHtml(data.artifact.title||'交付包完整性检查')}</div>`:(data.artifact?.path?`<div class="mt-3 rounded-xl bg-blue-50 dark:bg-blue-500/10 p-3 text-xs text-blue-700 dark:text-blue-300"><i class="far fa-file-lines mr-1"></i>完整性检查报告已生成：${escapeHtml(data.artifact.path)}</div>`:'');return `<div class="rounded-xl ${meta[1]} p-3 mb-3"><i class="fas ${meta[2]} mr-2"></i>${meta[0]} · 通过 ${data.summary?.ok||0}/${data.summary?.total||0}，警告 ${data.summary?.warning||0}，错误 ${data.summary?.error||0}</div><div class="rounded-xl bg-slate-50 dark:bg-white/5 p-3 text-xs text-slate-500 mb-3"><div>目录：${escapeHtml(data.package_dir||'未发现')}</div><div>版本：${escapeHtml(data.version||'')}</div><div>检查时间：${escapeHtml(data.checked_at||'')}</div></div><div class="grid gap-2">${checks}</div>${artifact}`;}
async function runPackageIntegrityCheck(button){const panel=document.getElementById('delivery-package-integrity-result');const old=button?.innerHTML;if(button){button.disabled=true;button.innerHTML='<i class="fas fa-spinner fa-spin mr-1"></i>检查中';}if(panel)panel.innerHTML='<div class="text-rose-600"><i class="fas fa-spinner fa-spin mr-1"></i>正在检查交付包完整性...</div>';try{const data=await intelligenceRequest('/api/release/package-integrity');if(panel)panel.innerHTML=renderPackageIntegrityCheck(data);if(typeof loadArtifactCenter==='function')loadArtifactCenter(true);else if(typeof loadArtifacts==='function')loadArtifacts();_wsToast?.(data.status==='success'?'交付包完整性检查通过':data.status==='error'?'交付包存在缺失或版本问题':'交付包检查完成，有可补齐项');}catch(error){const message=error.message||String(error);if(panel)panel.innerHTML=`<div class="rounded-xl bg-red-50 dark:bg-red-500/10 p-3 text-red-600">检查失败：${escapeHtml(message)}</div>`;_wsToast?.(`完整性检查失败：${message}`);}finally{if(button){button.disabled=false;button.innerHTML=old;}}}
