async function runMaintenancePlan(button){const panel=document.getElementById('maintenance-plan-result');const old=button?.innerHTML;if(button){button.disabled=true;button.innerHTML='<i class="fas fa-spinner fa-spin mr-1"></i>生成中';}if(panel)panel.innerHTML='<div class="text-cyan-600"><i class="fas fa-spinner fa-spin mr-1"></i>正在根据健康检查生成维护计划...</div>';try{const data=await intelligenceRequest('/api/maintenance/plan');if(panel)panel.innerHTML=renderMaintenancePlan(data);if(typeof loadArtifactCenter==='function')loadArtifactCenter(true);else if(typeof loadArtifacts==='function')loadArtifacts();_wsToast?.(data.status==='success'?'自动维护计划已生成':data.status==='error'?'维护计划已生成，有阻断项':'维护计划已生成，有优化项');}catch(error){const message=error.message||String(error);if(panel)panel.innerHTML=`<div class="rounded-xl bg-red-50 dark:bg-red-500/10 p-3 text-red-600">生成失败：${escapeHtml(message)}</div>`;_wsToast?.(`维护计划生成失败：${message}`);}finally{if(button){button.disabled=false;button.innerHTML=old;}}}
async function createMaintenanceSchedule(button){const old=button?.innerHTML;if(button){button.disabled=true;button.innerHTML='<i class="fas fa-spinner fa-spin mr-1"></i>创建中';}try{const data=await intelligenceRequest('/api/maintenance/schedule',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({})});if(data.status!=='success')throw new Error(data.message||'创建失败');_wsToast?.(data.message||'维护定时任务已创建');const panel=document.getElementById('maintenance-plan-result');if(panel){panel.insertAdjacentHTML('afterbegin',`<div class="mb-3 rounded-xl bg-emerald-50 dark:bg-emerald-500/10 p-3 text-xs text-emerald-700 dark:text-emerald-300"><i class="fas fa-circle-check mr-1"></i>${escapeHtml(data.message||'维护定时任务已创建')} 可在“我的自动化任务/运行记录”中查看。</div>`);}loadAutomationTasks?.();loadAutomationDashboard?.();}catch(error){const message=error.message||String(error);_wsToast?.(`创建维护定时任务失败：${message}`);const panel=document.getElementById('maintenance-plan-result');if(panel){panel.insertAdjacentHTML('afterbegin',`<div class="mb-3 rounded-xl bg-red-50 dark:bg-red-500/10 p-3 text-xs text-red-600">创建失败：${escapeHtml(message)}</div>`);}}finally{if(button){button.disabled=false;button.innerHTML=old;}}}
async function importAutomationTemplatesFile(input){const file=input?.files?.[0];if(!file)return;try{const text=await file.text(),data=JSON.parse(text),raw=data.templates||data.template||data;const list=Array.isArray(raw)?raw:[raw];let count=0;for(const item of list){if(!item||typeof item!=='object')continue;await intelligenceRequest('/api/intelligence/templates',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:item.name||'导入模板',description:item.description||'',prompt:item.prompt||item.description||'',kind:item.kind||'news',sources:item.sources||[],tags:item.tags||[],permissions:item.permissions||[],risks:item.risks||[],rating:item.rating||4.5,downloads:item.downloads||0,difficulty:item.difficulty||'自定义',action:item.action||'',config:item.config||{},favorite:item.favorite!==false,enabled:item.enabled!==false,source_url:item.source_url||''})});count++;}await loadAutomationTemplates();await loadAutomationHomeTemplates();_wsToast?.(`已导入 ${count} 个模板`);}catch(error){alert(`导入失败：${error.message||error}`);}finally{if(input)input.value='';}}
function openBrowserRecorder(){const m=document.getElementById('browser-recorder-modal');m.classList.remove('hidden');m.classList.add('flex');}
function closeBrowserRecorder(){const m=document.getElementById('browser-recorder-modal');m.classList.add('hidden');m.classList.remove('flex');}
async function saveBrowserRecording(){const status=document.getElementById('browser-record-status');const payload={name:document.getElementById('browser-record-name').value.trim(),url:document.getElementById('browser-record-url').value.trim(),steps:document.getElementById('browser-record-steps').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean)};try{await intelligenceRequest('/api/intelligence/browser-recordings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});closeBrowserRecorder();loadAutomationTemplates();}catch(error){status.textContent=error.message;}}

let automationRecordItems=[];
let automationRecordOffset=0;
let automationRecordCurrent=-1;
let automationRecordHasMore=false;
let automationRecordP1Filter='all';
function setAutomationRecordP1Filter(value){
    automationRecordP1Filter=value||'all';
    setFilterChipState('.automation-record-p1-chip','data-record-p1-filter',automationRecordP1Filter);
    loadAutomationRecords(true);
}
function visibleAutomationRecords(items){return (items||[]).filter(item=>matchesP1Filter(item,automationRecordP1Filter));}
async function loadAutomationRecords(reset=true) {
    const host = document.getElementById('automation-records-list');
    const query = encodeURIComponent(document.getElementById('automation-record-query').value.trim());
    const date = encodeURIComponent(document.getElementById('automation-record-date').value);
    const recovery = encodeURIComponent(document.getElementById('automation-record-recovery')?.value||'');
    const limit=Number(document.getElementById('automation-record-page-size').value||10);
    if(reset){automationRecordOffset=0;automationRecordItems=[];host.innerHTML = '<div class="py-12 text-center text-slate-400">正在读取运行记录...</div>';}
    try {
        const data = await intelligenceRequest(`/api/intelligence/hub/records?query=${query}&date=${date}&recovery=${recovery}&limit=${limit}&offset=${automationRecordOffset}`);
        automationRecordItems=automationRecordItems.concat(data.records||[]).sort((a,b)=>String(b.updated_at||b.date||'').localeCompare(String(a.updated_at||a.date||''))); automationRecordOffset=automationRecordItems.length;automationRecordHasMore=Boolean(data.has_more);resetAutomationSelection('record');
        const visibleRecords=visibleAutomationRecords(automationRecordItems);
        if (!visibleRecords.length) { host.innerHTML = '<div class="py-16 text-center text-slate-400"><i class="far fa-folder-open text-3xl block mb-3"></i>没有找到匹配的运行记录</div>';document.getElementById('automation-records-more').classList.toggle('hidden',!automationRecordHasMore);return; }
        host.innerHTML = visibleRecords.map((record) => {
            const index=automationRecordItems.findIndex(item=>item.id===record.id);
            const state=automationStatusBadge(record.run_status,'text-[10px]');
            const delivery=record.notification_summary?automationDeliveryBadge(automationDeliveryStatusMeta({notificationSummary:record.notification_summary}),'text-[10px]'):'';
            const recoveryBadge=automationRecoveryBadge(record,'text-[10px]');
            const meta=[record.kind_label,record.task_name].filter(Boolean).join(' · ');
            return `<div data-record-id="${escapeHtml(record.id||'')}" data-task-id="${escapeHtml(record.task_id||'')}" data-run-id="${escapeHtml(record.run_id||'')}" class="flex items-start gap-3 rounded-xl border border-slate-200 dark:border-white/10 bg-white dark:bg-[#202020] p-4 hover:border-primary-400"><input class="automation-select-box automation-record-check mt-1" type="checkbox" value="${record.id}" onchange="updateAutomationSelectionCount('record')"><button class="flex-1 text-left" onclick="showAutomationRecord(${index})"><div class="flex justify-between gap-3"><div class="min-w-0"><h3 class="font-semibold truncate">${escapeHtml(record.title)}</h3>${meta?`<p class="text-[11px] text-slate-400 mt-1 truncate">${escapeHtml(meta)}</p>`:''}</div><div class="shrink-0 flex flex-wrap items-center justify-end gap-2">${state}${delivery}${recoveryBadge}<span class="text-xs text-slate-400">${escapeHtml(record.date)}</span></div></div><p class="text-sm text-slate-500 mt-2 line-clamp-2">${highlightAutomationRecord(record.preview)}</p></button><button onclick="deleteSingleAutomationItem('record','${record.id}')" class="w-8 h-8 text-red-400"><i class="fas fa-trash-can text-xs"></i></button></div>`;
        }).join('');
        document.getElementById('automation-records-more').classList.toggle('hidden',!data.has_more);
    } catch (error) { host.innerHTML = `<div class="py-12 text-center text-red-500">${escapeHtml(error.message)}</div>`; }
}
function loadMoreAutomationRecords(){loadAutomationRecords(false);}
function highlightAutomationRecord(text){let safe=escapeHtml(text||'');safe=safe.replace(/(^|\n)(#{1,6}\s+[^\n]+)/g,'$1<span class="font-bold text-primary-600 dark:text-primary-300">$2</span>');safe=safe.replace(/(重要|关键|风险|异常|失败|警告|变化|影响|建议|成功|结论)/g,'<mark class="rounded bg-amber-200/70 dark:bg-amber-500/30 text-inherit px-0.5">$1</mark>');return safe;}
function showAutomationRecord(index){automationRecordCurrent=Number(index);const record=automationRecordItems[automationRecordCurrent];if(!record)return;document.getElementById('record-viewer-title').textContent=record.title;const state={success:'成功',failed:'失败',empty:'暂无内容',running:'运行中'}[record.run_status]||'';document.getElementById('record-viewer-meta').textContent=[record.date,record.updated_at,record.kind_label,record.task_name,state,record.notification_summary,record.execution_audit_summary].filter(Boolean).join(' · ');document.getElementById('record-task-button')?.classList.toggle('hidden',!(record.task_id||record.task_name));document.getElementById('record-run-button')?.classList.toggle('hidden',!record.run_id);const content=document.getElementById('record-viewer-content');content.innerHTML=automationExecutionAuditHtml(record,{title:'本次交付通知轨迹'})+renderMarkdown(record.content||'');applyHighlighting(content);styleAutomationReport(content);document.getElementById('record-viewer-position').textContent=`${automationRecordCurrent+1} / ${automationRecordItems.length}${automationRecordHasMore?' +':''}`;document.getElementById('record-viewer-prev').disabled=automationRecordCurrent<=0;document.getElementById('record-viewer-next').disabled=automationRecordCurrent>=automationRecordItems.length-1&&!automationRecordHasMore;const modal=document.getElementById('automation-record-modal');modal.classList.remove('hidden');modal.classList.add('flex');}
function closeAutomationRecord(){const modal=document.getElementById('automation-record-modal');modal.classList.add('hidden');modal.classList.remove('flex');}
async function navigateAutomationRecord(step){let target=automationRecordCurrent+step;if(target===automationRecordItems.length&&automationRecordHasMore){await loadAutomationRecords(false);target=automationRecordCurrent+step;}if(target>=0&&target<automationRecordItems.length)showAutomationRecord(target);}
function currentAutomationRecord(){return automationRecordItems[automationRecordCurrent]||null;}
function openCurrentAutomationRecordRun(){const record=currentAutomationRecord();if(!record?.run_id)return;closeAutomationRecord();showAutomationRun(record.run_id);}
function openCurrentAutomationRecordTask(){const record=currentAutomationRecord();if(!record)return;closeAutomationRecord();currentArtifact={task_id:record.task_id||'',task_name:record.task_name||'',kind_label:record.kind_label||'',trigger:record.kind_label==='定时任务'?'scheduled_agent':'',tags:record.tags||[]};openCurrentArtifactTask();}
async function copyCurrentAutomationRecord(){const record=automationRecordItems[automationRecordCurrent];if(!record)return;try{await navigator.clipboard.writeText(record.content);const meta=document.getElementById('record-viewer-meta');const old=meta.textContent;meta.textContent='已复制到剪贴板';setTimeout(()=>meta.textContent=old,1500);}catch(_){alert('复制失败，请手动选择正文复制');}}
async function deleteCurrentAutomationRecord(){const record=automationRecordItems[automationRecordCurrent];if(!record||!confirm(`确定删除记录“${record.title}”吗？删除后无法恢复。`))return;try{await intelligenceRequest('/api/intelligence/hub/records',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:record.id})});closeAutomationRecord();await loadAutomationRecords(true);loadAutomationDashboard();}catch(error){alert(error.message);}}
function automationSelection(type){return [...document.querySelectorAll(`.automation-${type}-check:checked`)].map(x=>x.value);}
function resetAutomationSelection(type){const all=document.getElementById(`automation-${type}-select-all`);if(all)all.checked=false;updateAutomationSelectionCount(type);}
function updateAutomationSelectionCount(type){const selected=automationSelection(type),count=document.getElementById(`automation-${type}-selected-count`),all=document.getElementById(`automation-${type}-select-all`),boxes=[...document.querySelectorAll(`.automation-${type}-check`)];if(count)count.textContent=`已选择 ${selected.length} 条`;if(all){all.checked=boxes.length>0&&selected.length===boxes.length;all.indeterminate=selected.length>0&&selected.length<boxes.length;}}
function toggleAutomationSelection(type,checked){document.querySelectorAll(`.automation-${type}-check`).forEach(x=>x.checked=checked);updateAutomationSelectionCount(type);}
async function deleteAutomationItems(type,payload){const endpoint=type==='record'?'/api/intelligence/hub/records':'/api/intelligence/runs';await intelligenceRequest(endpoint,{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(type==='record'){await loadAutomationRecords(true);loadAutomationDashboard();}else await loadAutomationRuns();}
async function deleteSingleAutomationItem(type,id){if(!confirm('确定删除这条记录吗？删除后无法恢复。'))return;try{await deleteAutomationItems(type,{id});}catch(error){alert(error.message);}}
async function deleteSelectedAutomationItems(type){const ids=automationSelection(type);if(!ids.length)return alert('请先选择需要删除的记录');if(!confirm(`确定删除选中的 ${ids.length} 条记录吗？`))return;try{await deleteAutomationItems(type,{ids});}catch(error){alert(error.message);}}
async function deleteAllAutomationItems(type){const name=type==='record'?'运行记录':'执行会话';if(!confirm(`确定清空全部${name}吗？此操作无法恢复。`))return;try{await deleteAutomationItems(type,{all:true});}catch(error){alert(error.message);}}

async function editAutomationTask(kind, encoded) {
    const task = JSON.parse(decodeURIComponent(encoded));
    const formKind=kind==='extended'?(task.kind||'social'):kind;automationEditContext={kind:formKind,task};openTaskCreator(false);selectTaskType(formKind);populateAutomationTaskForm(formKind,task);populateAutomationArtifactConfig(task);
}

function populateAutomationArtifactConfig(task){refreshAutomationArtifactTypeOptions(task?.artifact_type||'report');renderAutomationArtifactTags(task?.artifact_tags||['自动化','报告']);}

function populateAutomationTaskForm(kind,task){const set=(id,value)=>{const el=document.getElementById(id);if(el)el.value=value??'';};const schedule=(prefix,toggle)=>{set(`${prefix}-schedule-type`,task.schedule_type||'daily');set(`${prefix}-schedule`,task.schedule||'');set(`${prefix}-interval-value`,task.interval_minutes||30);set(`${prefix}-interval-unit`,1);toggle();};if(kind==='news'){set('news-name',task.name);set('news-sources',(task.sources||[]).join('\n'));set('news-keywords',(task.keywords||[]).join(','));set('news-max-items',task.max_items||20);set('news-rule-include',(task.rules?.include||[]).join(','));set('news-rule-exclude',(task.rules?.exclude||[]).join(','));set('news-rule-instruction',task.rules?.instruction||'');setNewsConnectedSources(task.official_sources||[],task.connected_sources||[]);setNewsSourceStrategy(task.source_strategy||NEWS_DEFAULT_SOURCE_STRATEGY);schedule('news',toggleNewsScheduleFields);}else if(kind==='github'){set('github-name',task.name);set('github-repositories',(task.repositories||[]).join('\n'));schedule('github',toggleGithubScheduleFields);}else if(kind==='website'){set('website-name',task.name);set('website-urls',(task.urls||[]).join('\n'));set('website-keywords',(task.keywords||[]).join(','));document.getElementById('website-notify-unchanged').checked=Boolean(task.notify_unchanged);schedule('website',toggleWebsiteScheduleFields);}else if(kind==='briefing'){set('briefing-name',task.name);set('briefing-lookback',task.lookback_hours||24);set('briefing-sources',(task.sources||[]).join('\n'));schedule('briefing',toggleBriefingScheduleFields);}else if(['social','product','ops'].includes(kind)){set('extended-kind',kind);set('extended-name',task.name);set('extended-sources',(task.sources||[]).join('\n'));set('extended-keywords',(task.keywords||[]).join(','));schedule('extended',toggleExtendedScheduleFields);}else if(kind==='email'){set('email-name',task.name);set('email-source-type',task.source_type||'local');set('email-local-path',task.local_path||task.folder||'work/cow-workspace/emails');set('email-folder',task.source_type==='imap'?(task.folder||'INBOX'):'INBOX');toggleEmailSourceFields();document.getElementById('email-unread-only').checked=Boolean(task.unread_only);set('email-max-messages',task.max_messages||20);set('email-recipient',task.recipient||'');document.getElementById('email-send-report').checked=Boolean(task.send_report);schedule('email',toggleEmailScheduleFields);}else if(kind==='maintenance'){set('maintenance-name',task.name);set('maintenance-type',task.maintenance_type||'readiness_check');set('maintenance-schedule-type',task.schedule_type||'daily');set('maintenance-failure-threshold',task.rules?.failure_rate_threshold||20);set('maintenance-cache-threshold',task.rules?.cache_limit_mb||500);const scheduleText=String(task.schedule||'每天09:00');const time=(scheduleText.match(/(\d{1,2}:\d{2})/)||[])[1]||'09:00';set('maintenance-daily-time',time.length===4?'0'+time:time);set('maintenance-weekly-time',scheduleText.startsWith('每周')?scheduleText:'每周一09:00');set('maintenance-interval-value',task.interval_minutes||60);set('maintenance-interval-unit',1);toggleMaintenanceScheduleFields();}}

const NEWS_DEFAULT_OFFICIAL_SOURCES=['https://www.mof.gov.cn/zhengwuxinxi/zhengcefabu/','https://fgk.chinatax.gov.cn/','https://www.chinatax.gov.cn/chinatax/index.html','https://www.gov.cn/zhengce/zuixin/'];
let newsConnectedSourceMeta={};
const NEWS_DEFAULT_SOURCE_STRATEGY={auto_enabled:true,primary_enabled:true,backup_enabled:true,domestic_enabled:true,international_enabled:true};
const NEWS_DEFAULT_SOURCE_POOLS={domestic_primary:['36kr.com','qbitai.com','jiqizhixin.com','ithome.com','gov.cn','miit.gov.cn','cac.gov.cn','most.gov.cn'],domestic_backup:['infoq.cn','leiphone.com','oschina.net','csdn.net'],international_primary:['openai.com','anthropic.com','blogs.microsoft.com','nvidianews.nvidia.com','blog.google','apple.com','about.fb.com'],international_backup:['reuters.com','theverge.com','techcrunch.com','wired.com','technologyreview.com']};
function newsPoolLines(id){return (document.getElementById(id)?.value||'').split(/\r?\n|[,，]/).map(x=>x.trim()).filter(Boolean);}
function newsSourcePools(){return {domestic_primary:newsPoolLines('news-pool-domestic-primary'),domestic_backup:newsPoolLines('news-pool-domestic-backup'),international_primary:newsPoolLines('news-pool-international-primary'),international_backup:newsPoolLines('news-pool-international-backup')};}
function setNewsSourcePools(pools={}){const merged={...NEWS_DEFAULT_SOURCE_POOLS,...(pools||{})};[['news-pool-domestic-primary','domestic_primary'],['news-pool-domestic-backup','domestic_backup'],['news-pool-international-primary','international_primary'],['news-pool-international-backup','international_backup']].forEach(([id,key])=>{const el=document.getElementById(id);if(el)el.value=(merged[key]||[]).join('\n');});}
function resetNewsSourcePools(){setNewsSourcePools(NEWS_DEFAULT_SOURCE_POOLS);}
function renderNewsSourceHealth(data={}){const summary=document.getElementById('news-source-health-summary'),list=document.getElementById('news-source-health-list');if(!summary||!list)return;const s=data.summary||{};summary.textContent=`共 ${s.total||0} 个来源，健康 ${s.healthy||0} 个，冷却 ${s.cooling_down||0} 个，手动停用 ${s.disabled||0} 个`;const items=(data.items||[]).slice(0,20);list.innerHTML=items.length?items.map(item=>{const state=item.disabled?'已停用':item.cooling_down?'冷却中':item.status==='success'?'正常':item.status==='empty'?'无新内容':item.status==='error'?'异常':'未知';const cls=item.disabled?'bg-slate-100 text-slate-500':item.cooling_down?'bg-amber-50 text-amber-700':item.status==='success'?'bg-emerald-50 text-emerald-600':item.status==='error'?'bg-red-50 text-red-500':'bg-slate-100 text-slate-500';return `<div class="rounded-lg border border-slate-200 dark:border-white/10 bg-white/70 dark:bg-black/10 p-3"><div class="flex flex-wrap items-start justify-between gap-2"><div class="min-w-0"><b class="block truncate">${escapeHtml(item.host||item.source||'来源')}</b><small class="block truncate text-slate-400" title="${escapeHtml(item.source||'')}">${escapeHtml(item.source||'')}</small></div><span class="rounded-full px-2 py-0.5 text-[10px] ${cls}">${escapeHtml(state)}</span></div><div class="mt-2 grid grid-cols-2 md:grid-cols-4 gap-2 text-[11px] text-slate-500"><span>成功率：${item.success_rate||0}%</span><span>连续失败：${item.consecutive_failures||0}</span><span>抓取条数：${item.items_collected||0}</span><span>下次重试：${escapeHtml(formatDateTime(item.next_retry_at)||'—')}</span></div>${item.last_error?`<p class="mt-2 text-[11px] text-red-500 line-clamp-2">${escapeHtml(item.last_error)}</p>`:''}<div class="mt-2 flex justify-end gap-2"><button type="button" onclick="toggleNewsSourceDisabled('${encodeURIComponent(item.source||'')}',${!item.disabled})" class="px-2 py-1 rounded border text-[11px]">${item.disabled?'恢复':'停用'}</button></div></div>`}).join(''):'<div class="rounded-lg border border-dashed p-3 text-center text-xs text-slate-400">暂无来源健康记录，运行任务后会自动生成。</div>';}
async function loadNewsSourceHealth(){const summary=document.getElementById('news-source-health-summary');if(summary)summary.textContent='正在加载来源健康…';try{const data=await intelligenceRequest('/api/intelligence/news/source-health');renderNewsSourceHealth(data);}catch(error){if(summary)summary.textContent=`来源健康读取失败：${error.message||error}`;}}
async function toggleNewsSourceDisabled(encoded,disabled){const source=decodeURIComponent(encoded||'');if(!source)return;try{const data=await intelligenceRequest('/api/intelligence/news/source-health',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:disabled?'disable':'enable',source})});renderNewsSourceHealth(data);}catch(error){alert(error.message||String(error));}}
async function cleanupNewsSourceHealth(){try{const data=await intelligenceRequest('/api/intelligence/news/source-health',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'cleanup',max_age_days:30})});renderNewsSourceHealth(data);alert(`已清理 ${data.archived_count||0} 条历史坏来源记录`);}catch(error){alert(error.message||String(error));}}
function newsSourceStrategy(){return {auto_enabled:document.getElementById('news-source-auto')?.checked!==false,primary_enabled:document.getElementById('news-source-primary')?.checked!==false,backup_enabled:document.getElementById('news-source-backup')?.checked!==false,domestic_enabled:document.getElementById('news-source-domestic')?.checked!==false,international_enabled:document.getElementById('news-source-international')?.checked!==false,pools:newsSourcePools()};}
function setNewsSourceStrategy(strategy={}){const merged={...NEWS_DEFAULT_SOURCE_STRATEGY,...(strategy||{})};[['news-source-auto','auto_enabled'],['news-source-primary','primary_enabled'],['news-source-backup','backup_enabled'],['news-source-domestic','domestic_enabled'],['news-source-international','international_enabled']].forEach(([id,key])=>{const el=document.getElementById(id);if(el)el.checked=merged[key]!==false;});setNewsSourcePools(merged.pools||NEWS_DEFAULT_SOURCE_POOLS);}
function newsConnectedSources(){try{return JSON.parse(document.getElementById('news-official-sources')?.value||'[]');}catch(_){return [];}}
function setNewsConnectedSources(urls,meta=[]){const input=document.getElementById('news-official-sources');if(!input)return;input.value=JSON.stringify([...new Set((urls||[]).map(x=>String(x).trim()).filter(Boolean))]);newsConnectedSourceMeta=Object.fromEntries((meta||[]).map(x=>[x.url,x]));renderNewsConnectedSources();}
function renderNewsConnectedSources(){const host=document.getElementById('news-connected-sources-list');if(!host)return;const urls=newsConnectedSources();host.innerHTML=urls.length?urls.map((url,index)=>{const item=newsConnectedSourceMeta[url]||{},status=item.status||'未检测',ok=status==='success',bad=status==='error';return `<div class="flex items-center gap-3 rounded-lg border border-slate-200 dark:border-white/10 bg-white dark:bg-[#202020] px-3 py-2"><span class="w-8 h-8 rounded-lg bg-blue-50 dark:bg-blue-500/10 text-blue-600 flex items-center justify-center"><i class="fas fa-building-columns"></i></span><span class="min-w-0 flex-1"><b class="block text-sm truncate">${escapeHtml(item.name||new URL(url).hostname)}</b><small class="block text-slate-400 truncate" title="${escapeHtml(url)}">${escapeHtml(url)}</small></span><span class="rounded-full px-2 py-1 text-[10px] ${ok?'bg-emerald-50 text-emerald-600':bad?'bg-red-50 text-red-500':'bg-slate-100 text-slate-500'}">${ok?'正常':bad?'异常':'未检测'}</span><button type="button" onclick="editNewsConnectedSource(${index})" class="text-slate-400 hover:text-blue-600" title="修改"><i class="fas fa-pen"></i></button><button type="button" onclick="deleteNewsConnectedSource(${index})" class="text-slate-400 hover:text-red-500" title="删除"><i class="fas fa-trash"></i></button></div>`}).join(''):'<div class="rounded-lg border border-dashed p-4 text-center text-xs text-slate-400">暂未接入来源，可点击“新增”添加</div>';}
function addNewsConnectedSource(){const url=prompt('请输入来源地址（完整网址）');if(!url)return;try{new URL(url);}catch(_){return alert('请输入以 http:// 或 https:// 开头的完整网址');}setNewsConnectedSources([...newsConnectedSources(),url]);}
function editNewsConnectedSource(index){const urls=newsConnectedSources(),url=prompt('修改来源地址',urls[index]||'');if(!url)return;try{new URL(url);}catch(_){return alert('请输入有效的完整网址');}urls[index]=url;setNewsConnectedSources(urls);}
function deleteNewsConnectedSource(index){const urls=newsConnectedSources();urls.splice(index,1);setNewsConnectedSources(urls);}
function restoreNewsOfficialSources(){setNewsConnectedSources(NEWS_DEFAULT_OFFICIAL_SOURCES);}

async function loadNewsTasks() {
    const container = document.getElementById('news-tasks');
    try {
        const data = await intelligenceRequest('/api/intelligence/news');
        if (!data.tasks.length) {
            container.innerHTML = '';
            return 0;
        }
        container.innerHTML = data.tasks.map(task => {
            const scheduleText = task.schedule_type === 'interval' ? `每隔 ${formatNewsInterval(task.interval_minutes)}` : task.schedule;
            return `
            <div class="rounded-xl border border-slate-200 dark:border-white/10 bg-white dark:bg-[#202020] p-5">
                <div class="flex flex-wrap items-start justify-between gap-3">
                    <div><h3 class="font-semibold text-slate-800 dark:text-slate-100">${escapeHtml(task.name)}</h3><p class="text-xs text-slate-400 mt-1">${escapeHtml(scheduleText)} · ${(task.sources||[]).length} 个订阅源 · ${(task.connected_sources||[]).length} 个已接入来源 · ${(task.keywords||[]).length ? escapeHtml(task.keywords.join('、')) : '全部主题'}</p></div>
                    <span class="px-2 py-1 rounded-full text-xs ${task.enabled ? 'bg-emerald-50 text-emerald-600 dark:bg-emerald-500/10' : 'bg-slate-100 text-slate-500'}">${task.enabled ? '已启用' : '已停用'}</span>
                </div>
                <p class="text-sm text-slate-500 dark:text-slate-400 mt-4">${escapeHtml(task.last_status || '等待执行')}</p>
                <div class="flex flex-wrap gap-2 mt-4">
                    <button onclick="runNewsTask('${task.id}', this)" class="px-3 py-1.5 rounded-lg bg-primary-500 text-white text-xs">立即抓取并生成日报</button>
                    <button onclick="editAutomationTask('news','${encodeURIComponent(JSON.stringify(task))}')" class="automation-edit-btn px-3 py-1.5 rounded-lg border border-slate-200 dark:border-white/10 text-xs"><i class="fas fa-pen mr-1"></i>编辑</button>
                    <button onclick="toggleNewsTask('${task.id}', ${!task.enabled})" class="px-3 py-1.5 rounded-lg border border-slate-200 dark:border-white/10 text-xs">${task.enabled ? '停用' : '启用'}</button>
                    <button onclick="deleteNewsTask('${task.id}')" class="px-3 py-1.5 rounded-lg text-red-500 text-xs">删除</button>
                </div>
            </div>`;
        }).join(''); return data.tasks.length;
    } catch (error) {
        container.innerHTML = `<div class="py-12 text-center text-red-500">${escapeHtml(error.message)}</div>`;
        return 0;
    }
}

async function saveNewsTask() {
    const status = document.getElementById('news-form-status');
    status.textContent = '';
    const scheduleType = document.getElementById('news-schedule-type').value;
    const intervalMinutes = Number(document.getElementById('news-interval-value').value || 0) * Number(document.getElementById('news-interval-unit').value || 1);
    const payload = {
        name: document.getElementById('news-name').value.trim(),
        schedule: document.getElementById('news-schedule').value.trim(),
        schedule_type: scheduleType,
        interval_minutes: scheduleType === 'interval' ? intervalMinutes : 0,
        sources: document.getElementById('news-sources').value.split(/\r?\n/).map(x => x.trim()).filter(Boolean),
        keywords: document.getElementById('news-keywords').value.split(/[,，]/).map(x => x.trim()).filter(Boolean),
        max_items: Number(document.getElementById('news-max-items').value || 20),
        official_sources: newsConnectedSources(),
        source_strategy: newsSourceStrategy(),
        rules: {
            include: document.getElementById('news-rule-include').value.split(/[,，]/).map(x => x.trim()).filter(Boolean),
            exclude: document.getElementById('news-rule-exclude').value.split(/[,，]/).map(x => x.trim()).filter(Boolean),
            instruction: document.getElementById('news-rule-instruction').value.trim(),
        },
        notifications: collectNotificationTargets(),
    };
    try {
        await saveAutomationPayload('news','/api/intelligence/news',payload);
        closeTaskCreator(); await loadAutomationTasks();
    } catch (error) { status.textContent = error.message; }
}

function formatNewsInterval(minutes) {
    if (minutes % 1440 === 0) return `${minutes / 1440} 天`;
    if (minutes % 60 === 0) return `${minutes / 60} 小时`;
    return `${minutes} 分钟`;
}

