async function loadGithubTasks() {
    const container = document.getElementById('github-tasks');
    try {
        const data = await intelligenceRequest('/api/intelligence/github');
        if (!data.tasks.length) { container.innerHTML = ''; return 0; }
        container.innerHTML = data.tasks.map(task => {
            const scheduleText = task.schedule_type === 'interval' ? `每隔 ${formatNewsInterval(task.interval_minutes)}` : task.schedule;
            return `<div class="rounded-xl border border-slate-200 dark:border-white/10 bg-white dark:bg-[#202020] p-5"><div class="flex flex-wrap items-start justify-between gap-3"><div><h4 class="font-semibold text-slate-800 dark:text-slate-100">${escapeHtml(task.name)}</h4><p class="text-xs text-slate-400 mt-1">${escapeHtml(scheduleText)} · ${task.repositories.length} 个仓库</p></div><span class="px-2 py-1 rounded-full text-xs ${task.enabled ? 'bg-emerald-50 text-emerald-600 dark:bg-emerald-500/10' : 'bg-slate-100 text-slate-500'}">${task.enabled ? '已启用' : '已停用'}</span></div><div class="flex flex-wrap gap-1 mt-3">${task.repositories.map(repo => `<span class="px-2 py-1 rounded bg-slate-100 dark:bg-white/5 text-xs font-mono">${escapeHtml(repo)}</span>`).join('')}</div><p class="text-sm text-slate-500 mt-3">${escapeHtml(task.last_status || '等待执行')}</p><div class="flex flex-wrap gap-2 mt-4"><button onclick="runGithubTask('${task.id}', this)" class="px-3 py-1.5 rounded-lg bg-slate-800 dark:bg-slate-100 dark:text-slate-900 text-white text-xs">立即检查并生成报告</button><button onclick="toggleGithubTask('${task.id}', ${!task.enabled})" class="px-3 py-1.5 rounded-lg border border-slate-200 dark:border-white/10 text-xs">${task.enabled ? '停用' : '启用'}</button><button onclick="deleteGithubTask('${task.id}')" class="px-3 py-1.5 rounded-lg text-red-500 text-xs">删除</button></div></div>`;
        }).join(''); return data.tasks.length;
    } catch (error) { container.innerHTML = `<div class="py-12 text-center text-red-500">${escapeHtml(error.message)}</div>`; return 0; }
}

async function saveGithubTask() {
    const type = document.getElementById('github-schedule-type').value;
    const interval = Number(document.getElementById('github-interval-value').value || 0) * Number(document.getElementById('github-interval-unit').value || 1);
    const payload = {name:document.getElementById('github-name').value.trim(), repositories:document.getElementById('github-repositories').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean), schedule_type:type, schedule:document.getElementById('github-schedule').value.trim(), interval_minutes:type==='interval'?interval:0, github_token:document.getElementById('github-token').value.trim()};
    const status = document.getElementById('github-form-status'); status.textContent = '';
    try { await saveAutomationPayload('github','/api/intelligence/github',payload); closeTaskCreator(); document.getElementById('github-token').value=''; await loadAutomationTasks(); }
    catch (error) { status.textContent = error.message; }
}

function automationRunSummary(data){
    const task=data?.task||{},parts=[];
    if(task.last_status)parts.push(task.last_status);
    if(Array.isArray(data?.items))parts.push(`结果 ${data.items.length} 条`);
    else if(Array.isArray(data?.projects))parts.push(`仓库 ${data.projects.length} 个`);
    else if(Array.isArray(data?.changes))parts.push(`变化 ${data.changes.filter(x=>x&&x.changed).length} 条`);
    else if(Array.isArray(data?.sections))parts.push(`汇总 ${data.sections.length} 组`);
    else if(Array.isArray(data?.results))parts.push(`结果 ${data.results.length} 条`);
    else if(Array.isArray(data?.messages))parts.push(`邮件 ${data.messages.length} 封`);
    const notifications=Array.isArray(data?.notifications)?data.notifications:[],failed=notifications.filter(x=>!x.success),sent=notifications.length-failed.length;
    if(notifications.length)parts.push(failed.length?`通知已发 ${sent} 个，失败 ${failed.length} 个`:`通知已发 ${sent} 个`);
    else parts.push('未配置通知，仅保存记录');
    if(data?.run_id)parts.push(`运行记录 ${data.run_id}`);
    return parts.filter(Boolean).join('；')||'执行完成';
}
async function refreshAutomationAfterManualRun(){
    const tasks=loadAutomationTasks().catch(()=>{});
    const runs=document.getElementById('automation-runs-list')&&typeof loadAutomationRuns==='function'?loadAutomationRuns().catch(()=>{}):Promise.resolve();
    const records=document.getElementById('automation-records-list')&&typeof loadAutomationRecords==='function'?loadAutomationRecords(true).catch(()=>{}):Promise.resolve();
    const artifacts=document.getElementById('view-artifacts')&&!document.getElementById('view-artifacts').classList.contains('hidden')&&typeof loadArtifacts==='function'?loadArtifacts().catch(()=>{}):Promise.resolve();
    await Promise.all([tasks,runs,records,artifacts]);
}
async function runAutomationTaskWithFeedback({id,button,endpoint,reportHost,reportPanel,runningText='正在执行...',defaultText='立即执行'}){
    const original=button?.textContent||defaultText;
    if(button){button.disabled=true;button.dataset.originalText=original;button.textContent=runningText;}
    try{
        const data=await intelligenceRequest(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({task_id:id})});
        if(data.report&&reportHost)renderAutomationReportTo(reportHost,data.report);
        if(reportPanel)document.getElementById(reportPanel)?.classList.remove('hidden');
        await refreshAutomationAfterManualRun();
        if(button){button.classList.add('bg-emerald-600');button.textContent='执行完成';}
        const summary=automationRunSummary(data);
        if(typeof showToast==='function')showToast(summary,'success');
        else console.info('[Automation]',summary);
        setTimeout(()=>{if(button){button.disabled=false;button.classList.remove('bg-emerald-600');button.textContent=original;}},1200);
        return data;
    }catch(error){
        await Promise.all([typeof loadAutomationRuns==='function'?loadAutomationRuns().catch(()=>{}):Promise.resolve(),typeof loadAutomationRecords==='function'?loadAutomationRecords(true).catch(()=>{}):Promise.resolve()]);
        if(button){button.disabled=false;button.textContent=original;}
        alert(`执行失败：${error.message||error}\n\n失败原因已写入“运行记录”和“产物/交付物中心”。`);
        throw error;
    }
}

async function runGithubTask(id, button) {
    return runAutomationTaskWithFeedback({id,button,endpoint:'/api/intelligence/github/run',reportHost:'github-report-content',reportPanel:'github-report',runningText:'正在检查...',defaultText:'立即检查并生成报告'});
}

