async function saveExtendedTask(){const type=document.getElementById('extended-schedule-type').value;const interval=Number(document.getElementById('extended-interval-value').value||0)*Number(document.getElementById('extended-interval-unit').value||1);const payload={kind:document.getElementById('extended-kind').value,name:document.getElementById('extended-name').value.trim(),sources:document.getElementById('extended-sources').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean),keywords:document.getElementById('extended-keywords').value.split(/[,，]/).map(x=>x.trim()).filter(Boolean),schedule_type:type,schedule:document.getElementById('extended-schedule').value.trim(),interval_minutes:type==='interval'?interval:0};const status=document.getElementById('extended-form-status');status.textContent='';try{await saveAutomationPayload(payload.kind,'/api/intelligence/extended',payload);closeTaskCreator();await loadAutomationTasks();}catch(error){status.textContent=error.message;}}
async function loadExtendedTasks(){const container=document.getElementById('extended-tasks');try{const data=await intelligenceRequest('/api/intelligence/extended');if(!data.tasks.length){container.innerHTML='';return 0;}container.innerHTML=data.tasks.map(task=>{const schedule=task.schedule_type==='interval'?`每隔 ${formatNewsInterval(task.interval_minutes)}`:task.schedule;return `<div class="rounded-xl border border-cyan-200 dark:border-cyan-500/20 bg-white dark:bg-[#202020] p-5"><div class="flex flex-wrap justify-between gap-3"><div><span class="text-xs text-cyan-600">${EXTENDED_LABELS[task.kind]||task.kind}</span><h4 class="font-semibold mt-1">${escapeHtml(task.name)}</h4><p class="text-xs text-slate-400 mt-1">${escapeHtml(schedule)} · ${task.sources.length} 个来源</p></div><span class="px-2 py-1 rounded-full text-xs ${task.enabled?'bg-emerald-50 text-emerald-600':'bg-slate-100 text-slate-500'}">${task.enabled?'已启用':'已停用'}</span></div><p class="text-sm text-slate-500 mt-3">${escapeHtml(task.last_status||'等待执行')}</p><div class="flex gap-2 mt-4 flex-wrap"><button onclick="runExtendedTask('${task.id}',this)" class="px-3 py-1.5 rounded-lg bg-cyan-600 text-white text-xs">立即执行并生成报告</button><button onclick="toggleExtendedTask('${task.id}',${!task.enabled})" class="px-3 py-1.5 rounded-lg border text-xs">${task.enabled?'停用':'启用'}</button><button onclick="deleteExtendedTask('${task.id}')" class="px-3 py-1.5 text-red-500 text-xs">删除</button></div></div>`}).join('');return data.tasks.length;}catch(error){container.innerHTML=`<div class="py-8 text-center text-red-500">${escapeHtml(error.message)}</div>`;return 0;}}
async function runExtendedTask(id,button){return runAutomationTaskWithFeedback({id,button,endpoint:'/api/intelligence/extended/run',reportHost:'extended-report-content',reportPanel:'extended-report',runningText:'正在执行...',defaultText:'立即执行并生成报告'});}
async function toggleExtendedTask(id,enabled){await intelligenceRequest('/api/intelligence/extended/toggle',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({task_id:id,enabled})});loadAutomationTasks();}
async function deleteExtendedTask(id){if(!confirm('确定删除这个任务吗？'))return;try{await intelligenceRequest('/api/intelligence/extended/delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({task_id:id})});await loadAutomationTasks();}catch(error){alert(`删除失败：${error.message}`);}}

function toggleEmailScheduleFields(){const interval=document.getElementById('email-schedule-type').value==='interval';document.getElementById('email-daily-field').classList.toggle('hidden',interval);document.getElementById('email-interval-field').classList.toggle('hidden',!interval);}
function toggleEmailSourceFields(){const type=document.getElementById('email-source-type')?.value||'local';document.getElementById('email-local-path-field')?.classList.toggle('hidden',type!=='local');document.getElementById('email-folder-field')?.classList.toggle('hidden',type!=='imap');['email-imap-host','email-imap-port','email-smtp-host','email-smtp-port','email-username','email-password'].forEach(id=>{const label=document.getElementById(id)?.closest('label');if(label)label.classList.toggle('opacity-50',type!=='imap');});}
async function loadEmailSettings(){try{const data=await intelligenceRequest('/api/intelligence/email');const s=data.settings||{};const source=s.source_type||'local';const sourceNode=document.getElementById('email-source-type');if(sourceNode)sourceNode.value=source;const localNode=document.getElementById('email-local-path');if(localNode)localNode.value=s.local_path||'work/cow-workspace/emails';['imap_host','imap_port','smtp_host','smtp_port','username'].forEach(key=>{const node=document.getElementById(`email-${key.replace('_','-')}`);if(node&&s[key]!==undefined&&s[key]!==null)node.value=s[key];});if(s.imap_ssl!==undefined)document.getElementById('email-imap-ssl').checked=!!s.imap_ssl;if(s.smtp_ssl!==undefined)document.getElementById('email-smtp-ssl').checked=!!s.smtp_ssl;toggleEmailSourceFields();}catch(error){document.getElementById('email-form-status').textContent=error.message;}}
async function saveEmailTask(){const type=document.getElementById('email-schedule-type').value;const sourceType=document.getElementById('email-source-type')?.value||'local';const localPath=document.getElementById('email-local-path')?.value.trim()||'work/cow-workspace/emails';const folder=sourceType==='imap'?(document.getElementById('email-folder').value.trim()||'INBOX'):localPath;const interval=Number(document.getElementById('email-interval-value').value||0)*Number(document.getElementById('email-interval-unit').value||1);const payload={name:document.getElementById('email-name').value.trim(),source_type:sourceType,local_path:localPath,folder,unread_only:document.getElementById('email-unread-only').checked,max_messages:Number(document.getElementById('email-max-messages').value||20),recipient:document.getElementById('email-recipient').value.trim(),send_report:document.getElementById('email-send-report').checked,schedule_type:type,schedule:document.getElementById('email-schedule').value.trim(),interval_minutes:type==='interval'?interval:0,settings:{source_type:sourceType,local_path:localPath,imap_host:document.getElementById('email-imap-host').value.trim(),imap_port:Number(document.getElementById('email-imap-port').value||993),imap_ssl:document.getElementById('email-imap-ssl').checked,smtp_host:document.getElementById('email-smtp-host').value.trim(),smtp_port:Number(document.getElementById('email-smtp-port').value||465),smtp_ssl:document.getElementById('email-smtp-ssl').checked,username:document.getElementById('email-username').value.trim(),password:document.getElementById('email-password').value}};const status=document.getElementById('email-form-status');status.textContent='';try{await saveAutomationPayload('email','/api/intelligence/email',payload);document.getElementById('email-password').value='';closeTaskCreator();await loadAutomationTasks();}catch(error){status.textContent=error.message;}}
async function loadEmailTasks(){const container=document.getElementById('email-tasks');try{const data=await intelligenceRequest('/api/intelligence/email');if(!data.tasks.length){container.innerHTML='';return 0;}container.innerHTML=data.tasks.map(task=>{const source=task.source_type==='imap'?'在线邮箱':'本地邮件文件';const location=task.source_type==='imap'?(task.folder||'INBOX'):(task.local_path||task.folder||'work/cow-workspace/emails');return `<div class="rounded-xl border border-violet-200 dark:border-violet-500/20 bg-white dark:bg-[#202020] p-5"><div class="flex flex-wrap justify-between gap-3"><div><span class="text-xs text-violet-600">邮件秘书 · ${source}</span><h4 class="font-semibold mt-1">${escapeHtml(task.name)}</h4><p class="text-xs text-slate-400 mt-1">${escapeHtml(task.schedule_type==='interval'?`每隔 ${formatNewsInterval(task.interval_minutes)}`:task.schedule)} · ${escapeHtml(location)} · 最多 ${task.max_messages} 封</p></div><span class="px-2 py-1 rounded-full text-xs ${task.enabled?'bg-emerald-50 text-emerald-600':'bg-slate-100 text-slate-500'}">${task.enabled?'已启用':'已停用'}</span></div><p class="text-sm text-slate-500 mt-3">${escapeHtml(task.last_status||'等待执行')}</p><div class="flex gap-2 mt-4 flex-wrap"><button onclick="runEmailTask('${task.id}',this)" class="px-3 py-1.5 rounded-lg bg-violet-600 text-white text-xs">读取并分析邮件</button><button onclick="toggleEmailTask('${task.id}',${!task.enabled})" class="px-3 py-1.5 rounded-lg border text-xs">${task.enabled?'停用':'启用'}</button><button onclick="deleteEmailTask('${task.id}')" class="px-3 py-1.5 text-red-500 text-xs">删除</button></div></div>`;}).join('');return data.tasks.length;}catch(error){container.innerHTML=`<div class="py-8 text-center text-red-500">${escapeHtml(error.message)}</div>`;return 0;}}
async function runEmailTask(id,button){return runAutomationTaskWithFeedback({id,button,endpoint:'/api/intelligence/email/run',reportHost:'email-report-content',reportPanel:'email-report',runningText:'正在读取...',defaultText:'读取并分析邮件'});}
async function toggleEmailTask(id,enabled){await intelligenceRequest('/api/intelligence/email/toggle',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({task_id:id,enabled})});loadAutomationTasks();}
async function deleteEmailTask(id){if(!confirm('确定删除这个邮件任务吗？'))return;try{await intelligenceRequest('/api/intelligence/email/delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({task_id:id})});await loadAutomationTasks();}catch(error){alert(`删除失败：${error.message}`);}}

function maintenanceStatusClasses(status){if(!status||status==='idle'||status==='unknown')return 'bg-slate-100 text-slate-500 dark:bg-white/10 dark:text-slate-300';if(status==='success')return 'bg-emerald-50 text-emerald-600 dark:bg-emerald-500/10 dark:text-emerald-300';if(status==='acknowledged')return 'bg-slate-100 text-slate-500 dark:bg-white/10 dark:text-slate-300';if(status==='error'||status==='failed')return 'bg-red-50 text-red-600 dark:bg-red-500/10 dark:text-red-300';if(status==='running')return 'bg-blue-50 text-blue-600 dark:bg-blue-500/10 dark:text-blue-300';return 'bg-orange-50 text-orange-600 dark:bg-orange-500/10 dark:text-orange-300';}
function maintenanceTodoIcon(level){if(level==='success')return '<i class="fas fa-circle-check text-emerald-500"></i>';if(level==='error')return '<i class="fas fa-circle-exclamation text-red-500"></i>';return '<i class="fas fa-triangle-exclamation text-orange-500"></i>';}
function renderMaintenanceTrend(items){items=items||[];const totalRuns=items.reduce((sum,x)=>sum+Number(x.total||0),0),totalFailed=items.reduce((sum,x)=>sum+Number(x.failed||0),0),maxRate=Math.max(0,...items.map(x=>Number(x.rate||0)));if(!items.length||!totalRuns||(!totalFailed&&!maxRate))return `<div class="maintenance-trend-empty"><i class="fas fa-circle-check"></i><span>暂无失败趋势</span><small>近 7 天失败率为 0%</small></div>`;const max=Math.max(1,...items.map(x=>Number(x.total||0)));return `<div class="maintenance-trend-chart">${items.map(item=>{const total=Number(item.total||0),failed=Number(item.failed||0),height=Math.max(6,Math.round(total/max*58)),rate=Number(item.rate||0);return `<div class="maintenance-trend-item"><div class="maintenance-trend-rate">${rate}%</div><div class="maintenance-trend-bar ${failed?'is-failed':'is-ok'}" style="height:${height}px" title="${escapeHtml(item.date)}：${total} 次，失败 ${failed} 次"></div><div class="maintenance-trend-label">${escapeHtml(item.label||'')}</div></div>`;}).join('')}</div>`;}
function renderMaintenanceDashboard(data){const summary=data.summary||{},latest=data.latest||{},cache=data.cache||{},notifications=data.notifications||{},todos=data.todos||[],trend=data.failure_trend||[];const channelText=(notifications.channels||[]).length?(notifications.channels||[]).join('、'):'未配置';return `<div class="maintenance-summary-grid"><div class="maintenance-card"><div class="flex items-center justify-between"><span class="text-xs text-slate-400">最近维护状态</span><span class="px-2 py-0.5 rounded-full text-[11px] ${maintenanceStatusClasses(latest.status)}">${escapeHtml(latest.label||'待检查')}</span></div><div class="font-semibold mt-2">${escapeHtml(latest.task_name||'暂无维护任务')}</div><p class="text-xs text-slate-500 mt-2 line-clamp-2">${escapeHtml(latest.summary||'等待维护任务运行')}</p><div class="text-[11px] text-slate-400 mt-2">${escapeHtml(latest.at||data.checked_at||'')}</div></div><div class="maintenance-card"><div class="text-xs text-slate-400">自动化失败率趋势</div>${renderMaintenanceTrend(trend)}<div class="text-xs text-slate-500 mt-1">今日失败率 ${summary.automation_failure_rate||0}%</div></div><div class="maintenance-card"><div class="flex items-center justify-between"><span class="text-xs text-slate-400">缓存占用</span><span class="px-2 py-0.5 rounded-full text-[11px] ${maintenanceStatusClasses(cache.status)}">${cache.status==='success'?'正常':'需关注'}</span></div><div class="text-2xl font-bold mt-3">${Number(cache.total_mb||0)}<span class="text-sm ml-1">MB</span></div><p class="text-xs text-slate-500 mt-2">文件 ${Number(cache.file_count||0)} 个 · 阈值 ${Number(cache.threshold_mb||0)}MB</p></div><div class="maintenance-card"><div class="flex items-center justify-between"><span class="text-xs text-slate-400">通知通道状态</span><span class="px-2 py-0.5 rounded-full text-[11px] ${maintenanceStatusClasses(notifications.status)}">${notifications.status==='success'?'正常':notifications.status==='error'?'未启用':'需关注'}</span></div><div class="font-semibold mt-3 break-words leading-6">${escapeHtml(channelText)}</div><p class="text-xs text-slate-500 mt-2">近 7 天成功 ${Number(notifications.success||0)} 次，失败 ${Number(notifications.failed||0)} 次</p></div></div><div class="mt-4 maintenance-card"><div class="flex items-center justify-between gap-3"><h4 class="font-semibold">本周待处理项</h4><span class="text-xs text-slate-400">维护任务 ${Number(summary.enabled_count||0)}/${Number(summary.task_count||0)} 已启用</span></div><div class="grid md:grid-cols-2 gap-3 mt-3">${todos.map(item=>`<div class="flex gap-3 rounded-lg border border-slate-100 dark:border-white/10 p-3"><div class="mt-0.5">${maintenanceTodoIcon(item.level)}</div><div><div class="font-medium text-sm">${escapeHtml(item.title||'待处理项')}</div><p class="text-xs text-slate-500 mt-1">${escapeHtml(item.summary||'')}</p></div></div>`).join('')}</div></div>`;}
async function loadMaintenanceDashboard(force=false){const card=document.getElementById('maintenance-dashboard-card'),content=document.getElementById('maintenance-dashboard-content');if(!card||!content)return;card.classList.remove('hidden');if(force)content.innerHTML='<div class="text-cyan-600"><i class="fas fa-spinner fa-spin mr-1"></i>正在刷新维护看板...</div>';try{const data=await intelligenceRequest('/api/maintenance/dashboard');try{content.innerHTML=renderMaintenanceDashboard(data);maintenanceDashboardEnsureBackendButton(content);}catch(renderError){console.warn('[MaintenanceDashboard] render fallback',renderError);content.innerHTML=renderMaintenanceDashboardFallback(data,renderError);maintenanceDashboardEnsureBackendButton(content);}}catch(error){console.warn('[MaintenanceDashboard] load fallback',error);content.innerHTML=renderMaintenanceDashboardFallback({status:'warning',checked_at:new Date().toISOString(),summary:{task_count:0,enabled_count:0,automation_failure_rate:0,cache_mb:0,notification_status:'warning'},latest:{status:'warning',label:'加载降级',task_name:'维护看板暂时无法完整加载',summary:'页面已进入降级展示，可刷新或运行健康检查。'},cache:{status:'warning',total_mb:0,file_count:0,threshold_mb:500},notifications:{status:'warning',channels:[],success:0,failed:0},todos:[{level:'warning',title:'维护看板加载降级',summary:error.message||String(error)}]},error);maintenanceDashboardEnsureBackendButton(content);}}
function maintenanceDashboardEnsureBackendButton(root){try{if(!root)return;const status=root.querySelector('#maintenance-dashboard-action-status');if(!status||!status.parentElement)return;const bar=status.previousElementSibling;if(!bar||!bar.classList.contains('gap-2'))return;if(!root.querySelector('[data-maintenance-backend-check]')){const btn=document.createElement('button');btn.type='button';btn.dataset.maintenanceBackendCheck='1';btn.className='px-3 py-1.5 rounded-lg bg-slate-700 text-white text-xs';btn.innerHTML='<i class="fas fa-server mr-1"></i>后端实例检查';btn.onclick=function(){maintenanceDashboardCheckBackend(this);};bar.insertBefore(btn,bar.querySelector('[onclick*="maintenanceDashboardOpenRuns"]')||null);}if(!root.querySelector('[data-maintenance-backend-restart]')){const restart=document.createElement('button');restart.type='button';restart.dataset.maintenanceBackendRestart='1';restart.className='px-3 py-1.5 rounded-lg bg-rose-600 text-white text-xs';restart.innerHTML='<i class="fas fa-power-off mr-1"></i>安全重启后端';restart.onclick=function(){maintenanceDashboardRestartBackend(this);};bar.insertBefore(restart,bar.querySelector('[onclick*="maintenanceDashboardOpenRuns"]')||null);}}catch(e){console.warn('[MaintenanceDashboard] backend button skipped',e);}}
let backendStartupSelfCheckDone=false;
function backendStartupWarningSignature(data){return JSON.stringify({issues:data?.issues||[],extra:data?.extra_backend_pids||[],lock:data?.instance_lock?.pid||'',port:data?.port_pids||[]});}
function dismissBackendStartupWarning(){const el=document.getElementById('backend-startup-warning'),signature=el?.dataset?.signature;if(signature)localStorage.setItem('cow_backend_startup_warning_dismissed',signature);el?.remove();}
function showBackendStartupWarning(data){const signature=backendStartupWarningSignature(data);if(localStorage.getItem('cow_backend_startup_warning_dismissed')===signature)return;let el=document.getElementById('backend-startup-warning');if(!el){el=document.createElement('div');el.id='backend-startup-warning';el.className='fixed right-5 top-20 z-[320] max-w-[520px] rounded-2xl border border-orange-200 bg-orange-50 text-orange-800 shadow-2xl p-4 text-sm dark:border-orange-500/30 dark:bg-orange-500/10 dark:text-orange-200';document.body.appendChild(el);}el.dataset.signature=signature;const issues=(data?.issues||[]).map(x=>`<li>${escapeHtml(x)}</li>`).join(''),extra=(data?.extra_backend_pids||[]).length?`<div class="mt-2 text-xs">疑似旧实例 PID：${escapeHtml((data.extra_backend_pids||[]).join('、'))}</div>`:'';el.innerHTML=`<div class="flex items-start gap-3"><i class="fas fa-triangle-exclamation mt-0.5 text-orange-500"></i><div class="min-w-0 flex-1"><div class="font-semibold">检测到后端实例风险</div><ul class="mt-2 list-disc pl-5 space-y-1 text-xs">${issues||'<li>后端实例自检异常，请打开维护看板查看。</li>'}</ul>${extra}<div class="mt-3 flex flex-wrap gap-2"><button onclick="openSettingsCenter?.();setTimeout(()=>{showSettingsView?.('maintenance','维护看板');setTimeout(()=>maintenanceDashboardCheckBackend?.(),500);},150)" class="px-3 py-1.5 rounded-lg bg-orange-600 text-white text-xs">打开维护看板</button><button onclick="backendStartupCleanupLocks(this)" class="px-3 py-1.5 rounded-lg bg-white/80 dark:bg-black/20 border border-orange-200 dark:border-orange-500/30 text-xs">清理过期锁</button><button onclick="dismissBackendStartupWarning()" class="px-3 py-1.5 rounded-lg bg-white/80 dark:bg-black/20 border border-orange-200 dark:border-orange-500/30 text-xs">暂不处理</button></div></div></div>`;}
async function backendStartupCleanupLocks(button){const old=button?.innerHTML;if(button){button.disabled=true;button.innerHTML='<i class="fas fa-spinner fa-spin mr-1"></i>清理中';}try{const response=await fetch('/api/backend-instances',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'cleanup_stale_locks'}),cache:'no-store'}),data=await response.json();if((data.issues||[]).length)showBackendStartupWarning(data);else{document.getElementById('backend-startup-warning')?.remove();_wsToast?.(data.message||'后端残留锁清理完成');}}catch(error){_wsToast?.(`清理失败：${error.message||error}`);}finally{if(button){button.disabled=false;button.innerHTML=old;}}}
function runBackendStartupSelfCheck(){if(backendStartupSelfCheckDone)return;backendStartupSelfCheckDone=true;setTimeout(async()=>{try{const response=await fetch('/api/backend-instances',{cache:'no-store'});const data=await response.json();const issues=data.issues||[];if(issues.length)showBackendStartupWarning(data);else if(Number(data.stale_lock_count||0)>0){fetch('/api/backend-instances',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'cleanup_stale_locks'}),cache:'no-store'}).catch(()=>{});}}catch(error){showBackendStartupWarning({issues:[`后端实例自检失败：${error.message||error}`]});}},1200);}
function runWecomOwnershipStartupCheck(){setTimeout(async()=>{try{const response=await fetch('/api/channels/health?channel=wecom_bot',{cache:'no-store'}),data=await response.json(),item=(data.channels||[])[0]||{},runtime=item.runtime||{};if(!item.active&&!item.configured)return;const suspicious=runtime.recently_taken_over||runtime.owner_matches_current===false||runtime.state==='takeover';if(!suspicious)return;showBackendStartupWarning({issues:[item.message||'企业微信长连接疑似被旧实例接管，已尝试触发重连。']});fetch('/api/channels/health',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({channel:'wecom_bot',action:'reconnect'})}).then(()=>setTimeout(()=>refreshChannelHealth?.(),1800)).catch(()=>{});}catch(_error){}},2200);}
function renderMaintenanceDashboardFallback(data={},error=null){const latest=data.latest||{},summary=data.summary||{},todos=data.todos||[];return `<div class="rounded-xl border border-orange-200 dark:border-orange-500/20 bg-orange-50/70 dark:bg-orange-500/10 p-4 text-orange-700 dark:text-orange-300"><div class="font-semibold"><i class="fas fa-triangle-exclamation mr-2"></i>维护看板降级展示</div><p class="mt-2 text-sm">${escapeHtml(error?.message||data.message||'看板局部数据异常，但自动化任务仍可继续运行。')}</p><button onclick="loadMaintenanceDashboard(true)" class="mt-3 px-3 py-1.5 rounded-lg bg-orange-600 text-white text-xs">重新刷新</button></div><div class="grid md:grid-cols-3 gap-3 mt-4"><div class="rounded-xl bg-white/80 dark:bg-white/5 border border-slate-100 dark:border-white/10 p-4"><span class="text-xs text-slate-400">最近维护状态</span><div class="font-semibold mt-2">${escapeHtml(latest.task_name||'暂无维护记录')}</div><p class="text-xs text-slate-500 mt-2">${escapeHtml(latest.summary||'等待维护检查')}</p></div><div class="rounded-xl bg-white/80 dark:bg-white/5 border border-slate-100 dark:border-white/10 p-4"><span class="text-xs text-slate-400">自动化失败率</span><div class="text-2xl font-bold mt-2">${Number(summary.automation_failure_rate||0)}%</div></div><div class="rounded-xl bg-white/80 dark:bg-white/5 border border-slate-100 dark:border-white/10 p-4"><span class="text-xs text-slate-400">通知状态</span><div class="font-semibold mt-2">${escapeHtml(summary.notification_status||'待检查')}</div></div></div><div class="mt-4 rounded-xl bg-white/80 dark:bg-white/5 border border-slate-100 dark:border-white/10 p-4"><h4 class="font-semibold">本周待处理项</h4><div class="grid md:grid-cols-2 gap-3 mt-3">${(todos.length?todos:[{level:'warning',title:'建议刷新看板',summary:'如仍异常，请运行维护健康检查。'}]).map(item=>`<div class="flex gap-3 rounded-lg border border-slate-100 dark:border-white/10 p-3"><div>${maintenanceTodoIcon(item.level)}</div><div><div class="font-medium text-sm">${escapeHtml(item.title||'待处理项')}</div><p class="text-xs text-slate-500 mt-1">${escapeHtml(item.summary||'')}</p></div></div>`).join('')}</div></div>`;}

function maintenanceDashboardNotice(message,tone='blue'){const host=document.getElementById('maintenance-dashboard-action-status');if(!host)return;const cls={blue:'bg-blue-50 text-blue-700 dark:bg-blue-500/10 dark:text-blue-300',green:'bg-emerald-50 text-emerald-700 dark:bg-emerald-500/10 dark:text-emerald-300',orange:'bg-orange-50 text-orange-700 dark:bg-orange-500/10 dark:text-orange-300',red:'bg-red-50 text-red-700 dark:bg-red-500/10 dark:text-red-300'}[tone]||'bg-blue-50 text-blue-700 dark:bg-blue-500/10 dark:text-blue-300';host.className=`mt-4 rounded-xl px-4 py-3 text-xs ${cls}`;host.innerHTML=escapeHtml(message);}
function maintenanceDashboardNoticeHtml(html,tone='blue'){const host=document.getElementById('maintenance-dashboard-action-status');if(!host)return;const cls={blue:'bg-blue-50 text-blue-700 dark:bg-blue-500/10 dark:text-blue-300',green:'bg-emerald-50 text-emerald-700 dark:bg-emerald-500/10 dark:text-emerald-300',orange:'bg-orange-50 text-orange-700 dark:bg-orange-500/10 dark:text-orange-300',red:'bg-red-50 text-red-700 dark:bg-red-500/10 dark:text-red-300'}[tone]||'bg-blue-50 text-blue-700 dark:bg-blue-500/10 dark:text-blue-300';host.className=`mt-4 rounded-xl px-4 py-3 text-xs ${cls}`;host.innerHTML=html;}
async function maintenanceDashboardAction(button,label,runner){const old=button?.innerHTML;if(button){button.disabled=true;button.innerHTML='<i class="fas fa-spinner fa-spin mr-1"></i>处理中';}maintenanceDashboardNotice(`${label}处理中…`,'blue');try{const result=await runner();await loadMaintenanceDashboard(true);maintenanceDashboardNotice(result?.message||`${label}完成，维护看板已刷新。`,'green');_wsToast?.(result?.message||`${label}完成`);return result;}catch(error){const message=error.message||String(error);maintenanceDashboardNotice(`${label}失败：${message}`,'red');_wsToast?.(`${label}失败：${message}`);throw error;}finally{if(button){button.disabled=false;button.innerHTML=old;}}}
async function maintenanceDashboardRunReadiness(button){return maintenanceDashboardAction(button,'维护健康检查',async()=>{const data=await intelligenceRequest('/api/maintenance/readiness');if(typeof loadArtifactCenter==='function')loadArtifactCenter(true);else if(typeof loadArtifacts==='function')loadArtifacts();return {message:data.status==='success'?'维护健康检查通过，报告已保存到产物/交付物。':data.status==='error'?'维护健康检查完成，发现阻断项，报告已保存。':'维护健康检查完成，发现优化项，报告已保存。'};});}
async function maintenanceDashboardGeneratePlan(button){return maintenanceDashboardAction(button,'生成维护计划',async()=>{const data=await intelligenceRequest('/api/maintenance/plan');if(typeof loadArtifactCenter==='function')loadArtifactCenter(true);else if(typeof loadArtifacts==='function')loadArtifacts();const s=data.summary||{};return {message:`维护计划已生成：立即 ${s.immediate||0} 项，每日 ${s.daily||0} 项，每周 ${s.weekly||0} 项，已保存到产物/交付物。`};});}
async function maintenanceDashboardCreateSchedule(button){return maintenanceDashboardAction(button,'创建维护定时任务',async()=>{const data=await intelligenceRequest('/api/maintenance/schedule',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({})});if(data.status&&data.status!=='success')throw new Error(data.message||'创建失败');await loadAutomationTasks();return {message:data.message||'维护定时任务已创建/更新。'};});}
async function maintenanceDashboardCheckBackend(button){const old=button?.innerHTML;if(button){button.disabled=true;button.innerHTML='<i class="fas fa-spinner fa-spin mr-1"></i>检查中';}maintenanceDashboardNotice('正在检查后端实例、端口和调度锁…','blue');try{const data=await intelligenceRequest('/api/backend-instances');const issues=data.issues||[],locks=Number(data.stale_lock_count||0),tone=issues.length?'orange':'green';const rows=[`当前进程：${data.current_pid||'-'}`,`Web端口：${data.web_port||9899} · 监听PID：${(data.port_pids||[]).join('、')||'未监听'}`,`单实例锁：${data.instance_lock?.is_current?'当前实例':'需关注'}`,`过期调度锁：${locks} 个`].map(x=>`<div class="py-1">${escapeHtml(x)}</div>`).join('');const issueHtml=issues.length?`<div class="mt-2 text-orange-600">${issues.map(x=>`<div>• ${escapeHtml(x)}</div>`).join('')}</div>`:'<div class="mt-2 text-emerald-600">后端实例状态正常。</div>';maintenanceDashboardNoticeHtml(`<div class="font-semibold mb-2"><i class="fas fa-server mr-1"></i>后端实例健康检查</div>${rows}${issueHtml}<div class="mt-3 flex flex-wrap gap-2"><button onclick="maintenanceDashboardCleanupBackend(this)" class="px-3 py-1.5 rounded-lg bg-cyan-600 text-white text-xs">一键清理过期锁</button><button onclick="maintenanceDashboardCheckBackend(this)" class="px-3 py-1.5 rounded-lg border text-xs">重新检查</button></div>`,tone);}catch(error){maintenanceDashboardNotice(`后端实例检查失败：${error.message||error}`,'red');}finally{if(button){button.disabled=false;button.innerHTML=old;}}}
async function maintenanceDashboardRestartBackend(button){if(!confirm('确认安全重启当前后端吗？系统只会重启当前 9899 对应实例，页面会自动等待恢复。'))return;const old=button?.innerHTML;if(button){button.disabled=true;button.innerHTML='<i class="fas fa-spinner fa-spin mr-1"></i>重启中';}maintenanceDashboardNotice('正在安全重启当前后端实例，请稍候…','orange');try{const response=await fetch('/api/backend-restart',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({}),cache:'no-store'}),data=await response.json();if(data.status!=='success')throw new Error(data.message||'安全重启失败');maintenanceDashboardNotice(`安全重启已发起，旧进程 ${data.old_pid||'-'}，正在等待新后端恢复…`,'orange');await maintenanceDashboardWaitBackendRestart(data.old_pid,button,old);}catch(error){maintenanceDashboardNotice(`安全重启失败：${error.message||error}`,'red');if(button){button.disabled=false;button.innerHTML=old;}}}
async function maintenanceDashboardWaitBackendRestart(oldPid,button,oldHtml){let lastError='';for(let attempt=0;attempt<40;attempt++){await new Promise(resolve=>setTimeout(resolve,1500));try{const response=await fetch('/api/backend-instances',{cache:'no-store'});const data=await response.json();if(data.status&&(Number(data.current_pid||0)!==Number(oldPid||0))&&!(data.issues||[]).length){const checks=await maintenanceDashboardPostRestartChecks();const rows=[`新后端进程：${data.current_pid}`,`Web端口：${data.web_port||9899}`,`企业微信：${checks.wecom}`,`微信：${checks.weixin}`,`定时任务：${checks.scheduler}`].map(x=>`<div class="py-1">${escapeHtml(x)}</div>`).join('');maintenanceDashboardNoticeHtml(`<div class="font-semibold mb-2 text-emerald-700 dark:text-emerald-200"><i class="fas fa-circle-check mr-1"></i>后端安全重启完成</div>${rows}<div class="mt-2 text-[11px] text-slate-500">如企业微信仍显示未就绪，请稍等长连接自动重连或发送测试消息。</div>`,'green');_wsToast?.('后端安全重启完成');if(button){button.disabled=false;button.innerHTML=oldHtml;}return data;}lastError=(data.issues||[]).join('；')||'等待新实例接管';}catch(error){lastError=error.message||String(error);}}maintenanceDashboardNotice(`安全重启已发起，但自动验证超时：${lastError}。请稍后点击“后端实例检查”。`,'orange');if(button){button.disabled=false;button.innerHTML=oldHtml;}}
async function maintenanceDashboardPostRestartChecks(){const result={wecom:'未检测',weixin:'未检测',scheduler:'未检测'};try{const response=await fetch('/api/channels/health',{cache:'no-store'}),data=await response.json(),items=data.channels||[];const pick=name=>items.find(x=>x.channel===name)||{};const wecom=pick('wecom_bot'),weixin=pick('weixin');result.wecom=wecom.ok?'正常':(wecom.message||'需检查');result.weixin=weixin.ok?'正常':(weixin.message||'需检查');}catch(error){result.wecom=result.weixin=`检测失败：${error.message||error}`;}try{const response=await fetch('/api/scheduler',{cache:'no-store'}),data=await response.json();const tasks=data.tasks||[];result.scheduler=`可用，任务 ${tasks.length} 个`;}catch(error){result.scheduler=`检测失败：${error.message||error}`;}return result;}
async function maintenanceDashboardCleanupBackend(button){return maintenanceDashboardAction(button,'清理后端残留锁',async()=>{const data=await intelligenceRequest('/api/backend-instances',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'cleanup_stale_locks'})});return {message:data.message||'后端残留锁清理完成。'};});}
async function maintenanceDashboardPreviewCache(button){const old=button?.innerHTML;if(button){button.disabled=true;button.innerHTML='<i class="fas fa-spinner fa-spin mr-1"></i>扫描中';}maintenanceDashboardNotice('正在扫描可安全清理的缓存文件…','blue');try{const data=await intelligenceRequest('/api/maintenance/cache-cleanup');const items=data.items||[];if(!items.length){maintenanceDashboardNotice('当前没有可清理的缓存文件。','green');await loadMaintenanceDashboard(true);return;}const rows=items.slice(0,8).map(item=>`<div class="flex justify-between gap-3 py-1 border-t border-blue-100/60 dark:border-blue-500/10 first:border-t-0"><span class="truncate">${escapeHtml(item.relative||item.name||'缓存文件')}</span><span class="shrink-0">${Number(item.size_kb||0)} KB</span></div>`).join('');maintenanceDashboardNoticeHtml(`<div class="font-semibold mb-2"><i class="fas fa-broom mr-1"></i>发现 ${Number(data.total_files||0)} 个可安全清理文件，约 ${Number(data.total_mb||0)} MB</div><div class="rounded-lg bg-white/60 dark:bg-black/10 p-2 max-h-48 overflow-auto">${rows}${data.truncated?'<div class="pt-1 text-slate-400">仅预览前 300 个文件，清理会按本次安全范围处理。</div>':''}</div><div class="mt-3 flex flex-wrap gap-2"><button onclick="maintenanceDashboardConfirmCache(this)" class="px-3 py-1.5 rounded-lg bg-teal-600 text-white text-xs">确认安全清理到回收区</button><button onclick="maintenanceDashboardOpenSettings('knowledge','数据管理')" class="px-3 py-1.5 rounded-lg border text-xs">打开数据管理</button></div>`,'blue');}catch(error){maintenanceDashboardNotice(`缓存预览失败：${error.message||error}`,'red');}finally{if(button){button.disabled=false;button.innerHTML=old;}}}
async function maintenanceDashboardConfirmCache(button){if(!confirm('确认把这些缓存文件移动到项目回收区吗？不会直接永久删除。'))return;return maintenanceDashboardAction(button,'安全清理缓存',async()=>{const data=await intelligenceRequest('/api/maintenance/cache-cleanup',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({})});if(data.status==='error')throw new Error(data.message||'清理失败');return {message:`${data.message||'缓存已安全清理'}${data.trash_dir?` 回收区：${data.trash_dir}`:''}`};});}
async function maintenanceDashboardRetryRun(runId,button){return maintenanceDashboardAction(button,'按推荐参数重试',async()=>{const data=await intelligenceRequest('/api/intelligence/runs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({run_id:runId})});const actions=data.recovery_retry_actions||[];await Promise.all([loadAutomationRuns?.().catch(()=>{}),loadAutomationRecords?.(true).catch(()=>{}),loadAutomationNotifications?.().catch(()=>{}),loadNotificationCenter?.().catch(()=>{})]);return {message:actions.length?`已按推荐参数重试：${actions.slice(0,3).join('；')}`:'失败任务已重新执行，维护看板已刷新。'};});}
async function maintenanceDashboardRetryAll(button){const ids=[...document.querySelectorAll('[data-maintenance-failed-run]')].map(node=>node.dataset.maintenanceFailedRun).filter(Boolean);if(!ids.length)return maintenanceDashboardNotice('当前没有可重试的失败任务。','green');return maintenanceDashboardAction(button,'一键重试失败任务',async()=>{let ok=0,fail=0;for(const runId of ids){try{await intelligenceRequest('/api/intelligence/runs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({run_id:runId})});ok++;}catch(_error){fail++;}}await Promise.all([loadAutomationRuns?.().catch(()=>{}),loadAutomationRecords?.(true).catch(()=>{}),loadAutomationNotifications?.().catch(()=>{}),loadNotificationCenter?.().catch(()=>{})]);return {message:`失败任务重试完成：成功 ${ok} 个，失败 ${fail} 个。`};});}
function maintenanceDashboardOpenRuns(filter='failed'){navigateTo('intelligence');setTimeout(()=>{switchAutomationTab('runs');const status=document.getElementById('automation-run-status'),trigger=document.getElementById('automation-run-trigger'),recovery=document.getElementById('automation-run-recovery');if(status)status.value=filter==='all'?'':filter;if(trigger)trigger.value='';if(recovery)recovery.value='';setFilterChipState?.('.automation-run-filter-chip','data-run-filter',filter||'all');loadAutomationRuns?.();},80);}
function maintenanceDashboardOpenNotifications(statusValue='failed'){navigateTo('intelligence');setTimeout(()=>{switchAutomationTab('notifications');const status=document.getElementById('automation-notification-status');if(status)status.value=statusValue||'';loadAutomationNotifications?.();},80);}
function maintenanceDashboardOpenSettings(view,title){openSettingsCenter?.();setTimeout(()=>showSettingsView?.(view,title),60);}
function maintenanceDashboardTodoActions(item){const title=String(item?.title||''),summary=String(item?.summary||''),text=title+summary;if(/通知|通道|Webhook|微信|邮箱/.test(text))return '<button onclick="maintenanceDashboardOpenSettings(\'channels\',\'通道与连接\')" class="mt-2 px-2.5 py-1 rounded-lg bg-blue-600 text-white text-[11px]">配置通道</button><button onclick="maintenanceDashboardOpenNotifications(\'failed\')" class="mt-2 ml-2 px-2.5 py-1 rounded-lg border text-[11px]">看通知失败</button>';if(/缓存|临时文件|清理/.test(text))return '<button onclick="maintenanceDashboardPreviewCache(this)" class="mt-2 px-2.5 py-1 rounded-lg bg-teal-600 text-white text-[11px]">预览可清理内容</button><button onclick="maintenanceDashboardOpenSettings(\'knowledge\',\'数据管理\')" class="mt-2 ml-2 px-2.5 py-1 rounded-lg border text-[11px]">数据管理</button>';if(/未启用自动维护|维护任务|定时任务/.test(text))return '<button onclick="maintenanceDashboardCreateSchedule(this)" class="mt-2 px-2.5 py-1 rounded-lg bg-cyan-600 text-white text-[11px]">一键创建维护任务</button>';if(/失败率|失败|暂无内容|无结果/.test(text))return '<button onclick="maintenanceDashboardOpenRuns(\'failed\')" class="mt-2 px-2.5 py-1 rounded-lg bg-red-600 text-white text-[11px]">查看失败会话</button><button onclick="maintenanceDashboardRunReadiness(this)" class="mt-2 ml-2 px-2.5 py-1 rounded-lg border text-[11px]">重新检查</button>';return '<button onclick="maintenanceDashboardRunReadiness(this)" class="mt-2 px-2.5 py-1 rounded-lg bg-cyan-600 text-white text-[11px]">立即检查</button>';}
function renderMaintenanceFailedRuns(items){items=items||[];if(!items.length)return '';const retryable=items.filter(item=>item.can_retry).length;return `<div class="mt-4 rounded-xl bg-white/80 dark:bg-white/5 border border-red-100 dark:border-red-500/20 p-4"><div class="flex flex-wrap items-center justify-between gap-3"><h4 class="font-semibold"><i class="fas fa-triangle-exclamation text-red-500 mr-2"></i>最近失败任务</h4><div class="flex gap-2">${retryable?`<button onclick="maintenanceDashboardRetryAll(this)" class="px-2.5 py-1 rounded-lg bg-red-600 text-white text-[11px]">一键重试全部</button>`:''}<button onclick="maintenanceDashboardOpenRuns('failed')" class="text-xs text-primary-500 hover:underline">查看全部失败会话</button></div></div><div class="grid md:grid-cols-2 gap-3 mt-3">${items.map(item=>{const meta=automationRunStatusMeta(item.status);return `<div class="rounded-lg border border-slate-100 dark:border-white/10 p-3" ${item.can_retry?`data-maintenance-failed-run="${escapeHtml(item.run_id||'')}"`:''}><div class="flex items-start justify-between gap-2"><div class="min-w-0"><div class="text-[11px] text-slate-400">${escapeHtml(item.kind||'自动化')} · ${escapeHtml(String(item.at||'').replace('T',' ').slice(0,19))}</div><div class="font-medium text-sm truncate mt-1">${escapeHtml(item.task_name||'失败任务')}</div></div><span class="shrink-0 px-2 py-0.5 rounded-full text-[11px] ${meta.badge}">${meta.label}</span></div><p class="mt-2 text-xs text-slate-500 line-clamp-2">${escapeHtml(item.reason||'任务未成功')}</p><div class="mt-3 flex flex-wrap gap-2">${item.can_retry?`<button onclick="maintenanceDashboardRetryRun('${escapeHtml(item.run_id||'')}',this)" class="px-2.5 py-1 rounded-lg bg-red-600 text-white text-[11px]">按推荐参数重试</button>`:''}<button onclick="showAutomationRun('${escapeHtml(item.run_id||'')}')" class="px-2.5 py-1 rounded-lg border text-[11px]">查看详情</button></div></div>`}).join('')}</div></div>`;}
function renderMaintenanceRecoveryRuns(items){items=items||[];if(!items.length)return '';return `<div class="mt-4 rounded-xl bg-white/80 dark:bg-white/5 border border-blue-100 dark:border-blue-500/20 p-4"><div class="flex items-center justify-between gap-3"><h4 class="font-semibold"><i class="fas fa-rotate-right text-blue-500 mr-2"></i>最近恢复重试</h4><button onclick="maintenanceDashboardOpenRuns('all')" class="text-xs text-primary-500 hover:underline">查看运行记录</button></div><div class="grid md:grid-cols-2 gap-3 mt-3">${items.map(item=>{const meta=automationRunStatusMeta(item.status),actions=(item.actions||[]).slice(0,3).map(x=>`<span class="rounded-full bg-blue-50 text-blue-600 dark:bg-blue-500/10 px-2 py-0.5 text-[11px]">${escapeHtml(x)}</span>`).join('');return `<div class="rounded-lg border border-slate-100 dark:border-white/10 p-3"><div class="flex items-start justify-between gap-2"><div class="min-w-0"><div class="text-[11px] text-slate-400">${escapeHtml(item.kind||'自动化')} · ${escapeHtml(String(item.at||'').replace('T',' ').slice(0,19))}</div><div class="font-medium text-sm truncate mt-1">${escapeHtml(item.task_name||'恢复重试')}</div></div><span class="shrink-0 px-2 py-0.5 rounded-full text-[11px] ${meta.badge}">${meta.label}</span></div><p class="mt-2 text-xs text-slate-500 line-clamp-2">${escapeHtml(item.summary||'恢复重试已记录')}</p>${actions?`<div class="mt-3 flex flex-wrap gap-1.5">${actions}</div>`:''}<div class="mt-3 flex flex-wrap gap-2"><button onclick="showAutomationRun('${escapeHtml(item.run_id||'')}')" class="px-2.5 py-1 rounded-lg border text-[11px]">查看重试详情</button>${item.source_run_id?`<button onclick="showAutomationRun('${escapeHtml(item.source_run_id||'')}')" class="px-2.5 py-1 rounded-lg border text-[11px]">查看原失败</button>`:''}</div></div>`}).join('')}</div></div>`;}
function renderMaintenanceInstanceSkips(items){items=items||[];if(!items.length)return '';return `<div class="mt-4 rounded-xl bg-white/80 dark:bg-white/5 border border-blue-100 dark:border-blue-500/20 p-4"><div class="flex flex-wrap items-center justify-between gap-3"><h4 class="font-semibold"><i class="fas fa-shield-halved text-blue-500 mr-2"></i>实例保护跳过</h4><button onclick="maintenanceDashboardOpenRuns('skipped_instance')" class="text-xs text-primary-500 hover:underline">查看相关记录</button></div><p class="mt-2 text-xs text-slate-500">这些记录表示旧后端或残留实例尝试执行任务时已被拦截，避免重复发送或重复生成内容。</p><div class="grid md:grid-cols-2 gap-3 mt-3">${items.map(item=>{const meta=automationRunStatusMeta('skipped_instance');return `<div class="rounded-lg border border-slate-100 dark:border-white/10 p-3"><div class="flex items-start justify-between gap-2"><div class="min-w-0"><div class="text-[11px] text-slate-400">${escapeHtml(item.kind||'自动化')} · ${escapeHtml(String(item.at||'').replace('T',' ').slice(0,19))}</div><div class="font-medium text-sm truncate mt-1">${escapeHtml(item.task_name||'实例保护')}</div></div><span class="shrink-0 px-2 py-0.5 rounded-full text-[11px] ${meta.badge}">${meta.label}</span></div><p class="mt-2 text-xs text-slate-500 line-clamp-2">${escapeHtml(item.reason||'旧实例已跳过本次执行')}</p>${item.run_id?`<div class="mt-3"><button onclick="showAutomationRun('${escapeHtml(item.run_id||'')}')" class="px-2.5 py-1 rounded-lg border text-[11px]">查看详情</button></div>`:''}</div>`}).join('')}</div></div>`;}
function renderInstanceGuardTrend(items){items=items||[];if(!items.length)return '';const max=Math.max(1,...items.map(x=>Number(x.count||0)));return `<div class="mt-4 rounded-xl bg-white/80 dark:bg-white/5 border border-blue-100 dark:border-blue-500/20 p-4"><div class="flex items-center justify-between gap-3"><div><h4 class="font-semibold"><i class="fas fa-chart-column text-blue-500 mr-2"></i>实例保护历史趋势</h4><p class="mt-1 text-xs text-slate-400">查看近 7 天是否反复出现旧实例或残留后端触发任务。</p></div><button onclick="maintenanceDashboardOpenRuns('skipped_instance')" class="text-xs text-primary-500 hover:underline">看跳过记录</button></div><div class="grid grid-cols-7 gap-2 items-end h-28 mt-3">${items.map(item=>{const count=Number(item.count||0),height=Math.max(8,Math.round(count/max*76));return `<div class="flex flex-col items-center justify-end gap-1"><div class="text-[10px] ${count?'text-blue-600':'text-slate-400'}">${count}</div><div class="w-full rounded-t-lg ${count?'bg-blue-500':'bg-slate-200 dark:bg-white/10'}" style="height:${height}px" title="${escapeHtml(item.date||'')}：${count} 次"></div><div class="text-[10px] text-slate-400">${escapeHtml(item.label||'')}</div></div>`;}).join('')}</div></div>`;}
function renderBackendRestartActions(items){items=items||[];if(!items.length)return '';const label={started:'已发起',helper_started_new_backend:'新后端已拉起',completed:'已完成',failed:'失败'};return `<div class="mt-4 rounded-xl bg-white/80 dark:bg-white/5 border border-rose-100 dark:border-rose-500/20 p-4"><div class="flex items-center justify-between gap-3"><div><h4 class="font-semibold"><i class="fas fa-power-off text-rose-500 mr-2"></i>安全重启动作记录</h4><p class="mt-1 text-xs text-slate-400">记录谁触发、何时触发、重启前后进程状态，方便追踪。</p></div><button onclick="maintenanceDashboardCheckBackend(this)" class="text-xs text-primary-500 hover:underline">检查当前实例</button></div><div class="mt-3 space-y-2">${items.map(item=>`<div class="rounded-lg border border-slate-100 dark:border-white/10 px-3 py-2 text-xs"><div class="flex flex-wrap items-center justify-between gap-2"><b>${escapeHtml(label[item.status]||item.status||'动作记录')}</b><span class="text-slate-400">${escapeHtml(String(item.updated_at||item.created_at||'').replace('T',' ').slice(0,19))}</span></div><p class="mt-1 text-slate-500">${escapeHtml(item.summary||'安全重启动作已记录')}</p><div class="mt-1 text-[11px] text-slate-400">触发：${escapeHtml(item.actor||'-')} · 旧 PID：${escapeHtml(String(item.old_pid||'-'))}${item.new_pid?` · 新 PID：${escapeHtml(String(item.new_pid))}`:''} · 端口：${escapeHtml(String(item.web_port||'-'))}</div></div>`).join('')}</div></div>`;}
function renderMaintenanceInstanceAlert(alert){alert=alert||{};if(!alert.active)return '';return `<div class="mb-4 rounded-2xl border border-orange-200 dark:border-orange-500/30 bg-orange-50/90 dark:bg-orange-500/10 p-4 text-orange-800 dark:text-orange-200"><div class="flex flex-wrap items-start justify-between gap-3"><div class="min-w-0"><div class="font-semibold"><i class="fas fa-triangle-exclamation mr-2"></i>${escapeHtml(alert.title||'疑似存在残留后端实例')}</div><p class="mt-1 text-sm leading-6">${escapeHtml(alert.summary||'实例保护已拦截旧实例执行任务，建议检查后端实例并按需安全重启。')}</p>${alert.latest_task?`<p class="mt-1 text-xs opacity-80">最近跳过：${escapeHtml(alert.latest_task)}${alert.latest_at?` · ${escapeHtml(String(alert.latest_at).replace('T',' ').slice(0,19))}`:''}</p>`:''}</div><div class="shrink-0 flex flex-wrap gap-2"><button onclick="maintenanceDashboardCheckBackend(this)" class="px-3 py-1.5 rounded-lg bg-orange-600 text-white text-xs">检查实例</button><button onclick="maintenanceDashboardCleanupBackend(this)" class="px-3 py-1.5 rounded-lg bg-white/80 dark:bg-black/20 border border-orange-200 dark:border-orange-500/30 text-xs">清理残留锁</button><button onclick="maintenanceDashboardRestartBackend(this)" class="px-3 py-1.5 rounded-lg bg-rose-600 text-white text-xs">安全重启</button></div></div></div>`;}
function renderMaintenanceInstanceAlert(alert){alert=alert||{};if(!alert.active)return '';const fix=alert.auto_remediation||{},fixTone=fix.level==='success'?'text-emerald-700 dark:text-emerald-200 bg-emerald-50/80 dark:bg-emerald-500/10 border-emerald-100 dark:border-emerald-500/20':'text-orange-700 dark:text-orange-200 bg-white/70 dark:bg-black/10 border-orange-100 dark:border-orange-500/20';return `<div class="mb-4 rounded-2xl border border-orange-200 dark:border-orange-500/30 bg-orange-50/90 dark:bg-orange-500/10 p-4 text-orange-800 dark:text-orange-200"><div class="flex flex-wrap items-start justify-between gap-3"><div class="min-w-0"><div class="font-semibold"><i class="fas fa-triangle-exclamation mr-2"></i>${escapeHtml(alert.title||'疑似存在残留后端实例')}</div><p class="mt-1 text-sm leading-6">${escapeHtml(alert.summary||'实例保护已拦截旧实例执行任务，建议检查后端实例并按需安全重启。')}</p>${fix.summary?`<div class="mt-2 rounded-xl border ${fixTone} px-3 py-2 text-xs"><i class="fas ${fix.removed_count?'fa-broom':'fa-shield-heart'} mr-1"></i>${escapeHtml(fix.summary)}${fix.at?`<span class="ml-2 opacity-70">${escapeHtml(String(fix.at).replace('T',' ').slice(0,19))}</span>`:''}</div>`:''}${alert.latest_task?`<p class="mt-1 text-xs opacity-80">最近跳过：${escapeHtml(alert.latest_task)}${alert.latest_at?` · ${escapeHtml(String(alert.latest_at).replace('T',' ').slice(0,19))}`:''}</p>`:''}</div><div class="shrink-0 flex flex-wrap gap-2"><button onclick="maintenanceDashboardCheckBackend(this)" class="px-3 py-1.5 rounded-lg bg-orange-600 text-white text-xs">检查实例</button><button onclick="maintenanceDashboardCleanupBackend(this)" class="px-3 py-1.5 rounded-lg bg-white/80 dark:bg-black/20 border border-orange-200 dark:border-orange-500/30 text-xs">清理残留锁</button><button onclick="maintenanceDashboardRestartBackend(this)" class="px-3 py-1.5 rounded-lg bg-rose-600 text-white text-xs">安全重启</button></div></div></div>`;}
function renderMaintenanceRecoveryEffectiveness(data){data=data||{};const items=data.items||[],summary=data.summary||{};const toneClass={success:'bg-emerald-50 text-emerald-600 dark:bg-emerald-500/10 dark:text-emerald-300',warning:'bg-orange-50 text-orange-600 dark:bg-orange-500/10 dark:text-orange-300',danger:'bg-red-50 text-red-600 dark:bg-red-500/10 dark:text-red-300'};if(!items.length)return `<div class="mt-4 rounded-xl bg-white/80 dark:bg-white/5 border border-indigo-100 dark:border-indigo-500/20 p-4"><div class="flex items-center justify-between gap-3"><h4 class="font-semibold"><i class="fas fa-chart-line text-indigo-500 mr-2"></i>恢复策略效果</h4><button onclick="switchAutomationTab('agent2')" class="text-xs text-primary-500 hover:underline">查看 Agent 2.0</button></div><p class="mt-3 text-sm text-slate-500">暂无恢复策略样本。后续失败任务完成兜底或按推荐参数重试后，会自动沉淀成功率。</p></div>`;return `<div class="mt-4 rounded-xl bg-white/80 dark:bg-white/5 border border-indigo-100 dark:border-indigo-500/20 p-4"><div class="flex flex-wrap items-center justify-between gap-3"><div><h4 class="font-semibold"><i class="fas fa-chart-line text-indigo-500 mr-2"></i>恢复策略效果</h4><p class="mt-1 text-xs text-slate-400">根据本机历史失败恢复记录，判断哪些兜底动作更值得优先使用。</p></div><button onclick="switchAutomationTab('agent2')" class="text-xs text-primary-500 hover:underline">查看 Agent 2.0 经验</button></div><div class="mt-3 grid md:grid-cols-4 gap-2 text-xs"><div class="rounded-lg bg-indigo-50 dark:bg-indigo-500/10 px-3 py-2"><span class="text-slate-400">平均成功率</span><b class="ml-2 text-indigo-600">${Number(summary.avg_success_rate||0)}%</b></div><div class="rounded-lg bg-emerald-50 dark:bg-emerald-500/10 px-3 py-2"><span class="text-slate-400">有效策略</span><b class="ml-2 text-emerald-600">${Number(summary.effective||0)}</b></div><div class="rounded-lg bg-orange-50 dark:bg-orange-500/10 px-3 py-2"><span class="text-slate-400">观察中</span><b class="ml-2 text-orange-600">${Number(summary.watch||0)}</b></div><div class="rounded-lg bg-slate-50 dark:bg-white/5 px-3 py-2 truncate"><span class="text-slate-400">最佳动作</span><b class="ml-2">${escapeHtml(summary.best_action||'待沉淀')}</b></div></div><div class="grid md:grid-cols-2 gap-3 mt-3">${items.map(item=>`<div class="rounded-lg border border-slate-100 dark:border-white/10 p-3"><div class="flex items-start justify-between gap-3"><div class="min-w-0"><div class="font-medium text-sm truncate">${escapeHtml(item.action||'恢复动作')}</div><div class="mt-1 text-[11px] text-slate-400">${escapeHtml(item.kind||'自动化')} · ${escapeHtml(item.category||'general')} · ${item.confidence==='high'?'样本较充分':'样本较少'}</div></div><span class="shrink-0 rounded-full px-2 py-0.5 text-[11px] ${toneClass[item.tone]||toneClass.warning}">${escapeHtml(item.recommendation||'观察中')}</span></div><div class="mt-3 flex items-center gap-3 text-xs"><div class="flex-1 h-2 rounded-full bg-slate-100 dark:bg-white/10 overflow-hidden"><div class="${item.tone==='success'?'bg-emerald-500':item.tone==='danger'?'bg-red-500':'bg-orange-500'} h-full" style="width:${Math.max(3,Math.min(100,Number(item.success_rate||0)))}%"></div></div><b>${Number(item.success_rate||0)}%</b></div><div class="mt-2 text-[11px] text-slate-400">成功 ${Number(item.successes||0)}/${Number(item.attempts||0)} · 空结果 ${Number(item.empty||0)} · 失败 ${Number(item.failures||0)} · 最近 ${escapeHtml(String(item.last_seen||'').replace('T',' ').slice(0,19))}</div></div>`).join('')}</div></div>`;}
function renderMaintenanceDashboard(data){const summary=data.summary||{},latest=data.latest||{},cache=data.cache||{},notifications=data.notifications||{},todos=data.todos||[],trend=data.failure_trend||[],failedRuns=data.failed_runs||[],recoveryRuns=data.recovery_runs||[],recoveryEffectiveness=data.recovery_effectiveness||{},instanceSkips=data.instance_guard_skips||[],instanceTrend=data.instance_guard_trend||[],restartActions=data.backend_restart_actions||[];const channelText=(notifications.channels||[]).length?(notifications.channels||[]).join('、'):'未配置';return `${renderMaintenanceInstanceAlert(data.instance_guard_alert)}<div class="maintenance-summary-grid"><div class="maintenance-card"><div class="flex items-center justify-between"><span class="text-xs text-slate-400">最近维护状态</span><span class="px-2 py-0.5 rounded-full text-[11px] ${maintenanceStatusClasses(latest.status)}">${escapeHtml(latest.label||'待检查')}</span></div><div class="font-semibold mt-2">${escapeHtml(latest.task_name||'暂无维护任务')}</div><p class="text-xs text-slate-500 mt-2 line-clamp-2">${escapeHtml(latest.summary||'等待维护任务运行')}</p><div class="text-[11px] text-slate-400 mt-2">${escapeHtml(latest.at||data.checked_at||'')}</div></div><div class="maintenance-card"><div class="text-xs text-slate-400">自动化失败率趋势</div>${renderMaintenanceTrend(trend)}<div class="text-xs text-slate-500 mt-1">今日失败率 ${summary.automation_failure_rate||0}%</div></div><div class="maintenance-card"><div class="flex items-center justify-between"><span class="text-xs text-slate-400">缓存占用</span><span class="px-2 py-0.5 rounded-full text-[11px] ${maintenanceStatusClasses(cache.status)}">${cache.status==='success'?'正常':'需关注'}</span></div><div class="text-2xl font-bold mt-3">${Number(cache.total_mb||0)}<span class="text-sm ml-1">MB</span></div><p class="text-xs text-slate-500 mt-2">文件 ${Number(cache.file_count||0)} 个 · 阈值 ${Number(cache.threshold_mb||0)}MB</p></div><div class="maintenance-card"><div class="flex items-center justify-between"><span class="text-xs text-slate-400">通知通道状态</span><span class="px-2 py-0.5 rounded-full text-[11px] ${maintenanceStatusClasses(notifications.status)}">${notifications.status==='success'?'正常':notifications.status==='error'?'未启用':'需关注'}</span></div><div class="font-semibold mt-3 break-words leading-6">${escapeHtml(channelText)}</div><p class="text-xs text-slate-500 mt-2">近 7 天成功 ${Number(notifications.success||0)} 次，失败 ${Number(notifications.failed||0)} 次</p></div></div><div class="mt-4 flex flex-wrap gap-2"><button onclick="maintenanceDashboardRunReadiness(this)" class="px-3 py-1.5 rounded-lg bg-cyan-600 text-white text-xs"><i class="fas fa-stethoscope mr-1"></i>立即健康检查</button><button onclick="maintenanceDashboardPreviewCache(this)" class="px-3 py-1.5 rounded-lg bg-teal-600 text-white text-xs"><i class="fas fa-broom mr-1"></i>预览缓存清理</button><button onclick="maintenanceDashboardGeneratePlan(this)" class="px-3 py-1.5 rounded-lg bg-indigo-600 text-white text-xs"><i class="fas fa-list-check mr-1"></i>生成维护计划</button><button onclick="maintenanceDashboardCreateSchedule(this)" class="px-3 py-1.5 rounded-lg bg-emerald-600 text-white text-xs"><i class="fas fa-clock mr-1"></i>一键创建维护任务</button><button onclick="maintenanceDashboardOpenRuns('failed')" class="px-3 py-1.5 rounded-lg border border-slate-200 dark:border-white/10 text-xs"><i class="fas fa-bug mr-1 text-red-500"></i>查看失败会话</button><button onclick="maintenanceDashboardOpenNotifications('failed')" class="px-3 py-1.5 rounded-lg border border-slate-200 dark:border-white/10 text-xs"><i class="far fa-bell mr-1 text-amber-500"></i>查看通知异常</button></div><div id="maintenance-dashboard-action-status" class="hidden"></div>${renderInstanceGuardTrend(instanceTrend)}${renderMaintenanceFailedRuns(failedRuns)}${renderMaintenanceInstanceSkips(instanceSkips)}${renderBackendRestartActions(restartActions)}${renderMaintenanceRecoveryRuns(recoveryRuns)}${renderMaintenanceRecoveryEffectiveness(recoveryEffectiveness)}<div class="mt-4 maintenance-card"><div class="flex items-center justify-between gap-3"><h4 class="font-semibold">本周待处理项</h4><span class="text-xs text-slate-400">维护任务 ${Number(summary.enabled_count||0)}/${Number(summary.task_count||0)} 已启用</span></div><div class="grid md:grid-cols-2 gap-3 mt-3">${todos.map(item=>`<div class="flex gap-3 rounded-lg border border-slate-100 dark:border-white/10 p-3"><div class="mt-0.5">${maintenanceTodoIcon(item.level)}</div><div class="min-w-0"><div class="font-medium text-sm">${escapeHtml(item.title||'待处理项')}</div><p class="text-xs text-slate-500 mt-1">${escapeHtml(item.summary||'')}</p>${maintenanceDashboardTodoActions(item)}</div></div>`).join('')}</div></div>`;}

function maintenanceDashboardIssueState(data={}) {
    const summary = data.summary || {}, latest = data.latest || {}, cache = data.cache || {}, notifications = data.notifications || {};
    const failedRuns = data.failed_runs || [], instanceSkips = data.instance_guard_skips || [], alert = data.instance_guard_alert || {};
    const issues = [];
    let level = 'success';
    const add = (tone, text) => { if (!text) return; issues.push(text); if (tone === 'error') level = 'error'; else if (level !== 'error') level = 'warning'; };
    if (['error','failed'].includes(latest.status)) add('error', latest.summary || latest.label || '最近维护任务失败');
    if (Number(summary.automation_failure_rate || 0) > 0 || failedRuns.length) add(failedRuns.length ? 'error' : 'warning', `自动化失败率 ${Number(summary.automation_failure_rate || 0)}%`);
    const cacheOverLimit = Number(cache.threshold_mb || 0) > 0 && Number(cache.total_mb || 0) >= Number(cache.threshold_mb || 0);
    if (cache.status === 'error' || cacheOverLimit) add(cache.status === 'error' ? 'error' : 'warning', `缓存占用需关注：${Number(cache.total_mb || 0)}MB`);
    if (notifications.status === 'error') add('error', '通知通道未启用');
    else if (Number(notifications.unhandled_failed || 0) > 0) add('warning', `通知通道异常：未处理失败 ${Number(notifications.unhandled_failed || 0)} 次`);
    if (alert.active) add('warning', alert.title || '疑似存在残留后端实例');
    if (instanceSkips.length) add('warning', `实例保护跳过 ${instanceSkips.length} 条`);
    return { level, issues };
}

function maintenanceCardStateClass(status, force=false) {
    if (force || status === 'error' || status === 'failed') return 'is-error';
    if (status && status !== 'success') return 'is-warning';
    return '';
}

function updateMaintenanceDashboardShell(data={}) {
    const shell = document.getElementById('maintenance-dashboard-card');
    const subtitle = document.getElementById('maintenance-dashboard-subtitle');
    const state = maintenanceDashboardIssueState(data);
    if (shell) {
        shell.classList.toggle('is-error', state.level === 'error');
        shell.classList.toggle('is-warning', state.level === 'warning');
    }
    if (subtitle) {
        subtitle.textContent = state.issues.length
            ? `发现 ${state.issues.length} 项需要关注，已同步到左下角铃铛提醒。`
            : '当前维护状态正常，只有出现异常风险时才高亮提示。';
        subtitle.className = `text-xs mt-1 ${state.level === 'error' ? 'text-red-500' : state.level === 'warning' ? 'text-orange-500' : 'text-slate-500'}`;
    }
    maintenanceDashboardBellHint(state);
    return state;
}

function maintenanceDashboardBellHint(state) {
    const badge = document.getElementById('notification-badge');
    if (!badge) return;
    if (!state?.issues?.length) return;
    const current = parseInt(badge.textContent || '0', 10) || 0;
    badge.textContent = String(Math.max(current, state.issues.length));
    badge.classList.remove('hidden');
    const list = document.getElementById('notification-list');
    if (list && !list.querySelector('[data-local-maintenance-warning]')) {
        const item = document.createElement('button');
        item.type = 'button';
        item.dataset.localMaintenanceWarning = '1';
        item.className = 'w-full text-left px-4 py-3 border-b border-slate-100 dark:border-white/10 hover:bg-slate-50 dark:hover:bg-white/5';
        item.onclick = () => { openSettingsCenter?.(); setTimeout(() => showSettingsView?.('maintenance','维护看板'), 80); };
        item.innerHTML = `<div class="flex items-start gap-2"><i class="fas fa-heart-pulse mt-0.5 ${state.level === 'error' ? 'text-red-500' : 'text-orange-500'}"></i><div class="min-w-0"><b class="text-sm">维护看板需要关注</b><p class="mt-1 text-xs text-slate-500">${escapeHtml(state.issues.slice(0,2).join('；'))}</p></div></div>`;
        list.prepend(item);
    }
}

function renderMaintenanceDecisionHealth(data){
    data=data||{};
    const summary=data.summary||{},items=data.items||[],suggestions=data.suggestions||[];
    const tone=data.status==='success'?'border-emerald-100 dark:border-emerald-500/20':'border-amber-100 dark:border-amber-500/20';
    const topActions=(summary.top_actions||[]).map(item=>`<span class="rounded-full bg-indigo-50 text-indigo-600 dark:bg-indigo-500/10 px-2 py-0.5 text-[11px]">${escapeHtml(item.action||'动作')} ×${Number(item.count||0)}</span>`).join('');
    const topFailures=(summary.top_failures||[]).slice(0,3).map(item=>`<span class="rounded-full bg-red-50 text-red-600 dark:bg-red-500/10 px-2 py-0.5 text-[11px]">${escapeHtml(item.reason||'失败')} ×${Number(item.count||0)}</span>`).join('');
    const unstableChannels=(summary.unstable_channels||[]).slice(0,3).map(item=>`<span class="rounded-full bg-orange-50 text-orange-600 dark:bg-orange-500/10 px-2 py-0.5 text-[11px]">${escapeHtml(item.channel||'通道')} ×${Number(item.count||0)}</span>`).join('');
    const pendingTasks=(summary.pending_tasks||[]).slice(0,3).map(item=>`<span class="rounded-full bg-blue-50 text-blue-600 dark:bg-blue-500/10 px-2 py-0.5 text-[11px]">${escapeHtml(item.task_name||'任务')} ×${Number(item.count||0)}</span>`).join('');
    const rows=items.slice(0,6).map(item=>`<div class="rounded-lg border border-slate-100 dark:border-white/10 p-3"><div class="flex flex-wrap items-center justify-between gap-2"><div class="min-w-0"><div class="font-medium text-sm truncate">${escapeHtml(item.task_name||'自动任务')}</div><div class="mt-1 text-[11px] text-slate-400">${escapeHtml(item.stage||'decision')} · ${escapeHtml(String(item.at||'').replace('T',' ').slice(0,19))}</div></div><span class="rounded-full px-2 py-0.5 text-[11px] ${item.auto_fixable?'bg-emerald-50 text-emerald-600 dark:bg-emerald-500/10':'bg-slate-50 text-slate-500 dark:bg-white/5'}">${item.auto_fixable?'可自动修复':'记录'}</span></div><p class="mt-2 text-xs text-slate-500 line-clamp-2">${escapeHtml(item.reason||'已生成结构化判断')}</p>${(item.actions||[]).length?`<div class="mt-2 flex flex-wrap gap-1.5">${item.actions.slice(0,4).map(action=>`<span class="rounded-full bg-blue-50 text-blue-600 dark:bg-blue-500/10 px-2 py-0.5 text-[11px]">${escapeHtml(action)}</span>`).join('')}</div>`:''}</div>`).join('');
    return `<div class="mt-4 rounded-xl bg-white/80 dark:bg-white/5 border ${tone} p-4"><div class="flex flex-wrap items-start justify-between gap-3"><div><h4 class="font-semibold"><i class="fas fa-brain text-indigo-500 mr-2"></i>决策体检</h4><p class="mt-1 text-xs text-slate-400">检查决策层是否正在驱动预检、发送、补发和失败归因。</p></div><span class="px-2.5 py-1 rounded-full text-xs ${data.status==='success'?'bg-emerald-50 text-emerald-600 dark:bg-emerald-500/10':'bg-amber-50 text-amber-600 dark:bg-amber-500/10'}">${data.status==='success'?'正常':'需关注'}</span></div><div class="mt-3 grid md:grid-cols-4 gap-2 text-xs"><div class="rounded-lg bg-indigo-50 dark:bg-indigo-500/10 px-3 py-2"><span class="text-slate-400">决策记录</span><b class="ml-2 text-indigo-600">${Number(summary.decisions_7d||0)}</b></div><div class="rounded-lg bg-blue-50 dark:bg-blue-500/10 px-3 py-2"><span class="text-slate-400">动作触发</span><b class="ml-2 text-blue-600">${Number(summary.actions_7d||0)}</b></div><div class="rounded-lg bg-emerald-50 dark:bg-emerald-500/10 px-3 py-2"><span class="text-slate-400">可自动修复</span><b class="ml-2 text-emerald-600">${Number(summary.auto_fixable_7d||0)}</b></div><div class="rounded-lg bg-orange-50 dark:bg-orange-500/10 px-3 py-2"><span class="text-slate-400">待补发</span><b class="ml-2 text-orange-600">${Number(summary.pending_retry||0)}</b></div></div>${topActions?`<div class="mt-3 flex flex-wrap gap-1.5">${topActions}</div>`:''}${(topFailures||unstableChannels||pendingTasks)?`<div class="mt-2 flex flex-wrap gap-1.5">${topFailures}${unstableChannels}${pendingTasks}</div>`:''}${suggestions.length?`<div class="mt-3 rounded-lg bg-slate-50 dark:bg-black/10 px-3 py-2 text-xs text-slate-500">${suggestions.map(x=>`<div><i class="fas fa-lightbulb text-amber-500 mr-1"></i>${escapeHtml(x)}</div>`).join('')}</div>`:''}${rows?`<div class="grid md:grid-cols-2 gap-3 mt-3">${rows}</div>`:'<p class="mt-3 text-sm text-slate-400">暂无最近决策样本。</p>'}</div>`;
}
function maintenanceDashboardOpenSelfHealing(statusValue=''){
    navigateTo('intelligence');
    setTimeout(()=>{switchAutomationTab('selfhealing');const status=document.getElementById('automation-selfhealing-status');if(status)status.value=statusValue||'';loadSelfHealingLogs?.();},80);
}
function renderMaintenanceSelfHealing(data){
    data=data||{};const summary=data.summary||{},items=data.items||[],suggestions=data.suggestions||[];
    const status=data.status==='success'?'success':'warning';
    const tone=status==='success'?'border-emerald-100 dark:border-emerald-500/20':'border-amber-100 dark:border-amber-500/20';
    const topActions=(summary.top_actions||[]).map(item=>`<span class="rounded-full bg-cyan-50 text-cyan-700 dark:bg-cyan-500/10 px-2 py-0.5 text-[11px]">${escapeHtml(selfHealingActionLabel?.(item.action)||item.action||'动作')} ×${Number(item.count||0)}</span>`).join('');
    const topChannels=(summary.top_channels||[]).map(item=>`<span class="rounded-full bg-blue-50 text-blue-700 dark:bg-blue-500/10 px-2 py-0.5 text-[11px]">${escapeHtml(pendingDeliveryChannelLabel?.(item.channel)||item.channel||'通道')} ×${Number(item.count||0)}</span>`).join('');
    const rows=items.slice(0,4).map(item=>{const meta=selfHealingStatusMeta?.(item.status)||{label:item.status||'记录',badge:'bg-slate-100 text-slate-600',icon:'fa-circle-info'};return `<div class="rounded-lg border border-slate-100 dark:border-white/10 p-3"><div class="flex flex-wrap items-start justify-between gap-2"><div class="min-w-0"><div class="font-medium text-sm truncate">${escapeHtml(item.title||'系统自愈')}</div><div class="mt-1 text-[11px] text-slate-400">${escapeHtml(item.task_name||'系统')} · ${escapeHtml(String(item.at||'').replace('T',' ').slice(0,19))}</div></div><span class="rounded-full px-2 py-0.5 text-[11px] ${meta.badge}"><i class="fas ${meta.icon} mr-1"></i>${meta.label}</span></div><p class="mt-2 text-xs text-slate-500 line-clamp-2">${escapeHtml(item.summary||'已记录自动处理动作。')}</p></div>`;}).join('');
    return `<div class="mt-4 rounded-xl bg-white/80 dark:bg-white/5 border ${tone} p-4"><div class="flex flex-wrap items-start justify-between gap-3"><div><h4 class="font-semibold"><i class="fas fa-shield-heart text-cyan-500 mr-2"></i>系统自愈概览</h4><p class="mt-1 text-xs text-slate-400">统计最近 24 小时自动补发、Web 兜底、跳过异常通道和后端修复动作。</p></div><div class="flex flex-wrap gap-2"><span class="px-2.5 py-1 rounded-full text-xs ${status==='success'?'bg-emerald-50 text-emerald-600 dark:bg-emerald-500/10':'bg-amber-50 text-amber-600 dark:bg-amber-500/10'}">${status==='success'?'运行正常':'需关注'}</span><button onclick="maintenanceDashboardOpenSelfHealing('${Number(summary.need_action||0)?'failed':''}')" class="px-3 py-1.5 rounded-lg border border-slate-200 dark:border-white/10 text-xs">查看自愈日志</button></div></div><div class="mt-3 grid md:grid-cols-4 gap-2 text-xs"><div class="rounded-lg bg-cyan-50 dark:bg-cyan-500/10 px-3 py-2"><span class="text-slate-400">24小时动作</span><b class="ml-2 text-cyan-600">${Number(summary.total_24h||0)}</b></div><div class="rounded-lg bg-emerald-50 dark:bg-emerald-500/10 px-3 py-2"><span class="text-slate-400">已修复</span><b class="ml-2 text-emerald-600">${Number(summary.success_24h||0)}</b></div><div class="rounded-lg bg-orange-50 dark:bg-orange-500/10 px-3 py-2"><span class="text-slate-400">观察中</span><b class="ml-2 text-orange-600">${Number(summary.warning_24h||0)}</b></div><div class="rounded-lg bg-red-50 dark:bg-red-500/10 px-3 py-2"><span class="text-slate-400">需处理</span><b class="ml-2 text-red-600">${Number(summary.need_action||0)}</b></div></div>${(topActions||topChannels)?`<div class="mt-3 flex flex-wrap gap-1.5">${topActions}${topChannels}</div>`:''}${suggestions.length?`<div class="mt-3 rounded-lg bg-slate-50 dark:bg-black/10 px-3 py-2 text-xs text-slate-500">${suggestions.map(x=>`<div><i class="fas fa-lightbulb text-amber-500 mr-1"></i>${escapeHtml(x)}</div>`).join('')}</div>`:''}${rows?`<div class="grid md:grid-cols-2 gap-3 mt-3">${rows}</div>`:'<p class="mt-3 text-sm text-slate-400">暂无最近自愈动作。</p>'}</div>`;
}

function renderMaintenanceSourceDeliveryCards(data={}){
    const delivery=data.delivery_e2e||{},source=data.source_health||{};
    return `<div class="grid md:grid-cols-2 gap-3 mt-4"><div class="maintenance-card ${maintenanceCardStateClass(delivery.status,true)}"><div class="flex items-center justify-between"><span class="text-xs text-slate-400">通知链路自检</span><span class="px-2 py-0.5 rounded-full text-[11px] ${maintenanceStatusClasses(delivery.status)}">${delivery.status==='success'?'可送达':delivery.status==='error'?'异常':'需关注'}</span></div><div class="font-semibold mt-2">${escapeHtml(delivery.summary||'等待检查')}</div><p class="text-xs text-slate-500 mt-2">可发送：${escapeHtml((delivery.sendable_channels||[]).join('、')||'无')}</p></div><div class="maintenance-card ${maintenanceCardStateClass(source.status,true)}"><div class="flex items-center justify-between"><span class="text-xs text-slate-400">新闻来源健康</span><span class="px-2 py-0.5 rounded-full text-[11px] ${maintenanceStatusClasses(source.status)}">${source.status==='success'?'正常':source.status==='error'?'异常':'需关注'}</span></div><div class="font-semibold mt-2">${escapeHtml(source.summary||'等待检查')}</div><p class="text-xs text-slate-500 mt-2">健康 ${Number(source.healthy||0)} / 总计 ${Number(source.total||0)}，冷却 ${Number(source.cooling_down||0)}，停用 ${Number(source.disabled||0)}</p></div></div>`;
}

function renderMaintenanceDashboard(data){
    const summary=data.summary||{},latest=data.latest||{},cache=data.cache||{},notifications=data.notifications||{},deliveryE2E=data.delivery_e2e||{},sourceHealth=data.source_health||{},todos=data.todos||[],trend=data.failure_trend||[],failedRuns=data.failed_runs||[],recoveryRuns=data.recovery_runs||[],recoveryEffectiveness=data.recovery_effectiveness||{},instanceSkips=data.instance_guard_skips||[],instanceTrend=data.instance_guard_trend||[],restartActions=data.backend_restart_actions||[];
    const state = updateMaintenanceDashboardShell(data);
    const channelText=(notifications.channels||[]).length?(notifications.channels||[]).join('、'):'未配置';
    const failureSummary = notifications.failure_summary || [];
    const failureDetailHtml = failureSummary.length ? `<div class="mt-2 space-y-1">${failureSummary.slice(0,3).map(item=>`<div class="rounded-lg bg-white/70 dark:bg-black/10 px-2 py-1 text-[11px] text-slate-500"><b>${escapeHtml(item.channel || 'unknown')}</b> · ${escapeHtml(item.reason || '发送失败')}<span class="ml-1 text-orange-500">×${Number(item.count || 0)}</span>${item.latest_task?`<span class="ml-1 text-slate-400">｜${escapeHtml(item.latest_task)}</span>`:''}${item.suggestion?`<div class="mt-0.5 text-[10px] text-slate-400">建议：${escapeHtml(item.suggestion)}</div>`:''}</div>`).join('')}</div>` : '';
    const failureRisk = Number(summary.automation_failure_rate||0) > 0 || failedRuns.length;
    const cacheRisk = cache.status === 'error' || (Number(cache.threshold_mb || 0) > 0 && Number(cache.total_mb || 0) >= Number(cache.threshold_mb || 0));
    const notifyRisk = notifications.status === 'error' || Number(notifications.unhandled_failed||0) > 0;
    const notificationLabel = notifications.status==='success'?'正常':notifications.status==='error'?'未启用':notifications.status==='acknowledged'?'已处理':'需关注';
    const filteredFailed = Number(notifications.filtered_failed || 0);
    const failureGroups = Number(notifications.failure_group_count || failureSummary.length || 0);
    const notificationStatText = Number(notifications.unhandled_failed||0) > 0
        ? `近 7 天通道成功 ${Number(notifications.success||0)} 次，需处理 ${failureGroups} 类 / ${Number(notifications.failed||0)} 次${filteredFailed?`；已过滤任务失败 ${filteredFailed} 次`:''}`
        : `近 7 天通道成功 ${Number(notifications.success||0)} 次，通道失败 ${Number(notifications.failed||0)} 次${filteredFailed?`；已过滤任务失败 ${filteredFailed} 次`:''}${Number(notifications.failed||0)>0?'（已查看，暂无新增失败）':''}`;
    const latestRisk = ['error','failed'].includes(latest.status);
    const actionBar = `<div class="mt-4 flex flex-wrap gap-2"><button onclick="maintenanceDashboardRunReadiness(this)" class="px-3 py-1.5 rounded-lg bg-cyan-600 text-white text-xs"><i class="fas fa-stethoscope mr-1"></i>立即健康检查</button><button onclick="maintenanceDashboardPreviewCache(this)" class="px-3 py-1.5 rounded-lg bg-teal-600 text-white text-xs"><i class="fas fa-broom mr-1"></i>预览缓存清理</button><button onclick="maintenanceDashboardGeneratePlan(this)" class="px-3 py-1.5 rounded-lg bg-indigo-600 text-white text-xs"><i class="fas fa-list-check mr-1"></i>生成维护计划</button><button onclick="maintenanceDashboardCreateSchedule(this)" class="px-3 py-1.5 rounded-lg bg-emerald-600 text-white text-xs"><i class="fas fa-clock mr-1"></i>一键创建维护任务</button><button onclick="maintenanceDashboardOpenRuns('failed')" class="px-3 py-1.5 rounded-lg border border-slate-200 dark:border-white/10 text-xs"><i class="fas fa-bug mr-1 text-red-500"></i>查看失败会话</button><button onclick="maintenanceDashboardOpenNotifications('failed')" class="px-3 py-1.5 rounded-lg border border-slate-200 dark:border-white/10 text-xs"><i class="far fa-bell mr-1 text-amber-500"></i>查看通知异常</button></div><div id="maintenance-dashboard-action-status" class="hidden"></div>`;
    const normalHint = state.issues.length ? `<div class="mb-4 rounded-xl ${state.level === 'error' ? 'bg-red-50 text-red-700 dark:bg-red-500/10 dark:text-red-300' : 'bg-orange-50 text-orange-700 dark:bg-orange-500/10 dark:text-orange-300'} px-4 py-3 text-xs"><i class="fas fa-triangle-exclamation mr-1"></i>${escapeHtml(state.issues.slice(0,3).join('；'))}</div>` : '';
    return `${normalHint}${renderMaintenanceInstanceAlert(data.instance_guard_alert)}<div class="maintenance-summary-grid"><div class="maintenance-card ${latestRisk?maintenanceCardStateClass(latest.status,true):''}"><div class="flex items-center justify-between"><span class="text-xs text-slate-400">最近维护状态</span><span class="px-2 py-0.5 rounded-full text-[11px] ${maintenanceStatusClasses(latest.status)}">${escapeHtml(latest.label||'待检查')}</span></div><div class="font-semibold mt-2">${escapeHtml(latest.task_name||'暂无维护任务')}</div><p class="text-xs text-slate-500 mt-2 line-clamp-2">${escapeHtml(latest.summary||'暂无维护记录，可手动运行一次健康检查。')}</p><div class="text-[11px] text-slate-400 mt-2">${escapeHtml(latest.at||data.checked_at||'')}</div></div><div class="maintenance-card ${failureRisk?'is-error':''}"><div class="text-xs text-slate-400">自动化失败率趋势</div>${renderMaintenanceTrend(trend)}<div class="text-xs text-slate-500 mt-1">今日失败率 ${summary.automation_failure_rate||0}%</div></div><div class="maintenance-card ${cacheRisk?maintenanceCardStateClass(cache.status,true):''}"><div class="flex items-center justify-between"><span class="text-xs text-slate-400">缓存占用</span><span class="px-2 py-0.5 rounded-full text-[11px] ${maintenanceStatusClasses(cache.status)}">${cache.status==='success'?'正常':'需关注'}</span></div><div class="text-2xl font-bold mt-3">${Number(cache.total_mb||0)}<span class="text-sm ml-1">MB</span></div><p class="text-xs text-slate-500 mt-2">文件 ${Number(cache.file_count||0)} 个 · 阈值 ${Number(cache.threshold_mb||0)}MB</p></div><div class="maintenance-card ${notifyRisk?maintenanceCardStateClass(notifications.status,true):''}"><div class="flex items-center justify-between"><span class="text-xs text-slate-400">通知通道状态</span><span class="px-2 py-0.5 rounded-full text-[11px] ${maintenanceStatusClasses(notifications.status)}">${escapeHtml(notificationLabel)}</span></div><div class="font-semibold mt-3 break-words leading-6">${escapeHtml(channelText)}</div><p class="text-xs text-slate-500 mt-2">${escapeHtml(notificationStatText)}</p>${failureDetailHtml}</div></div>${actionBar}${renderMaintenanceSourceDeliveryCards(data)}${renderMaintenanceSelfHealing(data.self_healing)}${renderMaintenanceDecisionHealth(data.decision_health)}${renderInstanceGuardTrend(instanceTrend)}${renderMaintenanceFailedRuns(failedRuns)}${renderMaintenanceInstanceSkips(instanceSkips)}${renderBackendRestartActions(restartActions)}${renderMaintenanceRecoveryRuns(recoveryRuns)}${renderMaintenanceRecoveryEffectiveness(recoveryEffectiveness)}<div class="mt-4 maintenance-card ${todos.some(item=>['error','warning'].includes(item.level))?'is-warning':''}"><div class="flex items-center justify-between gap-3"><h4 class="font-semibold">本周待处理项</h4><span class="text-xs text-slate-400">维护任务 ${Number(summary.enabled_count||0)}/${Number(summary.task_count||0)} 已启用</span></div><div class="grid md:grid-cols-2 gap-3 mt-3">${todos.map(item=>`<div class="flex gap-3 rounded-lg border border-slate-100 dark:border-white/10 p-3"><div class="mt-0.5">${maintenanceTodoIcon(item.level)}</div><div class="min-w-0"><div class="font-medium text-sm">${escapeHtml(item.title||'待处理项')}</div><p class="text-xs text-slate-500 mt-1">${escapeHtml(item.summary||'')}</p>${maintenanceDashboardTodoActions(item)}</div></div>`).join('')||'<div class="text-sm text-slate-400">暂无待处理项。</div>'}</div></div>`;
}

function toggleMaintenanceScheduleFields(){const type=document.getElementById('maintenance-schedule-type')?.value||'daily';document.getElementById('maintenance-daily-field')?.classList.toggle('hidden',type!=='daily');document.getElementById('maintenance-weekly-field')?.classList.toggle('hidden',type!=='weekly');document.getElementById('maintenance-interval-field')?.classList.toggle('hidden',type!=='interval');}
function maintenanceScheduleValue(){const type=document.getElementById('maintenance-schedule-type')?.value||'daily';if(type==='weekly')return (document.getElementById('maintenance-weekly-time')?.value||'每周一09:00').replace(/\s+/g,'');if(type==='interval')return '';return `每天${document.getElementById('maintenance-daily-time')?.value||'09:00'}`;}
async function saveMaintenanceTask(){const type=document.getElementById('maintenance-schedule-type')?.value||'daily',interval=Number(document.getElementById('maintenance-interval-value')?.value||0)*Number(document.getElementById('maintenance-interval-unit')?.value||1),payload={name:document.getElementById('maintenance-name')?.value.trim()||'',maintenance_type:document.getElementById('maintenance-type')?.value||'readiness_check',schedule_type:type,schedule:maintenanceScheduleValue(),interval_minutes:type==='interval'?interval:0,sources:['local_maintenance'],keywords:['维护','健康检查','自动化'],rules:{failure_rate_threshold:Number(document.getElementById('maintenance-failure-threshold')?.value||20),cache_limit_mb:Number(document.getElementById('maintenance-cache-threshold')?.value||500)},artifact_type:document.getElementById('automation-artifact-type')?.value||'维护报告',artifact_tags:automationArtifactTags().length?automationArtifactTags():['P4','自动维护','维护任务']};const status=document.getElementById('maintenance-form-status');if(status)status.textContent='';try{await saveAutomationPayload('maintenance','/api/intelligence/maintenance',payload);closeTaskCreator();await loadAutomationTasks();_wsToast?.('维护任务已保存');}catch(error){if(status)status.textContent=error.message||String(error);}}
const MAINTENANCE_LABELS={log_check:'系统日志',automation_failure_rate:'自动化失败率',channel_check:'通知通道',delivery_e2e_check:'通知链路自检',source_health_check:'来源健康',cache_review:'缓存清理建议',readiness_check:'维护健康检查',version_compare:'版本比对',package_integrity:'交付包完整性',artifact_growth:'产物增长'};
async function loadMaintenanceTasks(){const container=document.getElementById('maintenance-tasks');if(!container)return 0;try{const data=await intelligenceRequest('/api/intelligence/maintenance');if(!data.tasks.length){container.innerHTML='';return 0;}container.innerHTML=data.tasks.map(task=>{const schedule=task.schedule_type==='interval'?`每隔 ${formatNewsInterval(task.interval_minutes)}`:task.schedule,label=MAINTENANCE_LABELS[task.maintenance_type]||'自动维护';return `<div class="rounded-xl border border-cyan-200 dark:border-cyan-500/20 bg-white dark:bg-[#202020] p-5"><div class="flex flex-wrap justify-between gap-3"><div><span class="text-xs text-cyan-600">P4 自动维护 · ${escapeHtml(label)}</span><h4 class="font-semibold mt-1">${escapeHtml(task.name)}</h4><p class="text-xs text-slate-400 mt-1">${escapeHtml(schedule)} · ${automationTaskNotificationSummary(task)}</p></div><span class="px-2 py-1 rounded-full text-xs ${task.enabled?'bg-emerald-50 text-emerald-600 dark:bg-emerald-500/10':'bg-slate-100 text-slate-500'}">${task.enabled?'已启用':'已停用'}</span></div><p class="text-sm text-slate-500 mt-3">${escapeHtml(task.last_status||'等待执行')}</p><div class="flex gap-2 mt-4 flex-wrap"><button onclick="runMaintenanceTask('${task.id}',this)" class="px-3 py-1.5 rounded-lg bg-cyan-600 text-white text-xs">立即执行维护检查</button><button onclick="toggleMaintenanceTask('${task.id}',${!task.enabled})" class="px-3 py-1.5 rounded-lg border text-xs">${task.enabled?'停用':'启用'}</button><button onclick="deleteMaintenanceTask('${task.id}')" class="px-3 py-1.5 text-red-500 text-xs">删除</button></div></div>`}).join('');return data.tasks.length;}catch(error){container.innerHTML=`<div class="py-8 text-center text-red-500">${escapeHtml(error.message)}</div>`;return 0;}}
async function runMaintenanceTask(id,button){return runAutomationTaskWithFeedback({id,button,endpoint:'/api/intelligence/maintenance/run',reportHost:'maintenance-report-content',reportPanel:'maintenance-report',runningText:'正在维护检查...',defaultText:'立即执行维护检查'});}
async function toggleMaintenanceTask(id,enabled){await intelligenceRequest('/api/intelligence/maintenance/toggle',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({task_id:id,enabled})});loadAutomationTasks();}
async function deleteMaintenanceTask(id){if(!confirm('确定删除这个维护任务吗？'))return;try{await intelligenceRequest('/api/intelligence/maintenance/delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({task_id:id})});await loadAutomationTasks();}catch(error){alert(`删除失败：${error.message}`);}}

async function runNewsTask(id, button) {
    return runAutomationTaskWithFeedback({id,button,endpoint:'/api/intelligence/news/run',reportHost:'news-report-content',reportPanel:'news-report',runningText:'正在抓取...',defaultText:'立即抓取并生成日报'});
}

async function toggleNewsTask(id, enabled) {
    await intelligenceRequest('/api/intelligence/news/toggle', {method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({task_id: id, enabled})});
    loadAutomationTasks();
}

async function deleteNewsTask(id) {
    if (!confirm('确定删除这个新闻任务吗？')) return;
    try {
        await intelligenceRequest('/api/intelligence/news/delete', {method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({task_id: id})});
        await loadAutomationTasks();
    } catch (error) { alert(`删除失败：${error.message}`); }
}

// =====================================================================
// Knowledge View
// =====================================================================
let _knowledgeTreeData = [];
let _knowledgeRootFiles = [];
let _knowledgeCurrentFile = null;
let _knowledgeGraphLoaded = false;
let _knowledgeQuickFilter = '';
const KNOWLEDGE_IMPORT_MAX_FILES = 100;
const KNOWLEDGE_IMPORT_MAX_FILE_SIZE = 10 * 1024 * 1024;
const KNOWLEDGE_IMPORT_MAX_TOTAL_SIZE = 200 * 1024 * 1024;

function loadKnowledgeView(targetPath) {
    // Reset to docs tab
    switchKnowledgeTab('docs');
    _knowledgeGraphLoaded = false;
    _knowledgeCurrentFile = null;

    fetch('/api/knowledge/list').then(r => r.json()).then(data => {
        if (data.status !== 'success') return;
        initKnowledgeImportDropZone();

        const emptyEl = document.getElementById('knowledge-empty');
        const docsPanel = document.getElementById('knowledge-panel-docs');
        const statsEl = document.getElementById('knowledge-stats');

        const tree = filterKnowledgeSystemTree(data.tree || []);
        const rootFiles = (data.root_files || []).filter(file=>!isKnowledgeSystemEntry(file.name));
        _knowledgeTreeData = tree;
        _knowledgeRootFiles = rootFiles;
        const stats = data.stats || {};
        const totalPages = stats.pages || 0;
        const sizeStr = stats.size < 1024 ? stats.size + ' B' : (stats.size / 1024).toFixed(1) + ' KB';

        statsEl.textContent = totalPages + ' pages · ' + sizeStr;
        const pagesCard = document.getElementById('knowledge-stat-pages');
        if (pagesCard) pagesCard.textContent = String(totalPages);
        loadKnowledgeArchiveSettings?.();

        if (totalPages === 0 && tree.length === 0 && rootFiles.length === 0) {
            emptyEl.querySelector('p').textContent = t('knowledge_empty_hint');
            const guideEl = document.getElementById('knowledge-empty-guide');
            if (guideEl) guideEl.classList.remove('hidden');
            emptyEl.classList.remove('hidden');
            docsPanel.classList.add('hidden');
            return;
        }
        emptyEl.classList.add('hidden');
        docsPanel.classList.remove('hidden');

        renderKnowledgeTree(tree, rootFiles);

        // Prefer opening the just created/imported file; ensure its group is
        // expanded so the active item is visible in the tree.
        const targetTitle = targetPath ? _findKnowledgeFileTitle(targetPath) : null;
        if (targetTitle !== null) {
            _expandKnowledgeGroupFor(targetPath);
            openKnowledgeFile(targetPath, targetTitle);
            return;
        }

        // Auto-select the first file (desktop only)
        if (window.innerWidth >= 768) {
            const firstFile = rootFiles.length > 0 ? rootFiles[0] : null;
            const firstGroup = !firstFile ? tree.find(g => g.files && g.files.length > 0) : null;
            if (firstFile) {
                openKnowledgeFile(firstFile.name, firstFile.title);
            } else if (firstGroup) {
                const gf = firstGroup.files[0];
                openKnowledgeFile(firstGroup.dir + '/' + gf.name, gf.title);
            }
        } else {
            document.getElementById('knowledge-content-placeholder').classList.add('hidden');
            document.getElementById('knowledge-content-viewer').classList.add('hidden');
        }
    }).catch(() => {});
}

function isKnowledgeSystemEntry(name){const value=String(name||'').replace(/\\/g,'/').split('/').pop().toLowerCase();return ['index','index.md','index.json','log','log.md','logs','logs.md','sources','sources.md','sources.json'].includes(value)||value.startsWith('.index');}
function filterKnowledgeSystemTree(groups){return (groups||[]).filter(group=>!isKnowledgeSystemEntry(group.dir)).map(group=>({...group,files:(group.files||[]).filter(file=>!isKnowledgeSystemEntry(file.name)),children:filterKnowledgeSystemTree(group.children||[])}));}

// Find a file's display title by its relative path within the knowledge tree.
// Returns the title, or null when the path is not present.
function _findKnowledgeFileTitle(path) {
    if (!path) return null;
    const rootHit = (_knowledgeRootFiles || []).find(f => f.name === path);
    if (rootHit) return rootHit.title || rootHit.name;
    const walk = (groups, parentPath) => {
        for (const group of groups || []) {
            const groupPath = parentPath ? `${parentPath}/${group.dir}` : group.dir;
            const hit = (group.files || []).find(f => `${groupPath}/${f.name}` === path);
            if (hit) return hit.title || hit.name;
            const childHit = walk(group.children, groupPath);
            if (childHit !== null) return childHit;
        }
        return null;
    };
    return walk(_knowledgeTreeData, '');
}

// Open every ancestor group of the given file path so it is visible.
function _expandKnowledgeGroupFor(path) {
    if (!path || !path.includes('/')) return;
    const target = document.querySelector(`.knowledge-tree-file[data-path="${CSS.escape(path)}"]`);
    let node = target ? target.closest('.knowledge-tree-group') : null;
    while (node) {
        node.classList.add('open');
        node = node.parentElement ? node.parentElement.closest('.knowledge-tree-group') : null;
    }
}

function renderKnowledgeTree(tree, rootFilesOrFilter, filter) {
    const container = document.getElementById('knowledge-tree');
    container.innerHTML = '';
    let rootFiles, lowerFilter;
    if (typeof rootFilesOrFilter === 'string') {
        rootFiles = _knowledgeRootFiles;
        lowerFilter = (rootFilesOrFilter || '').toLowerCase();
    } else {
        rootFiles = rootFilesOrFilter || _knowledgeRootFiles;
        lowerFilter = (filter || '').toLowerCase();
    }
    (rootFiles || []).forEach(f => {
        if (!_knowledgeMatchesFilter(f, lowerFilter)) return;
        const fbtn = document.createElement('button');
        fbtn.className = 'knowledge-tree-file' + (_knowledgeCurrentFile === f.name ? ' active' : '');
        fbtn.dataset.path = f.name;
        fbtn.innerHTML = `<i class="fas fa-file-lines text-[10px] text-slate-400"></i><span class="truncate">${escapeHtml(f.title)}</span>${_knowledgeFileActions(f.name)}`;
        fbtn.onclick = () => openKnowledgeFile(f.name, f.title);
        container.appendChild(fbtn);
    });
    _renderKnowledgeGroups(container, tree, '', lowerFilter, 0);
}

function _renderKnowledgeGroups(container, groups, parentPath, lowerFilter, depth) {
    const indent = depth * 12;
    groups.forEach(group => {
        const groupPath = parentPath ? parentPath + '/' + group.dir : group.dir;
        const files = (group.files || []).filter(f => _knowledgeMatchesFilter(f, lowerFilter));
        const children = group.children || [];
        const hasMatchingChildren = lowerFilter ? _hasFilterMatch(children, lowerFilter) : children.length > 0;
        if (files.length === 0 && !hasMatchingChildren && lowerFilter) return;

        const div = document.createElement('div');
        div.className = 'knowledge-tree-group open';

        const fileCount = _countFiles(group);
        const btn = document.createElement('button');
        btn.className = 'knowledge-tree-group-btn';
        btn.style.paddingLeft = (8 + indent) + 'px';
        btn.innerHTML = `<i class="fas fa-chevron-right chevron"></i><i class="fas fa-folder text-amber-400 text-[11px]"></i><span>${escapeHtml(group.dir)}</span><span class="ml-auto text-[10px] text-slate-400">${fileCount}</span>${_knowledgeCategoryActions(groupPath)}`;
        btn.onclick = () => div.classList.toggle('open');
        div.appendChild(btn);

        const items = document.createElement('div');
        items.className = 'knowledge-tree-group-items';
        files.forEach(f => {
            const fbtn = document.createElement('button');
            const fpath = groupPath + '/' + f.name;
            fbtn.className = 'knowledge-tree-file' + (_knowledgeCurrentFile === fpath ? ' active' : '');
            fbtn.dataset.path = fpath;
            fbtn.style.paddingLeft = (24 + indent) + 'px';
            fbtn.innerHTML = `<i class="fas fa-file-lines text-[10px] text-slate-400"></i><span class="truncate">${escapeHtml(f.title)}</span>${_knowledgeFileActions(fpath)}`;
            fbtn.onclick = () => openKnowledgeFile(fpath, f.title);
            items.appendChild(fbtn);
        });
        if (children.length > 0) {
            _renderKnowledgeGroups(items, children, groupPath, lowerFilter, depth + 1);
        }
        div.appendChild(items);
        container.appendChild(div);
    });
}

function _knowledgeActionButton(icon, title, handler) {
    const danger = icon === 'fa-trash' ? ' danger' : '';
    return `<span role="button" tabindex="0" title="${escapeHtml(title)}" onclick="event.stopPropagation();${handler}" class="knowledge-action${danger}"><i class="fas ${icon}"></i></span>`;
}

function _knowledgeFileActions(path) {
    if (path === 'index.md' || path === 'log.md') return '';
    const value = JSON.stringify(path).replace(/"/g, '&quot;');
    return `<span class="knowledge-actions">${_knowledgeActionButton('fa-arrow-right-arrow-left', '移动', `moveKnowledgeDocument(${value})`)}${_knowledgeActionButton('fa-trash', '删除', `deleteKnowledgeDocument(${value})`)}</span>`;
}

function _knowledgeCategoryActions(path) {
    const value = JSON.stringify(path).replace(/"/g, '&quot;');
    return `<span class="knowledge-actions">${_knowledgeActionButton('fa-folder-plus', '在此新建子目录', `createKnowledgeCategory(${value})`)}${_knowledgeActionButton('fa-file-circle-plus', '在此新建文件', `createKnowledgeDocument(${value})`)}${_knowledgeActionButton('fa-pen', '重命名', `renameKnowledgeCategory(${value})`)}${_knowledgeActionButton('fa-trash', '删除', `deleteKnowledgeCategory(${value})`)}</span>`;
}

async function dispatchKnowledgeAction(action, payload, openPathResolver) {
    _setKnowledgeStatus(currentLang === 'zh' ? '处理中...' : 'Working...', false, true);
    try {
        const response = await fetch('/api/knowledge/action', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({action, payload}),
        });
        const result = await response.json();
        if (result.status !== 'success') {
            _setKnowledgeStatus(result.message || (currentLang === 'zh' ? '操作失败' : 'Operation failed'), true);
            loadKnowledgeView();
            return null;
        }
        _setKnowledgeStatus(_knowledgeResultMessage(action, result.payload), false);
        // Optionally auto-open the affected file after the tree refreshes.
        const openPath = openPathResolver ? openPathResolver(result.payload) : null;
        loadKnowledgeView(openPath || undefined);
        return result.payload;
    } catch (error) {
        _setKnowledgeStatus(currentLang === 'zh' ? '请求失败，请稍后重试' : 'Request failed, please try again', true);
        return null;
    }
}

function _setKnowledgeStatus(message, isError, persistent) {
    const el = document.getElementById('knowledge-action-status');
    el.textContent = message;
    el.className = `text-xs transition-opacity duration-200 ${isError ? 'text-red-500' : 'text-primary-500'}`;
    el.classList.remove('opacity-0');
    clearTimeout(el._hideTimer);
    if (!persistent) el._hideTimer = setTimeout(() => el.classList.add('opacity-0'), 3500);
}

function _knowledgeResultMessage(action, payload) {
    if (currentLang !== 'zh') {
        return action === 'create_category' ? 'Category created' :
            action === 'create_document' ? 'Document created' :
            action === 'rename_category' ? 'Category renamed' :
            action === 'delete_category' ? 'Category deleted' :
            action === 'import_documents' ? `${payload?.imported || 0} imported · ${payload?.skipped || 0} skipped · ${payload?.failed || 0} failed` :
            action === 'move_documents' ? `${payload?.moved || 0} document moved` :
            `${payload?.deleted || 0} document deleted`;
    }
    return action === 'create_category' ? '分类已创建' :
        action === 'create_document' ? '文档已创建' :
        action === 'rename_category' ? '分类已重命名' :
        action === 'delete_category' ? '分类已删除' :
        action === 'import_documents' ? `导入 ${payload?.imported || 0} 个，跳过 ${payload?.skipped || 0} 个，失败 ${payload?.failed || 0} 个` :
        action === 'move_documents' ? `已移动 ${payload?.moved || 0} 个文档` :
        `已删除 ${payload?.deleted || 0} 个文档`;
}

function _knowledgeCategoryPaths(groups, parent = '') {
    const paths = [];
    for (const group of groups || []) {
        const path = parent ? `${parent}/${group.dir}` : group.dir;
        paths.push(path, ..._knowledgeCategoryPaths(group.children || [], path));
    }
    return paths;
}

function openKnowledgeDialog(options) {
    const overlay = document.getElementById('knowledge-dialog-overlay');
    const card = document.getElementById('knowledge-dialog-card');
    const input = document.getElementById('knowledge-dialog-input');
    const select = document.getElementById('knowledge-dialog-select');
    const textarea = document.getElementById('knowledge-dialog-textarea');
    const documentForm = document.getElementById('knowledge-document-form');
    const documentFilename = document.getElementById('knowledge-document-filename');
    const documentContent = document.getElementById('knowledge-document-content');
    const templateBtn = document.getElementById('knowledge-document-template');
    const documentPathPreview = document.getElementById('knowledge-document-path-preview');
    const submit = document.getElementById('knowledge-dialog-submit');
    const cancel = document.getElementById('knowledge-dialog-cancel');
    document.getElementById('knowledge-dialog-title').textContent = options.title;
    document.getElementById('knowledge-dialog-subtitle').textContent = options.subtitle || '';
    document.getElementById('knowledge-dialog-label').textContent = options.label;
    document.getElementById('knowledge-dialog-hint').textContent = options.hint || '';
    document.getElementById('knowledge-dialog-error').classList.add('hidden');
    document.getElementById('knowledge-dialog-icon').className = `fas ${options.icon || 'fa-folder'} text-emerald-500`;
    card.classList.toggle('knowledge-document-dialog', options.type === 'document');
    input.classList.toggle('hidden', options.type === 'select' || options.type === 'textarea' || options.type === 'document');
    select.classList.toggle('hidden', options.type !== 'select');
    textarea.classList.toggle('hidden', options.type !== 'textarea');
    documentForm.classList.toggle('hidden', options.type !== 'document');
    input.value = options.value || '';
    textarea.value = options.value || '';
    documentFilename.value = options.filename || '';
    documentContent.value = options.content || '';
    document.getElementById('knowledge-document-category-label').textContent = currentLang === 'zh' ? '目标分类' : 'Destination category';
    documentPathPreview.textContent = options.category
        ? `knowledge/${options.category}/`
        : 'knowledge/';
    documentFilename.oninput = null;
    document.getElementById('knowledge-document-filename-label').textContent = currentLang === 'zh' ? '文件名' : 'Filename';
    document.getElementById('knowledge-document-content-label').textContent = currentLang === 'zh' ? 'Markdown 内容' : 'Markdown content';
    templateBtn.textContent = currentLang === 'zh' ? '插入模板' : 'Insert template';
    templateBtn.onclick = () => {
        if (documentContent.value.trim()) return;
        const title = (documentFilename.value || 'untitled').replace(/\.md$/i, '');
        documentContent.value = currentLang === 'zh'
            ? `# ${title}\n\n## 摘要\n\n\n## 关键点\n\n- \n\n## 参考\n\n`
            : `# ${title}\n\n## Summary\n\n\n## Key points\n\n- \n\n## References\n\n`;
        documentContent.focus();
    };
    if (options.type === 'select') {
        // Use the shared custom dropdown component instead of a native
        // <select> so the arrow / menu match the rest of the console.
        const ddOptions = (options.choices || []).map(value => ({ value, label: value }));
        initDropdown(select, ddOptions, (options.choices || [])[0] || '', null);
    }
    submit.textContent = currentLang === 'zh' ? '确定' : 'Confirm';
    cancel.textContent = currentLang === 'zh' ? '取消' : 'Cancel';
    submit.disabled = options.type === 'select' && !(options.choices || []).length;

    const close = () => overlay.classList.add('hidden');
    const submitAction = async () => {
        const rawValue = options.type === 'select' ? getDropdownValue(select) :
            (options.type === 'textarea' ? textarea.value :
            (options.type === 'document' ? {
                filename: documentFilename.value.trim(),
                content: documentContent.value,
            } : input.value));
        const value = options.type === 'textarea' || options.type === 'document' ? rawValue : rawValue.trim();
        const error = options.validate ? options.validate(value) : (!value ? (currentLang === 'zh' ? '此项不能为空' : 'This field is required') : '');
        if (error) {
            const errorEl = document.getElementById('knowledge-dialog-error');
            errorEl.textContent = error;
            errorEl.classList.remove('hidden');
            return;
        }
        submit.disabled = true;
        const ok = await options.onSubmit(value);
        submit.disabled = false;
        if (ok !== null) close();
    };
    submit.onclick = submitAction;
    cancel.onclick = close;
    overlay.onclick = event => { if (event.target === overlay) close(); };
    input.onkeydown = event => { if (event.key === 'Enter') submitAction(); };
    overlay.classList.remove('hidden');
    setTimeout(() => (options.type === 'select' ? select : (options.type === 'textarea' ? textarea : (options.type === 'document' ? documentFilename : input))).focus(), 0);
}

function closeKnowledgeNewMenu() {
    const list = document.getElementById('knowledge-new-menu-list');
    if (list) list.classList.add('hidden');
    document.removeEventListener('click', _knowledgeNewMenuOutside, true);
}

function _knowledgeNewMenuOutside(event) {
    const menu = document.getElementById('knowledge-new-menu');
    if (menu && !menu.contains(event.target)) closeKnowledgeNewMenu();
}

function toggleKnowledgeNewMenu(event) {
    if (event) event.stopPropagation();
    const list = document.getElementById('knowledge-new-menu-list');
    if (!list) return;
    const willOpen = list.classList.contains('hidden');
    list.classList.toggle('hidden');
    if (willOpen) {
        document.addEventListener('click', _knowledgeNewMenuOutside, true);
    } else {
        document.removeEventListener('click', _knowledgeNewMenuOutside, true);
    }
}

function createKnowledgeCategory(parentPath = '') {
    openKnowledgeDialog({
        title: currentLang === 'zh' ? '新建目录' : 'New folder',
        subtitle: currentLang === 'zh' ? (parentPath ? `将在“${parentPath}”内创建子目录` : '在知识库根目录创建目录') : (parentPath ? `Create under ${parentPath}` : 'Create under knowledge root'),
        label: currentLang === 'zh' ? '目录名称' : 'Folder name',
        hint: currentLang === 'zh' ? '可继续在新目录中创建子目录和文件' : 'You can create subfolders and files inside it',
        icon: 'fa-folder-plus',
        onSubmit: name => dispatchKnowledgeAction('create_category', {path: parentPath ? `${parentPath}/${name}` : name}),
    });
}

function createKnowledgeDocument(parentPath = '') {
    if (parentPath) {
        openKnowledgeDocumentEditor(parentPath);
        return;
    }
    const categories = _knowledgeCategoryPaths(_knowledgeTreeData);
    if (!categories.length) {
        _setKnowledgeStatus(currentLang === 'zh' ? '请先创建分类' : 'Create a category first', true);
        return;
    }
    openKnowledgeDialog({
        title: currentLang === 'zh' ? '新建文档' : 'New document',
        subtitle: currentLang === 'zh' ? '先选择分类，然后输入文件名' : 'Choose a category, then enter a filename',
        label: currentLang === 'zh' ? '目标分类' : 'Destination category',
        type: 'select',
        choices: categories,
        icon: 'fa-file-circle-plus',
        onSubmit: category => {
            openKnowledgeDocumentEditor(category);
            return null;
        },
    });
}

function openKnowledgeDocumentEditor(category) {
    openKnowledgeDialog({
        title: currentLang === 'zh' ? '新建文档' : 'New document',
        subtitle: currentLang === 'zh' ? `保存到 ${category}` : `Save to ${category}`,
        label: '',
        hint: currentLang === 'zh' ? '文件名可省略 .md 后缀；保存后会自动同步索引。' : 'The .md suffix is optional. Index sync runs after saving.',
        type: 'document',
        category,
        filename: '',
        content: '',
        icon: 'fa-file-circle-plus',
        validate: value => {
            if (!value.filename) return currentLang === 'zh' ? '文件名不能为空' : 'Filename is required';
            if (/\.[^.]+$/i.test(value.filename) && !/\.md$/i.test(value.filename)) {
                return currentLang === 'zh' ? '新建文档仅支持 .md 文件名' : 'New documents must be .md files';
            }
            if (!value.content.trim()) return currentLang === 'zh' ? '内容不能为空' : 'Content is required';
            if (new Blob([value.content]).size > KNOWLEDGE_IMPORT_MAX_FILE_SIZE) {
                return currentLang === 'zh' ? '内容不能超过 10MB' : 'Content cannot exceed 10MB';
            }
            return '';
        },
        onSubmit: value => {
            const safeName = value.filename.endsWith('.md') ? value.filename : `${value.filename}.md`;
            return dispatchKnowledgeAction('create_document', {
                path: `${category}/${safeName}`,
                content: value.content,
                overwrite: false,
            }, payload => payload?.path || `${category}/${safeName}`);
        },
    });
}

function selectKnowledgeImportFiles() {
    const input = document.getElementById('knowledge-import-input');
    input.value = '';
    input.onchange = () => {
        if (input.files && input.files.length) openKnowledgeImportDialog(Array.from(input.files));
    };
    input.click();
}

function openKnowledgeImportDialog(files) {
    const validationError = validateKnowledgeImportFiles(files);
    if (validationError) {
        _setKnowledgeStatus(validationError, true);
        return;
    }
    const choices = _knowledgeCategoryPaths(_knowledgeTreeData);
    openKnowledgeDialog({
        title: currentLang === 'zh' ? '导入文档' : 'Import documents',
        subtitle: currentLang === 'zh' ? `已选择 ${files.length} 个文件` : `${files.length} file(s) selected`,
        label: currentLang === 'zh' ? '目标分类' : 'Destination category',
        hint: choices.length ? (currentLang === 'zh' ? '支持 Markdown 和 TXT，TXT 会转成 Markdown 文档' : 'Markdown and TXT are supported. TXT is converted to Markdown.') :
            (currentLang === 'zh' ? '请先创建一个分类' : 'Create a category first'),
        type: 'select',
        choices,
        icon: 'fa-file-arrow-up',
        onSubmit: target => importKnowledgeDocuments(files, target),
    });
}

async function importKnowledgeDocuments(files, targetCategory) {
    const validationError = validateKnowledgeImportFiles(files);
    if (validationError) {
        _setKnowledgeStatus(validationError, true);
        return null;
    }
    const supported = files.filter(file => /\.(md|txt)$/i.test(file.name || ''));
    if (!supported.length) {
        _setKnowledgeStatus(currentLang === 'zh' ? '请选择 .md 或 .txt 文件' : 'Choose .md or .txt files', true);
        return null;
    }
    const formData = new FormData();
    formData.append('target_category', targetCategory);
    formData.append('conflict_strategy', 'rename');
    supported.forEach(file => formData.append('files', file, file.name));
    _setKnowledgeStatus(currentLang === 'zh' ? '正在导入...' : 'Importing...', false, true);
    try {
        const response = await fetch('/api/knowledge/import', { method: 'POST', body: formData });
        const result = await response.json();
        if (result.status !== 'success') {
            _setKnowledgeStatus(result.message || (currentLang === 'zh' ? '导入失败' : 'Import failed'), true);
            loadKnowledgeView();
            return null;
        }
        _setKnowledgeStatus(_knowledgeResultMessage('import_documents', result.payload), false);
        // Auto-open the first successfully imported document.
        const firstImported = (result.payload?.results || []).find(item => item.status === 'imported');
        loadKnowledgeView(firstImported ? firstImported.path : undefined);
        return result.payload;
    } catch (error) {
        _setKnowledgeStatus(currentLang === 'zh' ? '导入请求失败' : 'Import request failed', true);
        return null;
    }
}

function validateKnowledgeImportFiles(files) {
    if (!files || !files.length) return currentLang === 'zh' ? '请选择文件' : 'Choose files';
    if (files.length > KNOWLEDGE_IMPORT_MAX_FILES) {
        return currentLang === 'zh' ? `一次最多导入 ${KNOWLEDGE_IMPORT_MAX_FILES} 个文件` : `Import at most ${KNOWLEDGE_IMPORT_MAX_FILES} files at a time`;
    }
    let total = 0;
    for (const file of files) {
        total += file.size || 0;
        if ((file.size || 0) > KNOWLEDGE_IMPORT_MAX_FILE_SIZE) {
            return currentLang === 'zh' ? `${file.name} 超过 10MB` : `${file.name} exceeds 10MB`;
        }
    }
    if (total > KNOWLEDGE_IMPORT_MAX_TOTAL_SIZE) {
        return currentLang === 'zh' ? '单次导入总大小不能超过 200MB' : 'Total import size cannot exceed 200MB';
    }
    return '';
}

let _knowledgeImportDropReady = false;
function initKnowledgeImportDropZone() {
    if (_knowledgeImportDropReady) return;
    const panel = document.getElementById('knowledge-panel-docs');
    if (!panel) return;
    _knowledgeImportDropReady = true;
    ['dragenter', 'dragover'].forEach(name => {
        panel.addEventListener(name, event => {
            if (!event.dataTransfer || !event.dataTransfer.types.includes('Files')) return;
            event.preventDefault();
            panel.classList.add('knowledge-import-drag-over');
        });
    });
    ['dragleave', 'drop'].forEach(name => {
        panel.addEventListener(name, event => {
            if (event.type === 'drop') {
                event.preventDefault();
                const files = Array.from(event.dataTransfer?.files || []);
                if (files.length) openKnowledgeImportDialog(files);
            }
            panel.classList.remove('knowledge-import-drag-over');
        });
    });
}

